ATOMIC = [
    T.NullType, T.BooleanType, T.ByteType, T.ShortType, T.IntegerType, T.LongType,
    T.FloatType, T.DoubleType, T.StringType, T.BinaryType, T.DateType,
    T.TimestampType, T.TimestampNTZType, T.VariantType,
]


@pytest.mark.parametrize("cls", ATOMIC)
def test_atomic_types_instantiate_and_roundtrip(cls):
    t = cls()
    assert t.typeName()
    assert t.simpleString()
    assert pickle.loads(pickle.dumps(t)).simpleString() == t.simpleString()


def test_parameterized_types_roundtrip():
    cases = [
        T.DecimalType(12, 3), T.CharType(5), T.VarcharType(9), T.TimeType(3),
        T.CalendarIntervalType(), T.YearMonthIntervalType(0, 1),
        T.YearMonthIntervalType(0, 0), T.DayTimeIntervalType(0, 3),
        T.DayTimeIntervalType(0, 1),
    ]
    # Interval/time types expose repr but not simpleString; compare structurally
    # via the value round-tripped through pickle (which uses __reduce__'s JSON).
    for t in cases:
        assert repr(pickle.loads(pickle.dumps(t))) == repr(t)


def test_decimal_precision_scale():
    d = T.DecimalType(10, 2)
    assert d.precision == 10 and d.scale == 2


def test_type_constructors_check_their_arguments_as_pyspark():
    # As PySpark's: DayTimeIntervalType and YearMonthIntervalType take the fields of their
    # types, both of the defaults without any and the start field for the end without one, and
    # raise INVALID_INTERVAL_CASTING of the str of each for another; the types without
    # parameters, singletons of DataTypeSingleton, raise its TypeError of an argument.
    from pyspark.errors import PySparkRuntimeError

    D, Y = T.DayTimeIntervalType, T.YearMonthIntervalType
    assert D().simpleString() == "interval day to second"
    assert D(D.HOUR).simpleString() == "interval hour"
    assert D(D.MINUTE, D.HOUR).simpleString() == "interval minute to hour"
    assert D(1.0).simpleString() == "interval hour"
    assert Y().simpleString() == "interval year to month"
    assert Y(Y.MONTH).simpleString() == "interval month"
    for make, params in [
        (lambda: D(endField=D.SECOND), ("None", "3")),
        (lambda: D(123), ("123", "123")),
        (lambda: D("a"), ("a", "a")),
        (lambda: Y(endField=3), ("None", "3")),
        (lambda: Y(Y.YEAR, 5), ("0", "5")),
    ]:
        with pytest.raises(PySparkRuntimeError) as e:
            make()
        assert e.value.getCondition() == "INVALID_INTERVAL_CASTING"
        assert e.value.getMessageParameters() == {"start_field": params[0], "end_field": params[1]}

    assert T.CalendarIntervalType() is T.CalendarIntervalType()
    for make, message in [
        (lambda: T.CalendarIntervalType(3), "takes 1 positional argument but 2 were given"),
        (lambda: T.IntegerType(1, 2), "takes 1 positional argument but 3 were given"),
        (lambda: T.NullType(x=1), "got an unexpected keyword argument 'x'"),
        (lambda: T.LongType(1, y=2), "got an unexpected keyword argument 'y'"),
    ]:
        with pytest.raises(TypeError, match=r"^DataTypeSingleton\.__call__\(\) " + message):
            make()




def test_nested_types_pickle_roundtrip():
    nested = [
        T.ArrayType(T.IntegerType()),
        T.MapType(T.StringType(), T.ArrayType(T.IntegerType())),
        T.StructType([
            T.StructField("a", T.ArrayType(T.IntegerType())),
            T.StructField("b", T.MapType(T.StringType(), T.IntegerType()), False),
        ]),
        T.ArrayType(T.StructType([
            T.StructField("x", T.MapType(T.StringType(), T.ArrayType(T.DecimalType(10, 2)))),
        ])),
    ]
    for t in nested:
        assert pickle.loads(pickle.dumps(t)).simpleString() == t.simpleString()


def test_parse_datatype_json_string_nested():
    t = T.StructType([
        T.StructField("a", T.ArrayType(T.IntegerType())),
        T.StructField("b", T.MapType(T.StringType(), T.IntegerType())),
    ])
    # Round-trip via the JSON that __reduce__ emits.
    j = pickle.dumps(t)
    assert pickle.loads(j).simpleString() == t.simpleString()


def test_parse_datatype_json_string_atomic_forms():
    import json
    assert T._parse_datatype_json_string(json.dumps("integer")).simpleString() == "int"
    assert T._parse_datatype_json_string(json.dumps("decimal(10,2)")).simpleString() == "decimal(10,2)"
    assert T._parse_datatype_json_string(json.dumps("char(4)")).simpleString() == "char(4)"


def test_parse_datatype_json_string_rejects_garbage():
    import json
    with pytest.raises(ValueError):
        T._parse_datatype_json_string(json.dumps("not_a_type"))


# One instance of every DataType variant the drop-in has, including the parameterized
# forms whose JSON needs more than a bare type name (collations, spatial CRS names).
EVERY_TYPE = [
    T.NullType(), T.BooleanType(), T.ByteType(), T.ShortType(), T.IntegerType(),
    T.LongType(), T.FloatType(), T.DoubleType(), T.DecimalType(), T.DecimalType(38, 18),
    T.StringType(), T.StringType("UTF8_LCASE"), T.StringType("UNICODE_CI"),
    T.CharType(5), T.VarcharType(9), T.BinaryType(), T.DateType(), T.TimestampType(),
    T.TimestampNTZType(),
    T.TimeType(3), T.CalendarIntervalType(), T.YearMonthIntervalType(0, 1),
    T.YearMonthIntervalType(1, 1), T.DayTimeIntervalType(0, 3),
    T.DayTimeIntervalType(2, 2), T.VariantType(),
    T.GeometryType(0), T.GeometryType(3857), T.GeometryType(4326), T.GeometryType("ANY"),
    T.GeographyType(4326), T.GeographyType("ANY"),
    T.ArrayType(T.GeometryType(3857), False),
    T.MapType(T.StringType("UTF8_LCASE"), T.GeographyType("ANY"), False),
]


@pytest.mark.parametrize("t", EVERY_TYPE, ids=repr)
def test_every_datatype_pickle_roundtrip(t):
    r = pickle.loads(pickle.dumps(t))
    assert type(r) is type(t)
    assert r == t and hash(r) == hash(t)
    assert r.json() == t.json()


def test_every_datatype_pickle_roundtrip_nested_in_struct():
    st = T.StructType([
        T.StructField(f"f{i}", t, i % 2 == 0, {"i": i, "tag": "v"})
        for i, t in enumerate(EVERY_TYPE)
    ])
    nested = T.StructType([
        T.StructField("s", st),
        T.StructField("a", T.ArrayType(st)),
        T.StructField("m", T.MapType(T.StringType("UNICODE"), st)),
    ])
    for t in (st, nested):
        r = pickle.loads(pickle.dumps(t))
        assert r == t
        assert r.json() == t.json()
    r = pickle.loads(pickle.dumps(st))
    for got, want in zip(r.fields, st.fields):
        assert type(got.dataType) is type(want.dataType)
        assert got.dataType == want.dataType
        assert got.metadata == want.metadata


def test_spatial_and_collated_json_forms_parse():
    import json
    cases = {
        "geometry(SRID:0)": T.GeometryType(0),
        "geometry(EPSG:3857)": T.GeometryType(3857),
        "geometry(OGC:CRS84)": T.GeometryType(4326),
        "geometry(SRID:ANY)": T.GeometryType("ANY"),
        "geography(OGC:CRS84, SPHERICAL)": T.GeographyType(4326),
        "geography(SRID:ANY, SPHERICAL)": T.GeographyType("ANY"),
        "string collate UTF8_LCASE": T.StringType("UTF8_LCASE"),
    }
    for j, want in cases.items():
        assert T._parse_datatype_json_string(json.dumps(j)) == want
        assert want.json() == json.dumps(j)


def test_schema_spatial_srids_are_those_of_pyspark(mock_connect):
    # As PySpark's schema conversion, which builds the spatial type of each SRID that the server
    # sends with GeometryType(srid) or GeographyType(srid): the SRIDs that PySpark 4.3.0 takes
    # and the mixed SRID are read, and another SRID, such as 2154, raises ST_INVALID_SRID_VALUE.
    from pyspark.errors import IllegalArgumentException

    spark, service = mock_connect

    def schema_with(kind, srid):
        # DataType.geometry=26 or geography=27, with its srid=1; StructField: name=1,
        # data_type=2, nullable=3; Struct.fields=1, and DataType.struct=21.
        spatial = message_field(26 if kind == "geometry" else 27, varint_field(1, srid))
        field = message_field(1, "g") + message_field(2, spatial) + varint_field(3, 1)
        return message_field(21, message_field(1, field))

    for kind, srid, expected in [
        ("geometry", 3857, T.GeometryType(3857)),
        ("geometry", -1, T.GeometryType("ANY")),
        ("geography", 4326, T.GeographyType(4326)),
        ("geography", -1, T.GeographyType("ANY")),
    ]:
        service.data_type = schema_with(kind, srid)
        assert spark.range(1).schema["g"].dataType == expected
    for kind, srid in [("geometry", 2154), ("geography", 4269), ("geography", 3857)]:
        service.data_type = schema_with(kind, srid)
        with pytest.raises(IllegalArgumentException) as e:
            spark.range(1).schema["g"].dataType
        assert e.value.getCondition() == "ST_INVALID_SRID_VALUE"
        assert e.value.getMessageParameters() == {"srid": str(srid)}


def test_schema_surfaces_raise_for_a_spatial_srid_that_pyspark_does_not_take(mock_connect):
    # As PySpark, which converts the schema from its proto wherever it reads it: the schema, the
    # columns, the dtypes, repr, printSchema, the columns of a projection and a DDL schema that
    # the server parses raise ST_INVALID_SRID_VALUE for an SRID that PySpark does not take, also
    # nested in an array, a map or a struct, while the SRIDs that it takes are read. The first
    # type that the conversion fails on decides, a nanosecond timestamp's UNSUPPORTED_OPERATION
    # included.
    from pyspark.errors import IllegalArgumentException, PySparkValueError

    spark, service = mock_connect
    # repr reads the settings of the eager evaluation of the session, which the server has.
    service.confs = {"spark.sql.repl.eagerEval.enabled": "false",
                     "spark.sql.repl.eagerEval.maxNumRows": "20",
                     "spark.sql.repl.eagerEval.truncate": "20"}

    def spatial(kind, srid):
        # DataType.geometry=26 or geography=27, with its srid=1.
        return message_field(26 if kind == "geometry" else 27, varint_field(1, srid))

    def struct(*fields):
        # StructField: name=1, data_type=2, nullable=3; Struct.fields=1, and DataType.struct=21.
        return message_field(21, b"".join(
            message_field(1, message_field(1, name) + message_field(2, data_type)
                          + varint_field(3, 1))
            for name, data_type in fields))

    # DataType.long=7, string=11, array=20 (Array.element_type=1) and map=22 (Map.key_type=1,
    # value_type=2), and timestamp_ntz_nanos=29 (precision=1).
    long_type, string_type = message_field(7, b""), message_field(11, b"")
    nanos = message_field(29, varint_field(1, 9))
    for schema, srid in [
        (struct(("g", spatial("geometry", 2154))), 2154),
        (struct(("i", long_type), ("g", message_field(20, message_field(
            1, spatial("geography", 4269)) + varint_field(2, 1)))), 4269),
        (struct(("g", message_field(22, message_field(1, string_type) + message_field(
            2, spatial("geometry", 2154)) + varint_field(3, 1)))), 2154),
        (struct(("s", struct(("g", spatial("geography", 3857))))), 3857),
        (struct(("g", spatial("geometry", 2154)), ("t", nanos)), 2154),
    ]:
        service.data_type = schema
        df = spark.range(1)
        for surface in (
                lambda: df.schema,
                lambda: df.columns,
                lambda: df.dtypes,
                lambda: repr(df),
                lambda: df.printSchema(),
                lambda: df.select("g").columns,
        ):
            with pytest.raises(IllegalArgumentException) as e:
                surface()
            assert e.value.getCondition() == "ST_INVALID_SRID_VALUE"
            assert e.value.getMessageParameters() == {"srid": str(srid)}
    # A DDL schema, which the server parses (the mock parses these).
    for ddl, srid in [("g geometry(2154)", 2154), ("g array<geography(4269)>", 4269)]:
        with pytest.raises(IllegalArgumentException) as e:
            spark.createDataFrame([], ddl)
        assert e.value.getCondition() == "ST_INVALID_SRID_VALUE"
        assert e.value.getMessageParameters() == {"srid": str(srid)}
    # A nanosecond timestamp before the spatial type is the error of the timestamp.
    service.data_type = struct(("t", nanos), ("g", spatial("geometry", 2154)))
    with pytest.raises(PySparkValueError) as e:
        spark.range(1).columns
    assert e.value.getCondition() == "UNSUPPORTED_OPERATION"
    for kind, srid, simple in [
        ("geometry", 3857, "geometry(3857)"),
        ("geometry", 0, "geometry(0)"),
        ("geometry", -1, "geometry(any)"),
        ("geography", 4326, "geography(4326)"),
    ]:
        service.data_type = struct(("g", spatial(kind, srid)))
        df = spark.range(1)
        assert df.columns == ["g"]
        assert df.dtypes == [("g", simple)]
        assert repr(df) == f"DataFrame[g: {simple}]"


def test_collect_raises_the_srid_error_of_the_schema_before_a_later_stream_failure(mock_connect):
    # As PySpark, which converts the schema of the first response that carries one, so an SRID
    # that PySpark does not take raises ST_INVALID_SRID_VALUE before the stream fails after the
    # schema, in each read of the rows, and the rows are not converted.
    from pyspark.errors import IllegalArgumentException

    spark, service = mock_connect
    # The settings that toPandas reads before the execution.
    service.confs = {"spark.sql.session.timeZone": "UTC",
                     "spark.sql.execution.pandas.structHandlingMode": "legacy",
                     "spark.sql.execution.arrow.pyspark.selfDestruct.enabled": "false"}
    # DataType.geometry=26 with its srid=1; DataType.struct=21 (Struct.fields=1; StructField
    # name=1, data_type=2, nullable=3).
    geometry = message_field(26, varint_field(1, 2154))
    schema = message_field(21, message_field(
        1, message_field(1, "g") + message_field(2, geometry) + varint_field(3, 1)))
    # ExecutePlanResponse.schema=7, and then the stream fails.
    service.execute_payloads = [message_field(7, schema)]
    service.stream_failure = "INTERNAL"
    df = spark.range(1)
    for read in (lambda: df.collect(),
                 lambda: df.toPandas(),
                 lambda: df.first(),
                 lambda: df.head(2),
                 lambda: df.take(2),
                 lambda: df.tail(2),
                 lambda: list(df.toLocalIterator())):
        with pytest.raises(IllegalArgumentException) as e:
            read()
        assert e.value.getCondition() == "ST_INVALID_SRID_VALUE"
        assert e.value.getMessageParameters() == {"srid": "2154"}


def test_nested_types_assert_a_data_type_not_a_type_string_as_pyspark():
    # As PySpark's constructors, which assert that the type is a DataType, so a type string is an
    # AssertionError, as is any other value. StructType.add takes a type string, which it parses.
    import pyspark.sql.types as T

    data_type_class = "<class 'pyspark.sql.types.DataType'>"
    cases = [
        (lambda: T.StructField("g", "int"),
         f"dataType int should be an instance of {data_type_class}"),
        (lambda: T.StructField("g", None),
         f"dataType None should be an instance of {data_type_class}"),
        (lambda: T.StructField("g", "geography(2154)"),
         f"dataType geography(2154) should be an instance of {data_type_class}"),
        (lambda: T.ArrayType("int"), f"elementType int should be an instance of {data_type_class}"),
        (lambda: T.ArrayType(5), f"elementType 5 should be an instance of {data_type_class}"),
        (lambda: T.MapType("int", T.IntegerType()),
         f"keyType int should be an instance of {data_type_class}"),
        (lambda: T.MapType(T.IntegerType(), "int"),
         f"valueType int should be an instance of {data_type_class}"),
    ]
    for make, message in cases:
        with pytest.raises(AssertionError) as e:
            make()
        assert str(e.value) == message
    assert T.StructType().add("g", "string").fields[0].dataType == T.StringType()
    assert T.StructType().add("g", T.LongType()).fields[0].dataType == T.LongType()


def test_to_keeps_a_type_string_unparsed_and_fails_at_the_action_as_pyspark(mock_connect):
    # As PySpark's `DataFrame.to`, which keeps a str as the schema and does not parse it: `to`
    # does not raise, the str is the schema, and each action fails when it builds the plan, with
    # the UNSUPPORTED_OPERATION error of the str, before any request is sent.
    from pyspark.errors import PySparkValueError

    spark, service = mock_connect
    df = spark.range(1)
    sent = len(service.execute_requests)
    for text in ["foo bar", "a bigint", "a\ud800"]:
        to_text = df.to(text)
        assert to_text.schema == text
        for read in (lambda: to_text.collect(), lambda: to_text.count()):
            with pytest.raises(PySparkValueError) as e:
                read()
            assert e.value.getCondition() == "UNSUPPORTED_OPERATION"
            assert e.value.getMessageParameters() == {"operation": f"data type {text}"}
            assert str(e.value) == f"[UNSUPPORTED_OPERATION] data type {text} is not supported."
    assert len(service.execute_requests) == sent
    # The schema of a union of two equal ones is the same str, and of different ones is not.
    same = df.to("a bigint").union(df.to("a bigint"))
    assert same.schema == "a bigint"
    with pytest.raises(PySparkValueError):
        df.to("a bigint").union(df.to("a int")).schema
    # None is an AssertionError at the call, and another object fails at the action as a str does.
    with pytest.raises(AssertionError):
        df.to(None)
    assert df.to(5).schema == 5
    with pytest.raises(PySparkValueError) as e:
        df.to(5).collect()
    assert str(e.value) == "[UNSUPPORTED_OPERATION] data type 5 is not supported."


def test_struct_type_fields_raise_pyspark_errors_for_items_without_a_name():
    # As PySpark's `StructType.__init__`, which reads the name of each item before it asserts that
    # each item is a StructField: a DDL string, whose characters have no name, is an error of its
    # own, not a Debug dump of a Rust error, and a field of another kind is an assertion.
    import pyspark.sql.types as T

    int_type = T.IntegerType()
    F = namedtuple("F", ["name", "dataType"])
    cases = [
        (lambda: T.StructType(["a"]), AttributeError, "'str' object has no attribute 'name'"),
        (lambda: T.StructType("a int"), AttributeError, "'str' object has no attribute 'name'"),
        (lambda: T.StructType(["a int"]), AttributeError, "'str' object has no attribute 'name'"),
        (lambda: T.StructType([("a", int_type)]), AttributeError,
         "'tuple' object has no attribute 'name'"),
        (lambda: T.StructType(5), TypeError, "'int' object is not iterable"),
        (lambda: T.StructType([F("a", int_type)]), AssertionError,
         "fields should be a list of StructField"),
    ]
    for make, error, message in cases:
        with pytest.raises(error) as e:
            make()
        assert str(e.value) == message
    assert T.StructType([T.StructField("a", int_type)]).names == ["a"]


def test_struct_field_asserts_its_data_type_then_its_name_as_pyspark():
    # As PySpark's `StructField.__init__`: the data type is asserted first, then the name, which
    # is any str, so a name of another type is an AssertionError, not a TypeError.
    import pyspark.sql.types as T

    data_type_class = "<class 'pyspark.sql.types.DataType'>"
    cases = [
        (lambda: T.StructField(5, T.IntegerType()), "field name 5 should be a string"),
        (lambda: T.StructField(None, T.IntegerType()), "field name None should be a string"),
        (lambda: T.StructField(b"g", T.IntegerType()), "field name b'g' should be a string"),
        (lambda: T.StructField(5, "int"),
         f"dataType int should be an instance of {data_type_class}"),
        (lambda: T.StructField(5, 5), f"dataType 5 should be an instance of {data_type_class}"),
        (lambda: T.StructField(name=5, dataType=None),
         f"dataType None should be an instance of {data_type_class}"),
    ]
    for make, message in cases:
        with pytest.raises(AssertionError) as e:
            make()
        assert str(e.value) == message


def test_struct_type_add_asserts_as_struct_field_does():
    # As PySpark's `StructType.add`, which builds a StructField of its arguments: the data type is
    # asserted first, and a name is required only when it is a str.
    import pyspark.sql.types as T

    data_type_class = "<class 'pyspark.sql.types.DataType'>"
    cases = [
        (lambda: T.StructType().add("g", 5),
         f"dataType 5 should be an instance of {data_type_class}"),
        (lambda: T.StructType().add(5),
         f"dataType None should be an instance of {data_type_class}"),
        (lambda: T.StructType().add(None),
         f"dataType None should be an instance of {data_type_class}"),
        (lambda: T.StructType().add(5, T.IntegerType()), "field name 5 should be a string"),
    ]
    for make, message in cases:
        with pytest.raises(AssertionError) as e:
            make()
        assert str(e.value) == message


def test_nullable_flags_are_kept_as_given_as_pyspark_keeps_them():
    # As PySpark's plain classes, which keep `nullable`, `containsNull` and `valueContainsNull` as
    # they are given, of any type: the attribute, the repr and the JSON show the value, and it
    # compares as `__dict__` does (`1` equals `True`, but `"x"` does not).
    import pyspark.sql.types as T

    field = T.StructField("g", T.IntegerType(), "x")
    assert field.nullable == "x"
    assert repr(field) == "StructField('g', IntegerType(), x)"
    assert field.jsonValue() == {"name": "g", "type": "integer", "nullable": "x", "metadata": {}}
    assert field.json() == '{"metadata":{},"name":"g","nullable":"x","type":"integer"}'
    assert T.StructType([field]).json() == (
        '{"fields":[{"metadata":{},"name":"g","nullable":"x","type":"integer"}],"type":"struct"}'
    )
    assert repr(T.StructType([field])) == "StructType([StructField('g', IntegerType(), x)])"
    assert field == T.StructField("g", T.IntegerType(), "x")
    assert field != T.StructField("g", T.IntegerType(), True)
    assert T.StructType([field]) != T.StructType([T.StructField("g", T.IntegerType(), True)])

    array = T.ArrayType(T.IntegerType(), "x")
    assert array.containsNull == "x"
    assert repr(array) == "ArrayType(IntegerType(), x)"
    assert array.json() == '{"containsNull":"x","elementType":"integer","type":"array"}'
    assert array != T.ArrayType(T.IntegerType(), True)

    the_map = T.MapType(T.IntegerType(), T.IntegerType(), None)
    assert the_map.valueContainsNull is None
    assert repr(the_map) == "MapType(IntegerType(), IntegerType(), None)"
    assert the_map.json() == (
        '{"keyType":"integer","type":"map","valueContainsNull":null,"valueType":"integer"}'
    )

    one = T.StructField("g", T.IntegerType(), 1)
    assert one == T.StructField("g", T.IntegerType(), True)
    assert one.jsonValue()["nullable"] == 1

    # The flags, and the nested ones, survive pickling, as in PySpark.
    nested = T.StructType([T.StructField("a", T.ArrayType(T.StructType([field]), 0))])
    assert pickle.loads(pickle.dumps(nested)).json() == nested.json()
    assert pickle.loads(pickle.dumps(field)).nullable == "x"
    assert pickle.loads(pickle.dumps(array)).containsNull == "x"


def test_struct_field_nullable_is_kept_when_it_is_set():
    import pyspark.sql.types as T

    field = T.StructField("g", T.IntegerType())
    field.nullable = "x"
    assert field.nullable == "x"
    assert field.jsonValue()["nullable"] == "x"
    assert T.StructField("g", T.IntegerType()).nullable is True


def test_struct_type_item_errors_name_the_type_as_python_does():
    # As PySpark's `StructType.__init__`: the error of an item without a name, or of a struct that
    # is not iterable, names the type by its `__name__`, not by its module and name.
    import pyspark.sql.types as T

    with pytest.raises(AttributeError) as e:
        T.StructType([T.IntegerType()])
    assert str(e.value) == "'IntegerType' object has no attribute 'name'"
    with pytest.raises(TypeError) as e:
        T.StructType(T.StructField("a", T.IntegerType()))
    assert str(e.value) == "'StructField' object is not iterable"


def test_tree_string_prints_nullable_flags_as_given_as_pyspark_prints_them():
    # As PySpark's `_build_formatted_string`, which prints `str(flag).lower()` of each flag: a flag
    # that is not a bool is printed as it is, and a bool as `true` or `false`.
    import pyspark.sql.types as T

    def tree(*args):
        return T.StructType([T.StructField("a", *args)]).treeString()

    assert tree(T.IntegerType(), 0) == "root\n |-- a: integer (nullable = 0)\n"
    assert tree(T.IntegerType(), "x") == "root\n |-- a: integer (nullable = x)\n"
    assert tree(T.IntegerType(), None) == "root\n |-- a: integer (nullable = none)\n"
    assert tree(T.IntegerType(), True) == "root\n |-- a: integer (nullable = true)\n"
    assert tree(T.ArrayType(T.IntegerType(), 1)) == (
        "root\n |-- a: array (nullable = true)\n |    |-- element: integer (containsNull = 1)\n"
    )
    assert tree(T.MapType(T.IntegerType(), T.IntegerType(), 1)) == (
        "root\n |-- a: map (nullable = true)\n |    |-- key: integer\n"
        " |    |-- value: integer (valueContainsNull = 1)\n"
    )
    nested = T.StructType([T.StructField("b", T.IntegerType(), 0)])
    assert T.StructType([T.StructField("a", nested)]).treeString() == (
        "root\n |-- a: struct (nullable = true)\n |    |-- b: integer (nullable = 0)\n"
    )
    assert T.StructType([T.StructField("a", nested)]).treeString(1) == (
        "root\n |-- a: struct (nullable = true)\n"
    )


def test_container_attributes_are_assignable_as_pyspark():
    # As PySpark's plain classes: an assignment of `containsNull`, `elementType`, `keyType`,
    # `valueType`, `valueContainsNull`, `fields`, `names` and a field's `name` is the attribute,
    # and the JSON, repr, `simpleString`, equality and `treeString` follow it.
    import pyspark.sql.types as T

    array = T.ArrayType(T.IntegerType(), True)
    array.containsNull = 0
    assert array.containsNull == 0
    assert array.json() == '{"containsNull":0,"elementType":"integer","type":"array"}'
    assert repr(array) == "ArrayType(IntegerType(), 0)"
    assert array.simpleString() == "array<int>"
    assert array != T.ArrayType(T.IntegerType(), True)

    element = T.ArrayType(T.IntegerType())
    element.elementType = T.StringType()
    assert element.json() == '{"containsNull":true,"elementType":"string","type":"array"}'
    assert repr(element) == "ArrayType(StringType(), True)"
    assert element == T.ArrayType(T.StringType())

    the_map = T.MapType(T.StringType(), T.IntegerType())
    the_map.valueContainsNull = "x"
    assert repr(the_map) == "MapType(StringType(), IntegerType(), x)"
    the_map.keyType = T.LongType()
    the_map.valueType = T.DoubleType()
    assert the_map.json() == (
        '{"keyType":"long","type":"map","valueContainsNull":"x","valueType":"double"}'
    )
    assert the_map.simpleString() == "map<bigint,double>"

    struct = T.StructType([T.StructField("a", T.IntegerType())])
    struct.fields = [T.StructField("b", T.StringType())]
    assert struct.json() == (
        '{"fields":[{"metadata":{},"name":"b","nullable":true,"type":"string"}],"type":"struct"}'
    )
    assert struct.treeString() == "root\n |-- b: string (nullable = true)\n"
    assert len(struct) == 1
    # `names` is not recomputed by an assignment of `fields`, as in PySpark.
    assert struct.names == ["a"]
    assert struct.fieldNames() == ["a"]

    named = T.StructType([T.StructField("a", T.IntegerType())])
    named.names = ["zz"]
    assert named.names == ["zz"]
    assert named.fieldNames() == ["zz"]
    assert named != T.StructType([T.StructField("a", T.IntegerType())])

    field = T.StructField("a", T.IntegerType())
    field.name = 5
    assert field.name == 5
    assert repr(field) == "StructField('5', IntegerType(), True)"
    assert field.simpleString() == "5:int"
    assert field.json() == '{"metadata":{},"name":5,"nullable":true,"type":"integer"}'


def test_create_dataframe_asserts_the_nullable_flags_of_non_empty_rows(mock_connect):
    # As PySpark's converters of local rows, which assert that each `nullable` is a bool, after the
    # rows are taken apart; empty data is not converted, so it has no assertion.
    import pyspark.sql.types as T

    spark, _ = mock_connect
    for flag in (0, None, "x"):
        schema = T.StructType([T.StructField("x", T.IntegerType(), flag)])
        with pytest.raises(AssertionError) as e:
            spark.createDataFrame([(1,)], schema)
        assert str(e.value) == ""
        spark.createDataFrame([], schema)
    with pytest.raises(AssertionError):
        spark.createDataFrame([(1,)], T.StructType([
            T.StructField("x", T.ArrayType(T.IntegerType(), 0)),
        ]))
    # The converter of a struct in an array is made, so its fields are asserted too.
    inner = T.StructType([T.StructField("y", T.IntegerType(), 0)])
    with pytest.raises(AssertionError):
        spark.createDataFrame([([(1,)],)], T.StructType([
            T.StructField("x", T.ArrayType(inner, True)),
        ]))


def test_struct_field_is_a_data_type_as_pyspark(mock_connect):
    # As PySpark's `class StructField(DataType)`: a field is a type, which another type can hold.
    import pickle

    import pyspark.sql.types as T

    nested = T.StructField("a", T.StructField("b", T.IntegerType()))
    assert isinstance(nested, T.DataType)
    assert repr(nested) == "StructField('a', StructField('b', IntegerType(), True), True)"
    assert nested.json() == (
        '{"metadata":{},"name":"a","nullable":true,'
        '"type":{"metadata":{},"name":"b","nullable":true,"type":"integer"}}'
    )
    assert nested.jsonValue()["type"] == {
        "name": "b", "type": "integer", "nullable": True, "metadata": {},
    }
    assert nested.simpleString() == "a:b:int"
    assert nested.needConversion() is False
    assert nested == T.StructField("a", T.StructField("b", T.IntegerType()))
    assert hash(nested) == hash(T.StructField("a", T.StructField("b", T.IntegerType())))
    assert pickle.loads(pickle.dumps(nested)) == nested

    assert T.ArrayType(T.StructField("a", T.IntegerType())).json() == (
        '{"containsNull":true,"elementType":{"metadata":{},"name":"a","nullable":true,'
        '"type":"integer"},"type":"array"}'
    )
    assert T.MapType(T.StructField("a", T.IntegerType()), T.IntegerType()).simpleString() == (
        "map<a:int,int>"
    )
    added = T.StructType().add("a", T.StructField("b", T.IntegerType()))
    assert added.json() == (
        '{"fields":[{"metadata":{},"name":"a","nullable":true,"type":{"metadata":{},'
        '"name":"b","nullable":true,"type":"integer"}}],"type":"struct"}'
    )
    assert T.StructType([nested]).simpleString() == "struct<a:b:int>"
    assert repr(T.ArrayType(T.StructField("a", T.IntegerType()))) == (
        "ArrayType(StructField('a', IntegerType(), True), True)"
    )


def test_struct_field_as_a_type_fails_where_pyspark_fails(mock_connect):
    # The client of PySpark has no Arrow type, nor a proto, for a StructField as a type, and no
    # tree type name: each of its uses raises PySpark's error, at the same call.
    import pyspark.sql.types as T
    from pyspark.sql import functions as F

    spark, _ = mock_connect
    schema = T.StructType([T.StructField("x", T.StructField("b", T.IntegerType()))])
    with pytest.raises(Exception) as e:
        spark.createDataFrame([(1,)], schema)
    assert str(e.value) == (
        "[UNSUPPORTED_DATA_TYPE_FOR_ARROW_CONVERSION] StructField('b', IntegerType(), True) is not "
        "supported in conversion to Arrow."
    )
    # The plan of a `to` or of a column is sent with the action, where PySpark raises its error.
    df = spark.range(1)
    with pytest.raises(Exception) as e:
        df.to(schema).collect()
    assert str(e.value) == (
        "[UNSUPPORTED_OPERATION] data type StructField('b', IntegerType(), True) is not supported."
    )
    with pytest.raises(Exception) as e:
        schema.treeString()
    assert str(e.value) == (
        "[INVALID_TYPENAME_CALL] StructField does not have typeName. Use typeName on its type "
        "explicitly instead."
    )
    with pytest.raises(Exception) as e:
        df.select(F.col("id").cast(T.StructField("b", T.IntegerType()))).collect()
    assert str(e.value) == (
        "[UNSUPPORTED_OPERATION] data type StructField('b', IntegerType(), True) is not supported."
    )
    with pytest.raises(Exception) as e:
        spark.createDataFrame([(1,)], T.StructField("a", T.IntegerType()))
    assert str(e.value) == (
        "[NOT_EXPECTED_TYPE] Argument `schema` should be list, None or StructType, "
        "got StructField."
    )


def test_casts_to_types_that_pyspark_does_not_convert_fail_when_the_plan_is_built(mock_connect):
    # As PySpark's `CastExpression`, whose `to_plan` converts its type with
    # `pyspark_types_to_proto_types` when a request builds the plan: a DataType of none of its
    # types, as `DataType()` or a Python subclass, or a StructField, also one nested in a type,
    # makes a Column, which renders as the `simpleString` of the type, and whose plans raise the
    # UNSUPPORTED_OPERATION of the type that the conversion fails on.
    import pyspark.sql.types as T
    from pyspark.errors import PySparkValueError
    from pyspark.sql import functions as F

    class MyType(T.DataType):
        pass

    class Own(T.DataType):
        def simpleString(self):
            return "own_type"

    class Lone(T.DataType):
        # Its str, of the repr, has a lone surrogate, which the error shows as it is.
        def simpleString(self):
            return "lone"

        def __repr__(self):
            return "Lone\ud800()"

    spark, service = mock_connect
    df = spark.range(1)
    field = T.StructField("b", T.IntegerType())
    for data_type, text, unsupported in [
        (MyType(), "MY", "MyType()"),
        (T.DataType(), "DATA", "DataType()"),
        (Own(), "OWN_TYPE", "Own()"),
        (Lone(), "LONE", "Lone\ud800()"),
        (field, "B:INT", repr(field)),
        (T.ArrayType(field), "ARRAY<B:INT>", repr(field)),
        (T.StructType([T.StructField("x", field)]), "STRUCT<X:B:INT>", repr(field)),
    ]:
        for cast, name in ((F.col("id").cast, "CAST"), (F.col("id").try_cast, "TRY_CAST")):
            column = cast(data_type)
            assert repr(column) == f"Column<'{name}(id AS {text})'>"
            with pytest.raises(PySparkValueError) as error:
                df.select(column).schema
            assert error.value.getCondition() == "UNSUPPORTED_OPERATION"
            assert str(error.value) == (
                f"[UNSUPPORTED_OPERATION] data type {unsupported} is not supported.")
    assert service.analyze_requests == []


def test_udfs_of_types_that_pyspark_does_not_convert_fail_when_the_plan_is_built(mock_connect):
    # As PySpark's `PythonUDF.to_plan`, which converts the output type of a UDF with
    # `pyspark_types_to_proto_types` when a request builds the plan: a UDF whose eval type does not
    # check its type at the call, as one that is not Arrow-optimized, is applied, and its plans
    # raise the UNSUPPORTED_OPERATION of the type that the conversion fails on.
    import pyspark.sql.types as T
    from pyspark.errors import PySparkValueError
    from pyspark.sql import functions as F

    spark, service = mock_connect
    df = spark.range(1)
    field = T.StructField("b", T.IntegerType())
    for data_type, unsupported in [
        (T.AtomicType(), "AtomicType()"),
        (field, repr(field)),
        (T.StructType([T.StructField("x", field)]), repr(field)),
    ]:
        column = F.udf(lambda x: x, data_type, useArrow=False)("id")
        with pytest.raises(PySparkValueError) as error:
            df.select(column).schema
        assert error.value.getCondition() == "UNSUPPORTED_OPERATION"
        assert str(error.value) == f"[UNSUPPORTED_OPERATION] data type {unsupported} is not supported."
    assert service.analyze_requests == []


def test_json_forms_accept_trailing_whitespace_as_pyspark(mock_connect):
    # As PySpark's `_parse_datatype_json_value`, whose patterns match a prefix of the string: the
    # whitespace after a form with an argument or a field is not a part of it. A bare name is
    # matched whole, so `integer ` is not a type.
    import json

    cases = {
        "string collate UNICODE ": T.StringType("UNICODE"),
        "interval day ": T.DayTimeIntervalType(0),
        "interval day to second ": T.DayTimeIntervalType(0, 3),
        "decimal(10,2) ": T.DecimalType(10, 2),
    }
    for j, want in cases.items():
        assert T._parse_datatype_json_string(json.dumps(j)) == want
    with pytest.raises(ValueError):
        T._parse_datatype_json_string(json.dumps("integer "))


def test_private_type_helpers_are_those_of_pyspark():
    # As PySpark's pyspark.sql.types: the inference, merging, conversion and verification of the
    # types of Python objects and their tables, including tuple-based Rows.
    from array import array

    from pyspark.errors import PySparkTypeError, PySparkValueError
    from pyspark.sql.types import (
        JVM_INT_MAX,
        _acceptable_types,
        _array_type_mappings,
        _create_converter,
        _has_nulltype,
        _infer_schema,
        _infer_type,
        _make_type_verifier,
        _merge_type,
    )

    assert JVM_INT_MAX == 2**31 - 1
    assert _array_type_mappings["d"] is T.DoubleType and _array_type_mappings["i"] is T.IntegerType
    assert T.StructType in _acceptable_types and dict in _acceptable_types[T.StructType]
    assert _infer_type(array("d", [1.0])) == T.ArrayType(T.DoubleType(), False)
    assert _infer_type({"k": [1]}) == T.MapType(T.StringType(), T.ArrayType(T.LongType()))
    schema = T.StructType([T.StructField("a", T.LongType()), T.StructField("b", T.StringType())])
    assert _infer_schema(Row(a=1, b="x")) == schema
    assert _infer_schema(Row(1, "x"), names=["a", "b"]) == schema
    assert _has_nulltype(_infer_schema({"a": None}))
    merged = _merge_type(schema, T.StructType([T.StructField("c", T.DoubleType())]))
    assert merged.names == ["a", "b", "c"]
    with pytest.raises(PySparkTypeError) as error:
        _merge_type(T.LongType(), T.DoubleType())
    assert error.value.getCondition() == "CANNOT_MERGE_TYPE"

    verify = _make_type_verifier(T.StructType([T.StructField("a", T.IntegerType(), False)]))
    for value in (Row(a=1), (1,), {"a": 1}):
        verify(value)
    with pytest.raises(PySparkValueError) as error:
        verify(Row(a=None))
    assert error.value.getCondition() == "FIELD_NOT_NULLABLE_WITH_NAME"
    with pytest.raises(PySparkValueError) as error:
        verify(Row(a=1, b=2))
    assert error.value.getCondition() == "FIELD_STRUCT_LENGTH_MISMATCH"
    struct = T.StructType([T.StructField("m", T.MapType(T.StringType(), T.IntegerType()))])
    assert _create_converter(struct)(Row(m={"k": 1})) == ({"k": 1},)




def _type_verifier_cases():
    # The cases of Apache Spark's DataTypeVerificationTests.test_verify_type_not_nullable: the
    # values that a type takes, and those it rejects, of the error of each.
    import array
    import datetime
    import decimal

    from pyspark.testing.objects import ExamplePoint, ExamplePointUDT, PythonOnlyUDT

    schema = T.StructType(
        [T.StructField("s", T.StringType(), False), T.StructField("i", T.IntegerType(), True)]
    )

    class MyObj:
        def __init__(self, **kwargs):
            for k, v in kwargs.items():
                setattr(self, k, v)

    success = [
        ("", T.StringType()), (1, T.StringType()), ([], T.StringType()), ({}, T.StringType()),
        ("", T.StringType("UTF8_LCASE")), (1.0, T.CharType(10)), ({}, T.VarcharType(10)),
        (ExamplePoint(1.0, 2.0), ExamplePointUDT()), (True, T.BooleanType()),
        (-(2**7), T.ByteType()), (2**7 - 1, T.ByteType()), (-(2**15), T.ShortType()),
        (2**15 - 1, T.ShortType()), (-(2**31), T.IntegerType()), (2**31 - 1, T.IntegerType()),
        (-(2**63), T.LongType()), (2**63 - 1, T.LongType()), (1.0, T.FloatType()),
        (1.0, T.DoubleType()), (decimal.Decimal("1.0"), T.DecimalType()),
        (bytearray([1, 2]), T.BinaryType()), (datetime.date(2000, 1, 2), T.DateType()),
        (datetime.time(1, 0, 0), T.TimeType()), (datetime.datetime(2000, 1, 2), T.DateType()),
        (datetime.datetime(2000, 1, 2, 3, 4), T.TimestampType()),
        ([], T.ArrayType(T.IntegerType())), (["1", None], T.ArrayType(T.StringType())),
        ((1, 2), T.ArrayType(T.IntegerType())), (array.array("h", [1]), T.ArrayType(T.IntegerType())),
        ({"a": 1}, T.MapType(T.StringType(), T.IntegerType())),
        ({"a": None}, T.MapType(T.StringType(), T.IntegerType(), True)),
        ({"s": "a", "i": None}, schema), ({"s": "a", "f": 1.0}, schema), (Row(s="a", i=1), schema),
        (Row(s="a", i=None), schema), (["a", 1], schema), (("a", None), schema),
        (MyObj(s="a", i=1), schema), (MyObj(s="a"), schema),
    ]
    failure = [
        (None, T.StringType(), ValueError), (None, T.CharType(10), ValueError),
        (None, T.VarcharType(10), ValueError), (ExamplePoint(1.0, 2.0), PythonOnlyUDT(), ValueError),
        (1, T.BooleanType(), TypeError), ("True", T.BooleanType(), TypeError),
        (-(2**7) - 1, T.ByteType(), ValueError), (2**7, T.ByteType(), ValueError),
        ("1", T.ByteType(), TypeError), (1.0, T.ByteType(), TypeError),
        (2**15, T.ShortType(), ValueError), (2**31, T.IntegerType(), ValueError),
        (1, T.FloatType(), TypeError), (1, T.DoubleType(), TypeError),
        (1.0, T.DecimalType(), TypeError), ("1.0", T.DecimalType(), TypeError),
        (1, T.BinaryType(), TypeError), ("2000-01-02", T.DateType(), TypeError),
        ("23:59:59", T.TimeType(), TypeError), (946811040, T.TimestampType(), TypeError),
        (["1", None], T.ArrayType(T.StringType(), False), ValueError),
        ([1, "2"], T.ArrayType(T.IntegerType()), TypeError),
        ({"a": 1}, T.MapType(T.IntegerType(), T.IntegerType()), TypeError),
        ({"a": "1"}, T.MapType(T.StringType(), T.IntegerType()), TypeError),
        ({"a": None}, T.MapType(T.StringType(), T.IntegerType(), False), ValueError),
        ({"s": "a", "i": "1"}, schema, TypeError), (Row(s="a"), schema, ValueError),
        (Row(s="a", i="1"), schema, TypeError), (["a"], schema, ValueError),
        (["a", "1"], schema, TypeError), (MyObj(s="a", i="1"), schema, TypeError),
        (MyObj(s=None, i="1"), schema, ValueError),
    ]
    return success, failure


def test_type_verifiers_take_and_reject_the_values_of_pyspark():
    # As Apache Spark's DataTypeVerificationTests: _make_type_verifier takes the values of each
    # type, including Rows, and raises the errors of PySpark for the others with field names.
    from pyspark.errors import PySparkTypeError, PySparkValueError
    from pyspark.sql.types import _make_type_verifier

    success, failure = _type_verifier_cases()
    for obj, data_type in success:
        _make_type_verifier(data_type, nullable=False)(obj)
    for obj, data_type, error in failure:
        with pytest.raises(error):
            _make_type_verifier(data_type, nullable=False)(obj)
    for data_type in (T.IntegerType(), T.StringType(), T.StructType([])):
        _make_type_verifier(data_type, nullable=True)(None)
    with pytest.raises(PySparkValueError) as e:
        _make_type_verifier(T.StringType(), nullable=False, name="test_name")(None)
    assert e.value.getCondition() == "FIELD_NOT_NULLABLE_WITH_NAME"
    schema = T.StructType([T.StructField("a", T.StructType([T.StructField("b", T.IntegerType())]))])
    with pytest.raises(PySparkTypeError) as e:
        _make_type_verifier(schema)([["data"]])
    assert e.value.getCondition() == "FIELD_DATA_TYPE_UNACCEPTABLE_WITH_NAME"
    assert e.value.getMessageParameters()["field_name"] == "field b in field a"


def test_types_of_python_objects_are_inferred_merged_and_converted_as_pyspark():
    # As PySpark's _infer_type, _infer_schema, _merge_type and _create_converter, of the
    # values of each type, including nested Rows.
    import datetime
    import decimal

    from pyspark.errors import PySparkTypeError
    from pyspark.sql.types import (
        _create_converter,
        _infer_schema,
        _infer_type,
        _merge_type,
        _need_converter,
    )

    values = [
        (None, T.NullType()), (True, T.BooleanType()), (1, T.LongType()), (1.5, T.DoubleType()),
        ("s", T.StringType()), (b"b", T.BinaryType()),
        (decimal.Decimal("1.50"), T.DecimalType(38, 18)), (datetime.date(2000, 1, 1), T.DateType()),
        (datetime.datetime(2000, 1, 1), T.TimestampType()), (datetime.time(1, 2), T.TimeType()),
        (datetime.timedelta(1), T.DayTimeIntervalType()),
    ]
    for value, data_type in values:
        assert _infer_type(value) == data_type
    assert _infer_type([1, None]) == T.ArrayType(T.LongType())
    assert _infer_type([None, 1], infer_array_from_first_element=True) == T.ArrayType(
        T.NullType()
    )
    assert _infer_type({"a": {"b": 1}}, infer_dict_as_struct=True) == T.StructType(
        [T.StructField("a", T.StructType([T.StructField("b", T.LongType())]))]
    )
    assert _infer_type(datetime.datetime(2000, 1, 1), prefer_timestamp_ntz=True) == (
        T.TimestampNTZType()
    )
    assert _infer_type(Row(a=[Row(b=1)])) == T.StructType(
        [T.StructField("a", T.ArrayType(T.StructType([T.StructField("b", T.LongType())])))]
    )

    class Obj:
        def __init__(self):
            self.b, self.a = "x", 1

    assert _infer_schema(Obj()).names == ["a", "b"]
    assert _infer_schema((1, 2), names=["x"]).names == ["x", "_2"]
    with pytest.raises(PySparkTypeError) as e:
        _infer_schema(1)
    assert e.value.getCondition() == "CANNOT_INFER_SCHEMA_FOR_TYPE"

    a = T.StructType([T.StructField("f", T.ArrayType(T.NullType()))])
    b = T.StructType([T.StructField("f", T.ArrayType(T.LongType()))])
    assert _merge_type(a, b) == b and _merge_type(T.NullType(), T.LongType()) == T.LongType()
    assert _merge_type(
        T.MapType(T.StringType(), T.NullType()), T.MapType(T.StringType(), T.LongType())
    ) == T.MapType(T.StringType(), T.LongType())
    strings = T.StructType([T.StructField("f", T.ArrayType(T.StringType()))])
    assert _merge_type(b, strings) == strings
    with pytest.raises(PySparkTypeError) as e:
        _merge_type(b, T.StructType([T.StructField("f", T.ArrayType(T.DateType()))]))
    assert e.value.getCondition() == "CANNOT_MERGE_TYPE"

    struct = T.StructType(
        [T.StructField("m", T.MapType(T.StringType(), T.StringType())),
         T.StructField("s", T.StructType([T.StructField("x", T.LongType())]))]
    )
    assert _need_converter(struct) and not _need_converter(T.LongType())
    convert = _create_converter(struct)
    assert convert(Row(m={"k": "v"}, s=Row(x=1))) == ({"k": "v"}, (1,))
    assert convert({"m": None, "s": {"x": 2}}) == (None, (2,))
    with pytest.raises(PySparkTypeError) as e:
        convert(1)
    assert e.value.getCondition() == "UNSUPPORTED_DATA_TYPE"




def test_unparsed_datatype_pickle_roundtrip():
    # The UnparsedDataType of pyspark.sql.connect.types pickles of its DDL string, as its JSON
    # raises. Its JSON form is the core's only: a JSON type string never parses to it, as PySpark's
    # `_parse_datatype_json_value` parses none to it.
    from pyspark.sql.connect.types import UnparsedDataType

    t = UnparsedDataType("some_ddl")
    assert isinstance(t, UnparsedDataType) and t.data_type_string == "some_ddl"
    r = pickle.loads(pickle.dumps(t))
    assert r == t and repr(r) == "UnparsedDataType('some_ddl')"


def test_user_defined_type_pickle_roundtrip():
    import sys
    import types as _pytypes

    mod = _pytypes.ModuleType("_udt_pickle_mod")
    sys.modules["_udt_pickle_mod"] = mod
    src = (
        "from pyspark.sql.types import UserDefinedType, ArrayType, DoubleType\n"
        "class PointUDT(UserDefinedType):\n"
        "    @classmethod\n"
        "    def sqlType(cls): return ArrayType(DoubleType(), False)\n"
        "    @classmethod\n"
        "    def module(cls): return '_udt_pickle_mod'\n"
    )
    exec(compile(src, "_udt_pickle_mod", "exec"), mod.__dict__)
    try:
        u = mod.PointUDT()
        assert isinstance(pickle.loads(pickle.dumps(u)), mod.PointUDT)
        st = T.StructType([
            T.StructField("p", u), T.StructField("g", T.GeometryType(4326)),
        ])
        r = pickle.loads(pickle.dumps(st))
        assert isinstance(r.fields[0].dataType, mod.PointUDT)
        assert r.fields[1].dataType == T.GeometryType(4326)
    finally:
        del sys.modules["_udt_pickle_mod"]


