def test_sql_functions_is_an_attribute_once_pyspark_sql_is_imported():
    # As PySpark's, whose modules import pyspark.sql.functions, `functions` is an attribute of
    # pyspark.sql after `import pyspark.sql` alone, and of pyspark.sql through pyspark. A new
    # process keeps the modules that this test process has imported from hiding a missing one.
    import subprocess
    import sys
    import textwrap

    result = subprocess.run([sys.executable, "-c", textwrap.dedent("""
        import pyspark
        assert "functions" in dir(pyspark.sql), sorted(dir(pyspark.sql))
        assert pyspark.sql.functions.__name__ == "pyspark.sql.functions"
        print(repr(pyspark.sql.functions.col("a")))
    """)], capture_output=True, text=True)
    assert result.returncode == 0, result.stdout + result.stderr
    assert result.stdout.strip() == "Column<'a'>", result.stdout


def test_data_types_have_their_attributes_type_names_and_singletons_as_pyspark():
    # As PySpark's: the attributes of the parameters of the types, typeName as a classmethod of
    # the name of the class, INVALID_TYPENAME_CALL of StructField.typeName, and the types of
    # DataTypeSingleton, of which every call returns the one instance.
    from pyspark.errors import PySparkTypeError

    assert T.StringType("UTF8_LCASE").collation == "UTF8_LCASE"
    assert T.StringType().collation == "UTF8_BINARY"
    assert (T.CharType(3).length, T.VarcharType(4).length, T.TimeType(3).precision) == (3, 4, 3)
    interval = T.DayTimeIntervalType(T.DayTimeIntervalType.HOUR, T.DayTimeIntervalType.SECOND)
    assert (interval.startField, interval.endField) == (1, 3)
    assert (T.YearMonthIntervalType().startField, T.YearMonthIntervalType().endField) == (0, 1)
    assert T.DecimalType(10, 2).hasPrecisionInfo is True
    for cls, name in ((T.DataType, "data"), (T.AtomicType, "atomic"), (T.IntegerType, "integer"),
                      (T.DayTimeIntervalType, "daytimeinterval"), (T.StructType, "struct"),
                      (T.NullType, "void"), (T.TimestampNTZType, "timestamp_ntz"),
                      (T.CalendarIntervalType, "interval")):
        assert cls.typeName() == name
    assert T.CharType(3).typeName() == "char"

    class MyType(T.DataType):
        pass

    assert MyType.typeName() == MyType().typeName() == "my"
    with pytest.raises(PySparkTypeError) as e:
        T.StructField("a", T.IntegerType()).typeName()
    assert e.value.getCondition() == "INVALID_TYPENAME_CALL"
    for cls in (T.NullType, T.ByteType, T.IntegerType, T.LongType, T.DoubleType, T.BinaryType,
                T.DateType, T.TimestampNTZType, T.CalendarIntervalType):
        assert cls() is cls()
    assert T.StringType() is not T.StringType()
    assert T.ArrayType(T.IntegerType()).elementType is T.IntegerType()




def test_user_defined_type_eq_and_hash():
    class PointUDT(T.UserDefinedType):
        @classmethod
        def sqlType(cls):
            return T.ArrayType(T.DoubleType(), False)

    class OtherUDT(T.UserDefinedType):
        @classmethod
        def sqlType(cls):
            return T.ArrayType(T.DoubleType(), False)

    # pyspark: same class and equal __dict__ -> equal; a different UDT class (even with
    # the same sqlType) or a non-UDT type -> unequal.
    assert PointUDT() == PointUDT()
    assert hash(PointUDT()) == hash(PointUDT())
    assert PointUDT() != OtherUDT()
    assert PointUDT() != T.ArrayType(T.DoubleType(), False)
    assert T.ArrayType(T.DoubleType(), False) != PointUDT()
    assert T.LongType() != PointUDT()
    u = PointUDT()
    u.extra = 1
    assert u != PointUDT()


# --------------------------------------------------------------------------- StorageLevel

def test_storage_level():
    from pyspark.storagelevel import StorageLevel
    sl = StorageLevel(True, True, False, False, 2)
    assert sl.useDisk and sl.useMemory and sl.replication == 2
    assert "Disk" in str(sl) and "Replicated" in str(sl)
    assert repr(sl).startswith("StorageLevel(")
    assert StorageLevel.MEMORY_ONLY == StorageLevel(False, True, False, False, 1)
    assert StorageLevel.DISK_ONLY != StorageLevel.MEMORY_ONLY


def test_storage_levels_keep_their_values_as_pyspark():
    # As PySpark's StorageLevel, a plain Python class: its constructor keeps the values as they
    # are, unchecked, in attributes that may be set; repr shows the str() of each, str the names
    # of the flags that are true, and == compares the values with those of another
    # StorageLevel, and is False of anything else; it is unhashable, a subclass may override
    # __init__, and an instance pickles, at every protocol, and copies by its attributes. The
    # class shows the signature of its __init__.
    import copy
    import inspect

    from pyspark.storagelevel import StorageLevel

    level = StorageLevel(1.5, "x", None, 0, 2**40)
    assert vars(level) == {"useDisk": 1.5, "useMemory": "x", "useOffHeap": None,
                           "deserialized": 0, "replication": 2**40}
    assert repr(level) == "StorageLevel(1.5, x, None, 0, 1099511627776)"
    assert str(level) == "Disk Memory Serialized 1099511627776x Replicated"
    level.useMemory, level.replication = 0, "2"
    assert (repr(level), str(level)) == ("StorageLevel(1.5, 0, None, 0, 2)",
                                         "Disk Serialized 2x Replicated")
    assert StorageLevel(useDisk=1, useMemory=0, useOffHeap=0, deserialized=0).replication == 1
    assert StorageLevel(1, 0, 0, 0) == StorageLevel.DISK_ONLY
    assert StorageLevel(1, 0, 0, 0, 2.0) == StorageLevel.DISK_ONLY_2
    assert StorageLevel(1, 0, 0, 0, 3) != StorageLevel.DISK_ONLY_2
    assert (StorageLevel.DISK_ONLY == (True, False, False, False, 1)) is False
    assert StorageLevel.DISK_ONLY != 1
    assert StorageLevel.OFF_HEAP is StorageLevel.OFF_HEAP
    assert repr(StorageLevel.MEMORY_AND_DISK_DESER) == "StorageLevel(True, True, False, True, 1)"
    assert str(StorageLevel.OFF_HEAP) == "Disk Memory OffHeap Serialized 1x Replicated"
    with pytest.raises(TypeError, match="unhashable type"):
        hash(StorageLevel.DISK_ONLY)
    with pytest.raises(TypeError, match=r"__init__\(\) missing 1 required positional argument: "
                                        r"'deserialized'$"):
        StorageLevel(True, True, True)
    parameters = inspect.signature(StorageLevel).parameters
    assert list(parameters) == ["useDisk", "useMemory", "useOffHeap", "deserialized",
                                "replication"]
    assert parameters["replication"].default == 1

    class Replicated(StorageLevel):
        def __init__(self, replication):
            super().__init__(True, False, False, False, replication)

    assert Replicated(2) == StorageLevel.DISK_ONLY_2 and isinstance(Replicated(2), StorageLevel)
    pickles = [pickle.loads(pickle.dumps(level, protocol))
               for protocol in range(pickle.HIGHEST_PROTOCOL + 1)]
    for copied in (*pickles, copy.copy(level), copy.deepcopy(level)):
        assert type(copied) is StorageLevel and copied is not level
        assert vars(copied) == vars(level)
    copied = copy.copy(Replicated(3))
    assert type(copied) is Replicated and copied == StorageLevel.DISK_ONLY_3


