def test_storage_levels_are_converted_as_pyspark(mock_connect):
    # As PySpark's storage_level_to_proto, of persist, localCheckpoint and cacheTable: it asserts
    # a StorageLevel, a bare AssertionError of anything else, reads its attributes, and passes
    # them to pb2.StorageLevel(...), whose default (upb) backend converts them in their order:
    # None is unset, a flag is the truth of an int, of a NumPy bool too, and the int32
    # replication refuses a bool and an int beyond its range, before any request. cacheTable
    # converts a storage level that is true, so another false value is unset, as None is.
    from pyspark.storagelevel import StorageLevel

    spark, service = mock_connect
    df = spark.range(1)

    def sent_level():
        # AnalyzePlanRequest.persist=14 -> Persist.storage_level=2: use_disk=1, use_memory=2,
        # use_off_heap=3, deserialized=4 and replication=5, where false and 0 are not sent.
        persist = parse_message(parse_message(service.analyze_requests[-1])[14][0])
        return parse_message(persist[2][0])

    df.persist(StorageLevel(2, np.int64(1), None, np.bool_(False), np.int32(3)))
    assert sent_level() == {1: [1], 2: [1], 5: [3]}
    df.persist(StorageLevel(-1, 0, 2**62, True, None))
    assert sent_level() == {1: [1], 3: [1], 4: [1]}

    class Level:
        useDisk, useMemory, useOffHeap, deserialized, replication = True, False, False, False, 1

    # The attributes are read before any of them is converted.
    unread = StorageLevel(1.5, True, True, True)
    del unread.replication
    boolean = "Field spark.connect.StorageLevel.replication: Expected an int, got a boolean."
    requests = (len(service.analyze_requests), len(service.execute_requests))
    for level, error, message in [
            (Level(), AssertionError, "^$"),
            ((True, False, False, False, 1), AssertionError, "^$"),
            (unread, AttributeError, "object has no attribute 'replication'$"),
            (StorageLevel(1.5, True, True, True), TypeError,
             "^'float' object cannot be interpreted as an integer$"),
            (StorageLevel(True, "x", True, True, True), TypeError,
             "^'str' object cannot be interpreted as an integer$"),
            (StorageLevel(True, True, 2**63, True), OverflowError,
             "^Python int too large to convert to C long$"),
            (StorageLevel(True, True, True, np.array([1])), TypeError,
             r"^\[1\] has type ndarray, but expected one of: bool$"),
            (StorageLevel(True, True, None, True, False), TypeError, f"^{re.escape(boolean)}$"),
            (StorageLevel(True, True, True, True, 2**31), ValueError,
             "^Value out of range: 2147483648$"),
            (StorageLevel(True, True, True, True, 1.0), TypeError,
             "^'float' object cannot be interpreted as an integer$")]:
        for call in (lambda: df.persist(level),
                     lambda: df.localCheckpoint(storageLevel=level),
                     lambda: spark.catalog.cacheTable("t", level)):
            with pytest.raises(error, match=message) as e:
                call()
            assert type(e.value) is error
    assert (len(service.analyze_requests), len(service.execute_requests)) == requests
    for level in (None, 0, "", False):
        spark.catalog.cacheTable("t", level)
        # Relation.catalog=200 -> Catalog.cache_table=19: table_name=1 and storage_level=2.
        assert _sent_catalog(service.execute_requests[-1], 19) == {1: [b"t"]}
    spark.catalog.cacheTable("t", StorageLevel(0, 1, 0, 0))
    assert parse_message(_sent_catalog(service.execute_requests[-1], 19)[2][0]) == {2: [1], 5: [1]}


def test_persist_of_none_sends_no_storage_level_as_pyspark(mock_connect):
    # As PySpark's persist, whose omitted storageLevel is its default MEMORY_AND_DISK_DESER,
    # while its client sends no storage level for a given None (`if kwargs.get("storage_level",
    # None) is not None`), so that the server caches at its spark.sql.defaultCacheStorageLevel.
    from pyspark.storagelevel import StorageLevel

    spark, service = mock_connect
    df = spark.range(1)

    def sent():
        # AnalyzePlanRequest.persist=14 -> Persist.storage_level=2: use_disk=1, use_memory=2,
        # deserialized=4 and replication=5, where false and 0 are not sent.
        persist = parse_message(parse_message(service.analyze_requests[-1])[14][0])
        return parse_message(persist[2][0]) if 2 in persist else None

    assert df.persist() is df and sent() == {1: [1], 2: [1], 4: [1], 5: [1]}
    for call in (lambda: df.persist(None), lambda: df.persist(storageLevel=None)):
        assert call() is df and sent() is None
    df.persist(StorageLevel.DISK_ONLY)
    assert sent() == {1: [1], 5: [1]}


# --------------------------------------------------------------------------- session builder

def test_session_builder_chaining_offline():
    from pyspark.sql import SparkSession
    b = SparkSession.builder
    assert type(b).__name__ == "Builder"
    # Chainable, no server contacted until getOrCreate: each method returns the builder.
    b2 = b.remote("sc://localhost:15002").appName("x").config("k", "v")
    assert b2 is b


def test_sessions_are_got_or_created_as_pyspark():
    # As PySpark's builder: getOrCreate() returns the active session of the thread, or else
    # the default session, whatever the URL, and creates one when there is neither, of the
    # URL of remote() or else of SPARK_REMOTE; create() makes a new one, which is the default
    # and the active session only when they are not set; and stop() unsets them. In a new
    # interpreter, which has no default session.
    import subprocess
    import sys

    subprocess.run([sys.executable, "-c", """
import os
import threading

from pyspark.errors import PySparkRuntimeError
from pyspark.sql import SparkSession

def condition(call):
    try:
        call()
    except PySparkRuntimeError as error:
        return error.getCondition()
    raise AssertionError("no error")

os.environ.pop("SPARK_REMOTE", None)
assert condition(SparkSession.builder.getOrCreate) == "CONNECT_URL_NOT_SET"
assert condition(SparkSession.active) == "NO_ACTIVE_OR_DEFAULT_SESSION"

first = SparkSession.builder.remote("sc://localhost:1").getOrCreate()
assert SparkSession.builder.remote("sc://localhost:2").getOrCreate() is first
assert SparkSession.getActiveSession() is first and SparkSession.active() is first

seen = {}
def other_thread():
    seen["active"] = SparkSession.getActiveSession()
    seen["default"] = SparkSession.active()
    seen["got"] = SparkSession.builder.remote("sc://localhost:1").getOrCreate()
thread = threading.Thread(target=other_thread)
thread.start()
thread.join()
assert seen == {"active": None, "default": first, "got": first}, seen

created = SparkSession.builder.remote("sc://localhost:1").create()
assert created is not first and SparkSession.getActiveSession() is first

# No server at localhost:1 to release on: a release would wait for the retries of a refused port.
first.release_session_on_close = False
first.stop()
assert SparkSession.getActiveSession() is None
assert condition(SparkSession.active) == "NO_ACTIVE_OR_DEFAULT_SESSION"
os.environ["SPARK_REMOTE"] = "sc://localhost:1"
again = SparkSession.builder.getOrCreate()
assert again is not first and again is not created
assert SparkSession.getActiveSession() is again and SparkSession.active() is again
# The sessions left open would wait on the retries of their refused ports at exit: close them
# without a release, as the release of the first one was not sent either.
for session in (again, created):
    session.release_session_on_close = False
    session.stop()
"""], check=True)


def test_conf_warns_the_warnings_of_the_server_and_checks_its_arguments_as_pyspark(mock_connect):
    # As PySpark's RuntimeConf: set, unset and the options of the builder warn each warning
    # of the server; set sends a bool as "true" or "false", an int as its str(), and None as no
    # value, and raises the TypeError of protobuf for another value; get raises
    # NOT_EXPECTED_TYPE of a key, and of a default other than None, that is not a str.
    import warnings

    from pyspark.errors import PySparkTypeError
    from pyspark.sql import SparkSession

    spark, service = mock_connect
    service.config_warnings = ["one", "two"]
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        spark.conf.set("k", True)
        spark.conf.unset("k")
        builder = SparkSession.builder.remote("sc://localhost:1").config("spark.sql.k", "v")
        assert builder.getOrCreate() is spark
    assert [(w.category, str(w.message)) for w in caught] == [
        (UserWarning, "one"),
        (UserWarning, "two"),
    ] * 3
    assert service.unset_confs == [["k"]]
    service.config_warnings = []
    for value in [1, "x", None, b"y"]:
        spark.conf.set("v", value)
    assert [pairs for pairs, _ in service.set_confs] == [
        [("k", "true")],
        [("spark.sql.k", "v")],
        [("v", "1")],
        [("v", "x")],
        [("v", None)],
        [("v", "y")],
    ]
    # As protobuf's default (upb) backend, a value of another type is the TypeError of its string
    # field, and bytes that are not UTF-8 the UnicodeDecodeError of their decoding.
    for value in [1.5, [1], object(), bytearray(b"y")]:
        with pytest.raises(TypeError) as e:
            spark.conf.set("v", value)
        assert str(e.value) == "bad argument type for built-in operation"
    with pytest.raises(UnicodeDecodeError) as e:
        spark.conf.set("v", b"\xff")
    assert str(e.value) == "'utf-8' codec can't decode byte 0xff in position 0: invalid start byte"
    assert len(service.set_confs) == 6
    for args, arg_name, arg_type in [
        ((1,), "key", "int"),
        ((None,), "key", "NoneType"),
        (("k", 1), "default", "int"),
        (("k", True), "default", "bool"),
    ]:
        with pytest.raises(PySparkTypeError) as e:
            spark.conf.get(*args)
        assert e.value.getCondition() == "NOT_EXPECTED_TYPE"
        assert e.value.getMessageParameters() == {
            "arg_name": arg_name,
            "expected_type": "str",
            "arg_type": arg_type,
        }


