def test_collected_rows_take_the_names_of_the_schema_of_the_result_as_pyspark(mock_connect):
    # As PySpark Connect's, which builds the rows by the schema of the result: the fields of
    # nested structs have the names of the schema, which keep the duplicate names that the
    # server's Arrow data numbers; collect raises for a calendar interval, whose Arrow type
    # from_arrow_schema does not convert, while toLocalIterator does not check it.
    import pyarrow as pa
    from _mock_connect_server import data_type_proto
    from pyspark.errors import PySparkTypeError

    spark, service = mock_connect

    def respond(schema, table):
        sink = pa.BufferOutputStream()
        with pa.ipc.new_stream(sink, table.schema) as writer:
            writer.write_table(table)
        # ExecutePlanResponse.schema=7 and arrow_batch=2: ArrowBatch.row_count=1, data=2.
        service.execute_payload = message_field(7, schema) + message_field(
            2, varint_field(1, table.num_rows) + message_field(2, sink.getvalue().to_pybytes()))

    field = {"name": "a", "type": "integer", "nullable": True, "metadata": {}}
    pair = {"type": "struct", "fields": [field, field]}
    respond(data_type_proto({"type": "struct", "fields": [
        {"name": "v", "type": pair, "nullable": True, "metadata": {}}]}),
        pa.table({"v": pa.array([{"a_0": 1, "a_1": 2}])}))
    for rows in (spark.range(1).collect(), list(spark.range(1).toLocalIterator())):
        assert rows[0].v.__fields__ == ["a", "a"]
        assert tuple(rows[0].v) == (1, 2)
    # Struct.fields=1, StructField: name=1, data_type=2 (DataType.calendar_interval=17).
    respond(message_field(21, message_field(1, message_field(1, "v") + message_field(
        2, message_field(17, b"")))),
        pa.table({"v": pa.array([(1, 2, 3)], pa.month_day_nano_interval())}))
    with pytest.raises(PySparkTypeError) as e:
        spark.range(1).collect()
    assert e.value.getCondition() == "UNSUPPORTED_DATA_TYPE_FOR_ARROW_CONVERSION"
    assert e.value.getMessageParameters() == {"data_type": "month_day_nano_interval"}


def test_collect_of_a_string_that_is_not_utf8_raises_as_pyspark(mock_connect):
    # As PySpark's: a result is converted column by column, so the first invalid string of the
    # first column raises the UnicodeDecodeError of Python's decoder, whether it is a top-level
    # string or nested in an array.
    import pyarrow as pa
    from _mock_connect_server import data_type_proto

    spark, service = mock_connect

    def strings(*values):
        # The bytes of the values as a string array: pyarrow does not check that they are UTF-8.
        offsets, total = [0], 0
        for value in values:
            total += len(value)
            offsets.append(total)
        return pa.Array.from_buffers(pa.string(), len(values), [
            None, pa.array(offsets, pa.int32()).buffers()[1],
            pa.py_buffer(b"".join(values))])

    def respond(schema, table):
        sink = pa.BufferOutputStream()
        with pa.ipc.new_stream(sink, table.schema) as writer:
            writer.write_table(table)
        # ExecutePlanResponse.schema=7 and arrow_batch=2: ArrowBatch.row_count=1, data=2.
        service.execute_payload = message_field(7, schema) + message_field(
            2, varint_field(1, table.num_rows) + message_field(2, sink.getvalue().to_pybytes()))

    def python_error(value):
        with pytest.raises(UnicodeDecodeError) as e:
            value.decode("utf-8")
        return e.value

    def string_field(name):
        return {"name": name, "type": "string", "nullable": True, "metadata": {}}

    respond(data_type_proto({"type": "struct", "fields": [string_field("s")]}),
            pa.table({"s": strings(b"a", b"\xc3")}))
    with pytest.raises(UnicodeDecodeError) as e:
        spark.range(1).collect()
    assert type(e.value) is UnicodeDecodeError
    assert str(e.value) == str(python_error(b"\xc3"))

    respond(data_type_proto({"type": "struct", "fields": [{
        "name": "a", "type": {"type": "array", "elementType": "string", "containsNull": True},
        "nullable": True, "metadata": {}}]}),
        pa.table({"a": pa.ListArray.from_arrays([0, 1, 2], strings(b"a", b"\xc3"))}))
    with pytest.raises(UnicodeDecodeError) as e:
        spark.range(1).collect()
    assert str(e.value) == str(python_error(b"\xc3"))

    # Row 0 of column b is invalid too, but PySpark raises for the first column, at its row 1.
    respond(data_type_proto({"type": "struct", "fields": [
        string_field("a"), string_field("b")]}),
        pa.table({"a": strings(b"a", b"\xc3"), "b": strings(b"\xc4", b"b")}))
    with pytest.raises(UnicodeDecodeError) as e:
        spark.range(1).collect()
    assert str(e.value) == str(python_error(b"\xc3"))

    respond(data_type_proto({"type": "struct", "fields": [string_field("s")]}),
            pa.table({"s": strings(b"a")}))
    assert spark.range(1).collect() == [Row(s="a")]
    assert len(list(spark.range(1).toLocalIterator())) == 1

def test_malformed_arrow_chunks_raise_spark_connect_exception_as_pyspark(mock_connect):
    # As PySpark Connect's ExecuteAndFetchAsIterator: a chunk that is not the next one of its
    # batch, or a batch that does not start where the rows before it end, raises a
    # SparkConnectException of the message of the reference client, with no error class.
    from pyspark.errors.exceptions.connect import SparkConnectException

    spark, service = mock_connect

    def batch(index, num_chunks, data, start_offset=None):
        # ExecutePlanResponse.arrow_batch=2: ArrowBatch.row_count=1, data=2, start_offset=3,
        # chunk_index=4, num_chunks_in_batch=5. A batch that is not chunked has no chunk fields.
        fields = varint_field(1, 1) + message_field(2, data)
        if start_offset is not None:
            fields += varint_field(3, start_offset)
        if num_chunks is not None:
            fields += varint_field(4, index) + varint_field(5, num_chunks)
        return message_field(2, fields)

    cases = [
        (
            [batch(0, 3, b"a", start_offset=0), batch(2, 3, b"c")],
            "Expected chunk index 1 of the arrow batch but got 2.",
        ),
        (
            [batch(1, 2, b"b", start_offset=0)],
            "Expected chunk index 0 of the next arrow batch but got 1.",
        ),
        (
            [batch(0, None, b"a", start_offset=5)],
            "Expected arrow batch to start at row offset 0 in results, but received arrow batch "
            "starting at offset 5.",
        ),
    ]
    for payloads, message in cases:
        service.execute_payloads = payloads
        with pytest.raises(SparkConnectException) as e:
            spark.range(1).collect()
        assert type(e.value) is SparkConnectException
        assert str(e.value) == message
        assert e.value.getCondition() is None
    service.execute_payloads = None


def test_tags_are_those_of_each_thread_as_pyspark(mock_connect):
    # As PySpark's: the tags of addTag are those of the current thread, of a set of getTags,
    # which the operations that the thread starts carry; a new thread starts without tags. The
    # set of getTags is the live one, which the later tags change, as PySpark's.
    import threading

    spark, service = mock_connect

    def sent_tags():
        # ExecutePlanRequest.tags=7.
        return sorted(tag.decode() for tag in parse_message(service.execute_requests[-1]).get(7, []))

    spark.addTag("main")
    seen = {}

    def child():
        seen["before"] = set(spark.getTags())
        live = spark.getTags()
        spark.addTag("child")
        seen["after"] = spark.getTags()
        assert seen["after"] is live
        spark.range(1).collect()
        seen["sent"] = sent_tags()

    thread = threading.Thread(target=child)
    thread.start()
    thread.join()
    try:
        assert seen == {"before": set(), "after": {"child"}, "sent": ["child"]}
        assert spark.getTags() == {"main"}
        spark.range(1).collect()
        assert sent_tags() == ["main"]
    finally:
        spark.clearTags()


def test_tags_that_utf8_cannot_encode_fail_the_executions_that_carry_them_as_pyspark(
    mock_connect,
):
    # As PySpark's `addTag`, which checks the tag with `"," in tag` and `len(tag)`, and keeps it
    # in the set of the tags of the thread: a str that UTF-8 cannot encode is a tag, of getTags,
    # and each execution that carries it fails with the UnicodeEncodeError of its encoding, when
    # its request is built after its plan, until removeTag removes it. A schema, whose request
    # has no tags, is analyzed. An int or bytes raises the TypeError of `in`, and a list that of
    # the set, which does not hash it.
    from pyspark.errors import PySparkValueError
    from pyspark.sql import functions as F

    spark, service = mock_connect
    bad = "a\ud800b"
    message = "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed"
    spark.addTag(bad)
    try:
        assert spark.getTags() == {bad}
        with pytest.raises(UnicodeEncodeError) as error:
            spark.range(1).collect()
        assert str(error.value) == message
        assert service.execute_requests == []
        # The plan is built first, as PySpark builds it before the request.
        with pytest.raises(UnicodeEncodeError) as error:
            spark.range(1).select(F.col("b\ud801")).collect()
        assert "'\\ud801' in position 1" in str(error.value)
        assert spark.range(1).schema is not None
    finally:
        spark.removeTag(bad)
    assert spark.getTags() == set()
    spark.range(1).collect()
    assert len(service.execute_requests) == 1
    for tag, message in [
        (5, "argument of type 'int' is not iterable"),
        (b"x", "a bytes-like object is required, not 'str'"),
        (["x"], "unhashable type: 'list'"),
    ]:
        for method in (spark.addTag, spark.removeTag):
            with pytest.raises(TypeError) as error:
                method(tag)
            assert str(error.value) == message
    with pytest.raises(PySparkValueError) as error:
        spark.addTag("a,\ud800")
    assert error.value.getCondition() == "VALUE_ALLOWED"


def test_session_builders_set_their_options_and_validate_their_urls_as_pyspark(monkeypatch):
    # As PySpark's SparkSession.Builder: SparkSession.builder is a new builder of each access,
    # whose methods set their option on it and return it, and a master with a remote raises
    # CANNOT_CONFIGURE_SPARK_CONNECT_MASTER, also of MASTER or SPARK_REMOTE.
    from pyspark.errors import PySparkRuntimeError
    from pyspark.sql import SparkSession

    monkeypatch.delenv("SPARK_REMOTE", raising=False)
    monkeypatch.delenv("MASTER", raising=False)
    assert SparkSession.builder is not SparkSession.builder
    builder = SparkSession.builder
    assert type(builder).__qualname__ == "SparkSession.Builder"
    assert builder.config("k", "v") is builder and builder.appName("app") is builder
    assert builder.master("local[2]") is builder
    for make in (lambda: SparkSession.builder.master("local").remote("sc://host:1"),
                 lambda: SparkSession.builder.remote("sc://host:1").master("local"),
                 lambda: SparkSession.builder.config(
                     map={"spark.master": "local", "spark.remote": "sc://host:1"})):
        with pytest.raises(PySparkRuntimeError) as e:
            make()
        assert e.value.getCondition() == "CANNOT_CONFIGURE_SPARK_CONNECT_MASTER"
        assert e.value.getMessageParameters() == {
            "master_url": "local", "connect_url": "sc://host:1"}
    monkeypatch.setenv("SPARK_REMOTE", "sc://env:15002")
    with pytest.raises(PySparkRuntimeError) as e:
        SparkSession.builder.master("local")
    assert e.value.getMessageParameters()["connect_url"] == "sc://env:15002"
    monkeypatch.setenv("SPARK_LOCAL_REMOTE", "1")
    with pytest.raises(PySparkRuntimeError) as e:
        SparkSession.builder.remote("sc://other:1")
    assert e.value.getCondition() == "CANNOT_CONFIGURE_SPARK_CONNECT"
    SparkSession.builder.remote("local[2]")




def test_dataframes_give_back_their_session_object_as_pyspark(offline_spark):
    # As PySpark: the DataFrames of a session, its streams and its client give back the session
    # object itself, and two sessions do not mix. The registry holds the session objects
    # weakly, so a session that is dropped is freed.
    import gc
    import weakref

    def check(actual, expected):
        # Not an assert: pytest reprs a DataFrame in a failed assert, which asks the server.
        if actual is not expected:
            raise AssertionError("not the session object that PySpark gives back")

    spark = offline_spark
    df = spark.range(2)
    check(df.sparkSession, spark)
    check(df._session, spark)
    check(df.select("id").sparkSession, spark)
    check(df.groupBy("id").count().sparkSession, spark)
    check(df.na.drop().sparkSession, spark)
    check(spark.read.format("rate").load().sparkSession, spark)
    check(spark.udf.sparkSession, spark)
    check(spark.udtf.sparkSession, spark)
    check(spark.dataSource.sparkSession, spark)
    assert df.sparkSession == spark
    check(df.sparkSession.streams, spark.streams)
    check(df.sparkSession.client, spark.client)
    other = spark.newSession()
    check(other.range(1).sparkSession, other)
    if other.range(1).sparkSession is spark:
        raise AssertionError("two sessions mixed")
    check(other.range(1).sparkSession.streams, other.streams)
    if other.streams is spark.streams:
        raise AssertionError("two sessions share their streams")
    ref = weakref.ref(other)
    del other
    gc.collect()
    assert ref() is None
    check(df.sparkSession, spark)
    # Two sessions made apart, of the same session ID, are two objects, each that of its own
    # DataFrames. create() sets the default session, so this runs in a process of its own.
    import subprocess
    import sys

    subprocess.run([sys.executable, "-c", """
import uuid
from pyspark.sql import SparkSession
url = f"sc://localhost:1/;session_id={uuid.uuid4()}"
first = SparkSession.builder.remote(url).create()
second = SparkSession.builder.remote(url).create()
assert first is not second
assert first.range(1).sparkSession is first
assert second.range(1).sparkSession is second
# Closed without a release: no server listens at localhost:1, and the exit would retry it.
for session in (first, second):
    session.release_session_on_close = False
    session.stop()
"""], check=True)


