def test_sessions_raise_the_errors_of_their_arguments_as_pyspark(mock_connect, tmp_path):
    # As PySpark Connect's: the errors of the tags of addTag and removeTag, of the name of
    # table, of the paths of copyFromLocalToFs, and of the JVM attributes of a classic session.
    from pyspark.errors import PySparkAttributeError, PySparkTypeError, PySparkValueError

    spark, _ = mock_connect
    for method in (spark.addTag, spark.removeTag):
        for tag, condition in (("", "VALUE_NOT_NON_EMPTY_STR"), ("a,b", "VALUE_ALLOWED"),
                               (None, "CANNOT_BE_NONE")):
            with pytest.raises(PySparkValueError) as e:
                method(tag)
            assert e.value.getCondition() == condition
            assert e.value.getMessageParameters()["arg_name"] == "Spark Connect tag"
    spark.removeTag("absent")
    with pytest.raises(PySparkTypeError) as e:
        spark.table(1)
    assert e.value.getMessageParameters() == {
        "arg_name": "tableName", "expected_type": "str", "arg_type": "int"}
    local = tmp_path / "local.txt"
    local.write_text("x")
    with pytest.raises(PySparkValueError) as e:
        spark.copyFromLocalToFs(str(local), "hdfs://host/dest")
    assert e.value.getCondition() == "NO_SCHEMA_AND_DRIVER_DEFAULT_SCHEME"
    for path in (tmp_path / "missing.txt", tmp_path):
        with pytest.raises(AssertionError, match="local path must be a file path."):
            spark.copyFromLocalToFs(str(path), "/dest")
    for name in ("_jsc", "_jconf", "_jvm", "_jsparkSession", "sparkContext"):
        with pytest.raises(PySparkAttributeError) as e:
            getattr(spark, name)
        assert e.value.getMessageParameters() == {"attr_name": name}
    assert getattr(spark, "no_such_attribute", "default") == "default"
    # As PySpark's `object.__getattribute__`, whose AttributeError names the attribute as it is.
    for name in ("no_such_attribute", "a\ud800"):
        with pytest.raises(AttributeError) as e:
            getattr(spark, name)
        assert type(e.value) is AttributeError
        assert str(e.value) == f"'SparkSession' object has no attribute '{name}'"
    assert not hasattr(spark, "a\ud800")




def test_repartition_by_range_without_a_count_sends_none_as_pyspark(mock_connect):
    # As PySpark's repartitionByRange(col) and repartitionByRange(col, *cols): a
    # RepartitionByExpression with num_partitions unset, so the server picks the count;
    # repartitionByRange(n, *cols) sends n.
    from pyspark.sql import functions as F

    spark, service = mock_connect
    df = spark.range(1)

    def sent(dataframe):
        dataframe.collect()
        # ExecutePlanRequest.plan=3, Plan.root=1; Relation.repartition_by_expression=27,
        # RepartitionByExpression.num_partitions=3, which is absent when unset.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
        return parse_message(parse_message(plan)[27][0]).get(3)

    assert sent(df.repartitionByRange("id")) is None
    assert sent(df.repartitionByRange(F.col("id"))) is None
    assert sent(df.repartitionByRange("id", "id")) is None
    assert sent(df.repartitionByRange(2, "id")) == [2]



def test_repartition_does_not_unpack_a_list_among_its_columns_as_pyspark(mock_connect):
    # As PySpark's repartition and repartitionByRange, which give the tuple of *cols itself to
    # _to_cols: a list or a tuple among the columns is NOT_EXPECTED_TYPE, where select unpacks a
    # single one. repartitionByRange(n, []) is that error too, not CANNOT_BE_EMPTY.
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import functions as F

    spark, _ = mock_connect
    df = spark.range(1)
    for call, arg_type in [
        (lambda: df.repartition(2, ["id"]), "list"),
        (lambda: df.repartition(2, []), "list"),
        (lambda: df.repartition("id", ["id"]), "list"),
        (lambda: df.repartition(2, 1), "int"),
        (lambda: df.repartitionByRange(2, ["id"]), "list"),
        (lambda: df.repartitionByRange(2, ("id",)), "tuple"),
        (lambda: df.repartitionByRange(2, []), "list"),
        (lambda: df.repartitionByRange("id", ["id"]), "list"),
    ]:
        with pytest.raises(PySparkTypeError) as e:
            call()
        assert e.value.getCondition() == "NOT_EXPECTED_TYPE"
        assert e.value.getMessageParameters() == {
            "expected_type": "Column or str", "arg_name": "cols", "arg_type": arg_type}
    df.repartition(2, "id", F.col("id"))
    df.repartitionByRange(2, "id", F.col("id"))


def test_table_arg_partition_and_order_unpack_only_a_list_as_pyspark(mock_connect):
    # As PySpark's TableArg, whose _to_cols unpacks a single list but not a tuple: a tuple
    # among the columns of partitionBy or orderBy is NOT_EXPECTED_TYPE, and so is a list among
    # several of them, both of the argument col.
    from pyspark.errors import PySparkTypeError

    spark, _ = mock_connect
    table = spark.range(1).asTable()
    for call, arg_type in [
        (lambda: table.partitionBy(("id",)), "tuple"),
        (lambda: table.partitionBy("id", ["id"]), "list"),
        (lambda: table.partitionBy([1]), "int"),
        (lambda: table.partitionBy("id").orderBy(("id",)), "tuple"),
        (lambda: table.partitionBy("id").orderBy("id", ["id"]), "list"),
    ]:
        with pytest.raises(PySparkTypeError) as e:
            call()
        assert e.value.getCondition() == "NOT_EXPECTED_TYPE"
        assert e.value.getMessageParameters() == {
            "expected_type": "Column or str", "arg_name": "col", "arg_type": arg_type}
    # A lone list is unpacked.
    table.partitionBy(["id"]).orderBy(["id"])


def test_is_empty_sends_a_limit_of_one_row_over_an_empty_projection_as_pyspark(mock_connect):
    # As PySpark's select().take(1): Limit(1) over a Project with no expressions.
    spark, service = mock_connect
    spark.range(3).isEmpty()
    # ExecutePlanRequest.plan=3, Plan.root=1; Relation.limit=8, project=3, range=15;
    # Project.expressions=3.
    plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
    relation = parse_message(plan)
    assert 9 not in relation
    limit = parse_message(relation[8][0])
    assert limit[2] == [1]
    project = parse_message(parse_message(limit[1][0])[3][0])
    assert 3 not in project
    assert 15 in parse_message(project[1][0])


def test_is_empty_reads_the_binary_setting_after_its_execution_as_pyspark(mock_connect):
    # As PySpark's isEmpty, select().take(1), whose collect reads
    # spark.sql.execution.pyspark.binaryAsBytes once the rows are fetched; it is asked once.
    spark, service = mock_connect
    df = spark.range(3)
    before = len(service.rpc_events)
    df.isEmpty()
    df.isEmpty()
    assert service.rpc_events[before:] == ["execute", "config"]
