def test_spatial_types():
    g = T.GeometryType(4326)
    assert [c.__name__ for c in type(g).__mro__ if c.__name__ != "object"] == [
        "GeometryType", "SpatialType", "AtomicType", "DataType",
    ]
    assert g.srid == 4326
