def test_datatype_object_model(mock_connect):
    # json / jsonValue / typeName / simpleString / needConversion match official pyspark.
    assert T.IntegerType().typeName() == "integer"
    assert T.IntegerType().simpleString() == "int"
    assert T.IntegerType().json() == '"integer"'
    assert T.IntegerType().jsonValue() == "integer"
    assert T.IntegerType().needConversion() is False
    assert T.ArrayType(T.IntegerType()).typeName() == "array"
    assert T.DecimalType(10, 2).json() == '"decimal(10,2)"'
    # fromInternal/toInternal default to identity.
    assert T.IntegerType().fromInternal(5) == 5
    assert T.IntegerType().toInternal(5) == 5
    # fromDDL parses a DDL string client-side.
    assert T.DataType.fromDDL("a int, b string").simpleString() == "struct<a:int,b:string>"
    # A single-field DDL schema (no comma) must also parse to a one-field struct, not be
    # misread as a bare type (SPARK-59113 follow-up).
    assert T.DataType.fromDDL("i int").simpleString() == "struct<i:int>"
    assert T.StructType.fromDDL("id long").simpleString() == "struct<id:bigint>"


def test_structfield_collation_methods():
    f = T.StructField("a", T.StringType())
    assert f.getCollationsMap({}) == {}
    assert f.getCollationsMap({"__COLLATIONS": {"a": "icu.UNICODE"}}) == {"a": "UNICODE"}
    assert f.schemaCollationValue(T.StringType()) == "spark.UTF8_BINARY"


def test_structfield_object_model():
    f = T.StructField("a", T.IntegerType(), True)
    assert f.simpleString() == "a:int"
    assert f.json() == '{"metadata":{},"name":"a","nullable":true,"type":"integer"}'
    assert f.jsonValue() == {"name": "a", "type": "integer", "nullable": True, "metadata": {}}
    assert f.needConversion() is False
    assert f.getCollationMetadata() == {}
    # StructField.typeName raises (use typeName on the type instead), as in pyspark.
    with pytest.raises(TypeError):
        f.typeName()
    # fromJson round-trips.
    assert T.StructField.fromJson(f.jsonValue()).simpleString() == "a:int"


def test_structtype_object_model():
    st = T.StructType([
        T.StructField("a", T.IntegerType(), True),
        T.StructField("b", T.StringType(), False),
    ])
    assert st.typeName() == "struct"
    assert st.fieldNames() == ["a", "b"]
    assert "root" in st.treeString() and "a: integer (nullable = true)" in st.treeString()
    # toNullable makes every field nullable.
    assert st.toNullable().simpleString() == "struct<a:int,b:string>"
    # json round-trips through fromJson.
    assert T.StructType.fromJson(st.jsonValue()).simpleString() == st.simpleString()
    # needConversion true for a struct with fields.
    assert isinstance(st.needConversion(), bool)


def test_higher_order_functions():
    from pyspark.sql import functions as F

    def is_col(x):
        return type(x).__name__ == "Column"

    # Every higher-order function builds a Column via the lambda machinery.
    assert is_col(F.transform("arr", lambda x: x + 1))
    assert is_col(F.transform("arr", lambda x, i: x + i))  # 2-arg (element, index)
    assert is_col(F.filter("arr", lambda x: x > 0))
    assert is_col(F.filter("arr", lambda x, i: i > 0))
    assert is_col(F.exists("arr", lambda x: x > 0))
    assert is_col(F.forall("arr", lambda x: x > 0))
    assert is_col(F.aggregate("arr", F.lit(0), lambda acc, x: acc + x))
    assert is_col(F.aggregate("arr", F.lit(0), lambda acc, x: acc + x, lambda acc: acc * 2))
    assert is_col(F.reduce("arr", F.lit(0), lambda acc, x: acc + x))
    assert is_col(F.zip_with("a", "b", lambda x, y: x + y))
    assert is_col(F.transform_keys("m", lambda k, v: k))
    assert is_col(F.transform_values("m", lambda k, v: v + 1))
    assert is_col(F.map_filter("m", lambda k, v: v > 0))
    assert is_col(F.map_zip_with("m1", "m2", lambda k, v1, v2: v1 + v2))
    # Nested lambdas must get distinct fresh variable names (no collision).
    assert is_col(F.transform("arr", lambda x: F.transform(x, lambda y: y + 1)))


def test_higher_order_function_validation():
    from pyspark.errors import PySparkValueError
    from pyspark.sql import functions as F

    # arity must be 1..3
    with pytest.raises(PySparkValueError):
        F.transform("arr", lambda: 1)
    with pytest.raises(PySparkValueError):
        F.transform("arr", lambda a, b, c, d: a)
    # the lambda must return a Column
    with pytest.raises(PySparkValueError):
        F.transform("arr", lambda x: 123)


def test_higher_order_functions_check_their_column_arguments_as_pyspark():
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import functions as F

    one = lambda x: x * 10  # noqa: E731
    two = lambda x, y: x + y  # noqa: E731
    three = lambda k, a, b: a  # noqa: E731
    # Each builder takes the column argument in the position under test, and the name of
    # the function that the Column it builds starts with.
    cases = [
        ("transform", lambda c: F.transform(c, one)),
        ("exists", lambda c: F.exists(c, one)),
        ("forall", lambda c: F.forall(c, one)),
        ("filter", lambda c: F.filter(c, one)),
        ("aggregate", lambda c: F.aggregate(c, F.lit(0), two)),
        ("aggregate", lambda c: F.aggregate("a", c, two)),
        ("reduce", lambda c: F.reduce(c, F.lit(0), two)),
        ("reduce", lambda c: F.reduce("a", c, two)),
        ("array_sort", lambda c: F.array_sort(c)),
        ("array_sort", lambda c: F.array_sort(c, two)),
        ("zip_with", lambda c: F.zip_with(c, "b", two)),
        ("zip_with", lambda c: F.zip_with("a", c, two)),
        ("transform_keys", lambda c: F.transform_keys(c, two)),
        ("transform_values", lambda c: F.transform_values(c, two)),
        ("map_filter", lambda c: F.map_filter(c, two)),
        ("map_zip_with", lambda c: F.map_zip_with(c, "m2", three)),
        ("map_zip_with", lambda c: F.map_zip_with("m1", c, three)),
    ]
    for name, make in cases:
        # A list is not a column: PySpark names the argument `col` whatever its position.
        with pytest.raises(PySparkTypeError) as error:
            make([1, 2, 3])
        assert error.value.getCondition() == "NOT_EXPECTED_TYPE", name
        assert error.value.getMessageParameters() == {
            "expected_type": "Column or str", "arg_name": "col", "arg_type": "list"}, name
        # A Column and a column name are built as before.
        for arg in (F.col("a"), "a"):
            column = make(arg)
            assert type(column).__name__ == "Column"
            assert repr(column).startswith(f"Column<'{name}("), name


def test_misc_functions():
    from pyspark.sql import functions as F

    def is_col(x):
        return type(x).__name__ == "Column"

    assert is_col(F.cume_dist())
    assert is_col(F.column("a"))
    assert is_col(F.call_udf("my_udf", F.col("a"), F.col("b")))
    assert is_col(F.call_udf("my_udf", "a", "b"))  # str args coerced to columns
    assert is_col(F.call_function("my_fn", F.col("a")))
    assert is_col(F.call_function("my_fn", "a"))


def test_column_attributes_are_fields_and_slices_are_substrings_as_pyspark():
    from pyspark.errors import PySparkAttributeError, PySparkTypeError, PySparkValueError
    from pyspark.sql import functions as F

    c = F.col("a")
    # An attribute that a Column does not have is the field of that name.
    assert repr(c.b) == repr(c["b"])
    assert repr(c.b.c) == repr(c["b"]["c"])
    assert repr(c._private) == repr(c["_private"])
    assert callable(c.alias)
    for name, condition in (("_jc", "JVM_ATTRIBUTE_NOT_SUPPORTED"), ("__x__", "ATTRIBUTE_NOT_SUPPORTED"),
                            ("__\ud800", "ATTRIBUTE_NOT_SUPPORTED")):
        with pytest.raises(PySparkAttributeError) as error:
            getattr(c, name)
        assert error.value.getCondition() == condition
        assert error.value.getMessageParameters() == {"attr_name": name}
    assert not hasattr(c, "__array__")
    # A name that UTF-8 cannot encode is the field of its literal, which fails its plans.
    assert hasattr(c, "a\ud800") and repr(getattr(c, "a\ud800")) == repr(c["a\ud800"])
    # A slice is substr(start, stop), whose arguments are of one type, a Column or an int.
    assert repr(c[1:3]) == "Column<'substr(a, 1, 3)'>"
    assert repr(c[F.lit(1):F.lit(2)]) == "Column<'substr(a, 1, 2)'>"
    with pytest.raises(PySparkValueError) as error:
        c[1:3:2]
    assert error.value.getCondition() == "SLICE_WITH_STEP"
    for args, condition, parameters in (
        ((1, F.lit(2)), "NOT_SAME_TYPE", {
            "arg_name1": "startPos", "arg_name2": "length", "arg_type1": "int",
            "arg_type2": "Column"}),
        ((None, 3), "NOT_SAME_TYPE", {
            "arg_name1": "startPos", "arg_name2": "length", "arg_type1": "NoneType",
            "arg_type2": "int"}),
        (("x", "y"), "NOT_EXPECTED_TYPE", {
            "expected_type": "Column or int", "arg_name": "startPos", "arg_type": "str"}),
    ):
        with pytest.raises(PySparkTypeError) as error:
            c.substr(*args)
        assert error.value.getCondition() == condition
        assert error.value.getMessageParameters() == parameters
    with pytest.raises(PySparkTypeError, match="NOT_SAME_TYPE"):
        c[:3]


def test_column_getattr_is_a_function_of_the_class_as_pyspark():
    # As PySpark Connect's Column.__getattr__, a function of the class, which a caller calls of a
    # Column: the field of the name, also of a name that the Column has as an attribute, as
    # `self[item]`, and the errors of `_jc` and of a dunder name. The class takes its other
    # attributes as PySpark's does, of object's __getattribute__, before __getattr__.
    import inspect
    import pickle
    import types

    from pyspark.errors import PySparkAttributeError
    from pyspark.sql import functions as F
    from pyspark.sql.connect.column import Column

    c = F.col("a")
    getattr_ = vars(Column)["__getattr__"]
    assert isinstance(getattr_, types.FunctionType)
    assert (getattr_.__name__, getattr_.__qualname__, getattr_.__module__) == (
        "__getattr__", "Column.__getattr__", "pyspark.sql.connect.column")
    assert list(inspect.signature(getattr_).parameters) == ["self", "item"]
    assert "__getattribute__" not in vars(Column)
    assert repr(Column.__getattr__(c, "b")) == repr(c["b"]) == repr(c.b)
    assert repr(Column.__getattr__(c, "alias")) == repr(c["alias"])
    assert c.alias("x") is not None and repr(c.__getattr__("b")) == repr(c["b"])
    for name, condition in (("_jc", "JVM_ATTRIBUTE_NOT_SUPPORTED"), ("__x__", "ATTRIBUTE_NOT_SUPPORTED")):
        with pytest.raises(PySparkAttributeError) as error:
            Column.__getattr__(c, name)
        assert error.value.getCondition() == condition
    assert pickle.loads(pickle.dumps(Column.__getattr__)) is Column.__getattr__


def _serve_one_raw_http2_call(answer):
    """The URL of a server of one connection, in raw HTTP/2 frames, that answers the request of a
    call with `answer`: "reset" sends the response headers and the start of a message, and then
    resets the connection; "reset_at_once" resets the connection on the request; "status" ends the
    response with the status UNKNOWN "boom" that the server sends."""
    import socket
    import struct
    import threading

    def frame(kind, flags, stream, payload=b""):
        return struct.pack(">I", len(payload))[1:] + bytes([kind, flags]) + struct.pack(
            ">I", stream) + payload

    def read_exact(conn, size):
        data = b""
        while len(data) < size:
            chunk = conn.recv(size - len(data))
            if not chunk:
                raise EOFError
            data += chunk
        return data

    def reset(conn):
        # Closing the socket now sends a RST instead of a FIN.
        conn.setsockopt(socket.SOL_SOCKET, socket.SO_LINGER, struct.pack("ii", 1, 0))
        conn.close()

    # HPACK: ":status: 200" (static entry 8), and "content-type: application/grpc", a literal of
    # the static name 31.
    headers = b"\x88\x0f\x10\x10application/grpc"
    trailers = b"\x00\x0bgrpc-status\x012\x00\x0cgrpc-message\x04boom"
    listener = socket.socket()
    listener.bind(("127.0.0.1", 0))
    listener.listen(4)

    def serve():
        conn, _ = listener.accept()
        try:
            read_exact(conn, 24)
            conn.sendall(frame(0x4, 0, 0))
            while True:
                head = read_exact(conn, 9)
                read_exact(conn, int.from_bytes(head[:3], "big"))
                kind, flags = head[3], head[4]
                stream = int.from_bytes(head[5:9], "big") & 0x7FFFFFFF
                if kind == 0x4 and not flags & 0x1:
                    conn.sendall(frame(0x4, 0x1, 0))
                elif kind == 0x1 and answer == "reset_at_once":
                    return reset(conn)
                elif kind == 0x1:
                    conn.sendall(frame(0x1, 0x4, stream, headers))
                    if answer == "status":
                        conn.sendall(frame(0x1, 0x5, stream, trailers))
                        continue
                    # The first 2 bytes of a message of 1000 bytes.
                    conn.sendall(frame(0x0, 0, stream, b"\x00\x00\x00\x03\xe8\x01\x02"))
                    time.sleep(0.3)
                    return reset(conn)
        except (EOFError, OSError):
            conn.close()
        finally:
            listener.close()

    threading.Thread(target=serve, daemon=True).start()
    return f"sc://127.0.0.1:{listener.getsockname()[1]}"


@pytest.mark.parametrize("answer,call,code", [
    ("reset", "next", 14),
    ("reset_at_once", "execute_plan", 14),
    ("reset_at_once", "config", 14),
    ("status", "next", 2),
    ("status", "config", 2),
])
def test_the_transport_reports_a_dropped_connection_as_unavailable_as_grpc_python(
    answer, call, code
):
    # As grpc-python, the code of the errors of the stub that the reference client drives is
    # UNAVAILABLE (14) for a connection that drops, which that client retries and reattaches,
    # where tonic says UNKNOWN (2). A status that the server sends keeps its code.
    from pyspark import _pyspark

    stub = _pyspark.RustConnectStub(_serve_one_raw_http2_call(answer))
    with pytest.raises(_pyspark.RustRpcError) as error:
        if call == "config":
            stub.config(b"")
        else:
            responses = stub.execute_plan(b"")
            next(iter(responses))
    assert error.value.args[0] == code, error.value.args
    if answer == "status":
        assert "boom" in error.value.args[2]


def test_create_raises_for_a_keepalive_param_that_is_not_an_integer_as_pyspark():
    # As PySpark's client, whose channel options read the keepalive time with int() as it opens
    # its channel: the ValueError of int(), before a session is made.
    from pyspark.sql import SparkSession

    with pytest.raises(ValueError) as error:
        SparkSession.builder.remote("sc://localhost:1/;grpc_keepalive_time_ms=abc").create()
    assert str(error.value) == "invalid literal for int() with base 10: 'abc'"


def test_create_raises_for_a_port_that_urllib_rejects_as_pyspark():
    # As PySpark's channel builder, whose port (urllib's) raises a ValueError of the builtin
    # when the session is made, with no URL and no token in the message.
    from pyspark.sql import SparkSession

    for url, message in [
        ("sc://localhost:99999/;token=SECRET", "Port out of range 0-65535"),
        ("sc://localhost:+80/;token=SECRET", "Port could not be cast to integer value as '+80'"),
        ("sc://localhost:notaport/;token=SECRET",
         "Port could not be cast to integer value as 'notaport'"),
    ]:
        with pytest.raises(ValueError) as error:
            SparkSession.builder.remote(url).create()
        assert type(error.value) is ValueError, url
        assert str(error.value) == message, url


def test_create_raises_for_an_authority_that_urllib_rejects_as_pyspark():
    # As PySpark's channel builder, whose netloc urlsplit checks before the path and the params
    # are read, and whose port urllib reads: the ValueErrors of urllib, with no token in them.
    from pyspark.sql import SparkSession

    for url, message in [
        ("sc://a:1:2", "Port could not be cast to integer value as '1:2'"),
        ("sc://localhost:15012:1/", "Port could not be cast to integer value as '15012:1'"),
        ("sc://localhost:x;token=SECRET",
         "Port could not be cast to integer value as 'x;token=<redacted>'"),
        ("sc://[::1]x", "Invalid IPv6 URL"),
        ("sc://[::1]x:15002", "Invalid IPv6 URL"),
        ("sc://[1.2.3.4]:15002", "An IPv4 address cannot be in brackets"),
        ("sc://[localhost]:15002", "'localhost' does not appear to be an IPv4 or IPv6 address"),
        ("sc://[a;token=SECRET]:1",
         "'a;token=<redacted>' does not appear to be an IPv4 or IPv6 address"),
    ]:
        with pytest.raises(ValueError) as error:
            SparkSession.builder.remote(url).create()
        assert type(error.value) is ValueError, url
        assert str(error.value) == message, url
    # The userinfo ends at the last '@', so the host is localhost and the token is plaintext, as
    # urllib reads it: the session is made, and no TLS is configured for it.
    session = SparkSession.builder.remote("sc://user@localhost:15012/;token=SECRET").create()
    # No server to release on: a release would wait for the retries of a refused port.
    session.release_session_on_close = False
    session.stop()


def test_a_too_long_user_agent_raises_at_each_request_as_pyspark(mock_connect, monkeypatch, caplog):
    # As PySpark's `userAgent`, which its requests read when they are built: the session of a
    # user agent of more than 2048 characters after the URL escaping is made, and each request
    # that carries the user agent raises a SparkConnectException of the message of the reference
    # client and is not sent. stop() logs that error, of the release of the session, to the
    # logger of Spark Connect, as PySpark's `except Exception as e` of its f-string of `${e}`.
    from pyspark.errors.exceptions.connect import SparkConnectException
    from pyspark.sql import SparkSession
    from pyspark.sql.connect.logging import logger

    _, service = mock_connect
    monkeypatch.delenv("SPARK_CONNECT_USER_AGENT", raising=False)
    spark = SparkSession.builder.remote(service.remote + "/;user_agent=" + "a" * 2049).create()
    message = (
        "'user_agent' parameter should not exceed 2048 characters after URL escaping, "
        "found 2049 characters."
    )
    for request in [
        lambda: spark.range(1).count(),
        lambda: spark.conf.get("spark.sql.session.timeZone"),
        lambda: spark.version,
        spark.interruptAll,
    ]:
        with pytest.raises(SparkConnectException) as error:
            request()
        assert type(error.value) is SparkConnectException
        assert str(error.value) == message
        assert error.value.getCondition() is None
    # The logger is disabled unless SPARK_CONNECT_LOG_LEVEL is set.
    monkeypatch.setattr(logger, "disabled", False)
    with caplog.at_level("WARNING", logger=logger.name):
        assert spark.stop() is None
    assert spark.is_stopped
    messages = [record.message for record in caplog.records if record.name.startswith("pyspark")]
    assert messages == [f"session.stop(): Session could not be released. Error: ${message}"]
    session_id = spark.session_id.encode()
    assert not any(session_id in request for _, request in service.recorded_order)


@pytest.mark.parametrize("put", ["relation", "to_proto"])
def test_the_request_of_a_hook_is_sent_as_it_is_as_pyspark(mock_connect, put):
    # As PySpark's executions, which send the request that the hooks return as it is: the relation
    # of a DataFrame that an on_execute_plan hook sets as the root of the plan is sent as it is,
    # over the threshold too, and the plan of its `to_proto`, which compresses it, compressed. The
    # plan of the execution, which the hook replaces, is compressed once, before the hook.
    pytest.importorskip("google.protobuf")
    from pyspark.sql.connect.session import SparkSession

    _, service = mock_connect
    service.confs = _plan_confs("1024")
    frames = []

    class PlanHook(SparkSession.Hook):
        def on_execute_plan(self, request):
            if put == "relation":
                request.plan.root.CopyFrom(frames[0]._plan.plan(None))
            else:
                request.plan.CopyFrom(frames[0]._plan.to_proto(frames[0].sparkSession.client))
            return request

    builder = SparkSession.builder.remote(service.remote)
    builder._registerHook(lambda _: PlanHook())
    spark = builder.create()
    try:
        frames.append(_long_literal_frame(spark))
        spark.range(1).collect()
    finally:
        spark.stop()
    plan = _sent_plan(service.execute_requests)
    if put == "relation":
        assert 1 in plan and 3 not in plan
    else:
        assert 1 not in plan and 3 in plan


