def test_na_and_stat_functions_check_their_arguments_as_pyspark():
    # As PySpark's NA and statistic functions of a DataFrame, which check their arguments on
    # the client.
    from pyspark.errors import PySparkTypeError, PySparkValueError

    df = _offline_session().range(1)

    def not_expected(arg_name, expected_type, arg_type):
        return (PySparkTypeError, "NOT_EXPECTED_TYPE",
                {"arg_name": arg_name, "expected_type": expected_type, "arg_type": arg_type})

    for call, (error_type, condition, parameters) in (
        (lambda: df.dropna(how="bogus"), (PySparkValueError, "VALUE_NOT_ALLOWED",
                                          {"arg_name": "how", "allowed_values": "['any', 'all']"})),
        (lambda: df.na.drop(how=1), not_expected("how", "str", "int")),
        (lambda: df.dropna(thresh=1.5), not_expected("thresh", "int", "float")),
        (lambda: df.dropna(subset=1), not_expected("subset", "list, str or tuple", "int")),
        (lambda: df.na.drop(subset=["id", 1]), not_expected("cols", "list, str or tuple", "int")),
        (lambda: df.fillna([1]), not_expected("value", "bool, dict, float, int or str", "list")),
        (lambda: df.na.fill({}), (PySparkValueError, "CANNOT_BE_EMPTY", {"item": "value"})),
        (lambda: df.fillna({1: 0}), not_expected("key type of dict", "str", "int")),
        (lambda: df.fillna({"id": [1]}),
         not_expected("value type of dict", "bool, float, int or str", "list")),
        (lambda: df.fillna(0, subset=1), not_expected("subset", "list or tuple", "int")),
        (lambda: df.summary(1), not_expected("statistics", "list[str]", "int")),
        (lambda: df.cov("id", 1), not_expected("col2", "str", "int")),
        (lambda: df.stat.corr(1, "id"), not_expected("col1", "str", "int")),
        (lambda: df.corr("id", "id", "kendall"), (PySparkValueError, "VALUE_NOT_ALLOWED",
                                                  {"arg_name": "method",
                                                   "allowed_values": "['pearson']"})),
        (lambda: df.stat.crosstab("id", 1), not_expected("col2", "str", "int")),
        (lambda: df.freqItems("id"), not_expected("cols", "list or tuple", "str")),
        (lambda: df.approxQuantile(1, [0.5], 0.0), not_expected("col", "list, str or tuple", "int")),
        (lambda: df.approxQuantile(["id", 1], [0.5], 0.0), not_expected("columns", "list[str]", "int")),
        (lambda: df.stat.approxQuantile("id", 0.5, 0.0),
         not_expected("probabilities", "list or tuple", "float")),
        (lambda: df.approxQuantile("id", [1.5], 0.0),
         not_expected("probabilities", "list[float, int]", "float")),
        (lambda: df.approxQuantile("id", [0.5], "0"), not_expected("relativeError", "float or int", "str")),
        (lambda: df.approxQuantile("id", [0.5], -1), (PySparkValueError, "NEGATIVE_VALUE",
                                                     {"arg_name": "relativeError", "arg_value": "-1"})),
    ):
        with pytest.raises(error_type) as error:
            call()
        assert error.value.getCondition() == condition
        assert error.value.getMessageParameters() == parameters


def test_dropna_thresh_that_the_proto_refuses_is_refused_as_pyspark():
    # As PySpark sends `thresh` as a proto int, after it checks `how` and `subset`, when its
    # `NADrop` plan is built: a bool, which is an int, is the TypeError of protobuf's default
    # (upb) backend, since protobuf 7.34, and an int out of the range of an int32 a ValueError,
    # which the requests of the DataFrame raise.
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import DataFrame

    df = _offline_session().range(1)
    refused = "Field spark.connect.NADrop.min_non_nulls: Expected an int, got a boolean."
    cases = (
        (lambda: df.dropna(thresh=True), TypeError, refused),
        (lambda: df.na.drop(thresh=False), TypeError, refused),
        (lambda: df.dropna(thresh=True, subset=["id"]), TypeError, refused),
        (lambda: df.dropna(thresh=2**40), ValueError, "Value out of range: 1099511627776"),
        (lambda: df.na.drop(thresh=-(2**31) - 1), ValueError, "Value out of range: -2147483649"),
        (lambda: df.dropna(how="all", thresh=2**40), ValueError,
         "Value out of range: 1099511627776"),
    )
    for call, error_type, message in cases:
        plan = call()
        assert isinstance(plan, DataFrame)
        for request in (lambda: plan.schema, plan.collect):
            with pytest.raises(error_type) as error:
                request()
            assert type(error.value) is error_type
            assert str(error.value) == message
    # The `subset` is checked before the `thresh` is sent.
    with pytest.raises(PySparkTypeError) as error:
        df.dropna(thresh=True, subset=1)
    assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
    # The bounds of an int32 are those of the proto.
    assert isinstance(df.dropna(thresh=2**31 - 1), DataFrame)
    assert isinstance(df.na.drop(thresh=-(2**31)), DataFrame)


def test_counts_that_the_proto_refuses_are_refused_as_pyspark():
    # As PySpark's limit, offset, tail, head, take, repartition, coalesce, repartitionByRange and
    # repartitionById, whose plans set the count in a proto int32 after PySpark's own checks:
    # protobuf's default (upb) backend refuses a bool, which is an int, since protobuf 7.34, takes
    # any other value by its __index__, so a float, a str or None is the TypeError of
    # operator.index, and refuses an int out of the range of the field with a ValueError, of the
    # value itself, or of its int when that is beyond a long. PySpark raises these once it sends
    # the plan, so limit, offset, repartition, repartitionByRange, repartitionById and coalesce
    # return a DataFrame that raises them at each action. tail, head and take are actions, which
    # raise them at the call.
    import operator

    from pyspark.errors import PySparkTypeError, PySparkValueError
    from pyspark.sql import DataFrame

    class Shown(int):
        def __str__(self):
            return "shown"

    def index_error(value):
        with pytest.raises(TypeError) as error:
            operator.index(value)
        return str(error.value)

    def refused(field):
        return TypeError, f"Field spark.connect.{field}: Expected an int, got a boolean."

    df = _offline_session().range(1)
    for method, field in (
        (df.limit, "Limit.limit"),
        (df.offset, "Offset.offset"),
        (df.tail, "Tail.limit"),
        (df.head, "Limit.limit"),
        (df.take, "Limit.limit"),
    ):
        for value, error_type, message in (
            (True, *refused(field)),
            (False, *refused(field)),
            (1.5, TypeError, index_error(1.5)),
            ("1", TypeError, index_error("1")),
            (np.True_, TypeError, index_error(np.True_)),
            (2**40, ValueError, "Value out of range: 1099511627776"),
            (-(2**31) - 1, ValueError, "Value out of range: -2147483649"),
            (np.int64(2**31), ValueError, "Value out of range: 2147483648"),
            (Shown(2**40), ValueError, "Value out of range: shown"),
            (Shown(2**70), ValueError, "Value out of range: 1180591620717411303424"),
        ):
            if method in (df.limit, df.offset):
                plan = method(value)
                assert isinstance(plan, DataFrame), (method, value)
                call = plan.collect
            else:
                call = lambda: method(value)  # noqa: E731
            with pytest.raises(error_type) as error:
                call()
            assert type(error.value) is error_type, (method, value)
            assert str(error.value) == message, (method, value)
    # The counts of these plans are converted as the plan is sent, after the checks of PySpark.
    lazy_cases = [
        (lambda: df.limit(None), TypeError, index_error(None)),
        (lambda: df.limit(num=True), *refused("Limit.limit")),
        (lambda: df.offset(None), TypeError, index_error(None)),
        (lambda: df.repartition(True), *refused("Repartition.num_partitions")),
        (lambda: df.repartition(True, "id"), *refused("RepartitionByExpression.num_partitions")),
        (lambda: df.coalesce(True), *refused("Repartition.num_partitions")),
        (lambda: df.repartitionByRange(True, "id"),
         *refused("RepartitionByExpression.num_partitions")),
        (lambda: df.repartition(2**40), ValueError, "Value out of range: 1099511627776"),
        (lambda: df.repartition(2**31, "id"), ValueError, "Value out of range: 2147483648"),
        (lambda: df.coalesce(2**70), ValueError, "Value out of range: 1180591620717411303424"),
        (lambda: df.repartitionByRange(Shown(2**40), "id"), ValueError,
         "Value out of range: shown"),
        (lambda: df.repartitionById(2**40, "id"), ValueError, "Value out of range: 1099511627776"),
        # coalesce compares a float or a bool with 0, and the proto takes it as its int.
        (lambda: df.coalesce(1.5), TypeError, index_error(1.5)),
        (lambda: df.coalesce(np.True_), TypeError, index_error(np.True_)),
    ]
    for call, error_type, message in lazy_cases:
        plan = call()
        assert isinstance(plan, DataFrame), message
        with pytest.raises(error_type) as error:
            plan.collect()
        assert type(error.value) is error_type, message
        assert str(error.value) == message
        with pytest.raises(error_type):
            plan.schema
    # The actions, and the comparison of coalesce, which PySpark makes as it is called.
    eager_cases = [
        (lambda: df.take(None), TypeError, index_error(None)),
        (lambda: df.head(n=True), *refused("Limit.limit")),
        (lambda: df.coalesce(None), TypeError,
         "'>' not supported between instances of 'NoneType' and 'int'"),
        (lambda: df.coalesce("1"), TypeError,
         "'>' not supported between instances of 'str' and 'int'"),
    ]
    for call, error_type, message in eager_cases:
        with pytest.raises(error_type) as error:
            call()
        assert type(error.value) is error_type, message
        assert str(error.value) == message

    def not_positive(value):
        return PySparkValueError, "VALUE_NOT_POSITIVE", {
            "arg_name": "numPartitions", "arg_value": value}

    def not_expected(arg_name, expected_type, arg_type):
        return PySparkTypeError, "NOT_EXPECTED_TYPE", {
            "arg_name": arg_name, "expected_type": expected_type, "arg_type": arg_type}

    # PySpark's own checks come first, of the str of the count, and so do those of the columns.
    pyspark_cases = [
        (lambda: df.repartition(False), not_positive("False")),
        (lambda: df.repartition(Shown(0), "id"), not_positive("shown")),
        (lambda: df.coalesce(False), not_positive("False")),
        (lambda: df.coalesce(np.False_), not_positive("False")),
        (lambda: df.repartitionByRange(False, "id"), not_positive("False")),
        (lambda: df.repartitionById(Shown(0), "id"), not_positive("shown")),
        (lambda: df.repartitionByRange(True),
         (PySparkValueError, "CANNOT_BE_EMPTY", {"item": "cols"})),
        (lambda: df.repartition(np.int64(2)),
         not_expected("numPartitions", "Column or str", "int64")),
        (lambda: df.repartitionByRange(np.int64(2), "id"),
         not_expected("numPartitions", "Column, int or str", "int64")),
        (lambda: df.repartition(2**40, 1.5), not_expected("cols", "Column or str", "float")),
        (lambda: df.repartitionByRange(True, 1.5),
         not_expected("cols", "Column or str", "float")),
        (lambda: df.repartitionById(2**40, 1.5), not_expected("col", "Column or str", "float")),
    ]
    for call, (error_type, condition, parameters) in pyspark_cases:
        with pytest.raises(error_type) as error:
            call()
        assert error.value.getCondition() == condition
        assert error.value.getMessageParameters() == parameters


def test_counts_and_seeds_that_fail_the_plan_keep_the_cached_schema_as_pyspark(mock_connect):
    # As PySpark's limit, coalesce, repartition, repartitionByRange, repartitionById, sample and
    # randomSplit, which copy the _cached_schema of their input: of a count or a seed that the
    # proto refuses, whose plan fails each request, the schema is that of the input once the
    # input has one, with no request, while the actions still fail. offset and sampleBy do not
    # copy it, so their schema is that of their plan, which fails before a request, as it does
    # for all of them before the input has a schema.
    spark, service = mock_connect
    df = spark.range(3)
    keeping = [
        lambda d: d.limit(2.0),
        lambda d: d.limit(2**40),
        lambda d: d.coalesce(2**40),
        lambda d: d.repartition(2**40),
        lambda d: d.repartition(2**40, "id"),
        lambda d: d.repartitionByRange(2**40, "id"),
        lambda d: d.repartitionById(2**40, "id"),
        lambda d: d.sample(fraction=0.5, seed=2**70),
        lambda d: d.sample(True, 0.5, 2**70),
        lambda d: d.randomSplit([0.5, 0.5], seed=2**70)[0],
        lambda d: d.randomSplit([0.5, 0.5], seed=2**70)[1],
    ]
    dropping = [lambda d: d.offset(2**40), lambda d: d.sampleBy("id", {0: 0.5}, seed=2**70)]
    for make in keeping + dropping:
        with pytest.raises((TypeError, ValueError)):
            make(df).schema
    assert service.analyze_requests == []
    schema = df.schema
    assert len(service.analyze_requests) == 1
    for make in keeping:
        plan = make(df)
        assert plan.schema == schema
        assert plan.columns == ["id"]
        # A transformation that keeps the schema keeps it again.
        assert plan.limit(1).columns == ["id"]
        with pytest.raises((TypeError, ValueError)):
            plan.collect()
    for make in dropping:
        with pytest.raises(ValueError, match="Value out of range"):
            make(df).columns
    assert len(service.analyze_requests) == 1
    assert service.execute_requests == []


def test_counts_are_sent_by_their_index_as_pyspark(mock_connect):
    # As protobuf's default (upb) backend takes the count of these plans, by its __index__: a
    # NumPy int, an int of a subclass, or another object with __index__ is sent as its int, and so
    # are the bounds of an int32, for the server to check. A count that it refuses sends nothing.
    spark, service = mock_connect
    df = spark.range(3)

    class Index:
        def __index__(self):
            return 2

    class Shown(int):
        def __str__(self):
            return "shown"

    def sent(field, number):
        # ExecutePlanRequest.plan=3, Plan.root=1; Relation.limit=8, offset=13, repartition=17,
        # tail=22 and repartition_by_expression=27, of their counts.
        return _sent_relation(service.execute_requests[-1], field, execute=True)[number]

    for run, field, number, count in (
        (lambda: df.limit(np.int64(2)).collect(), 8, 2, 2),
        (lambda: df.limit(Index()).collect(), 8, 2, 2),
        (lambda: df.limit(2**31 - 1).collect(), 8, 2, 2**31 - 1),
        (lambda: df.limit(-(2**31)).collect(), 8, 2, 2**64 - 2**31),
        (lambda: df.offset(np.int32(1)).collect(), 13, 2, 1),
        (lambda: df.tail(np.int64(2)), 22, 2, 2),
        (lambda: df.take(Index()), 8, 2, 2),
        (lambda: df.head(Shown(2)), 8, 2, 2),
        (lambda: df.coalesce(np.int64(2)).collect(), 17, 2, 2),
        (lambda: df.repartition(Shown(2)).collect(), 17, 2, 2),
        (lambda: df.repartition(Shown(2), "id").collect(), 27, 3, 2),
        (lambda: df.repartitionByRange(Shown(2), "id").collect(), 27, 3, 2),
        (lambda: df.repartitionById(Shown(2), "id").collect(), 27, 3, 2),
    ):
        run()
        assert sent(field, number) == [count]
    before = len(service.execute_requests)
    for run, error_type in (
        (lambda: df.take(True), TypeError),
        (lambda: df.head(False), TypeError),
        (lambda: df.tail(2**40), ValueError),
        (lambda: df.limit(True).collect(), TypeError),
        (lambda: df.coalesce(True).collect(), TypeError),
    ):
        with pytest.raises(error_type):
            run()
    assert len(service.execute_requests) == before


def test_avro_protobuf_partitioning_submodules():
    # The official import paths resolve (the implementations live in
    # pyspark.sql.functions and are re-exported here).
    import pyspark.sql.avro.functions as af
    import pyspark.sql.functions.partitioning as part
    import pyspark.sql.protobuf.functions as pf
    from pyspark.sql import functions as F

    assert hasattr(af, "from_avro") and hasattr(af, "to_avro")
    assert hasattr(pf, "from_protobuf") and hasattr(pf, "to_protobuf")
    for n in ("bucket", "days", "hours", "months", "years"):
        assert hasattr(part, n), f"partitioning.{n} missing"
        assert hasattr(F.partitioning, n)


def test_java_functions_are_registered_of_their_return_types_as_pyspark(mock_connect):
    # As PySpark's spark.udf, whose sparkSession is the session, and whose registerJavaFunction
    # sends a DDL string as an unparsed data type, which the server parses, and a DataType as
    # itself, in a JavaUDF that is not deterministic.
    from pyspark.errors import PySparkValueError
    from pyspark.sql.types import IntegerType

    spark, service = mock_connect
    assert spark.udf.sparkSession is spark

    def registered():
        # ExecutePlanRequest.plan=3, Plan.command=2, Command.register_function=1;
        # CommonInlineUserDefinedFunction.function_name=1, deterministic=2, java_udf=6.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        function = parse_message(parse_message(plan[2][0])[1][0])
        return function, parse_message(function[6][0])

    spark.udf.registerJavaFunction("f", "com.example.F", "int")
    function, udf = registered()
    assert function[1] == [b"f"]
    assert function.get(2, [0]) == [0]
    # JavaUDF.class_name=1, output_type=2, aggregate=3; DataType.unparsed=24 of
    # Unparsed.data_type_string=1, and DataType.integer=6.
    assert udf[1] == [b"com.example.F"]
    assert parse_message(parse_message(udf[2][0])[24][0]) == {1: [b"int"]}
    spark.udf.registerJavaFunction("g", "com.example.G", IntegerType())
    _, udf = registered()
    assert list(parse_message(udf[2][0])) == [6]
    spark.udf.registerJavaFunction("h", "com.example.H")
    _, udf = registered()
    assert 2 not in udf and udf.get(3, [0]) == [0]
    spark.udf.registerJavaUDAF("i", "com.example.I")
    _, udf = registered()
    assert 2 not in udf and udf[3] == [1]
    calls = len(service.execute_requests)
    with pytest.raises(PySparkValueError) as e:
        spark.udf.registerJavaFunction("j", "com.example.J", 1)
    assert e.value.getCondition() == "UNSUPPORTED_OPERATION"
    assert e.value.getMessageParameters() == {"operation": "data type 1"}
    assert len(service.execute_requests) == calls


def test_registrations_and_interrupts_take_their_names_as_protobuf_as_pyspark(mock_connect):
    # As PySpark's commands, which set their names in the string fields of their requests at the
    # call, as protobuf converts them: registerJavaFunction and registerJavaUDAF (the name, then
    # the class), the register of spark.udf of a UDF and of spark.udtf, the `name()` of the class
    # of spark.dataSource.register, interruptTag and interruptOperation take bytes of UTF-8, and
    # raise "bad argument type for built-in operation" of another value, before any request. A
    # function registered of no name is registered as `fun_` and a random hex, as PySpark's client
    # does, and the interrupts assert a tag or an ID that is not None. The UNSUPPORTED_OPERATION
    # of a return type names its str as it is. (The register of a plain function names the
    # function of its wrapper, so of a name that is not a str it raises that of `__name__`, as
    # PySpark's.)
    from pyspark.errors import PySparkValueError
    from pyspark.sql.connect.proto import base_pb2
    from pyspark.sql.datasource import DataSource
    from pyspark.sql.functions import udf, udtf

    spark, service = mock_connect

    def command():
        return base_pb2.ExecutePlanRequest.FromString(service.execute_requests[-1]).plan.command

    @udtf(returnType="x int")
    class Table:
        def eval(self):
            yield (1,)

    def source(source_name):
        class Source(DataSource):
            @classmethod
            def name(cls):
                return source_name

        return Source

    spark.udf.registerJavaFunction(b"f", b"com.example.F")
    function = command().register_function
    assert (function.function_name, function.java_udf.class_name) == ("f", "com.example.F")
    spark.udf.registerJavaUDAF(b"g", "com.example.G")
    assert command().register_function.function_name == "g"
    function = udf(lambda x: x)
    for f in (lambda x: x, function):
        assert callable(spark.udf.register(None, f))
        name = command().register_function.function_name
        assert re.fullmatch("fun_[0-9a-f]{32}", name), name
    assert spark.udf.register(b"h", function) is function
    assert command().register_function.function_name == "h"
    assert spark.udtf.register(b"t", Table) is Table
    assert command().register_table_function.function_name == "t"
    spark.dataSource.register(source(b"s"))
    assert command().register_data_source.name == "s"
    spark.interruptOperation(b"y")
    # InterruptRequest.operation_id=6.
    assert parse_message(service.interrupt_requests[-1])[6] == [b"y"]
    requests = len(service.execute_requests), len(service.interrupt_requests)
    bad_type = "^bad argument type for built-in operation$"
    for call in (
        lambda: spark.udf.registerJavaFunction(5, "C"),
        lambda: spark.udf.registerJavaFunction("f", None),
        lambda: spark.udf.registerJavaUDAF(None, b"\xff"),
        lambda: spark.udf.register(5, function),
        lambda: spark.udtf.register(None, Table),
        lambda: spark.dataSource.register(source(5)),
        lambda: spark.dataSource.register(source(None)),
        lambda: spark.interruptTag(5),
        lambda: spark.interruptOperation(1.5),
    ):
        with pytest.raises(TypeError, match=bad_type):
            call()
    with pytest.raises(UnicodeEncodeError):
        spark.dataSource.register(source("s\ud800"))
    with pytest.raises(UnicodeDecodeError):
        spark.dataSource.register(source(b"\xff"))
    for call in (lambda: spark.interruptTag(None), lambda: spark.interruptOperation(None)):
        with pytest.raises(AssertionError) as error:
            call()
        assert str(error.value) == ""

    class Lone:
        def __str__(self):
            return "lone\ud800"

    for register in (
        lambda: spark.udf.registerJavaFunction("j", "C", Lone()),
        lambda: spark.udtf.register("t", udtf(Table.func, returnType=Lone())),
    ):
        with pytest.raises(PySparkValueError) as error:
            register()
        assert error.value.getMessageParameters() == {"operation": "data type lone\ud800"}
    assert (len(service.execute_requests), len(service.interrupt_requests)) == requests


def test_udf_registration_has_java_methods():
    # The UDFRegistration class (what spark.udf returns) exposes the Java methods.
    from pyspark.sql.connect.udf import UDFRegistration
    for m in ("register", "registerJavaFunction", "registerJavaUDAF"):
        assert hasattr(UDFRegistration, m), f"UDFRegistration missing {m}"


def test_udf_udtf_determinism_and_extras(mock_connect):
    from pyspark.sql import functions as F
    from pyspark.sql.connect.udf import UserDefinedFunction, udf
    from pyspark.sql.connect.udtf import udtf

    # As PySpark's, asNondeterministic() of the function wrapper of a UDF marks the UDF
    # nondeterministic, in place, and returns a wrapper of it.
    u = udf(lambda x: x, T.IntegerType())
    nd = u.asNondeterministic()
    assert isinstance(nd._unwrapped, UserDefinedFunction) and nd.deterministic is False
    assert nd._unwrapped is u._unwrapped and u._unwrapped.deterministic is False
    assert u.returnType is not None

    @udtf(returnType="a int")
    class E:
        def eval(self, n):
            yield (n,)

    d = E.asDeterministic()
    assert d.deterministic is True

    # functions.random is an alias for rand.
    assert F.random is F.rand
    # StructField.fromDDL is DataType.fromDDL, which parses a list of fields to a StructType.
    assert T.StructField.fromDDL("a int").simpleString() == "struct<a:int>"
    assert T.StructField.fromDDL("b: string").simpleString() == "struct<b:string>"


def test_catalog_result_classes():
    # As PySpark's: the catalog metadata result classes are the NamedTuples of
    # pyspark.sql.catalog, and the Table `database` property derives from a single-element
    # namespace. The Catalog of a session is PySpark Connect's, of pyspark.sql.connect.catalog,
    # and that of pyspark.sql.catalog is PySpark's classic class.
    from pyspark.sql.catalog import (
        Catalog,
        CatalogMetadata,
        Column,
        Database,
        Function,
        Table,
        TablePartition,
    )
    from pyspark.sql.connect.catalog import Catalog as ConnectCatalog

    assert Catalog.__module__ == "pyspark.sql.catalog"
    assert ConnectCatalog.__module__ == "pyspark.sql.connect.catalog"
    assert ConnectCatalog is not Catalog
    for cls in (CatalogMetadata, Database, Table, Column, Function, TablePartition):
        assert cls.__module__ == "pyspark.sql.catalog", f"{cls.__name__} module = {cls.__module__}"
        assert issubclass(cls, tuple)
    assert Column._fields == (
        "name", "description", "dataType", "nullable", "isPartition", "isBucket", "isCluster")
    assert Table("t", None, ["db"], None, "MANAGED", False).database == "db"
    assert Table("t", None, ["a", "b"], None, "MANAGED", False).database is None


def test_unparsed_data_types_are_those_of_pyspark(mock_connect):
    # As PySpark Connect's: UnparsedDataType of pyspark.sql.connect.types is a DDL string of a
    # type that the server parses, whose JSON and conversions raise
    # INVALID_CALL_ON_UNRESOLVED_OBJECT; the returnType of a UDTF of a DDL string is one; and
    # the registration of a data source without a name raises the AttributeError of name().
    import pickle

    from pyspark.errors import PySparkAssertionError
    from pyspark.sql.connect.types import UnparsedDataType
    from pyspark.sql.functions import udtf

    spark, _ = mock_connect
    unparsed = UnparsedDataType("a int, b string")
    assert isinstance(unparsed, T.DataType)
    assert repr(unparsed) == "UnparsedDataType('a int, b string')"
    assert unparsed.simpleString() == "unparsed('a int, b string')"
    for name, call in (("jsonValue", unparsed.jsonValue), ("jsonValue", unparsed.json),
                       ("needConversion", unparsed.needConversion),
                       ("toInternal", lambda: unparsed.toInternal(1)),
                       ("fromInternal", lambda: unparsed.fromInternal(1))):
        with pytest.raises(PySparkAssertionError) as e:
            call()
        assert e.value.getCondition() == "INVALID_CALL_ON_UNRESOLVED_OBJECT"
        assert e.value.getMessageParameters() == {"func_name": name}
    assert repr(pickle.loads(pickle.dumps(unparsed))) == repr(unparsed)

    @udtf(returnType="x int")
    class Tables:
        def eval(self, n: int):
            yield (n,)

    assert repr(Tables.returnType) == "UnparsedDataType('x int')"
    with pytest.raises(AttributeError):
        spark.dataSource.register(1)




def test_udtf_analyze_result_family():
    from pyspark.sql.udtf import (
        AnalyzeResult,
        OrderingColumn,
        PartitioningColumn,
        SelectedColumn,
        SkipRestOfInputTableException,
    )
    assert PartitioningColumn("x").name == "x"
    oc = OrderingColumn("y", ascending=False)
    assert oc.name == "y" and oc.ascending is False and oc.overrideNullsFirst is None
    assert SelectedColumn("z", alias="a").alias == "a"
    ar = AnalyzeResult(schema=T.StructType([T.StructField("a", T.IntegerType())]),
                       withSinglePartition=True, partitionBy=[PartitioningColumn("x")])
    assert ar.withSinglePartition is True and len(ar.partitionBy) == 1
    ar.withSinglePartition = False  # mutable dataclass
    assert ar.withSinglePartition is False
    assert issubclass(SkipRestOfInputTableException, Exception)


def test_udtf_analyze_result_subclass_preserves_custom_state():
    from dataclasses import dataclass, fields

    from pyspark.serializers import CloudPickleSerializer
    from pyspark.sql.connect.udtf import AnalyzeResult as ConnectAnalyzeResult
    from pyspark.sql.connect.udtf import udtf
    from pyspark.sql.udtf import AnalyzeResult

    assert ConnectAnalyzeResult is AnalyzeResult

    @dataclass
    class ResultWithBuffer(AnalyzeResult):
        buffer: str = ""

    schema = T.StructType([T.StructField("buffer", T.StringType())])
    result = ResultWithBuffer(schema, buffer="kept")
    assert [field.name for field in fields(result)] == [
        "schema", "withSinglePartition", "partitionBy", "orderBy", "select", "buffer",
    ]
    assert result.partitionBy == result.orderBy == result.select == ()
    assert result.withSinglePartition is False
    result.buffer = "updated"
    restored = CloudPickleSerializer().loads(CloudPickleSerializer().dumps(result))
    assert isinstance(restored, AnalyzeResult)
    assert restored == result

    class Handler:
        def __init__(self, analyze_result):
            self.buffer = analyze_result.buffer

        @staticmethod
        def analyze(argument):
            return ResultWithBuffer(schema, withSinglePartition=True, buffer="kept")

        def eval(self, argument):
            yield (self.buffer,)

    from pyspark.sql.connect.udtf import _pickled_handler

    function = udtf(Handler, useArrow=False)
    # The handler class as it is sent, pickled, as PySpark Connect's PythonUDTF.command.
    handler = CloudPickleSerializer().loads(_pickled_handler(function.func))
    analysis = handler.analyze(None)
    assert isinstance(analysis, AnalyzeResult)
    assert analysis.schema == schema and analysis.withSinglePartition is True
    assert list(handler(analysis).eval(None)) == [("kept",)]


def test_udtf_analysis_classes_are_the_frozen_dataclasses_of_pyspark():
    # As PySpark's: the arguments and the columns of the analysis of a UDTF are frozen dataclasses,
    # which a handler that captures them pickles with, by reference, of which the Python worker
    # of the server unpickles PySpark's.
    import dataclasses

    from pyspark.serializers import CloudPickleSerializer
    from pyspark.sql.udtf import (
        AnalyzeArgument,
        AnalyzeResult,
        OrderingColumn,
        PartitioningColumn,
        SelectedColumn,
    )

    missing = dataclasses.MISSING
    for cls, fields in [
        (AnalyzeArgument, [("dataType", missing), ("value", missing), ("isTable", missing),
                           ("isConstantExpression", missing)]),
        (PartitioningColumn, [("name", missing)]),
        (OrderingColumn, [("name", missing), ("ascending", True), ("overrideNullsFirst", None)]),
        (SelectedColumn, [("name", missing), ("alias", "")]),
    ]:
        assert dataclasses.is_dataclass(cls) and cls.__dataclass_params__.frozen, cls
        assert cls.__module__ == "pyspark.sql.udtf"
        assert [(f.name, f.default) for f in dataclasses.fields(cls)] == fields
    ordering = OrderingColumn("a", ascending=False)
    with pytest.raises(dataclasses.FrozenInstanceError):
        ordering.name = "b"
    assert ordering == OrderingColumn("a", False) and hash(ordering) == hash(OrderingColumn("a", False))
    assert repr(ordering) == "OrderingColumn(name='a', ascending=False, overrideNullsFirst=None)"
    result = AnalyzeResult(
        T.StructType().add("a", T.StringType()), partitionBy=[PartitioningColumn("a")],
        orderBy=[ordering], select=[SelectedColumn("a", alias="b")],
    )

    def analyze():
        return result

    serializer = CloudPickleSerializer()
    assert serializer.loads(serializer.dumps(analyze))() == result
    assert serializer.loads(serializer.dumps(PartitioningColumn("a"))) == PartitioningColumn("a")


def test_variant_spatial_and_user_defined_values_are_sent_as_pyspark(mock_connect):
    # As PySpark's LocalDataToArrowConversion: a VariantVal is the struct of its value and
    # metadata, a Geometry or a Geography that of its srid and WKB, whose metadata tags the
    # struct as of its type, and a value of a user-defined type is serialized by the UDT and
    # sent as its SQL type; a value of another type for these is malformed, of the condition
    # alone, whose message parameters are None, as PySpark's `PySparkValueError(errorClass=...)`
    # of its converters, also nested.
    import pyarrow as pa
    from pyspark.errors import PySparkValueError
    from pyspark.testing.objects import ExamplePoint

    spark, service = mock_connect
    wkb = bytes.fromhex("0101000000000000000000F03F0000000000000040")
    variant = T.VariantVal(b"\x0c\x01", b"\x01\x00\x00")

    def local_relation(df):
        df.toArrow()
        request = parse_message(service.execute_requests[-1])
        relation = parse_message(parse_message(request[3][0])[1][0])
        while 18 in relation:  # Relation.to_df -> ToDF.input.
            relation = parse_message(parse_message(relation[18][0])[1][0])
        # Relation.local_relation=11 -> LocalRelation.data=1, schema=2.
        local = parse_message(relation[11][0])
        table = pa.ipc.open_stream(local[1][0]).read_all()
        return table, [field["type"] for field in json.loads(local[2][0])["fields"]]

    table, types = local_relation(spark.createDataFrame([
        (variant, T.Geometry.fromWKB(wkb, 4326), T.Geography.fromWKB(wkb, 4326),
         ExamplePoint(1.0, 2.0)),
        (None, None, None, None),
    ]))
    assert types[:3] == [
        T.VariantType().jsonValue(), T.GeometryType(4326).jsonValue(),
        T.GeographyType(4326).jsonValue(),
    ]
    assert types[3]["type"] == "udt" and types[3]["sqlType"]["type"] == "array"
    variant_type, geometry_type, geography_type, udt_type = table.schema.types
    assert variant_type.field("metadata").metadata == {b"variant": b"true"}
    assert geometry_type.field("wkb").metadata == {b"geometry": b"true", b"srid": b"4326"}
    assert geography_type.field("wkb").metadata == {b"geography": b"true", b"srid": b"4326"}
    assert geometry_type.field("srid").type == pa.int32()
    assert pa.types.is_list(udt_type) and udt_type.value_type == pa.float64()
    assert table.to_pylist() == [
        {"_1": {"value": b"\x0c\x01", "metadata": b"\x01\x00\x00"},
         "_2": {"srid": 4326, "wkb": wkb}, "_3": {"srid": 4326, "wkb": wkb}, "_4": [1.0, 2.0]},
        {"_1": None, "_2": None, "_3": None, "_4": None},
    ]
    for ddl, value, condition in (("v variant", "x", "MALFORMED_VARIANT"),
                                  ("g geometry(4326)", "x", "MALFORMED_GEOMETRY"),
                                  ("g geography(4326)", 1, "MALFORMED_GEOGRAPHY"),
                                  ("v array<variant>", ["x"], "MALFORMED_VARIANT"),
                                  ("s struct<g: geometry(4326)>", ("x",), "MALFORMED_GEOMETRY")):
        with pytest.raises(PySparkValueError) as error:
            spark.createDataFrame([(value,)], ddl)
        assert error.value.getCondition() == condition
        assert error.value.getMessageParameters() is None
    # The attributes of PySpark's spatial values.
    geometry = T.Geometry.fromWKB(wkb, 4326)
    assert (geometry.srid, geometry.wkb) == (4326, wkb)


def test_collected_spatial_values_are_their_objects_as_pyspark():
    # As PySpark's ArrowTableToRowsConversion, a collected GEOMETRY or GEOGRAPHY is the
    # Geometry or Geography of its WKB and srid.
    from pyspark.sql.types import _udt_field_converters

    wkb = b"\x01\x01"
    schema = T.StructType([
        T.StructField("g", T.GeometryType(4326)),
        T.StructField("gs", T.ArrayType(T.GeographyType(4326))),
    ])
    g, gs = _udt_field_converters(schema)
    assert g(Row(srid=4326, wkb=wkb)) == T.Geometry.fromWKB(wkb, 4326)
    assert gs([Row(srid=4326, wkb=wkb), None]) == [T.Geography.fromWKB(wkb, 4326), None]
    assert g(None) is None


def test_spatial_types_are_parsed_of_their_json_as_pyspark():
    # As PySpark's _parse_datatype_json_value, of the patterns of the JSON of the spatial types:
    # the default CRS OGC:CRS84 and algorithm SPHERICAL without them, the CRSs of geo_utils and
    # SRID:ANY of any case, and the errors of PySpark of the other forms.
    from pyspark.errors import IllegalArgumentException, PySparkValueError
    from pyspark.sql.types import _parse_datatype_json_string, _parse_datatype_json_value

    valid = [
        ("geometry", T.GeometryType(4326)),
        ("geometry(OGC:CRS84)", T.GeometryType(4326)),
        ("geometry(EPSG:3857)", T.GeometryType(3857)),
        ("geometry(SRID:0)", T.GeometryType(0)),
        ("geometry(srid:any)", T.GeometryType("ANY")),
        ("geography", T.GeographyType(4326)),
        ("geography(SPHERICAL)", T.GeographyType(4326)),
        ("geography(OGC:CRS84, SPHERICAL)", T.GeographyType(4326)),
        ("geography(SRID:ANY)", T.GeographyType("ANY")),
    ]
    for json_value, expected in valid:
        assert _parse_datatype_json_value(json_value) == expected
        assert _parse_datatype_json_string(expected.json()) == expected
    invalid = [
        ("geometry(4326)", PySparkValueError, "CANNOT_PARSE_DATATYPE"),
        ("geometry()", PySparkValueError, "CANNOT_PARSE_DATATYPE"),
        ("geometry(SRID:1)", IllegalArgumentException, "ST_INVALID_CRS_VALUE"),
        ("geometry(ocg:crs84)", IllegalArgumentException, "ST_INVALID_CRS_VALUE"),
        ("geography(4326)", IllegalArgumentException, "ST_INVALID_ALGORITHM_VALUE"),
        ("geography(EPSG:3857)", IllegalArgumentException, "ST_INVALID_CRS_VALUE"),
        ("geography(OGC:CRS84, spherical)", IllegalArgumentException, "ST_INVALID_ALGORITHM_VALUE"),
        ("geography(SRID:0,)", PySparkValueError, "CANNOT_PARSE_DATATYPE"),
    ]
    for json_value, error, condition in invalid:
        with pytest.raises(error) as e:
            _parse_datatype_json_value(json_value)
        assert e.value.getCondition() == condition
    # Of the classmethods `_from_crs` of the types, of which PySpark's JSON parses them.
    assert T.GeometryType._from_crs("EPSG:3857") == T.GeometryType(3857)
    assert T.GeometryType._from_crs("srid:ANY") == T.GeometryType("ANY")
    assert T.GeographyType._from_crs("OGC:CRS84", "SPHERICAL") == T.GeographyType(4326)
    for make, condition in [
        (lambda: T.GeometryType._from_crs("EPSG:4326"), "ST_INVALID_CRS_VALUE"),
        (lambda: T.GeographyType._from_crs("SRID:0", "SPHERICAL"), "ST_INVALID_CRS_VALUE"),
        (lambda: T.GeographyType._from_crs("OGC:CRS84", "PLANAR"), "ST_INVALID_ALGORITHM_VALUE"),
    ]:
        with pytest.raises(IllegalArgumentException) as e:
            make()
        assert e.value.getCondition() == condition


def test_a_server_side_session_change_stops_the_session_as_pyspark():
    # As PySpark's, a server-side session ID that changes closes the client: the session is
    # stopped and no longer the active session, getOrCreate() makes a working session, and
    # stop() of the closed session sends no ReleaseSession.
    import grpc
    import pyspark.sql.connect.proto as pb2
    from pyspark.errors import PySparkAssertionError

    pytest.importorskip("grpc")
    server_side_ids = ["srv-A"]
    released = []

    def config(raw, context):
        request = pb2.ConfigRequest.FromString(raw)
        if request.operation.HasField("get"):
            keys = list(request.operation.get.keys)
        else:
            keys = [pair.key for pair in request.operation.get_with_default.pairs]
        response = pb2.ConfigResponse(
            session_id=request.session_id, server_side_session_id=server_side_ids[0]
        )
        for key in keys:
            response.pairs.add(key=key, value="value")
        return response.SerializeToString()

    def release_session(raw, context):
        request = pb2.ReleaseSessionRequest.FromString(raw)
        released.append(request.session_id)
        return pb2.ReleaseSessionResponse(
            session_id=request.session_id, server_side_session_id=server_side_ids[0]
        ).SerializeToString()

    server = grpc.server(ThreadPoolExecutor(max_workers=4))
    server.add_generic_rpc_handlers(
        (
            grpc.method_handlers_generic_handler(
                "spark.connect.SparkConnectService",
                {
                    "Config": grpc.unary_unary_rpc_method_handler(config),
                    "ReleaseSession": grpc.unary_unary_rpc_method_handler(release_session),
                },
            ),
        )
    )
    port = server.add_insecure_port("127.0.0.1:0")
    server.start()
    remote = f"sc://127.0.0.1:{port}"
    key = "spark.sql.shuffle.partitions"
    try:
        spark = SparkSession.builder.remote(remote).getOrCreate()
        assert spark.conf.get(key) == "value"
        assert not spark.is_stopped

        server_side_ids[0] = "srv-B"
        with pytest.raises(PySparkAssertionError, match="server side session identifier"):
            spark.conf.get(key)
        assert spark.is_stopped and spark._client.is_closed
        assert SparkSession.getActiveSession() is None

        new = SparkSession.builder.remote(remote).getOrCreate()
        try:
            assert new is not spark and not new.is_stopped
            assert new.conf.get(key) == "value"
            spark.stop()
            assert released == []
        finally:
            new.stop()
        assert len(released) == 1
    finally:
        server.stop(0).wait()


def test_variant_and_geo_values():
    from pyspark.sql.types import Geography, Geometry, VariantVal
    v = VariantVal.parseJson('{"a": 1, "b": [2, 3]}')
    assert v.toJson() == '{"a":1,"b":[2,3]}'
    assert v.toPython() == {"a": 1, "b": [2, 3]}
    g = Geometry(b"\x01\x02", 4326)
    assert g.getSrid() == 4326 and g.getBytes() == b"\x01\x02"
    assert g == Geometry.fromWKB(b"\x01\x02", 4326)
    gg = Geography.fromWKB(b"\x03", 4326)
    assert gg.getSrid() == 4326 and gg.getBytes() == b"\x03"


