def test_struct_types_give_back_their_struct_field_objects_as_pyspark():
    # As PySpark's StructType, which holds its fields: the fields, the items of a name or an
    # index, the iteration and a slice give back the StructField objects that the struct was
    # made of or added, and the same objects of the others each time.
    f1 = T.StructField("f1", T.StringType(), True)
    struct = T.StructType([f1, T.StructField("f2", T.IntegerType())])
    assert struct.fields[0] is f1 and struct["f1"] is f1 and struct[0] is f1
    assert list(struct)[0] is f1 and struct[0:1].fields[0] is f1
    assert struct[1] is struct["f2"] is struct.fields[1] and struct[-1] is struct.fields[1]
    added = T.StructType().add("f1", T.StringType(), True).add("f2", T.StringType(), True, None)
    assert added["f1"] is added.fields[0] and added[0] is added.fields[0]
    assert added[0:1] == T.StructType(added.fields[0:1])
    g = T.StructField("g", T.LongType())
    assert added.add(g).fields[2] is g and added["g"] is g and added.names == ["f1", "f2", "g"]
    parsed = T._parse_datatype_json_string(struct.json())
    assert parsed["f1"] is parsed.fields[0] and parsed == struct




def test_struct_type_fields_is_the_live_list_of_the_struct():
    # As PySpark's StructType, whose `fields` is a list attribute that the struct keeps: the
    # same list each time, and an edit of it (append, item, pop, sort, del) is an edit of the
    # struct, which its simpleString, json, len, iteration and indexing show.
    st = T.StructType([T.StructField("a", T.IntegerType()), T.StructField("b", T.StringType())])
    fields = st.fields
    assert st.fields is fields
    fields.append(T.StructField("c", T.LongType(), False))
    assert st.simpleString() == "struct<a:int,b:string,c:bigint>"
    assert len(st) == 3 and [f.name for f in st] == ["a", "b", "c"]
    assert st[2].nullable is False and '"nullable":false' in st.json()
    fields[0] = T.StructField("z", T.DateType())
    assert st.simpleString() == "struct<z:date,b:string,c:bigint>"
    assert st["z"] is fields[0] and st[0] is fields[0]
    assert fields.pop().name == "c" and st.simpleString() == "struct<z:date,b:string>"
    fields.sort(key=lambda f: f.name, reverse=True)
    assert [f.name for f in st] == ["z", "b"]
    del fields[0]
    assert st.simpleString() == "struct<b:string>" and len(st) == 1


def test_struct_type_add_keeps_the_fields_list():
    # As PySpark's add, which appends to the list the struct keeps, so a list kept before
    # add sees the new field, and a field appended to the list is seen by add's struct.
    st = T.StructType([T.StructField("a", T.IntegerType())])
    fields = st.fields
    st.add("b", T.StringType())
    assert st.fields is fields and len(fields) == 2 and fields[1].name == "b"
    fields.append(T.StructField("c", T.LongType()))
    st.add(T.StructField("d", T.LongType()))
    assert [f.name for f in fields] == ["a", "b", "c", "d"]
    assert st.simpleString() == "struct<a:int,b:string,c:bigint,d:bigint>"


def test_struct_type_names_are_apart_from_fields():
    # As PySpark's StructType: `names` is a list of its own, which __init__ and add set and
    # nothing else sets. So fieldNames() (a copy of names) does not follow an edit of fields,
    # while simpleString, json, len and the fields do; and a rename of a field is not a name.
    st = T.StructType([T.StructField("a", T.IntegerType())])
    assert st.names is st.names and st.fieldNames() is not st.names
    st.fields.append(T.StructField("b", T.StringType()))
    assert st.fieldNames() == ["a"] and st.names == ["a"]
    assert st.simpleString() == "struct<a:int,b:string>" and len(st) == 2
    st.add("c", T.LongType())
    assert st.fieldNames() == ["a", "c"] and st.names == ["a", "c"]
    st.names.append("n")
    assert st.fieldNames() == ["a", "c", "n"]
    st.fieldNames().append("m")
    assert st.fieldNames() == ["a", "c", "n"]
    st.fields[0].name = "renamed"
    assert st.fieldNames() == ["a", "c", "n"] and st.names == ["a", "c", "n"]
    assert st[0].name == "renamed" and st["renamed"] is st.fields[0]
    assert st != T.StructType(list(st.fields))


def test_struct_field_attributes_are_assignable():
    # As PySpark's StructField, whose name, dataType, nullable and metadata are plain
    # attributes: an assignment of them is the field's, and so is the struct's the field is in.
    # This is how the nullability of a schema is changed in place.
    f = T.StructField("n", T.IntegerType())
    st = T.StructType([f])
    f.nullable = False
    assert st.simpleString() == "struct<n:int>" and st[0].nullable is False
    assert st.json() == T.StructType([T.StructField("n", T.IntegerType(), False)]).json()
    f.name = "m"
    assert st.simpleString() == "struct<m:int>" and st.fieldNames() == ["n"]
    f.dataType = T.StringType()
    assert st.simpleString() == "struct<m:string>" and f.simpleString() == "m:string"
    f.metadata = {"k": "v"}
    assert '"metadata":{"k":"v"}' in st.json() and st.fields[0].metadata == {"k": "v"}
    fresh = T.StructType([T.StructField("m", T.StringType(), False, {"k": "v"})])
    assert T.StructType([f]) == fresh and st.json() == fresh.json()
    assert T.StructType([f]) != T.StructType([T.StructField("m", T.StringType(), True)])
    parsed = pickle.loads(pickle.dumps(T.StructType([f])))
    assert parsed.json() == fresh.json() and parsed.simpleString() == "struct<m:string>"
    assert pickle.loads(pickle.dumps(f)) == fresh[0]


def test_struct_type_edits_reach_its_core_type():
    # The live view: a UDF's return type and the JSON of a struct read the fields as they are
    # now, after edits of the list and of the fields in place.
    from pyspark.sql import functions as F

    st = T.StructType([T.StructField("a", T.LongType())])
    st.fields.append(T.StructField("b", T.DoubleType(), False))
    st.fields[0].nullable = False
    wrapper = F.udf(lambda x: x, returnType=st)
    assert wrapper.returnType.simpleString() == "struct<a:bigint,b:double>"
    assert wrapper.returnType.fields[0].nullable is False
    assert T._parse_datatype_json_string(st.json()).simpleString() == "struct<a:bigint,b:double>"
    assert st.toNullable().simpleString() == "struct<a:bigint,b:double>"
    assert st.toNullable().fields[1].nullable is True
    assert st[1:].simpleString() == "struct<b:double>"


def test_struct_type_nested_types_are_kept_as_pyspark_keeps_them():
    # As PySpark's attributes: dataType, elementType, keyType and valueType are the same object
    # each time, and an edit of a nested type, in place or through its parent, is seen by the
    # outer type: its json, simpleString, equality and pickling, and a walk of its fields.
    def nested():
        return T.StructType([
            T.StructField("s", T.StructType([T.StructField("x", T.IntegerType())])),
            T.StructField("a", T.ArrayType(T.StructType([T.StructField("y", T.IntegerType())]))),
            T.StructField("m", T.MapType(
                T.StringType(), T.StructType([T.StructField("z", T.IntegerType())]))),
        ])

    st = nested()
    assert st["s"].dataType is st["s"].dataType
    assert st["a"].dataType.elementType is st["a"].dataType.elementType
    assert st["m"].dataType.valueType is st["m"].dataType.valueType
    element = T.StringType()
    assert T.ArrayType(element).elementType is element
    assert T.MapType(element, element).keyType is element

    def walk(schema, nullable):
        for field in schema.fields:
            field.nullable = nullable
            if isinstance(field.dataType, T.StructType):
                walk(field.dataType, nullable)

    walked = nested()
    walk(walked, False)
    assert walked.json().count('"nullable":false') == 4
    assert walked.simpleString() == "struct<s:struct<x:int>,a:array<struct<y:int>>,m:map<string,struct<z:int>>>"

    edited = nested()
    edited["a"].dataType.elementType.fields[0].nullable = False
    edited["m"].dataType.valueType.fields[0].nullable = False
    assert edited.json().count('"nullable":false') == 2
    assert edited == T.StructType(list(edited.fields))
    assert pickle.loads(pickle.dumps(edited)).json() == edited.json()
    assert hash(edited) == hash(T.StructType(list(edited.fields)))


def test_struct_type_introspection():
    """StructType.fields / names / __getitem__ / __iter__ / __len__ + chainable add."""
    st = T.StructType(
        [T.StructField("a", T.IntegerType(), True), T.StructField("b", T.StringType(), False)]
    )
    assert len(st) == 2
    assert st.names == ["a", "b"] == st.fieldNames()
    assert [f.name for f in st.fields] == ["a", "b"]
    assert [type(f.dataType).__name__ for f in st.fields] == ["IntegerType", "StringType"]
    # index by position and by name
    assert st[0].name == "a"
    assert st["b"].name == "b"
    assert not st["b"].nullable
    # iteration
    assert [f.name for f in st] == ["a", "b"]
    # slice yields a StructType
    sl = st[0:1]
    assert isinstance(sl, T.StructType)
    assert sl.fieldNames() == ["a"]
    # out-of-range + missing name
    with pytest.raises(IndexError):
        _ = st[5]
    with pytest.raises(KeyError):
        _ = st["nope"]
    # chainable add
    st2 = T.StructType().add("x", "integer").add("y", T.StringType(), False).add(
        T.StructField("z", T.IntegerType())
    )
    assert st2.fieldNames() == ["x", "y", "z"]
    assert isinstance(st2, T.StructType)


def test_struct_types_take_their_keys_and_fields_as_pyspark():
    # As PySpark's StructType: __getitem__ raises KEY_NOT_EXISTS of a name,
    # INDEX_OUT_OF_RANGE of an index and NOT_EXPECTED_TYPE of another key, and add takes the
    # JSON value of a data type as a str, and requires a data type of a name.
    from pyspark.errors import (
        PySparkIndexError,
        PySparkKeyError,
        PySparkTypeError,
        PySparkValueError,
    )
    from pyspark.sql import types as T

    st = T.StructType([T.StructField("a", T.IntegerType())])
    with pytest.raises(PySparkKeyError) as e:
        st["zz"]
    assert e.value.getCondition() == "KEY_NOT_EXISTS"
    assert e.value.getMessageParameters() == {"key": "zz"}
    for index in (1, -2):
        with pytest.raises(PySparkIndexError) as e:
            st[index]
        assert e.value.getMessageParameters() == {"arg_name": "StructType", "index": str(index)}
    assert st[-1].name == "a"
    with pytest.raises(PySparkTypeError) as e:
        st[1.5]
    assert e.value.getMessageParameters() == {
        "expected_type": "int, slice or str",
        "arg_name": "key",
        "arg_type": "float",
    }
    added = T.StructType().add("a", "integer").add("b", "decimal(10,2)", False)
    assert added.simpleString() == "struct<a:int,b:decimal(10,2)>"
    assert added["b"].nullable is False
    with pytest.raises(PySparkValueError) as e:
        T.StructType().add("a", "int")
    assert e.value.getCondition() == "CANNOT_PARSE_DATATYPE"
    with pytest.raises(PySparkValueError) as e:
        T.StructType().add("a")
    assert e.value.getCondition() == "ARGUMENT_REQUIRED"


def test_struct_field_attributes():
    """StructField exposes name / dataType / nullable / metadata and a faithful repr/eq."""
    f = T.StructField("m", T.IntegerType(), True, {"k": "v"})
    assert f.name == "m"
    assert isinstance(f.dataType, T.IntegerType)
    assert f.nullable is True
    assert f.metadata == {"k": "v"}
    assert repr(f) == "StructField('m', IntegerType(), True)"
    assert f == T.StructField("m", T.IntegerType(), True, {"k": "v"})
    assert f != T.StructField("m", T.StringType(), True)


def test_user_defined_type():
    """UserDefinedType subclasses the Rust DataType and round-trips via json/fromJson."""
    import sys
    import types as _pytypes

    # Define the UDT in an importable module so cloudpickle serializes it by reference.
    mod = _pytypes.ModuleType("_udt_test_mod")
    sys.modules["_udt_test_mod"] = mod
    src = (
        "from pyspark.sql.types import UserDefinedType, ArrayType, DoubleType\n"
        "class PointUDT(UserDefinedType):\n"
        "    @classmethod\n"
        "    def sqlType(cls): return ArrayType(DoubleType(), False)\n"
        "    @classmethod\n"
        "    def module(cls): return '_udt_test_mod'\n"
        "    def serialize(self, obj): return [obj[0], obj[1]]\n"
        "    def deserialize(self, datum): return (datum[0], datum[1])\n"
    )
    exec(compile(src, "_udt_test_mod", "exec"), mod.__dict__)
    PointUDT = mod.PointUDT

    u = PointUDT()
    assert isinstance(u, T.DataType)
    assert isinstance(u, T.UserDefinedType)
    assert u.typeName() == "pointudt"
    assert u.simpleString() == "udt"
    assert u.needConversion() is True
    assert u.scalaUDT() == ""
    # serialize / deserialize round-trip
    assert u.serialize((1.0, 2.0)) == [1.0, 2.0]
    assert u.deserialize([1.0, 2.0]) == (1.0, 2.0)
    # jsonValue carries the udt envelope
    jv = u.jsonValue()
    assert jv["type"] == "udt"
    assert jv["pyClass"] == "_udt_test_mod.PointUDT"
    assert "serializedClass" in jv
    assert jv["sqlType"] == T.ArrayType(T.DoubleType(), False).jsonValue()
    # embed in a schema and parse it back -> reconstructs the UDT class
    sch = T.StructType([T.StructField("p", u, True)])
    rt = T._parse_datatype_json_string(sch.json())
    assert isinstance(rt.fields[0].dataType, PointUDT)
    del sys.modules["_udt_test_mod"]


def test_user_defined_type_not_implemented():
    """The abstract UDT hooks raise the pyspark NOT_IMPLEMENTED error."""
    from pyspark.errors import PySparkNotImplementedError

    class Bare(T.UserDefinedType):
        pass

    with pytest.raises(PySparkNotImplementedError):
        Bare.sqlType()
    with pytest.raises(PySparkNotImplementedError):
        Bare.module()
    with pytest.raises(PySparkNotImplementedError):
        Bare().serialize(object())
    with pytest.raises(PySparkNotImplementedError):
        Bare().deserialize(object())


# --------------------------------------------------------------------------- utils

def test_get_lit_sql_str():
    """Test SQL string literal escaping."""
    from pyspark.sql.utils import get_lit_sql_str

    # Simple strings
    assert get_lit_sql_str("hello") == "'hello'"
    assert get_lit_sql_str("") == "''"

    # Backslash escaping
    assert get_lit_sql_str("a\\b") == "'a\\\\b'"

    # Quote escaping
    assert get_lit_sql_str("it's") == "'it\\'s'"

    # Combined
    assert get_lit_sql_str("path\\to\\'file") == "'path\\\\to\\\\\\'file'"


def test_numpy_helper_linspace():
    """Test NumpyHelper.linspace for generating float sequences."""
    from pyspark.sql.utils import NumpyHelper

    # Single point
    assert NumpyHelper.linspace(0, 10, 1) == [0.0]

    # Two points
    assert NumpyHelper.linspace(0, 10, 2) == [0.0, 10.0]

    # Three points
    result = NumpyHelper.linspace(0, 10, 3)
    assert len(result) == 3
    assert result[0] == 0.0
    assert result[-1] == 10.0
    assert abs(result[1] - 5.0) < 1e-10

    # Negative range
    result = NumpyHelper.linspace(-10, 10, 5)
    assert len(result) == 5
    assert result[0] == -10.0
    assert result[-1] == 10.0


def test_version_utils_major_minor_version():
    """Test VersionUtils.majorMinorVersion parsing."""
    from pyspark.util import VersionUtils

    # Standard versions
    assert VersionUtils.majorMinorVersion("2.4.0") == (2, 4)
    assert VersionUtils.majorMinorVersion("3.0.0") == (3, 0)
    assert VersionUtils.majorMinorVersion("4.2.1") == (4, 2)

    # SNAPSHOT versions
    assert VersionUtils.majorMinorVersion("2.3.0-SNAPSHOT") == (2, 3)
    assert VersionUtils.majorMinorVersion("3.5.1-SNAPSHOT") == (3, 5)

    # Single digit
    assert VersionUtils.majorMinorVersion("1.0") == (1, 0)

    # Invalid versions
    with pytest.raises(ValueError):
        VersionUtils.majorMinorVersion("invalid")
    with pytest.raises(ValueError):
        VersionUtils.majorMinorVersion("a.b.c")
    with pytest.raises(ValueError):
        VersionUtils.majorMinorVersion("1")


