def test_the_exception_of_a_done_call_replaces_the_error_of_a_batch_as_pyspark(mock_connect):
    # As PySpark's Progress.__exit__, which makes the done call when the decoding of a batch raises
    # in the `with` of the execution: the exception of the done call replaces that error, for
    # collect as for an iterator, instead of going unreported when the execution is dropped.
    spark, service = mock_connect
    # ExecutePlanResponse.arrow_batch=2: row_count=1, data=2 of bytes that are not Arrow IPC.
    service.execute_payload = message_field(2, varint_field(1, 1) + message_field(2, b"not arrow"))
    error = ValueError("the done call raises")

    def failing(**kwargs):
        if kwargs["done"]:
            raise error

    for action in [lambda: spark.range(3).collect(),
                   lambda: next(spark.range(3).toLocalIterator())]:
        with pytest.raises(Exception) as decoding:
            action()
        assert decoding.value is not error
        spark.registerProgressHandler(failing)
        try:
            with pytest.raises(ValueError) as raised:
                action()
            assert raised.value is error
        finally:
            spark.clearProgressHandlers()


def test_strings_that_utf8_cannot_encode_raise_value_error_as_options_and_fills_as_pyspark(
    mock_connect,
):
    # As PySpark, whose protobuf string fields raise the UnicodeEncodeError, a ValueError, of a str
    # that UTF-8 cannot encode (a lone surrogate), in protobuf's default (upb) backend: an option
    # is not sent as another text (another path), and a fill value raises the error of its
    # encoding rather than a TypeError of its type, when its `NAFill` plan is built.
    spark, service = mock_connect
    bad = "a\ud800b"
    message = re.escape(
        "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed")
    df = spark.range(1)
    # The fill of a value, of a dict's key and of a subset column is sent in a string field too.
    for call in [
        lambda: df.fillna(bad),
        lambda: df.fillna({bad: 1}),
        lambda: df.fillna("x", subset=[bad]),
    ]:
        plan = call()
        with pytest.raises(UnicodeEncodeError, match=message):
            plan.collect()
    assert service.execute_requests == []


def test_strings_that_utf8_cannot_encode_raise_value_error_in_option_keys_conf_and_names_as_pyspark(
    mock_connect,
):
    # As PySpark, whose protobuf string fields raise the UnicodeEncodeError of a str that UTF-8
    # cannot encode, in protobuf's default (upb) backend, for the key of an option, a key or value
    # of the runtime conf, a name of a table and the text of a query.
    spark, service = mock_connect
    bad = "a\ud800b"
    message = re.escape(
        "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed")
    for call in [
        lambda: spark.readStream.format("rate").load().writeStream.option(bad, "v"),
        lambda: spark.conf.set(bad, "v"),
        lambda: spark.conf.set("spark.k", bad),
        lambda: spark.conf.get(bad),
        lambda: spark.conf.unset(bad),
        lambda: spark.conf.isModifiable(bad),
    ]:
        with pytest.raises(UnicodeEncodeError, match=message):
            call()
    query = "select '" + bad + "'"
    with pytest.raises(UnicodeEncodeError) as error:
        spark.sql(query)
    assert str(error.value) == (
        "'utf-8' codec can't encode character '\\ud800' in position 9: surrogates not allowed"
    )
    assert service.execute_requests == []


def test_writers_and_readers_reject_a_path_that_is_not_a_str_as_pyspark(mock_connect):
    # As PySpark's upb protobuf backend, which raises a TypeError of this message for a path
    # that is not a str, in every writer method and in DataStreamWriter.start.
    spark, service = mock_connect
    df = spark.range(1)
    stream = spark.readStream.format("rate").load().writeStream
    message = "bad argument type for built-in operation"
    for path in [123, 1.5, ["a", 1], bytearray(b"p")]:
        for call in [
            lambda: df.write.save(path),
            lambda: df.write.json(path),
            lambda: df.write.csv(path),
            lambda: df.write.parquet(path),
            lambda: df.write.orc(path),
            lambda: df.write.text(path),
            lambda: df.write.xml(path),
            lambda: stream.start(path),
        ]:
            with pytest.raises(TypeError) as error:
                call()
            assert type(error.value) is TypeError and str(error.value) == message
    assert service.execute_requests == []


def test_writers_take_a_bytes_path_as_pyspark(mock_connect):
    # As PySpark's default protobuf backend (upb), which sets a bytes value of a string field as
    # its UTF-8 text: the writers and DataStreamWriter.start write to a bytes path, and bytes that
    # are not UTF-8 raise the UnicodeDecodeError of their decoding.
    spark, service = mock_connect

    def sent_command():
        # ExecutePlanRequest.plan=3 -> Plan.command=2.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(plan[2][0])

    for write in [
        lambda path: spark.range(1).write.save(path),
        lambda path: spark.range(1).write.json(path),
        lambda path: spark.range(1).write.parquet(path),
    ]:
        write(b"p")
        # Command.write_operation=2 -> WriteOperation.path=3.
        assert parse_message(sent_command()[2][0])[3] == [b"p"]
        with pytest.raises(UnicodeDecodeError) as error:
            write(b"\xff")
        assert str(error.value) == (
            "'utf-8' codec can't decode byte 0xff in position 0: invalid start byte"
        )
    # ExecutePlanResponse.write_stream_operation_start_result=8: query_id=1 (id=1, run_id=2).
    service.execute_payload = message_field(
        8, message_field(1, message_field(1, "q") + message_field(2, "r")))
    spark.readStream.format("rate").load().writeStream.start(b"s")
    # Command.write_stream_operation_start=6 -> WriteStreamOperationStart.path=11.
    assert parse_message(sent_command()[6][0])[11] == [b"s"]


def test_catalog_takes_bytes_names_and_paths_as_pyspark(mock_connect):
    # As PySpark's catalog, which sets each name, pattern and path in a string field of its plan
    # as it is, which protobuf's default backend (upb) converts: bytes are sent decoded, bytes
    # that are not UTF-8 raise the UnicodeDecodeError of their decoding, and another object the
    # TypeError of the field, before any request. The mock answers each request with no rows.
    spark, service = mock_connect
    catalog = spark.catalog
    # Relation.catalog=200 -> the Catalog operation of each call, of these string fields.
    for call, operation, fields in [
        (lambda: catalog.setCurrentCatalog(b"c"), 25, {1: [b"c"]}),
        (lambda: catalog.listCatalogs(b"c*"), 26, {1: [b"c*"]}),
        (lambda: catalog.setCurrentDatabase(b"d"), 2, {1: [b"d"]}),
        (lambda: catalog.listDatabases(b"d*"), 3, {1: [b"d*"]}),
        (lambda: catalog.getDatabase(b"d"), 7, {1: [b"d"]}),
        (lambda: catalog.databaseExists(b"d"), 10, {1: [b"d"]}),
        (lambda: catalog.listTables(b"d", b"t*"), 4, {1: [b"d"], 2: [b"t*"]}),
        (lambda: catalog.getTable(b"t"), 8, {1: [b"t"]}),
        (lambda: catalog.tableExists(b"t"), 11, {1: [b"t"]}),
        (lambda: catalog.listFunctions(b"d", b"f*"), 5, {1: [b"d"], 2: [b"f*"]}),
        (lambda: catalog.getFunction(b"f"), 9, {1: [b"f"]}),
        (lambda: catalog.functionExists(b"f"), 12, {1: [b"f"]}),
        (lambda: catalog.listColumns(b"t"), 6, {1: [b"t"]}),
        (lambda: catalog.dropTempView(b"v"), 15, {1: [b"v"]}),
        (lambda: catalog.dropGlobalTempView(b"v"), 16, {1: [b"v"]}),
        (lambda: catalog.recoverPartitions(b"t"), 17, {1: [b"t"]}),
        (lambda: catalog.isCached(b"t"), 18, {1: [b"t"]}),
        (lambda: catalog.cacheTable(b"t"), 19, {1: [b"t"]}),
        (lambda: catalog.uncacheTable(b"t"), 20, {1: [b"t"]}),
        (lambda: catalog.refreshTable(b"t"), 22, {1: [b"t"]}),
        (lambda: catalog.refreshByPath(b"/p"), 23, {1: [b"/p"]}),
        (lambda: catalog.dropTable(b"t"), 27, {1: [b"t"]}),
        (lambda: catalog.dropView(b"v"), 28, {1: [b"v"]}),
        # CreateDatabase.properties=3, a map of strings, of entries of key=1 and value=2.
        (lambda: catalog.createDatabase(b"d", properties={b"k": b"v"}), 29,
         {1: [b"d"], 3: [message_field(1, "k") + message_field(2, "v")]}),
        (lambda: catalog.dropDatabase(b"d"), 30, {1: [b"d"]}),
        (lambda: catalog.listPartitions(b"t"), 31, {1: [b"t"]}),
        (lambda: catalog.listViews(b"d", b"v*"), 32, {1: [b"d"], 2: [b"v*"]}),
        (lambda: catalog.getTableProperties(b"t"), 33, {1: [b"t"]}),
        (lambda: catalog.getCreateTableString(b"t"), 34, {1: [b"t"]}),
        (lambda: catalog.truncateTable(b"t"), 35, {1: [b"t"]}),
        (lambda: catalog.analyzeTable(b"t"), 36, {1: [b"t"]}),
    ]:
        requests = len(service.execute_requests)
        with contextlib.suppress(Exception):
            call()
        assert len(service.execute_requests) == requests + 1
        assert _sent_catalog(service.execute_requests[-1], operation) == fields
    requests = len(service.execute_requests)
    for name, error in [(b"\xff", UnicodeDecodeError), (1, TypeError)]:
        for call in [
            lambda: catalog.setCurrentDatabase(name),
            lambda: catalog.listTables(pattern=name),
            lambda: catalog.getTable(name),
            lambda: catalog.cacheTable(name),
            lambda: catalog.refreshByPath(name),
            lambda: catalog.dropTable(name),
            lambda: catalog.createDatabase("d", properties={"k": name}),
            lambda: catalog.listViews(name),
        ]:
            with pytest.raises(error) as e:
                call()
            assert type(e.value) is error
    # None is the TypeError of a field that PySpark's plan sets, while the constructor of the
    # message of cacheTable, dropTable, dropView, createDatabase and dropDatabase leaves it unset.
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        catalog.getTable(None)
    assert len(service.execute_requests) == requests
    for call, operation in [
        (lambda: catalog.cacheTable(None), 19),
        (lambda: catalog.dropTable(None), 27),
        (lambda: catalog.dropView(None), 28),
        (lambda: catalog.createDatabase(None), 29),
        (lambda: catalog.dropDatabase(None), 30),
    ]:
        with contextlib.suppress(Exception):
            call()
        assert _sent_catalog(service.execute_requests[-1], operation) == {}


def test_catalog_converts_its_names_in_the_order_of_pyspark(mock_connect):
    from pyspark.errors import PySparkTypeError

    spark, service = mock_connect
    catalog = spark.catalog
    requests = len(service.execute_requests)
    # createTable checks the schema, and then its plan sets the table, the path, the source and
    # the description, in this order, before the options.
    with pytest.raises(PySparkTypeError) as error:
        catalog.createTable(1, schema=5)
    assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
    for kwargs, error in [
        ({"tableName": b"\xff", "path": 1}, UnicodeDecodeError),
        ({"tableName": "t", "path": b"\xff", "source": 1}, UnicodeDecodeError),
        ({"tableName": "t", "path": 1, "source": b"\xff"}, TypeError),
        ({"tableName": "t", "source": 1, "description": b"\xff"}, TypeError),
        ({"tableName": "t", "description": b"\xff", "k": 1}, UnicodeDecodeError),
    ]:
        with pytest.raises(error) as e:
            catalog.createTable(**kwargs)
        assert type(e.value) is error
    # createExternalTable warns first, and the deprecated dbName warns before the names are set.
    with pytest.warns(FutureWarning, match="createExternalTable is deprecated"):
        with pytest.raises(UnicodeDecodeError):
            catalog.createExternalTable(b"\xff")
    for call in [
        lambda: catalog.tableExists(1, 2),
        lambda: catalog.functionExists(1, 2),
        lambda: catalog.listColumns(1, 2),
    ]:
        with pytest.warns(FutureWarning, match="`dbName` has been deprecated"):
            with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
                call()
    # cacheTable sets the table before it converts the storage level.
    with pytest.raises(UnicodeDecodeError):
        catalog.cacheTable(b"\xff", "not a level")
    assert len(service.execute_requests) == requests
    # listViews of a pattern without a database asks for the current database first.
    with contextlib.suppress(Exception):
        catalog.listViews(pattern=1)
    assert len(service.execute_requests) == requests + 1
    assert _sent_catalog(service.execute_requests[-1], 1) == {}
    catalog.createTable(b"t", path=b"/p", source=b"parquet", description=b"d")
    # Catalog.create_table=14: table_name=1, path=2, source=3 and description=4.
    create = _sent_catalog(service.execute_requests[-1], 14)
    assert (create[1], create[2], create[3], create[4]) == ([b"t"], [b"/p"], [b"parquet"], [b"d"])
    with pytest.warns(FutureWarning):
        catalog.createExternalTable(b"e", path=b"/e")
    create = _sent_catalog(service.execute_requests[-1], 14)
    assert (create[1], create[2]) == ([b"e"], [b"/e"])


def test_tables_of_the_writers_readers_and_views_take_bytes_as_pyspark(mock_connect):
    # As PySpark, which sets the table of saveAsTable, insertInto, read.table, changes and the
    # stream reader's, and the name of a view, in a string field of its plan as it is: bytes are
    # sent decoded, as protobuf's default backend (upb) converts them.
    from pyspark.errors import AnalysisException, PySparkTypeError

    spark, service = mock_connect
    df = spark.range(1)

    def sent_command():
        # ExecutePlanRequest.plan=3 -> Plan.command=2.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(plan[2][0])

    # Command.write_operation=2 -> WriteOperation.table=4 -> SaveTable.table_name=1 and
    # save_method=2 (TABLE_SAVE_METHOD_SAVE_AS_TABLE=1, TABLE_SAVE_METHOD_INSERT_INTO=2).
    df.write.saveAsTable(b"t")
    assert parse_message(parse_message(sent_command()[2][0])[4][0]) == {1: [b"t"], 2: [1]}
    df.write.insertInto(b"t")
    assert parse_message(parse_message(sent_command()[2][0])[4][0]) == {1: [b"t"], 2: [2]}
    # The table of None is no table, so that the write is that of save() without a path
    # (WriteOperation.path=3), here of WriteOperation.source=2.
    for write in [df.write.format("noop").saveAsTable, df.write.format("noop").insertInto]:
        write(None)
        operation = parse_message(sent_command()[2][0])
        assert 3 not in operation and 4 not in operation and operation[2] == [b"noop"]
    # Command.create_dataframe_view=3 -> CreateDataFrameViewCommand.name=2.
    for create in [df.createTempView, df.createOrReplaceTempView, df.createGlobalTempView,
                   df.createOrReplaceGlobalTempView, df.registerTempTable]:
        create(b"v")
        assert parse_message(sent_command()[3][0])[2] == [b"v"]
    # Relation.read=2 -> Read.named_table=1 -> NamedTable.unparsed_identifier=1, and
    # Relation.relation_changes=46 -> RelationChanges.unparsed_identifier=1, in the requests of
    # the schema.
    for read in [spark.read.table, spark.readStream.table]:
        assert read(b"t").schema is not None
        named_table = parse_message(_sent_relation(service.analyze_requests[-1], 2)[1][0])
        assert named_table[1] == [b"t"]
    for changes in [spark.read.changes, spark.readStream.changes]:
        assert changes(b"t").schema is not None
        assert _sent_relation(service.analyze_requests[-1], 46)[1] == [b"t"]
    requests = (len(service.analyze_requests), len(service.execute_requests))
    for name, error in [(b"\xff", UnicodeDecodeError), (1, TypeError)]:
        for call in [
            lambda: df.write.saveAsTable(name),
            lambda: df.write.insertInto(name),
            lambda: df.createTempView(name),
            lambda: df.createOrReplaceGlobalTempView(name),
            lambda: df.registerTempTable(name),
        ]:
            with pytest.raises(error) as e:
                call()
            assert type(e.value) is error
    # The table of a read, and of changes, is converted when its plan is built, not at the call,
    # as PySpark's is: the DataFrame is given, and its plan raises the error.
    for name, error in [(b"\xff", UnicodeDecodeError), (1, TypeError)]:
        for read in [spark.read.table, spark.read.changes]:
            with pytest.raises(error) as e:
                read(name).collect()
            assert type(e.value) is error
        for read in [spark.readStream.table, spark.readStream.changes]:
            with pytest.raises(error) as e:
                read(name).isStreaming
            assert type(e.value) is error
    assert (len(service.analyze_requests), len(service.execute_requests)) == requests
    # The write sets the table after the bucket count and before it checks the save mode.
    with pytest.raises(UnicodeDecodeError):
        df.write.mode("bogus").insertInto(b"\xff")
    with pytest.raises(TypeError, match="^Field spark.connect.WriteOperation.BucketBy.num_buckets"):
        df.write.bucketBy(True, "id").saveAsTable(b"\xff")
    # changes checks the schema of its reader first.
    for reader in [spark.read, spark.readStream]:
        with pytest.raises(AnalysisException) as error:
            reader.schema("a INT").changes(b"\xff")
        assert error.value.getCondition() == "_LEGACY_ERROR_TEMP_1189"
    # spark.table still raises NOT_EXPECTED_TYPE for a name that is not a str, as PySpark's.
    with pytest.raises(PySparkTypeError) as error:
        spark.table(b"t")
    assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
    assert (len(service.analyze_requests), len(service.execute_requests)) == requests


def test_write_to_and_merge_into_set_their_table_at_each_write_as_pyspark(mock_connect):
    # As PySpark's DataFrameWriterV2 and MergeIntoWriter, which keep the table as it is given and
    # set it in the string field of the command of each write: bytes are sent decoded, None
    # leaves the field unset, and a table that the field does not take fails each write, and
    # not the call that gives it.
    import gc
    import weakref

    from pyspark.errors import PySparkTypeError
    from pyspark.sql import functions as F

    spark, service = mock_connect
    df = spark.range(1)

    def sent_command():
        # ExecutePlanRequest.plan=3 -> Plan.command=2.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(plan[2][0])

    # Command.write_operation_v2=4 -> WriteOperationV2.table_name=2, mode=7 (MODE_APPEND=4).
    df.writeTo(b"t").append()
    operation = parse_message(sent_command()[4][0])
    assert operation[2] == [b"t"] and operation[7] == [4]
    df.writeTo(None).append()
    assert 2 not in parse_message(sent_command()[4][0])
    # Command.merge_into_table_command=16 -> MergeIntoTableCommand.target_table_name=1.
    df.mergeInto(b"t", F.lit(True)).whenMatched().delete().merge()
    assert parse_message(sent_command()[16][0])[1] == [b"t"]
    requests = len(service.execute_requests)
    message = "^bad argument type for built-in operation$"
    writer = df.writeTo(1).option("k", "v")
    for write in [writer.create, writer.replace, writer.createOrReplace, writer.append,
                  writer.overwritePartitions, lambda: writer.overwrite(F.lit(True))]:
        with pytest.raises(TypeError, match=message):
            write()
    writer = df.writeTo(b"\xff")
    with pytest.raises(UnicodeDecodeError):
        writer.append()
    # overwrite converts its condition before the command sets the table.
    with pytest.raises(PySparkTypeError) as error:
        writer.overwrite(123)
    assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
    merge = df.mergeInto(1, F.lit(True)).whenNotMatched().insertAll()
    for _ in range(2):
        with pytest.raises(TypeError, match=message):
            merge.merge()
    with pytest.raises(UnicodeDecodeError):
        df.mergeInto(b"\xff", F.lit(True)).whenMatched().delete().merge()
    assert len(service.execute_requests) == requests

    # The writers keep such a table where Python's garbage collector sees it, which frees a
    # reference cycle through it.
    class Table:
        pass

    for write in [lambda table: df.writeTo(table), lambda table: df.mergeInto(table, F.lit(1))]:
        table = Table()
        table.writer = write(table)
        ref = weakref.ref(table.writer)
        del table
        gc.collect()
        assert ref() is None


def test_writer_formats_take_bytes_and_fail_the_write_as_pyspark(mock_connect):
    # As PySpark's WriteOperation, which sets the source as it is given and converts it at the
    # command: bytes are sent decoded, and another object raises at each write, the TypeError of
    # the field, or the error of its decoding, while the call of format keeps it. A format method
    # of PySpark sets its own format over the kept one.
    spark, service = mock_connect
    df = spark.range(1)

    def sent_operation():
        # ExecutePlanRequest.plan=3 -> Plan.command=2 -> Command.write_operation=2.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(parse_message(plan[2][0])[2][0])

    # WriteOperation.source=2, and WriteOperation.mode=5 (SAVE_MODE_OVERWRITE=2).
    df.write.format(b"noop").mode("overwrite").save()
    assert sent_operation()[2] == [b"noop"] and sent_operation()[5] == [2]
    df.write.save(format=b"noop", mode="overwrite")
    assert sent_operation()[2] == [b"noop"]
    df.write.format(5).format("noop").mode("overwrite").save()
    assert sent_operation()[2] == [b"noop"]
    df.write.format(5).json("p")
    assert sent_operation()[2] == [b"json"]

    # None unsets the format, so that no source is sent.
    df.write.format(None).mode("overwrite").save()
    assert 2 not in sent_operation()
    requests = len(service.execute_requests)
    for source in [5, bytearray(b"noop")]:
        writer = df.write.format(source)
        assert len(service.execute_requests) == requests
        with pytest.raises(TypeError) as error:
            writer.mode("overwrite").save()
        assert str(error.value) == "bad argument type for built-in operation"
    for source, error, message in [
        (b"\xff", UnicodeDecodeError, "'utf-8' codec can't decode byte 0xff in position 0: invalid start byte"),
        ("\ud800", UnicodeEncodeError, "'utf-8' codec can't encode character '\\ud800' in position 0: surrogates not allowed"),
    ]:
        with pytest.raises(error) as raised:
            df.write.format(source).save()
        assert str(raised.value) == message
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        df.write.save(format=5)
    assert len(service.execute_requests) == requests


def test_writer_without_a_mode_sends_it_unspecified_as_pyspark(mock_connect):
    # As PySpark's WriteOperation, whose mode is None until a mode is set, and which sends none
    # then: the protobuf default, UNSPECIFIED=0, which the server writes as an error when the path
    # exists. mode(None) leaves the mode as it is, so it is unspecified too, and a mode set
    # before it stays.
    spark, service = mock_connect
    df = spark.range(1)

    def sent_mode():
        # ExecutePlanRequest.plan=3 -> Plan.command=2 -> Command.write_operation=2 -> mode=5.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        operation = parse_message(parse_message(plan[2][0])[2][0])
        return operation.get(5, [0])[0]

    df.write.format("noop").save()
    assert sent_mode() == 0
    df.write.format("noop").mode(None).save()
    assert sent_mode() == 0
    df.write.format("noop").mode("error").save()
    assert sent_mode() == 3
    df.write.format("noop").mode("error").mode(None).save()
    assert sent_mode() == 3
    df.write.format("noop").mode("overwrite").save()
    assert sent_mode() == 2


def test_writer_modes_take_any_object_and_fail_the_write_as_pyspark(mock_connect):
    # As PySpark's WriteOperation, which resolves a mode that is not a str at the write, after its
    # path: `lower()` of it is one of the four modes, else UNSUPPORTED_OPERATION of the mode, and
    # an object without `lower` raises its AttributeError. None leaves the mode as it is, and a
    # later mode, or insertInto's overwrite, replaces the kept one.
    from pyspark.errors import PySparkValueError

    spark, service = mock_connect
    df = spark.range(1)
    requests = len(service.execute_requests)
    writer = df.write.format("noop").mode(b"append").mode(None)
    assert len(service.execute_requests) == requests
    with pytest.raises(PySparkValueError) as error:
        writer.save()
    assert error.value.getCondition() == "UNSUPPORTED_OPERATION"
    assert error.value.getMessageParameters() == {"operation": b"append"}
    assert str(error.value) == "[UNSUPPORTED_OPERATION] b'append' is not supported."
    with pytest.raises(PySparkValueError) as error:
        df.write.format("noop").mode(bytearray(b"append")).save()
    assert error.value.getMessageParameters() == {"operation": bytearray(b"append")}
    with pytest.raises(AttributeError, match="^'int' object has no attribute 'lower'$"):
        df.write.format("noop").mode(5).save()
    with pytest.raises(PySparkValueError):
        df.write.save(format="noop", mode=b"append")
    with pytest.raises(PySparkValueError):
        df.write.parquet("p", mode=b"append")
    assert len(service.execute_requests) == requests
    # The later mode replaces the kept one, and insertInto's overwrite too.
    df.write.format("noop").mode(5).mode("overwrite").save()
    df.write.mode(b"append").insertInto(b"t", True)
    assert len(service.execute_requests) == requests + 2


def test_stream_writer_formats_and_output_modes_take_bytes_at_the_call_as_pyspark(mock_connect):
    # As PySpark's DataStreamWriter, which sets the format and the output mode in their protobuf
    # string fields at the call: bytes are sent decoded, and another object raises the TypeError of
    # the field at the call, and so does start with it, before any request.
    spark, service = mock_connect
    stream = spark.readStream.format("rate").load().writeStream
    stream.format(b"noop").outputMode(b"append")
    requests = len(service.execute_requests)
    for call in [
        lambda: stream.format(5),
        lambda: stream.format(None),
        lambda: stream.outputMode(bytearray(b"append")),
        lambda: stream.outputMode(None),
    ]:
        with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
            call()
    assert len(service.execute_requests) == requests
    # ExecutePlanResponse.write_stream_operation_start_result=8: query_id=1 (id=1, run_id=2).
    service.execute_payload = message_field(
        8, message_field(1, message_field(1, "q") + message_field(2, "r")))
    stream.start(format=b"noop", outputMode=b"append")
    # Command.write_stream_operation_start=6 -> WriteStreamOperationStart.format=2, output_mode=9.
    plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
    start = parse_message(parse_message(plan[2][0])[6][0])
    assert start[2] == [b"noop"] and start[9] == [b"append"]
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        stream.start(format=5)
    assert len(service.execute_requests) == requests + 1


def test_reader_formats_are_kept_until_load_as_pyspark(mock_connect):
    # As PySpark's DataFrameReader, whose DataSource asserts the format at load, and whose format
    # methods of a path set their own. The assertion has no message.
    spark, service = mock_connect
    for call in [
        lambda: spark.read.format(b"noop").load(),
        lambda: spark.read.format(5).load("p"),
        lambda: spark.read.load(format=bytearray(b"noop")),
    ]:
        with pytest.raises(AssertionError) as error:
            call()
        assert str(error.value) == ""
    assert service.analyze_requests == [] and service.execute_requests == []
    spark.read.format(b"noop").format("noop").load()
    df = spark.read.format(5).parquet("p")
    assert df.schema is not None
    # Read.data_source=2 -> DataSource.format=1.
    data_source = parse_message(_sent_relation(service.analyze_requests[-1], 2)[2][0])
    assert data_source[1] == [b"parquet"]


def test_dataframe_arguments_that_utf8_cannot_encode_fail_when_the_plan_is_built_as_pyspark(
    mock_connect,
):
    # As PySpark's plans, which keep the names, the strs of literals and the SQL strings that
    # the methods of a DataFrame and of grouped data take, and set them in their protobuf string
    # fields when a request builds the plan: a str that UTF-8 cannot encode makes a DataFrame,
    # whose requests, as `df.schema` and `collect()`, fail with the UnicodeEncodeError of its
    # encoding, and are not sent.
    from pyspark.sql import DataFrame, Observation
    from pyspark.sql import functions as F

    spark, service = mock_connect
    bad = "a\ud800b"
    message = "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed"
    calls = [
        lambda df: df.alias(bad),
        lambda df: df.select(bad),
        lambda df: df.select(["id", bad]),
        lambda df: df.selectExpr(bad),
        lambda df: df.selectExpr(["id", bad]),
        lambda df: df.filter(bad),
        lambda df: df.where(bad),
        lambda df: df.withColumn(bad, F.lit(1)),
        lambda df: df.withColumnRenamed(bad, "z"),
        lambda df: df.withColumnRenamed("id", bad),
        lambda df: df.withColumnsRenamed({"id": bad}),
        lambda df: df.withMetadata(bad, {"k": 1}),
        lambda df: df.hint(bad),
        lambda df: df.hint("broadcast", bad),
        lambda df: df.hint("broadcast", ["x", bad]),
        lambda df: df.drop(bad),
        lambda df: df.drop("id", bad),
        lambda df: df.dropDuplicates([bad]),
        lambda df: df.drop_duplicates([bad]),
        lambda df: df.dropDuplicatesWithinWatermark([bad]),
        lambda df: df.toDF(bad),
        lambda df: df.withWatermark(bad, "1 second"),
        lambda df: df.withWatermark("id", bad),
        lambda df: df.unpivot(bad, ["id"], "var", "val"),
        lambda df: df.unpivot("id", [bad], "var", "val"),
        lambda df: df.unpivot("id", ["id"], bad, "val"),
        lambda df: df.melt("id", ["id"], "var", bad),
        lambda df: df.transpose(bad),
        lambda df: df.observe(bad, F.count(F.lit(1))),
        lambda df: df.observe("o", F.max(bad)),
        lambda df: df.observe(Observation(bad), F.count(F.lit(1))),
        lambda df: df.groupBy(bad).count(),
        lambda df: df.groupby(["id", bad]).count(),
        lambda df: df.rollup(bad).count(),
        lambda df: df.cube(bad).count(),
        lambda df: df.groupingSets([[bad]], bad).count(),
        lambda df: df.groupBy("id").agg({bad: "max"}),
        lambda df: df.groupBy("id").agg({"id": bad}),
        lambda df: df.agg({bad: "max"}),
        lambda df: df.agg({"id": bad}),
        lambda df: df.groupBy("id").pivot(bad).count(),
        lambda df: df.groupBy("id").pivot("id", ["x", bad]).count(),
        lambda df: df.sort(bad),
        lambda df: df.orderBy(bad, ascending=False),
        lambda df: df.sortWithinPartitions(bad),
        lambda df: df.describe(bad),
        lambda df: df.describe(["id", bad]),
        lambda df: df.summary(bad),
        lambda df: df.fillna(bad),
        lambda df: df.na.fill({bad: 1}),
        lambda df: df.na.fill({"id": bad}),
        lambda df: df.na.fill(1, subset=[bad]),
        lambda df: df.na.drop(subset=[bad]),
        lambda df: df.dropna(subset=bad),
        lambda df: df.na.replace("x", bad),
        lambda df: df.replace(bad, "x"),
        lambda df: df.na.replace("x", "y", subset=[bad]),
        lambda df: df.crosstab(bad, "id"),
        lambda df: df.stat.crosstab("id", bad),
        lambda df: df.freqItems([bad]),
        lambda df: df.stat.freqItems((bad,)),
        lambda df: df.sampleBy(bad, {0: 0.5}, 1),
        lambda df: df.stat.sampleBy("id", {bad: 0.5}, 1),
        lambda df: df.join(df, bad),
        lambda df: df.join(df, ["id", bad]),
        lambda df: df.join(df, F.col(bad) == F.col("id")),
        lambda df: df._joinAsOf(df, "id", "id", on=bad),
        lambda df: df.repartition(bad),
        lambda df: df.repartition(2, bad),
        lambda df: df.repartitionByRange(bad),
        lambda df: df.repartitionByRange(2, bad),
        lambda df: df.repartitionById(2, bad),
    ]
    for call in calls:
        df = spark.range(1)
        plan = call(df)
        assert isinstance(plan, DataFrame)
        for request in (lambda: plan.schema, plan.collect):
            with pytest.raises(UnicodeEncodeError) as error:
                request()
            assert type(error.value) is UnicodeEncodeError
            assert str(error.value) == message
    # The one request is the `isStreaming` of the DataFrame that the Observation observes, which
    # PySpark's `Observation._on` asks.
    assert len(service.analyze_requests) == 1 and service.execute_requests == []


def test_dataframes_of_values_that_fail_keep_the_cached_schema_that_pyspark_copies(mock_connect):
    # As PySpark's alias, hint, dropDuplicates, observe, filter, sort, sortWithinPartitions and
    # repartitions, which copy the `_cached_schema` of their input: of a value that their plan
    # fails to build, `schema` gives the cached schema without a request, and their other
    # requests raise the error. withColumnRenamed, toDF and the other plans, which do not copy
    # it, raise the error at `schema` too.
    from pyspark.sql import Observation
    from pyspark.sql import functions as F

    spark, service = mock_connect
    bad = "a\ud800b"
    df = spark.range(1)
    schema = df.schema
    sent = len(service.analyze_requests)
    copies = [
        df.alias(bad),
        df.hint(bad),
        df.dropDuplicates([bad]),
        df.observe(bad, F.count(F.lit(1))),
        df.filter(bad),
        df.where(F.col(bad) > 0),
        df.sort(bad),
        df.sortWithinPartitions(bad),
        df.repartition(bad),
        df.repartitionByRange(2, bad),
        df.repartitionById(2, bad),
    ]
    for plan in copies:
        assert plan.schema == schema
        with pytest.raises(UnicodeEncodeError):
            plan.collect()
    assert len(service.analyze_requests) == sent
    # The observation of an Observation asks whether its DataFrame is streaming, as PySpark's.
    observed = df.observe(Observation(bad), F.count(F.lit(1)))
    assert observed.schema == schema
    for plan in (df.withColumnRenamed(bad, "z"), df.toDF(bad), df.drop(bad), df.describe(bad)):
        with pytest.raises(UnicodeEncodeError):
            plan.schema
    assert service.execute_requests == []


def test_dataframe_values_that_protobuf_refuses_fail_when_the_plan_is_built_as_pyspark(
    mock_connect,
):
    # As PySpark's plans, which set these values in their protobuf fields as they are given when
    # a request builds the plan, as protobuf's default (upb) backend converts them: a string field
    # takes bytes of UTF-8 too, and refuses another object with a TypeError; an int field refuses
    # an int beyond it with a ValueError; a double field a str with a TypeError. A join on a list
    # of conditions is their conjunction, of `&`, and a join on a tuple reads its `to_plan`, when
    # the plan is built: of an operand that is a Row, `&` raises the PySparkAttributeError of its
    # `_expr`.
    from pyspark.errors import PySparkAttributeError
    from pyspark.sql import DataFrame, Row

    spark, service = mock_connect
    bad_type = "bad argument type for built-in operation"
    not_supported = "[ATTRIBUTE_NOT_SUPPORTED] Attribute `_expr` is not supported."
    refused = "Field spark.connect.NADrop.min_non_nulls: Expected an int, got a boolean."
    calls = [
        (lambda df: df.alias(5), TypeError, bad_type),
        (lambda df: df.alias(None), TypeError, bad_type),
        (lambda df: df.alias(b"\xff"), UnicodeDecodeError,
         "'utf-8' codec can't decode byte 0xff in position 0: invalid start byte"),
        (lambda df: df.withColumnRenamed(1, "z"), TypeError, bad_type),
        (lambda df: df.withColumnRenamed("id", None), TypeError, bad_type),
        (lambda df: df.withColumnsRenamed({"id": 1}), TypeError, bad_type),
        (lambda df: df.unpivot("id", ["id"], 1, "val"), TypeError, bad_type),
        (lambda df: df.melt("id", ["id"], "var", None), TypeError, bad_type),
        (lambda df: df.describe(b"ab"), TypeError, bad_type),
        (lambda df: df.freqItems(["id", 1]), TypeError, bad_type),
        (lambda df: df.freqItems(["id"], support="x"), TypeError, "must be real number, not str"),
        (lambda df: df.fillna(2**70), ValueError, "Value out of range: 1180591620717411303424"),
        (lambda df: df.na.fill({"id": 2**70}), ValueError,
         "Value out of range: 1180591620717411303424"),
        (lambda df: df.dropna(thresh=True), TypeError, refused),
        (lambda df: df.dropna(thresh=2**40), ValueError, "Value out of range: 1099511627776"),
        (lambda df: df.na.replace(1, 2, subset=[1]), TypeError, bad_type),
        (lambda df: df.join(df, on=["id", 1]), TypeError, bad_type),
        (lambda df: df.join(df, on=("id",)), AttributeError,
         "'tuple' object has no attribute 'to_plan'"),
        (lambda df: df.join(df, on=[df.id == df.id, object()]), AttributeError,
         "'object' object has no attribute '_expr'"),
        (lambda df: df.join(df, on=[df.id == df.id, Row(a=1)]), PySparkAttributeError,
         not_supported),
        (lambda df: df._joinAsOf(df, "id", "id", on=[Row(a=1), df.id == df.id]),
         PySparkAttributeError, not_supported),
        (lambda df: df._joinAsOf(df, "id", "id", on=("id",)), AttributeError,
         "'tuple' object has no attribute 'to_plan'"),
        (lambda df: df.zipWithIndex(5), TypeError, bad_type),
        (lambda df: df.zipWithIndex(None), TypeError, bad_type),
        (lambda df: df.zipWithIndex("a\ud800"), UnicodeEncodeError,
         "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed"),
        (lambda df: df.zipWithIndex(b"\xff"), UnicodeDecodeError,
         "'utf-8' codec can't decode byte 0xff in position 0: invalid start byte"),
        (lambda df: spark.range(2**70), ValueError, "Value out of range: 1180591620717411303424"),
        (lambda df: spark.range(0, 10, 2**70), ValueError,
         "Value out of range: 1180591620717411303424"),
        (lambda df: spark.range(0, 10, 1, 2**40), ValueError,
         "Value out of range: 1099511627776"),
        (lambda df: spark.tvf.range(2**70), ValueError,
         "Value out of range: 1180591620717411303424"),
    ]
    for call, error_type, message in calls:
        plan = call(spark.range(1))
        assert isinstance(plan, DataFrame), message
        with pytest.raises(error_type) as error:
            plan.collect()
        assert type(error.value) is error_type, message
        assert str(error.value) == message
    assert service.analyze_requests == [] and service.execute_requests == []
    # A string field takes bytes of UTF-8, which PySpark sends as their str.
    from pyspark.sql.connect.proto import Relation

    df = spark.range(1)
    relation = Relation.FromString(df.alias(b"q")._relation_bytes())
    assert relation.subquery_alias.alias == "q"
    relation = Relation.FromString(df.withColumnRenamed(b"id", b"z")._relation_bytes())
    assert [(r.col_name, r.new_col_name) for r in relation.with_columns_renamed.renames] == [
        ("id", "z")]
    relation = Relation.FromString(df.unpivot("id", ["id"], b"var", "val")._relation_bytes())
    assert relation.unpivot.variable_column_name == "var"
    relation = Relation.FromString(df.join(df, on=["id", b"id"])._relation_bytes())
    assert list(relation.join.using_columns) == ["id", "id"]
    # zipWithIndex's name is the alias of the index, of `F._invoke_function(...).alias(name)`.
    relation = Relation.FromString(df.zipWithIndex(b"q")._relation_bytes())
    assert list(relation.project.expressions[1].alias.name) == ["q"]
    # A condition and a str are the conjunction of the condition and the literal of the str.
    relation = Relation.FromString(df.join(df, on=[df.id == df.id, "x"])._relation_bytes())
    condition = relation.join.join_condition.unresolved_function
    assert condition.function_name == "and"
    assert condition.arguments[1].literal.string == "x"


def test_dataframe_arguments_raise_the_errors_of_pyspark_in_its_order(mock_connect):
    # As PySpark's: `withColumn` checks the Column before its `WithColumns` plan asserts a str
    # name; `withMetadata` takes `self[columnName]` first, of the NOT_EXPECTED_TYPE of bytes; a
    # str that UTF-8 cannot encode is no explain mode, no `how` of `dropna`, and no join type,
    # which the error names as it is; `explain` builds the plan before it checks the mode.
    from pyspark.errors import AnalysisException, PySparkTypeError, PySparkValueError
    from pyspark.sql import functions as F

    spark, _ = mock_connect
    df = spark.range(1)
    bad = "a\ud800b"
    for call in (lambda: df.withColumn(1, F.lit(1)), lambda: df.withColumn(None, F.lit(1))):
        with pytest.raises(AssertionError) as error:
            call()
        assert type(error.value) is AssertionError and str(error.value) == ""
    for call, arg_name, arg_type in [
        (lambda: df.withColumn(1, 5), "col", "int"),
        (lambda: df.withMetadata(b"id", {"k": 1}), "item", "bytes"),
    ]:
        with pytest.raises(PySparkTypeError) as error:
            call()
        assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
        assert error.value.getMessageParameters()["arg_name"] == arg_name
        assert error.value.getMessageParameters()["arg_type"] == arg_type
    for call, arg_name in [
        (lambda: df.explain(bad), "explain_mode"),
        (lambda: df.explain(mode=bad), "explain_mode"),
        (lambda: df.dropna(how=bad), "how"),
    ]:
        with pytest.raises(PySparkValueError) as error:
            call()
        assert error.value.getCondition() == "VALUE_NOT_ALLOWED"
        assert error.value.getMessageParameters()["arg_name"] == arg_name
    with pytest.raises(UnicodeEncodeError):
        df.filter(bad).explain("formatted ")
    for join in (lambda: df.join(df, "id", bad), lambda: df.lateralJoin(df, how=bad)):
        with pytest.raises(AnalysisException) as error:
            join()
        assert error.value.getCondition() == "UNSUPPORTED_JOIN_TYPE"
        assert error.value.getMessageParameters()["typ"] == bad


def test_plans_fail_with_the_first_error_of_pysparks_build_order(mock_connect):
    # As PySpark's plans, which build their input before themselves, but for a repartition, which
    # builds its partitioning first, and sets the count of the partitioning of columns after its
    # input, and set the name of a hint or of an observation before their expressions, and the
    # name of a column after its Column: of two values that fail, the request raises the error of
    # the first, such as of a str that UTF-8 cannot encode.
    from pyspark.sql import functions as F

    spark, _ = mock_connect
    df = spark.range(1)
    first, second = "a\ud800", "a\ud801"
    for plan, character in [
        (df.select(F.col(first)).alias(second), "\\ud800"),
        (df.alias(first).select(F.col(second)), "\\ud800"),
        (df.hint(first, second), "\\ud800"),
        (df.observe(first, F.max(second)), "\\ud800"),
        (df.withColumn(second, F.col(first)), "\\ud800"),
        (df.toDF(first).withColumnRenamed(second, "z"), "\\ud800"),
        (df.alias(second).repartition(F.col(first)), "\\ud800"),
        (df.alias(second).repartition(2**40, F.col(first)), "\\ud800"),
        (df.alias(second).repartitionByRange(3, F.col(first)), "\\ud800"),
        (df.alias(second).repartitionByRange(2**40, F.col(first)), "\\ud800"),
        (df.alias(second).repartitionById(3, F.col(first)), "\\ud800"),
        (df.alias(second).repartitionById(2**40, F.col(first)), "\\ud800"),
    ]:
        with pytest.raises(UnicodeEncodeError) as error:
            plan.collect()
        assert f"character '{character}' in position 1" in str(error.value)
    # The error of a count beyond the int32 of the plan comes after that of its input, of an alias
    # that protobuf refuses.
    for repartition in (
        df.alias(5).repartition, df.alias(5).repartitionByRange, df.alias(5).repartitionById
    ):
        with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
            repartition(2**40, "id").collect()
    with pytest.raises(ValueError, match="^Value out of range: 1099511627776$"):
        df.repartition(2**40, "id").collect()


def test_with_columns_asserts_its_mapping_as_pyspark(mock_connect):
    # As PySpark's WithColumns plan, which asserts, as the call builds it, that the mapping is not
    # empty, and of str names and Columns: a bare AssertionError. A name that UTF-8 cannot encode
    # fails the plan as it is sent, with the UnicodeEncodeError of its encoding.
    from pyspark.sql import DataFrame
    from pyspark.sql import functions as F

    spark, _ = mock_connect
    df = spark.range(1)
    for mapping in ({}, {b"a": F.lit(1)}, {1: F.lit(1)}, {"a": 1}, {"a": F.lit(1), 2: F.lit(2)}):
        with pytest.raises(AssertionError) as error:
            df.withColumns(mapping)
        assert type(error.value) is AssertionError
        assert str(error.value) == ""
    assert isinstance(df.withColumns({"a": F.lit(1)}), DataFrame)
    plan = df.withColumns({"a": F.lit(1), "\ud800": F.lit(2)})
    with pytest.raises(UnicodeEncodeError):
        plan.columns
    with pytest.raises(UnicodeEncodeError):
        plan.collect()


def test_the_properties_of_a_plan_that_fails_read_the_column_of_its_schema_as_pyspark(
    mock_connect,
):
    # As PySpark's properties, which read `self._schema`: the property raises the AttributeError
    # of the plan, of a join on a tuple or on a Row, after which Python gives the `__getattr__` of
    # the DataFrame, the Column of `_schema`. So `schema` is a deep copy of that Column, `columns`
    # and `dtypes` iterate its `fields`, a Column, which raises NOT_ITERABLE, and so do the
    # representation, `dir`, the key completions and `toArrow`, of them; `printSchema` calls
    # its `treeString`, a Column.
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import Column, Row

    spark, service = mock_connect
    service.confs = {"spark.sql.repl.eagerEval.enabled": "false",
                     "spark.sql.repl.eagerEval.maxNumRows": "20",
                     "spark.sql.repl.eagerEval.truncate": "20"}
    df = spark.range(1)
    for failed in (df.join(df, on=(1, 2)), df.join(df, on=[df.id == df.id, Row(a=1)])):
        schema = failed.schema
        assert isinstance(schema, Column) and repr(schema) == "Column<'_schema'>"
        assert failed.schema is not schema
        for read in (
            lambda: failed.columns,
            lambda: failed.dtypes,
            lambda: repr(failed),
            lambda: dir(failed),
            failed._ipython_key_completions_,
            failed.toArrow,
        ):
            with pytest.raises(PySparkTypeError) as error:
                read()
            assert error.value.getCondition() == "NOT_ITERABLE"
            assert error.value.getMessageParameters() == {"objectName": "Column"}
        with pytest.raises(TypeError, match="^'Column' object is not callable$"):
            failed.printSchema()
        with pytest.raises(AttributeError):
            failed.collect()
    assert service.analyze_requests == [] and service.execute_requests == []


def test_to_keeps_a_schema_that_is_not_a_datatype_as_pyspark_reads_it(mock_connect):
    # As PySpark's `to`, which keeps the schema as it is given: columns and dtypes read the fields
    # of the object, and printSchema its treeString, so an object that lacks them raises what
    # Python raises for it. columns and dtypes fall back to a Column, which the representation,
    # of the dtypes, and `dir`, of the columns, cannot iterate.
    import pyspark.sql.types as T
    from pyspark.errors import PySparkTypeError

    spark, service = mock_connect
    # repr reads the settings of the eager evaluation of the session, which the server has.
    service.confs = {"spark.sql.repl.eagerEval.enabled": "false",
                     "spark.sql.repl.eagerEval.maxNumRows": "20",
                     "spark.sql.repl.eagerEval.truncate": "20"}
    bogus = T.StructType([T.StructField("x", T.StructField("b", T.IntegerType()))])
    df = spark.range(1).to(bogus)
    assert df.columns == ["x"]
    assert df.dtypes == [("x", "b:int")]
    assert repr(df) == "DataFrame[x: b:int]"
    with pytest.raises(PySparkTypeError) as error:
        df.printSchema()
    assert error.value.getCondition() == "INVALID_TYPENAME_CALL"

    text = spark.range(1).to("int")
    assert type(text.columns).__name__ == "Column"
    assert type(text.dtypes).__name__ == "Column"
    assert type(text._ipython_key_completions_()).__name__ == "Column"
    for read in (repr, dir):
        with pytest.raises(PySparkTypeError) as error:
            read(text)
        assert error.value.getCondition() == "NOT_ITERABLE"
    with pytest.raises(AttributeError, match="'str' object has no attribute 'treeString'"):
        text.printSchema()
    assert text.schema == "int"


def test_the_schema_of_to_is_cached_and_copied_as_pyspark(mock_connect):
    # As PySpark's `to`, which sets the `_cached_schema` of its DataFrame to the schema whatever it
    # is, a DataType that is not a struct too, and the methods that copy the `_cached_schema` of
    # their input, which give that schema without a request: alias, filter and where, limit, the
    # sorts, hint, the repartitions and coalesce, distinct and dropDuplicates, sample, randomSplit
    # and observe. select, which does not copy it, asks the plan, which does not build of a schema
    # that is not a DataType; the plan of a DataType that is not a struct is sent, and so the
    # server rejects it.
    import pyspark.sql.types as T
    from pyspark.errors import PySparkValueError
    from pyspark.sql import Observation
    from pyspark.sql import functions as F

    spark, service = mock_connect
    keeping = [
        lambda d: d.alias("x"),
        lambda d: d.filter("a > 0"),
        lambda d: d.where("a > 0"),
        lambda d: d.limit(1),
        lambda d: d.limit(2.0),
        lambda d: d.sort("a"),
        lambda d: d.orderBy("a"),
        lambda d: d.sortWithinPartitions("a"),
        lambda d: d.hint("broadcast"),
        lambda d: d.repartition(2),
        lambda d: d.repartition(2, "a"),
        lambda d: d.repartition("a"),
        lambda d: d.repartitionByRange(2, "a"),
        lambda d: d.repartitionById(2, "a"),
        lambda d: d.coalesce(1),
        lambda d: d.distinct(),
        lambda d: d.dropDuplicates(),
        lambda d: d.drop_duplicates(["a"]),
        lambda d: d.sample(0.5, seed=1),
        lambda d: d.randomSplit([1.0, 1.0], seed=1)[1],
        lambda d: d.observe("o", F.count(F.lit(1))),
    ]
    for schema in ("a long", T.LongType(), T.ArrayType(T.StringType())):
        df = spark.range(3).to(schema)
        assert df.schema == schema
        for make in keeping:
            assert make(df).schema == schema
            assert make(df).limit(1).schema == schema
    assert service.analyze_requests == []
    with pytest.raises(PySparkValueError) as error:
        spark.range(3).to("a long").select("a").schema
    assert error.value.getCondition() == "UNSUPPORTED_OPERATION"
    # observe of an Observation asks whether the DataFrame is streaming first, as PySpark's
    # `Observation._on`, whose plan does not build of a schema that is not a DataType.
    with pytest.raises(PySparkValueError) as error:
        spark.range(3).to("a long").observe(Observation(), F.count(F.lit(1)))
    assert error.value.getCondition() == "UNSUPPORTED_OPERATION"
    observed = spark.range(3).to(T.LongType()).observe(Observation(), F.count(F.lit(1)))
    assert len(service.analyze_requests) == 1
    assert observed.schema == T.LongType()
    assert len(service.analyze_requests) == 1
    with pytest.raises(AttributeError, match="'LongType' object has no attribute 'treeString'"):
        spark.range(3).to(T.LongType()).printSchema()
    spark.range(3).to(T.LongType()).collect()
    assert len(service.execute_requests) == 1
    assert len(service.analyze_requests) == 1


def test_sequence_arguments_are_unpacked_as_pyspark_does(mock_connect):
    # As PySpark's `_to_cols`: a single argument that is a collections.abc.Sequence, and not an
    # int, a str or a Column, stands for its items, so a range, bytes, a UserList and a Sequence of
    # one's own unpack. The items of bytes are ints, which select and orderBy do not take as names.
    from collections import UserList
    from collections.abc import Sequence

    from pyspark.errors import PySparkIndexError, PySparkTypeError

    class Items(Sequence):
        def __init__(self, items):
            self._items = list(items)

        def __getitem__(self, index):
            return self._items[index]

        def __len__(self):
            return len(self._items)

    spark, _ = mock_connect
    df = spark.range(2)
    for items in (range(0), b"", UserList(["id"]), Items(["id"])):
        df.select(items).collect()
    df.groupBy(range(0)).count().collect()
    with pytest.raises(PySparkTypeError) as error:
        df.select(range(2))
    assert error.value.getMessageParameters() == {
        "arg_name": "cols", "expected_type": "Column or str", "arg_type": "int"}
    with pytest.raises(PySparkTypeError) as error:
        df.select(b"ab")
    assert error.value.getMessageParameters() == {
        "arg_name": "cols", "expected_type": "Column or str", "arg_type": "int"}
    with pytest.raises(PySparkIndexError) as error:
        df.groupBy(range(1))
    assert error.value.getCondition() == "INDEX_NOT_POSITIVE"
    with pytest.raises(IndexError, match="^list index out of range$"):
        df.orderBy(b"ab")


def test_writers_keep_their_instance_attributes_through_copy_as_pyspark(mock_connect):
    # As PySpark's plain classes: copy.copy shares the attributes that were set on a writer, and
    # copy.deepcopy copies them, for DataFrameWriter and DataFrameWriterV2 alike.
    import copy

    spark, _ = mock_connect
    df = spark.range(1)
    for writer in (df.write, df.writeTo("t")):
        writer.foo = [1, 2]
        shallow = copy.copy(writer)
        deep = copy.deepcopy(writer)
        assert type(shallow) is type(writer) and type(deep) is type(writer)
        assert shallow.foo is writer.foo
        assert deep.foo == [1, 2] and deep.foo is not writer.foo


def test_deep_copy_of_a_dataframe_of_a_stopped_session_fails_as_pyspark(mock_connect):
    # As PySpark's, whose deep copy looks up `__deepcopy__` through `__getattr__`, which reads the
    # columns: the schema request of a closed client raises SparkConnectException, which is
    # NO_ACTIVE_SESSION.
    import copy

    from pyspark.errors.exceptions.connect import SparkConnectException
    from pyspark.sql import SparkSession

    _, service = mock_connect
    other = SparkSession.builder.remote(service.remote).create()
    df = other.range(1)
    other.stop()
    with pytest.raises(SparkConnectException) as error:
        copy.deepcopy(df)
    assert error.value.getCondition() == "NO_ACTIVE_SESSION"


def test_copies_of_a_dataframe_request_its_schema_as_pyspark_does(mock_connect):
    # As PySpark's copy, which reads the columns of the DataFrame that the reconstruction of a copy
    # makes: copy.copy makes one schema request, whether the DataFrame has its schema or not, and
    # copy.deepcopy makes one for the copy, and one more for the DataFrame when it has no schema.
    import copy

    spark, service = mock_connect

    def schema_requests(call):
        before = len(service.analyze_requests)
        call()
        return len(service.analyze_requests) - before

    df = spark.range(1)
    assert schema_requests(lambda: copy.copy(df)) == 1
    assert schema_requests(lambda: copy.deepcopy(df)) == 2
    assert schema_requests(lambda: copy.deepcopy(df)) == 1
    cached = spark.range(1)
    cached.columns
    assert schema_requests(lambda: copy.copy(cached)) == 1
    assert schema_requests(lambda: copy.deepcopy(cached)) == 1


def test_copies_keep_the_schema_that_they_request_apart_from_the_cached_one_as_pyspark(
        mock_connect):
    # As PySpark's reconstruction of a copy, a deep copy or an unpickle of a DataFrame, which reads
    # the columns of the new DataFrame, so that it requests its schema and keeps it as its
    # `_cached_schema_serialized`, before the state sets the `_cached_schema` of the DataFrame:
    # `schema`, `printSchema`, the set operations of equal cached schemas and the numeric
    # aggregations of grouped data give the schema that it requested, and `columns`, `dtypes`,
    # `repr` and the DataFrames of the methods that copy the cached schema give the cached one,
    # with no more request. They differ when the schema on the server changed since it was
    # cached. So do the copies of a copy, of the schema that they request. A copy of a DataFrame of
    # no cached schema requests it again, as PySpark's `_schema` does, which keeps it as both.
    import contextlib
    import copy
    import io

    import cloudpickle
    from pyspark.sql.connect.proto import Relation

    spark, service = mock_connect
    service.confs = {"spark.sql.repl.eagerEval.enabled": "false",
                     "spark.sql.repl.eagerEval.maxNumRows": "20",
                     "spark.sql.repl.eagerEval.truncate": "20"}
    df = spark.range(1)
    df.schema
    service.data_type = ddl_data_type("a int, b string")
    requested = "struct<a:int,b:string>"
    copies = [copy.copy, copy.deepcopy, lambda frame: cloudpickle.loads(cloudpickle.dumps(frame))]
    for make in copies:
        before = len(service.analyze_requests)
        c = make(df)
        assert len(service.analyze_requests) == before + 1
        assert c.schema.simpleString() == requested
        printed = io.StringIO()
        with contextlib.redirect_stdout(printed):
            c.printSchema()
        assert printed.getvalue() == c.schema.treeString() + "\n"
        assert c.columns == ["id"] and c.dtypes == [("id", "bigint")]
        assert repr(c) == "DataFrame[id: bigint]"
        for result in (c.union(c), c.intersect(c), c.subtract(c), c.unionByName(c), c.union(df)):
            assert result.schema.simpleString() == requested
        for result in (df.union(c), c.filter("true"), c.alias("t"), c.limit(1)):
            assert result.schema.simpleString() == "struct<id:bigint>"
        aggregate = Relation.FromString(c.groupBy().sum()._relation_bytes()).aggregate
        assert [expression.unresolved_function.arguments[0].unresolved_attribute.unparsed_identifier
                for expression in aggregate.aggregate_expressions] == ["a"]
        assert len(service.analyze_requests) == before + 1
        service.data_type = ddl_data_type("z string")
        again = copy.copy(c)
        assert again.schema.simpleString() == "struct<z:string>" and again.columns == ["id"]
        service.data_type = ddl_data_type("a int, b string")
    fresh = spark.range(1)
    before = len(service.analyze_requests)
    c = copy.copy(fresh)
    assert c.schema.simpleString() == requested and c.columns == ["a", "b"]
    assert len(service.analyze_requests) == before + 2


def test_reader_strings_that_utf8_cannot_encode_fail_the_plan_as_pyspark(mock_connect):
    # As PySpark's DataSource, which builds its plan at a request: its format is set before its
    # paths, and protobuf's string fields raise the UnicodeEncodeError of a str that UTF-8 cannot
    # encode, so that load, and every reader of a path, returns a DataFrame that fails at its
    # first request, with no request sent, and a format or a path that a later call replaces
    # does not fail.
    import copy

    import cloudpickle

    spark, service = mock_connect
    bad = "\ud800"
    message = re.escape(
        "'utf-8' codec can't encode character '\\ud800' in position 0: surrogates not allowed")
    for build in [
        lambda: spark.read.format(bad).load("p"),
        lambda: spark.read.format(bad).load(),
        lambda: spark.read.load("p", format=bad),
        lambda: spark.read.format("noop").load(bad),
        lambda: spark.read.format("noop").load(["p", bad]),
        lambda: spark.read.load(bad),
        lambda: spark.read.load([bad]),
        lambda: spark.read.parquet(bad),
        lambda: spark.read.parquet("p", bad),
        lambda: spark.read.json(bad),
        lambda: spark.read.csv(bad),
        lambda: spark.read.orc(bad),
        lambda: spark.read.text(bad),
        lambda: copy.copy(spark.read.format(bad)).load("p"),
        lambda: copy.deepcopy(spark.read.format(bad)).load("p"),
        lambda: cloudpickle.loads(cloudpickle.dumps(spark.read.format(bad))).load("p"),
    ]:
        df = build()
        with pytest.raises(UnicodeEncodeError, match=message) as error:
            df.schema
        assert type(error.value) is UnicodeEncodeError
        with pytest.raises(UnicodeEncodeError, match=message):
            df.count()
    assert service.analyze_requests == [] and service.execute_requests == []
    # The error of the format precedes the one of a path, as PySpark's DataSource sets its format
    # before its paths, and a later format replaces the one that fails.
    with pytest.raises(UnicodeEncodeError) as error:
        spark.read.format(bad).load("x\udfff").schema
    assert str(error.value).startswith(
        "'utf-8' codec can't encode character '\\ud800' in position 0")
    with pytest.raises(UnicodeEncodeError) as error:
        spark.read.load(["p", "x\udfff"]).schema
    assert str(error.value).startswith(
        "'utf-8' codec can't encode character '\\udfff' in position 1")
    assert spark.read.format(bad).format("parquet").load("p").schema is not None
    assert spark.read.format(bad).parquet("p").schema is not None
    # A format that is not a str still fails the assertion at load, as before.
    with pytest.raises(AssertionError):
        spark.read.format(5).load(bad)


def test_reader_options_schemas_and_table_names_that_utf8_cannot_encode_fail_the_plan_as_pyspark(
    mock_connect,
):
    # As PySpark's Read and DataSource plans, which keep a str of a table name, an option or a
    # schema as it is, and whose protobuf string fields raise the UnicodeEncodeError of a str that
    # UTF-8 cannot encode when the plan is built: the call returns, and the DataFrame fails at its
    # first request, with no request sent. The plan has the format, the schema, the options and
    # the paths, in that order, and the error is the first of them. A later call that unsets or
    # replaces the str leaves no error.
    spark, service = mock_connect
    bad = "a\ud800b"
    message = re.escape(
        "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed")
    path = "/p"
    for build in [
        lambda: spark.read.table(bad),
        lambda: spark.table(bad),
        lambda: spark.read.option(bad, "v").json(path),
        lambda: spark.read.option("path", bad).json(path),
        lambda: spark.read.options(k=bad).json(path),
        lambda: spark.read.options(**{bad: "v"}).parquet(path),
        lambda: spark.read.json(path, primitivesAsString=bad),
        lambda: spark.read.schema(bad + " INT").json(path),
        lambda: spark.read.json(path, schema=bad + " INT"),
        lambda: spark.read.csv(path, schema=bad + " INT"),
        lambda: spark.read.format("noop").load(path, schema=bad),
        lambda: spark.read.format("noop").load(path, **{"k": bad}),
        lambda: spark.read.load(path, format="noop", schema=bad),
        lambda: spark.read.option("k", "v").schema(bad).load(path),
    ]:
        df = build()
        with pytest.raises(UnicodeEncodeError, match=message) as error:
            df.schema
        assert type(error.value) is UnicodeEncodeError
        with pytest.raises(UnicodeEncodeError, match=message):
            df.count()
    assert service.analyze_requests == [] and service.execute_requests == []
    # The format precedes the schema, and the schema the options.
    with pytest.raises(UnicodeEncodeError) as error:
        spark.read.format(bad).schema("x\udfff INT").option(bad, "v").load(path).schema
    assert str(error.value).startswith(
        "'utf-8' codec can't encode character '\\ud800' in position 1")
    with pytest.raises(UnicodeEncodeError) as error:
        spark.read.option(bad, "v").schema("x\udfff INT").json(path).schema
    assert str(error.value).startswith(
        "'utf-8' codec can't encode character '\\udfff' in position 1")
    # A str that a later call unsets, or replaces, is no longer in the plan.
    assert spark.read.option(bad, "v").option(bad, None).json(path).schema is not None
    assert spark.read.option("k", bad).option("k", "v").json(path).schema is not None
    assert spark.read.options(**{bad: None}).json(path).schema is not None
    assert spark.read.schema(bad).schema("a INT").json(path).schema is not None
    # Another option leaves the str of an option that is still set.
    with pytest.raises(UnicodeEncodeError, match=message):
        spark.read.option(bad, "v").option("k", "v").json(path).schema
    # A copy of the reader keeps the str of the reader that set it.
    import copy

    reader = spark.read.option("k", bad)
    with pytest.raises(UnicodeEncodeError, match=message):
        copy.copy(reader).json(path).schema
    # A schema that is not a str fails at the call, as before.
    from pyspark.errors import PySparkTypeError

    with pytest.raises(PySparkTypeError) as error:
        spark.read.schema(5)
    assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
    # A table read keeps a key that is not a str, and its plan fails with the TypeError of protobuf
    # for an object, which the bytes of UTF-8 avoid, as their text.
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        spark.read.option(1, "v").table("t").schema
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        spark.readStream.option(None, "v").table("t").isStreaming


def test_writer_options_and_builder_configs_fail_the_write_or_getOrCreate_as_pyspark(mock_connect):
    # As PySpark's writers, which keep an option, a table property, a partitioning or a sorting
    # column in a dict or a list, and build the command at the write, which fails with the error of
    # the first one that does not encode, or is not a str: the setter returns, and the write
    # raises, with no request sent. The builder keeps each config, and getOrCreate sends them in one
    # request after the session is created, which fails with the same error.
    from pyspark.sql.connect.session import SparkSession

    spark, service = mock_connect
    bad = "a\ud800b"
    message = re.escape(
        "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed")
    df = spark.range(1)
    bad_type = "^bad argument type for built-in operation$"
    cases = [
        (lambda: df.write.option(bad, "v"), lambda w: w.parquet("/p"), UnicodeEncodeError, message),
        (lambda: df.write.option("k", bad), lambda w: w.parquet("/p"), UnicodeEncodeError, message),
        (lambda: df.write.options(**{bad: "v"}), lambda w: w.save("/p"), UnicodeEncodeError,
         message),
        (lambda: df.write.option(bad, "v").option(bad, None), lambda w: w.csv("/p"),
         UnicodeEncodeError, message),
        (lambda: df.write.bucketBy(2, bad), lambda w: w.saveAsTable("t"), UnicodeEncodeError,
         message),
        (lambda: df.write.sortBy(bad), lambda w: w.parquet("/p"), UnicodeEncodeError, message),
        (lambda: df.write.option(1, "v"), lambda w: w.parquet("/p"), TypeError, bad_type),
        (lambda: df.writeTo("t").option(bad, "v"), lambda w: w.create(), UnicodeEncodeError,
         message),
        (lambda: df.writeTo("t").option("k", bad), lambda w: w.append(), UnicodeEncodeError,
         message),
        (lambda: df.writeTo("t").options(**{bad: "v"}), lambda w: w.createOrReplace(),
         UnicodeEncodeError, message),
        (lambda: df.writeTo("t").tableProperty(bad, "v"), lambda w: w.create(),
         UnicodeEncodeError, message),
        (lambda: df.writeTo("t").tableProperty("k", bad), lambda w: w.create(),
         UnicodeEncodeError, message),
        (lambda: df.writeTo("t").partitionedBy(bad), lambda w: w.create(),
         UnicodeEncodeError, message),
        (lambda: df.writeTo("t").option(1, "v"), lambda w: w.create(), TypeError, bad_type),
    ]
    for setup, action, error_type, error_message in cases:
        writer = setup()
        with pytest.raises(error_type, match=error_message):
            action(writer)
    assert service.analyze_requests == [] and service.execute_requests == []
    # A builder keeps its configs, and getOrCreate fails with the first of them.
    builder = SparkSession.builder.config(bad, "v").config("spark.k", "v")
    with pytest.raises(UnicodeEncodeError, match=message):
        builder.getOrCreate()
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        SparkSession.builder.config(1, "v").getOrCreate()


def test_table_property_values_that_are_not_str_fail_the_write_as_pyspark(mock_connect):
    # As PySpark's tableProperty, which keeps a value as it is in its dict, and whose command sends
    # the map at the write: a value or a key that is not a str or bytes fails the write with the
    # TypeError of protobuf, and bytes that are not UTF-8 with its UnicodeDecodeError, while bytes
    # that are UTF-8 are sent as their text. The setter returns, with no request sent.
    spark, service = mock_connect
    df = spark.range(1)
    bad_type = "^bad argument type for built-in operation$"
    for value in [5, 5.5, True, [1], ("a",), bytearray(b"x")]:
        with pytest.raises(TypeError, match=bad_type):
            df.writeTo("t").tableProperty("k", value).create()
    with pytest.raises(TypeError, match=bad_type):
        df.writeTo("t").tableProperty(5, "v").create()
    with pytest.raises(TypeError, match=bad_type):
        df.writeTo("t").tableProperty(None, "v").create()
    with pytest.raises(UnicodeDecodeError, match="^'utf-8' codec can't decode byte 0xff"):
        df.writeTo("t").tableProperty("k", b"\xff").create()
    assert service.analyze_requests == [] and service.execute_requests == []
    # A value that is replaced, or unset, by a later call is no longer in the map.
    writer = df.writeTo("t").tableProperty("k", 5).tableProperty("k", "ok")
    writer.append()
    writer = df.writeTo("t").tableProperty("k", 5).tableProperty("k", None)
    writer.append()
    # Bytes that are UTF-8 are sent as their text, WriteOperationV2.table_properties=6.
    df.writeTo("t").tableProperty("k", b"x").append()
    plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
    sent = parse_message(parse_message(plan[2][0])[4][0])
    assert [parse_message(entry)[2] for entry in sent.get(6, [])] == [[b"x"]]


def test_stream_reader_strings_that_utf8_cannot_encode_fail_the_plan_as_pyspark(mock_connect):
    # As PySpark's DataStreamReader, whose DataSource and Read plans keep a str of a format, a
    # schema, an option, a path or a table name, and fail when isStreaming builds the plan: the
    # call returns, with no request sent.
    spark, service = mock_connect
    bad = "a\ud800b"
    message = re.escape(
        "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed")
    path = "/p"
    for build in [
        lambda: spark.readStream.format(bad).load(),
        lambda: spark.readStream.format(bad).load(path),
        lambda: spark.readStream.format("json").load(bad),
        lambda: spark.readStream.table(bad),
        lambda: spark.readStream.parquet(bad),
        lambda: spark.readStream.schema("a INT").parquet(bad),
        lambda: spark.readStream.json(bad),
        lambda: spark.readStream.csv(bad),
        lambda: spark.readStream.orc(bad),
        lambda: spark.readStream.text(bad),
        lambda: spark.readStream.option(bad, "v").json(path),
        lambda: spark.readStream.option("k", bad).json(path),
        lambda: spark.readStream.options(k=bad).json(path),
        lambda: spark.readStream.options(**{bad: "v"}).json(path),
        lambda: spark.readStream.schema(bad + " INT").json(path),
        lambda: spark.readStream.format("json").load(path, schema=bad),
        lambda: spark.readStream.format("json").load(path, **{"k": bad}),
        lambda: spark.readStream.format("json").option("k", bad).load(path),
    ]:
        df = build()
        with pytest.raises(UnicodeEncodeError, match=message) as error:
            df.isStreaming
        assert type(error.value) is UnicodeEncodeError
    assert service.analyze_requests == [] and service.execute_requests == []
    # A format that a later call replaces is no longer in the plan. An option of None leaves the
    # str of an option that is set, as PySpark's stream reader does, and a replaced one is gone.
    assert spark.readStream.format(bad).format("json").load(path).isStreaming is not None
    with pytest.raises(UnicodeEncodeError, match=message):
        spark.readStream.option(bad, "v").option(bad, None).json(path).isStreaming
    assert spark.readStream.option("k", bad).option("k", "v").json(path).isStreaming is not None


def test_stream_reader_formats_are_kept_until_load_as_pyspark(mock_connect):
    # As PySpark's DataStreamReader.load, which checks the path before its DataSource asserts the
    # format, and whose format methods of a path set their own.
    from pyspark.errors import PySparkValueError

    spark, service = mock_connect
    with pytest.raises(PySparkValueError) as error:
        spark.readStream.format(5).load("")
    assert error.value.getCondition() == "VALUE_NOT_NON_EMPTY_STR"
    for call in [
        lambda: spark.readStream.format(b"rate").load(),
        lambda: spark.readStream.load(format=b"rate"),
    ]:
        with pytest.raises(AssertionError) as error:
            call()
        assert str(error.value) == ""
    stream = spark.readStream.format(b"rate").format("rate").load()
    assert stream.schema is not None
    # Read.data_source=2 -> DataSource.format=1.
    data_source = parse_message(_sent_relation(service.analyze_requests[-1], 2)[2][0])
    assert data_source[1] == [b"rate"]
    spark.readStream.format(5).json("p")


def test_reader_jdbc_sends_url_and_dbtable_as_options_of_to_str_as_pyspark(mock_connect):
    # As PySpark's DataFrameReader.jdbc, which sets url and dbtable as the options of to_str: a
    # bool is "true" or "false", another object its str(), and None leaves the option out.
    spark, service = mock_connect

    def options(df):
        assert df.schema is not None
        # Read.data_source=2 -> DataSource.options=3, the entries of which have key=1, value=2.
        data_source = parse_message(_sent_relation(service.analyze_requests[-1], 2)[2][0])
        return {parse_message(e)[1][0]: parse_message(e)[2][0] for e in data_source.get(3, [])}

    assert options(spark.read.jdbc("jdbc:zz:nx", b"t")) == {
        b"url": b"jdbc:zz:nx", b"dbtable": b"b't'"}
    assert options(spark.read.jdbc("jdbc:zz:nx", 7))[b"dbtable"] == b"7"
    assert options(spark.read.jdbc(True, "t"))[b"url"] == b"true"
    unset = options(spark.read.jdbc("jdbc:zz:nx", None))
    assert b"dbtable" not in unset and unset[b"url"] == b"jdbc:zz:nx"


def test_writer_jdbc_sends_url_and_dbtable_as_options_of_to_str_as_pyspark(mock_connect):
    # As PySpark's DataFrameWriter.jdbc, which sets url and dbtable as options, which skip a None,
    # of to_str, and writes with the format "jdbc".
    spark, service = mock_connect
    df = spark.range(1)
    df.write.jdbc("jdbc:zz:nx", b"t")
    # Command.write_operation=2 -> WriteOperation.source=2, options=9 (key=1, value=2).
    plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
    operation = parse_message(parse_message(plan[2][0])[2][0])
    assert operation[2] == [b"jdbc"]
    assert {parse_message(e)[1][0]: parse_message(e)[2][0] for e in operation[9]} == {
        b"url": b"jdbc:zz:nx", b"dbtable": b"b't'"}
    df.write.jdbc(None, 7)
    plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
    operation = parse_message(parse_message(plan[2][0])[2][0])
    assert {parse_message(e)[1][0]: parse_message(e)[2][0] for e in operation[9]} == {
        b"dbtable": b"7"}


def test_partition_columns_take_bytes_at_each_write_as_pyspark(mock_connect):
    # As PySpark's WriteOperation, which sets each partitioning column in its string field at the
    # write: bytes are sent decoded, a list or tuple alone stands for its items, a later call
    # replaces the columns, and a column that is not a str of UTF-8 fails each write, not the call.
    spark, service = mock_connect
    df = spark.range(1)

    def sent_operation():
        # ExecutePlanRequest.plan=3 -> Plan.command=2 -> Command.write_operation=2.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(parse_message(plan[2][0])[2][0])

    # WriteOperation.partitioning_columns=7.
    df.write.partitionBy(b"k").format("noop").save()
    assert sent_operation()[7] == [b"k"]
    df.write.save(format="noop", partitionBy=[b"a", "b"])
    assert sent_operation()[7] == [b"a", b"b"]
    requests = len(service.execute_requests)
    writer = df.write.partitionBy(5)
    assert len(service.execute_requests) == requests
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        writer.format("noop").save()
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        df.write.partitionBy("a", ["b"]).format("noop").save()
    df.write.partitionBy(5).partitionBy(b"k").format("noop").save()
    assert sent_operation()[7] == [b"k"]
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        df.write.parquet("p", partitionBy=5)
    assert len(service.execute_requests) == requests + 1


def test_v2_using_takes_bytes_and_fails_each_write_as_pyspark(mock_connect):
    # As PySpark's WriteOperationV2, which sets the provider after the table at each write: bytes
    # are sent decoded, and another object fails each write after the table, while using keeps it.
    from pyspark.sql import functions as F

    spark, service = mock_connect
    df = spark.range(1)

    def sent_operation():
        # ExecutePlanRequest.plan=3 -> Plan.command=2 -> Command.write_operation_v2=4.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(parse_message(plan[2][0])[4][0])

    # WriteOperationV2.table_name=2, provider=3.
    df.writeTo("t").using(b"noop").append()
    assert sent_operation()[3] == [b"noop"]
    df.writeTo("t").using(5).using("noop").append()
    assert sent_operation()[3] == [b"noop"]
    df.writeTo("t").using(5).using(None).append()
    assert 3 not in sent_operation()
    requests = len(service.execute_requests)
    writer = df.writeTo("t").using(5)
    assert len(service.execute_requests) == requests
    for write in [writer.create, writer.replace, writer.createOrReplace, writer.append,
                  writer.overwritePartitions, lambda: writer.overwrite(F.lit(True))]:
        with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
            write()
    with pytest.raises(UnicodeDecodeError):
        df.writeTo(b"\xff").using(5).append()
    assert len(service.execute_requests) == requests


def test_kept_arguments_of_the_writers_and_readers_are_seen_by_the_collector_as_pyspark(
        mock_connect):
    # The kept arguments of the writers and readers are visited by Python's garbage collector, which
    # frees a reference cycle through them.
    import gc
    import weakref

    spark, _ = mock_connect
    df = spark.range(1)

    class Holder:
        pass

    for keep in [
        lambda h: df.write.format(h),
        lambda h: df.write.mode(h),
        lambda h: df.write.partitionBy(h),
        lambda h: df.write.clusterBy(h),
        lambda h: df.writeTo("t").using(h),
        lambda h: df.writeTo("t").clusterBy(h),
        lambda h: spark.read.format(h),
        lambda h: spark.readStream.format(h),
    ]:
        holder = Holder()
        holder.kept = keep(holder)
        ref = weakref.ref(holder.kept)
        del holder
        gc.collect()
        assert ref() is None


def test_stream_writer_columns_take_bytes_at_the_call_as_pyspark(mock_connect):
    # As PySpark's DataStreamWriter, which clears and then extends the partitioning and clustering
    # columns in their protobuf string fields at the call: bytes are sent decoded, a list or tuple
    # alone stands for its items, and a column that does not convert raises at the call, leaving
    # none.
    spark, service = mock_connect
    stream = spark.readStream.format("rate").load().writeStream

    def sent_start():
        # ExecutePlanRequest.plan=3 -> Plan.command=2 -> Command.write_stream_operation_start=6.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(parse_message(plan[2][0])[6][0])

    stream.partitionBy(b"k", "j").clusterBy([b"c"])
    # ExecutePlanResponse.write_stream_operation_start_result=8: query_id=1 (id=1, run_id=2).
    service.execute_payload = message_field(
        8, message_field(1, message_field(1, "q") + message_field(2, "r")))
    stream.start(format="noop")
    # WriteStreamOperationStart.partitioning_column_names=4, clustering_column_names=15.
    assert sent_start()[15] == [b"c"]
    stream.start(partitionBy=[b"p", "q"], format="noop")
    assert sent_start()[4] == [b"p", b"q"]
    requests = len(service.execute_requests)
    message = "^bad argument type for built-in operation$"
    with pytest.raises(TypeError, match=message):
        stream.partitionBy(b"a", 5)
    with pytest.raises(TypeError, match=message):
        stream.clusterBy(None)
    with pytest.raises(UnicodeDecodeError):
        stream.start(partitionBy=b"\xff")
    assert len(service.execute_requests) == requests
    stream.start(format="noop")
    assert 4 not in sent_start()


def test_writer_clusters_take_bytes_and_fail_each_write_as_pyspark(mock_connect):
    # As PySpark's DataFrameWriter.clusterBy, which asserts the count after a list or tuple alone is
    # unpacked, and keeps the columns for each write: bytes are sent decoded, another object fails
    # each write after the partitioning columns, and not the call.
    spark, service = mock_connect
    df = spark.range(1)

    def sent_operation():
        # ExecutePlanRequest.plan=3 -> Plan.command=2 -> Command.write_operation=2.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(parse_message(plan[2][0])[2][0])

    # WriteOperation.clustering_columns=10.
    df.write.clusterBy(b"k").format("noop").mode("overwrite").save()
    assert sent_operation()[10] == [b"k"]
    df.write.clusterBy([b"a", "b"]).format("noop").mode("overwrite").save()
    assert sent_operation()[10] == [b"a", b"b"]
    with pytest.raises(AssertionError, match="^clusterBy needs one or more clustering columns.$"):
        df.write.clusterBy([])
    requests = len(service.execute_requests)
    writer = df.write.clusterBy(5)
    assert len(service.execute_requests) == requests
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        writer.format("noop").mode("overwrite").save()
    # The partitioning columns are converted first.
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        df.write.partitionBy(5).clusterBy(b"\xff").format("noop").save()
    with pytest.raises(UnicodeDecodeError):
        df.write.clusterBy(b"\xff").format("noop").save()
    assert len(service.execute_requests) == requests


