def test_stream_writer_keeps_the_steps_before_a_failing_one_as_pyspark(mock_connect):
    # As PySpark's _start_internal, which sets the options, the output mode, the partitioning
    # columns, the format and the query name on the writer in turn, each in place: a step that
    # fails keeps the steps before it, and a failing partitioning clears its columns.
    from pyspark.errors import PySparkValueError

    spark, service = mock_connect
    # ExecutePlanResponse.write_stream_operation_start_result=8: query_id=1 (id=1, run_id=2).
    service.execute_payload = message_field(
        8, message_field(1, message_field(1, "q") + message_field(2, "r")))
    message = "^bad argument type for built-in operation$"

    def started(stream):
        # Command.write_stream_operation_start=6 -> WriteStreamOperationStart; its options=3 map
        # has key=1 and value=2, partitioning_column_names=4, output_mode=9.
        stream.start(format="noop")
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        start = parse_message(parse_message(plan[2][0])[6][0])
        options = {parse_message(e)[1][0]: parse_message(e)[2][0] for e in start.get(3, [])}
        return start, options

    rate = spark.readStream.format("rate").load()
    stream = rate.writeStream
    with pytest.raises(TypeError, match=message):
        stream.start(outputMode=5, foo="1")
    start, options = started(stream)
    assert options == {b"foo": b"1"} and 9 not in start

    stream = rate.writeStream
    with pytest.raises(TypeError, match=message):
        stream.start(outputMode=b"append", format=5)
    start, _ = started(stream)
    assert start[9] == [b"append"]

    stream = rate.writeStream
    with pytest.raises(TypeError, match=message):
        stream.start(partitionBy=5, bar="1")
    start, options = started(stream)
    assert options == {b"bar": b"1"} and 4 not in start

    stream = rate.writeStream
    stream.partitionBy(b"k")
    with pytest.raises(TypeError, match=message):
        stream.start(partitionBy=5)
    start, _ = started(stream)
    assert 4 not in start

    stream = rate.writeStream
    with pytest.raises(TypeError, match=message):
        stream.toTable("t", format=5, qux="1")
    start, options = started(stream)
    assert options == {b"qux": b"1"}

    stream = rate.writeStream
    with pytest.raises(PySparkValueError) as error:
        stream.start(queryName="", quux="1")
    assert error.value.getCondition() == "VALUE_NOT_NON_EMPTY_STR"
    start, options = started(stream)
    assert options == {b"quux": b"1"}


def test_readers_keep_the_format_of_a_load_whose_schema_fails_as_pyspark(mock_connect):
    # As PySpark's load, which sets the format, then the schema, then the options on the reader in
    # turn: a schema that is not a str or a struct fails after the format, which the reader keeps,
    # and before the options, which are not applied.
    from pyspark.errors import PySparkTypeError

    spark, service = mock_connect
    reader = spark.read
    with pytest.raises(PySparkTypeError) as error:
        reader.load(format="csv", schema=5, foo="1")
    assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
    assert reader.load().schema is not None
    # Read.data_source=2 -> DataSource.format=1, and options=3 (key=1).
    data_source = parse_message(_sent_relation(service.analyze_requests[-1], 2)[2][0])
    assert data_source[1] == [b"csv"]
    assert b"foo" not in {parse_message(e)[1][0] for e in data_source.get(3, [])}

    stream_reader = spark.readStream
    with pytest.raises(PySparkTypeError):
        stream_reader.load(format="rate", schema=5, foo="1")
    assert stream_reader.load().schema is not None
    data_source = parse_message(_sent_relation(service.analyze_requests[-1], 2)[2][0])
    assert data_source[1] == [b"rate"]


def test_stream_writer_skips_a_false_path_and_table_as_pyspark(mock_connect):
    # As PySpark's `_start_internal`, which sets the path of start and the table of toTable in
    # the string fields of its command only `if path:` and `if tableName:`: a false one, such as
    # 0 or "", starts the query on the sink of its format, and another is converted as protobuf's
    # default backend (upb) converts a string field.
    spark, service = mock_connect
    # ExecutePlanResponse.write_stream_operation_start_result=8: query_id=1 (id=1, run_id=2).
    service.execute_payload = message_field(
        8, message_field(1, message_field(1, "q") + message_field(2, "r")))
    stream = spark.readStream.format("rate").load().writeStream.format("noop")

    def sent_start():
        # ExecutePlanRequest.plan=3 -> Plan.command=2 -> Command.write_stream_operation_start=6.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(parse_message(plan[2][0])[6][0])

    for false in [0, False, [], {}, "", b"", None]:
        for start in [stream.start, stream.toTable]:
            start(false)
            # WriteStreamOperationStart.path=11 and table_name=12.
            assert not {11, 12} & set(sent_start())
    stream.toTable(b"t")
    assert sent_start()[12] == [b"t"]
    requests = len(service.execute_requests)
    for call in [lambda: stream.start([1]), lambda: stream.toTable(1),
                 lambda: stream.toTable([1])]:
        with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
            call()
    with pytest.raises(UnicodeDecodeError):
        stream.toTable(b"\xff")

    class Ambiguous:
        def __bool__(self):
            raise ValueError("ambiguous")

    for start in [stream.start, stream.toTable]:
        with pytest.raises(ValueError, match="^ambiguous$"):
            start(Ambiguous())
    assert len(service.execute_requests) == requests


def _untyped_group_function(key, data: object) -> object:
    # Of type hints from which PySpark's applyInPandas and applyInArrow infer no eval type.
    return data


def _warned_grouped_apply(spark):
    from pyspark.sql.functions import PandasUDFType, pandas_udf

    grouped_map = pandas_udf(lambda pdf: pdf, "id long", PandasUDFType.GROUPED_MAP)
    return spark.range(1).groupBy("id").apply(grouped_map)


def _warned_window(spark):
    # A request of a window of no partitions, whose plan PySpark builds as it sends it.
    from pyspark.sql import Window
    from pyspark.sql import functions as F

    return spark.range(1).select(F.row_number().over(Window.orderBy("id"))).collect()


def _warned_column_key(method):
    def call(spark):
        from pyspark.sql import functions as F

        return getattr(F.col("a"), method)(F.col("k"))

    return call


# The calls that warn, with the module of `pyspark.sql.connect` and the line of PySpark's
# `warnings.warn` of each warning, of Apache Spark v4.3.0, and the category of the warning.
PYSPARKS_WARNINGS = [
    ("registerTempTable", lambda spark: spark.range(1).registerTempTable("v"),
     "dataframe", 2259, FutureWarning),
    ("replace", lambda spark: spark.range(1).replace({1: 2}, value=3), "dataframe", 1541,
     UserWarning),
    ("na.replace", lambda spark: spark.range(1).na.replace({1: 2}, 3), "dataframe", 1541,
     UserWarning),
    ("getItem", _warned_column_key("getItem"), "column", 527, FutureWarning),
    ("getField", _warned_column_key("getField"), "column", 537, FutureWarning),
    ("functionExists", lambda spark: spark.catalog.functionExists("f", "db"), "catalog", 168,
     FutureWarning),
    ("listColumns", lambda spark: spark.catalog.listColumns("t", "db"), "catalog", 195,
     FutureWarning),
    ("tableExists", lambda spark: spark.catalog.tableExists("t", "db"), "catalog", 218,
     FutureWarning),
    ("createExternalTable",
     lambda spark: spark.catalog.createExternalTable("t", "/tmp/t", "parquet"), "catalog", 236,
     FutureWarning),
    ("registerFunction", lambda spark: spark.catalog.registerFunction("f", lambda x: x),
     "catalog", 403, FutureWarning),
    ("apply", _warned_grouped_apply, "group", 285, UserWarning),
    ("applyInPandas",
     lambda spark: spark.range(1).groupBy("id").applyInPandas(_untyped_group_function, "id long"),
     "group", 308, UserWarning),
    ("applyInArrow",
     lambda spark: spark.range(1).groupBy("id").applyInArrow(_untyped_group_function, "id long"),
     "group", 495, UserWarning),
    ("samplingRatio", lambda spark: _local_create_dataframe([(1,)], None, 0.5, session=spark),
     "session", 484, UserWarning),
    ("verifySchema",
     lambda spark: _local_create_dataframe([(1,)], None, None, True, session=spark), "session",
     487, UserWarning),
    ("conf.set", lambda spark: spark.conf.set("k", "v"), "conf", 45, UserWarning),
    ("conf.unset", lambda spark: spark.conf.unset("k"), "conf", 100, UserWarning),
    ("builder.config",
     lambda spark: SparkSession.builder.remote("sc://localhost:1").config("k", "v").getOrCreate(),
     "conf", 61, UserWarning),
    ("window", _warned_window, "expressions", 1126, UserWarning),
]


@pytest.mark.parametrize(
    "call, module, line, category",
    [case[1:] for case in PYSPARKS_WARNINGS],
    ids=[case[0] for case in PYSPARKS_WARNINGS],
)
def test_warnings_are_of_the_module_and_line_of_pysparks_warn(
    mock_connect, call, module, line, category
):
    # As PySpark's `warnings.warn` of each, whose warning is of the frame of its module of
    # `pyspark.sql.connect`: of that module, of its registry of the warnings that it showed, and of
    # the line of the call, in the file of the drop-in's module of that name. So the filters of a
    # module, such as `filterwarnings("ignore", module="pyspark")`, and of a line take it, and the
    # "default" action shows it once, as PySpark's. The drop-in's module ends before the line, so
    # the warning shows no source line.
    import importlib
    import linecache
    import warnings

    spark, service = mock_connect
    service.config_warnings = ["The configuration is deprecated."]
    shim = importlib.import_module(f"pyspark.sql.connect.{module}")

    def warned(action, *filters):
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter(action)
            for keywords in filters:
                warnings.filterwarnings("ignore", **keywords)
            for _ in range(2):
                with contextlib.suppress(Exception):
                    call(spark)
        return [w for w in caught if w.category is category]

    assert {(w.filename, w.lineno) for w in warned("always")} == {(shim.__file__, line)}
    assert linecache.getline(shim.__file__, line) == ""
    assert warned("always", {"module": "pyspark"}) == []
    assert warned("always", {"module": shim.__name__, "lineno": line}) == []
    assert len(warned("default")) == 1


def test_register_temp_table_warns_and_replaces_the_view_as_pyspark(mock_connect):
    # As PySpark's registerTempTable, which warns that it is deprecated, and then replaces the view
    # as createOrReplaceTempView does, which converts the name after the warning.
    import warnings

    spark, service = mock_connect
    df = spark.range(1)
    message = "Deprecated in 2.0, use createOrReplaceTempView instead."
    with pytest.warns(FutureWarning) as record:
        df.registerTempTable("v")
    assert [str(w.message) for w in record] == [message]
    # ExecutePlanRequest.plan=3 -> Plan.command=2 -> Command.create_dataframe_view=3:
    # CreateDataFrameViewCommand.name=2 and replace=4, not is_global=3.
    plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
    view = parse_message(parse_message(plan[2][0])[3][0])
    assert (view[2], view[4], 3 in view) == ([b"v"], [1], False)
    requests = len(service.execute_requests)
    with pytest.warns(FutureWarning, match=re.escape(message)):
        with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
            df.registerTempTable(1)
    with warnings.catch_warnings():
        warnings.simplefilter("error", FutureWarning)
        with pytest.raises(FutureWarning, match=re.escape(message)):
            df.registerTempTable(1)
    assert len(service.execute_requests) == requests


def test_catalog_writer_and_unpersist_flags_convert_as_pyspark(mock_connect):
    # As PySpark: the flags that the catalog passes to the constructor of its message (dropTable,
    # dropView, createDatabase and dropDatabase) or sets in its plan (asSerde, noScan), and the
    # `blocking` of unpersist, are converted as protobuf's default backend (upb) converts a bool
    # field: an int by its truth, a NumPy bool, and the TypeError or OverflowError of another
    # object; None leaves a field of a constructor unset, and is the TypeError of a field that the
    # plan sets. insertInto takes the truth of an `overwrite` that is not None.
    spark, service = mock_connect
    catalog = spark.catalog
    for call, operation, fields in [
        (lambda: catalog.dropTable("t", ifExists=1, purge=np.bool_(True)), 27,
         {1: [b"t"], 2: [1], 3: [1]}),
        (lambda: catalog.dropTable("t", None, 0), 27, {1: [b"t"]}),
        (lambda: catalog.dropView("v", ifExists=2), 28, {1: [b"v"], 2: [1]}),
        (lambda: catalog.createDatabase("d", ifNotExists=-1), 29, {1: [b"d"], 2: [1]}),
        (lambda: catalog.dropDatabase("d", 1, None), 30, {1: [b"d"], 2: [1]}),
        (lambda: catalog.getCreateTableString("t", asSerde=1), 34, {1: [b"t"], 2: [1]}),
        (lambda: catalog.analyzeTable("t", 1), 36, {1: [b"t"], 2: [1]}),
    ]:
        requests = len(service.execute_requests)
        with contextlib.suppress(Exception):
            call()
        assert len(service.execute_requests) == requests + 1
        assert _sent_catalog(service.execute_requests[-1], operation) == fields
    requests = len(service.execute_requests)
    for flag, error, message in [
        ("x", TypeError, "'str' object cannot be interpreted as an integer"),
        (1.5, TypeError, "'float' object cannot be interpreted as an integer"),
        (np.array([1]), TypeError, "[1] has type ndarray, but expected one of: bool"),
        (2**70, OverflowError, "Python int too large to convert to C long"),
    ]:
        for call in [
            lambda: catalog.dropTable("t", ifExists=flag),
            lambda: catalog.dropTable("t", purge=flag),
            lambda: catalog.dropView("v", ifExists=flag),
            lambda: catalog.createDatabase("d", ifNotExists=flag),
            lambda: catalog.dropDatabase("d", cascade=flag),
            lambda: catalog.getCreateTableString("t", asSerde=flag),
            lambda: catalog.analyzeTable("t", noScan=flag),
            lambda: spark.range(1).unpersist(flag),
        ]:
            with pytest.raises(error, match=f"^{re.escape(message)}$"):
                call()
    for call in [lambda: catalog.getCreateTableString("t", None),
                 lambda: catalog.analyzeTable("t", noScan=None)]:
        with pytest.raises(TypeError, match="^'NoneType' object cannot be interpreted as an "):
            call()
    # In the order of the fields: the name, and then each flag.
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        catalog.dropTable(1, ifExists="x")
    with pytest.raises(TypeError, match="^'str' object"):
        catalog.dropTable("t", ifExists="x", purge=1.5)
    assert len(service.execute_requests) == requests
    # AnalyzePlanRequest.unpersist=15 -> Unpersist.blocking=2, which PySpark's request sets
    # unless it is None: of its default False too, and not of None, which leaves the server's.
    for call, sent in [
        (lambda: spark.range(1).unpersist(blocking=1), [1]),
        (lambda: spark.range(1).unpersist(np.bool_(False)), [0]),
        (lambda: spark.range(1).unpersist(), [0]),
        (lambda: spark.range(1).unpersist(None), None),
        (lambda: spark.range(1).unpersist(blocking=None), None),
    ]:
        call()
        assert parse_message(parse_message(service.analyze_requests[-1])[15][0]).get(2) == sent

    def sent_mode():
        # ExecutePlanRequest.plan=3 -> Plan.command=2 -> Command.write_operation=2 ->
        # WriteOperation.mode=5 (SAVE_MODE_APPEND=1, SAVE_MODE_OVERWRITE=2).
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(parse_message(plan[2][0])[2][0]).get(5)

    for overwrite, mode in [(1, [2]), ("x", [2]), ([1], [2]), (0, [1]), ("", [1]), ([], [1])]:
        spark.range(1).write.insertInto("t", overwrite=overwrite)
        assert sent_mode() == mode

    class Ambiguous:
        def __bool__(self):
            raise ValueError("ambiguous")

    requests = len(service.execute_requests)
    with pytest.raises(ValueError, match="^ambiguous$"):
        spark.range(1).write.insertInto(1, overwrite=Ambiguous())
    assert len(service.execute_requests) == requests


def test_create_database_takes_no_properties_of_a_false_value_as_pyspark(mock_connect):
    # As PySpark's CreateDatabase, which takes `properties or {}`, before the constructor of its
    # message converts the database and `ifNotExists`, and then sets each of the
    # `properties.items()`.
    import types

    spark, service = mock_connect
    catalog = spark.catalog
    for properties in [[], 0, "", (), {}, None]:
        catalog.createDatabase("d", properties=properties)
        # Catalog.create_database=29: db_name=1, and properties=3, a map of key=1 and value=2.
        assert _sent_catalog(service.execute_requests[-1], 29) == {1: [b"d"]}
    catalog.createDatabase("d", properties=types.MappingProxyType({"k": "v"}))
    assert _sent_catalog(service.execute_requests[-1], 29)[3] == [
        message_field(1, "k") + message_field(2, "v")]

    class Ambiguous:
        def __bool__(self):
            raise ValueError("ambiguous")

    requests = len(service.execute_requests)
    for properties, error, message in [
        ([("k", "v")], AttributeError, "'list' object has no attribute 'items'"),
        ("kv", AttributeError, "'str' object has no attribute 'items'"),
    ]:
        with pytest.raises(error, match=f"^{re.escape(message)}$"):
            catalog.createDatabase("d", properties=properties)
    with pytest.raises(ValueError, match="^ambiguous$"):
        catalog.createDatabase(1, properties=Ambiguous())
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        catalog.createDatabase(1, properties=[("k", "v")])
    with pytest.raises(TypeError, match="^'str' object cannot be interpreted as an integer$"):
        catalog.createDatabase("d", ifNotExists="x", properties=[("k", "v")])
    assert len(service.execute_requests) == requests


def test_create_table_and_create_external_table_bind_their_arguments_as_pyspark(mock_connect):
    # As PySpark's createExternalTable(tableName, path=None, source=None, schema=None, **options),
    # which takes no description but of the options, which it passes to createTable, and
    # createTable(tableName, path=None, source=None, schema=None, description=None, **options):
    # Python's binding raises its TypeErrors, which count self, before the method warns.
    import inspect
    import warnings

    spark, service = mock_connect
    catalog = spark.catalog
    requests = len(service.execute_requests)
    with warnings.catch_warnings(record=True) as record:
        warnings.simplefilter("always")
        for call, message in [
            (lambda: catalog.createExternalTable("t", None, None, None, "d"),
             "Catalog.createExternalTable() takes from 2 to 5 positional arguments but 6 were "
             "given"),
            (lambda: catalog.createTable("t", None, None, None, None, "x", "y"),
             "Catalog.createTable() takes from 2 to 6 positional arguments but 8 were given"),
            (lambda: catalog.createTable("t", None, None, 5, None, "x"),
             "Catalog.createTable() takes from 2 to 6 positional arguments but 7 were given"),
            (lambda: catalog.createExternalTable("t", None, None, None, 1, path="p"),
             "Catalog.createExternalTable() got multiple values for argument 'path'"),
            (lambda: catalog.createExternalTable(path="p"),
             "Catalog.createExternalTable() missing 1 required positional argument: 'tableName'"),
        ]:
            with pytest.raises(TypeError, match=f"^{re.escape(message)}$"):
                call()
    assert record == [] and len(service.execute_requests) == requests
    with pytest.warns(FutureWarning, match="createExternalTable is deprecated"):
        catalog.createExternalTable("t", "/p", description="d", k="v")
    # Catalog.create_table=14: table_name=1, path=2, description=4 and options=6.
    create = _sent_catalog(service.execute_requests[-1], 14)
    assert (create[1], create[2], create[4]) == ([b"t"], [b"/p"], [b"d"])
    assert [parse_message(entry) for entry in create[6]] == [{1: [b"k"], 2: [b"v"]}]
    with pytest.warns(FutureWarning):
        catalog.createExternalTable("t", description=None)
    assert _sent_catalog(service.execute_requests[-1], 14) == {1: [b"t"]}
    catalog.createTable("t", "/p", "parquet", None, "d")
    create = _sent_catalog(service.execute_requests[-1], 14)
    assert (create[2], create[3], create[4]) == ([b"/p"], [b"parquet"], [b"d"])

    def parameters(method):
        signature = inspect.signature(method)
        return [(p.name, p.kind.name, p.default) for p in signature.parameters.values()]

    empty = inspect.Parameter.empty
    head = [("tableName", "POSITIONAL_OR_KEYWORD", empty), ("path", "POSITIONAL_OR_KEYWORD", None),
            ("source", "POSITIONAL_OR_KEYWORD", None), ("schema", "POSITIONAL_OR_KEYWORD", None)]
    options = [("options", "VAR_KEYWORD", empty)]
    assert parameters(catalog.createExternalTable) == head + options
    assert parameters(catalog.createTable) == head + [
        ("description", "POSITIONAL_OR_KEYWORD", None)] + options


def test_readers_keep_their_settings_when_the_path_is_not_a_str_as_pyspark(mock_connect):
    # As PySpark, whose format readers set the options and the format before they check the path,
    # which is an AssertionError for a path that is not a str.
    from pyspark.errors import PySparkTypeError

    spark, _ = mock_connect
    reader = spark.read.option("wholetext", True)
    with pytest.raises(AssertionError):
        reader.text(123)
    assert reader._format == "text" and reader._options == {"wholetext": "false"}
    reader = spark.read.option("mergeSchema", True)
    with pytest.raises(AssertionError):
        reader.parquet(123)
    assert reader._format == "parquet" and reader._options == {"mergeSchema": "true"}
    reader = spark.read.option("sep", ";")
    with pytest.raises(AssertionError):
        reader.csv(123)
    assert reader._format == "csv" and reader._options == {"sep": ";"}
    # json and xml raise a PySparkTypeError, after their options, and xml's schema, which
    # json does not set on a path of another type.
    reader = spark.read
    with pytest.raises(PySparkTypeError) as error:
        reader.json(123, schema="a int", multiLine=True)
    assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
    assert reader._format is None and reader._options == {"multiLine": "true"}
    assert reader._schema == ""
    reader = spark.read
    with pytest.raises(PySparkTypeError):
        reader.xml(123, schema="a int", rowTag="r")
    assert reader._format is None and reader._options == {"rowTag": "r"}
    assert reader._schema == "a int"


def test_writers_keep_their_settings_when_the_path_is_not_a_str_as_pyspark(mock_connect):
    # As PySpark, whose writer sets the settings of a call before it checks the path: a later
    # save of the writer sends the format and the options of the failed call.
    spark, service = mock_connect

    def sent_write():
        # ExecutePlanRequest.plan=3, Plan.command=2, Command.write_operation=2.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(parse_message(plan[2][0])[2][0])

    writer = spark.range(1).write.option("compression", "gzip")
    with pytest.raises(TypeError):
        writer.json(123)
    writer.save("p")
    # WriteOperation.source=2, and options=9, of entries of key=1 and value=2.
    assert sent_write()[2] == [b"json"]
    options = {parse_message(entry)[1][0]: parse_message(entry)[2][0] for entry in sent_write()[9]}
    assert options == {b"compression": b"gzip"}

    writer = spark.range(1).write.mode("overwrite")
    with pytest.raises(TypeError):
        writer.save(123, format="parquet")
    writer.save("p")
    # WriteOperation.source=2 and mode=5, of SAVE_MODE_OVERWRITE=2.
    assert sent_write()[2] == [b"parquet"] and sent_write()[5] == [2]


def test_stream_writers_keep_their_settings_when_the_path_is_not_a_str_as_pyspark(mock_connect):
    # As PySpark, whose start sets the format, query name and output mode before it checks the
    # path: a later start of the stream writer starts the query of the failed call's settings.
    spark, service = mock_connect
    # ExecutePlanResponse.write_stream_operation_start_result=8: query_id=1 (id=1, run_id=2).
    service.execute_payload = message_field(
        8, message_field(1, message_field(1, "q") + message_field(2, "r")))
    writer = spark.readStream.format("rate").load().writeStream
    with pytest.raises(TypeError):
        writer.start(123, format="memory", queryName="q", outputMode="append")
    assert service.execute_requests == []
    writer.start()
    # ExecutePlanRequest.plan=3 -> Plan.command=2 -> Command.write_stream_operation_start=6.
    plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
    start = parse_message(parse_message(plan[2][0])[6][0])
    # WriteStreamOperationStart.format=2, output_mode=9, query_name=10.
    assert start[2] == [b"memory"] and start[9] == [b"append"] and start[10] == [b"q"]
    assert 11 not in start


def test_protobuf_string_fields_take_bytes_and_refuse_other_objects_as_pyspark(mock_connect):
    # As protobuf's default (upb) backend, whose string fields PySpark sets as they are with the
    # keys of the runtime conf and of the options of the builder, the text of sql, the names of
    # `on` of _joinAsOf and the subset of replace: bytes are decoded as UTF-8, bytes that are not
    # UTF-8 raise the UnicodeDecodeError of their decoding, and another object the TypeError of
    # the field. A key of None is the empty key, as the constructor of KeyValue leaves it unset.
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import SparkSession

    spark, service = mock_connect
    df = spark.range(1)
    spark.conf.set(b"spark.k", b"v")
    spark.conf.set(None, "w")
    spark.conf.unset(b"spark.k")
    assert [pairs for pairs, _ in service.set_confs[-2:]] == [[("spark.k", "v")], [("", "w")]]
    assert service.unset_confs[-1] == ["spark.k"]
    builder = SparkSession.builder.remote("sc://localhost:1").config(b"spark.sql.b", "1")
    assert builder.config(map={b"spark.sql.m": "2"}).getOrCreate() is spark
    assert sorted(service.set_confs[-1][0]) == [("spark.sql.b", "1"), ("spark.sql.m", "2")]
    spark.sql(b"select 1")
    # ExecutePlanRequest.plan=3, Plan.command=2, Command.sql_command=5, SqlCommand.input=6,
    # Relation.sql=10, SQL.query=1.
    command = parse_message(parse_message(service.execute_requests[-1])[3][0])[2][0]
    relation = parse_message(parse_message(parse_message(command)[5][0])[6][0])
    assert parse_message(relation[10][0])[1] == [b"select 1"]
    # Relation.as_of_join=39 of AsOfJoin.using_columns=6, and Relation.replace=92 of
    # NAReplace.cols=2.
    df._joinAsOf(spark.range(1), "id", "id", on=["id", b"id"]).collect()
    assert _sent_relation(service.execute_requests[-1], 39, execute=True)[6] == [b"id", b"id"]
    df.replace(1, 2, subset=[b"id"]).collect()
    assert _sent_relation(service.execute_requests[-1], 92, execute=True)[2] == [b"id"]
    sent = len(service.execute_requests), len(service.set_confs), len(service.unset_confs)
    for call in [
        lambda: spark.conf.set(1, "v"),
        lambda: spark.conf.set("spark.k", 1.5),
        lambda: spark.conf.unset(None),
        lambda: spark.conf.isModifiable(1),
        lambda: spark.sql(None),
        lambda: spark.sql(1),
        # The names of these plans are set when the plan is built, which their requests raise.
        lambda: df._joinAsOf(spark.range(1), "id", "id", on=["id", 1]).collect(),
        lambda: df._joinAsOf(spark.range(1), "id", "id", on=["id", None]).schema,
        lambda: df.replace(1, 2, subset=["id", 1]).collect(),
        lambda: df.replace(1, 2, subset=("id", bytearray(b"id"))).schema,
    ]:
        with pytest.raises(TypeError) as error:
            call()
        assert type(error.value) is TypeError
        assert str(error.value) == "bad argument type for built-in operation"
    with pytest.raises(UnicodeDecodeError) as error:
        spark.sql(b"select \xff")
    assert str(error.value) == (
        "'utf-8' codec can't decode byte 0xff in position 7: invalid start byte")
    # The query is formatted as it is, and `args` are checked before it is set in the plan.
    with pytest.raises(TypeError, match="^expected str, got bytes$"):
        spark.sql(b"select {x}", x=1)
    with pytest.raises(PySparkTypeError) as error:
        spark.sql(1, args=1)
    assert error.value.getCondition() == "INVALID_TYPE"
    # An as-of column that is not a Column is a name, which PySpark's ColumnReference asserts is
    # a str, before `on` is looked at.
    for column in (1, b"id", None):
        for left, right in ((column, "id"), ("id", column)):
            with pytest.raises(AssertionError) as error:
                df._joinAsOf(spark.range(1), left, right, on=5)
            assert type(error.value) is AssertionError and str(error.value) == ""
    assert (len(service.execute_requests), len(service.set_confs),
            len(service.unset_confs)) == sent


def test_option_keys_are_checked_as_the_dicts_and_the_plans_of_pyspark(mock_connect):
    # As PySpark: the option of a writer of a value of None returns before it looks at the key,
    # as DataStreamReader.option does, while DataFrameReader.option keeps the None in its dict,
    # which hashes the key. The writers keep their other options in a dict too, which raises the
    # TypeError of an unhashable key, and set the key in a protobuf map of strings as it is, as
    # the writer of a stream does at once: bytes are decoded, and another object is the
    # TypeError of the field. The DataSource plan of the readers asserts that a key is a str.
    spark, service = mock_connect
    df = spark.range(1)
    stream = spark.readStream.format("rate").load().writeStream
    for writer in (df.write, df.writeTo("t"), stream, spark.readStream):
        assert writer.option([1], None) is writer
    with pytest.raises(TypeError, match="^unhashable type: 'list'$"):
        spark.read.option([1], None)
    reader = spark.read.option("k", "v")
    assert reader.option(1, None) is reader and reader.option(b"k", None) is reader
    assert reader._options == {"k": "v", 1: None, b"k": None}
    assert stream.option(b"k", "v") is stream
    for call in [
        lambda: df.write.option(bytearray(b"k"), "v"),
        lambda: df.writeTo("t").option([1], "v"),
        lambda: spark.read.option({}, "v"),
        lambda: spark.readStream.option(bytearray(b"k"), "v"),
    ]:
        with pytest.raises(TypeError, match="^unhashable type: "):
            call()
    for call in [
        lambda: stream.option(bytearray(b"k"), "v"),
        lambda: stream.option(1, "v"),
    ]:
        with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
            call()
    # As PySpark's, a key that is not a str is kept by option, and the DataSource of a format read
    # asserts it, at the call of the read; a table read fails at its plan instead (see below).
    for key in [1, b"k"]:
        reader = spark.read.option(key, "v")
        with pytest.raises(AssertionError) as error:
            reader.json("/p")
        assert type(error.value) is AssertionError and str(error.value) == ""
    for key in [b"k", None]:
        stream_reader = spark.readStream.option(key, "v")
        with pytest.raises(AssertionError) as error:
            stream_reader.json("/p")
        assert type(error.value) is AssertionError and str(error.value) == ""
    # A bytes key of a writer is sent decoded: Command.write_operation=2, WriteOperation.options=9.
    df.write.format("noop").option(b"k", "v").save()
    plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
    write = parse_message(parse_message(plan[2][0])[2][0])
    assert [parse_message(entry) for entry in write[9]] == [{1: [b"k"], 2: [b"v"]}]


