def test_sessions_and_dataframes_pickle_of_the_active_session_as_pyspark(mock_connect):
    # As PySpark Connect's, with cloudpickle: a session pickles as a function of its ID, which
    # gives back the active session of that ID, and a DataFrame of its session and its plan, of
    # its plan IDs, so that it is sent as it is. Where no session is active, as on a Python
    # worker of the server, both raise NO_ACTIVE_SESSION, as the session unpickles first; where
    # another is, PySparkAssertionError. Plain pickle cannot pickle the function, a local one.
    import pickle
    import threading

    from pyspark.errors import PySparkAssertionError, PySparkRuntimeError
    from pyspark.serializers import CloudPickleSerializer
    from pyspark.sql.connect.session import SparkSession

    spark, _ = mock_connect
    serializer = CloudPickleSerializer()
    assert serializer.loads(serializer.dumps(spark)) is spark
    df = spark.range(3).selectExpr("id * 2 AS x")
    copy = serializer.loads(serializer.dumps(df))
    assert type(copy) is type(df) and copy._relation_bytes() == df._relation_bytes()
    assert copy.sparkSession.session_id == spark.session_id
    for obj in (spark, df):
        with pytest.raises((AttributeError, pickle.PicklingError)):
            pickle.dumps(obj)

    errors = []

    def unpickle(data):
        try:
            serializer.loads(data)
        except PySparkRuntimeError as error:
            errors.append(error.getCondition())

    for obj in (spark, df):
        thread = threading.Thread(target=unpickle, args=(serializer.dumps(obj),))
        thread.start()
        thread.join()
    assert errors == ["NO_ACTIVE_SESSION", "NO_ACTIVE_SESSION"]
    with pytest.raises(PySparkAssertionError, match="Expected session ID does not match"):
        SparkSession._getActiveSessionIfMatches("another")


def test_unpickled_dataframes_request_their_schema_and_keep_the_cached_one_as_pyspark(
        mock_connect):
    # As PySpark's unpickle of a DataFrame, which builds the plan of the new DataFrame and requests
    # its schema, as pickle looks its `__setstate__` up through `__getattr__`, which reads its
    # columns, and then sets the `_cached_schema` of the state of the pickle: one request at each
    # unpickle, whose error the unpickle raises, and then the schema of a DataFrame that had one
    # is known, while one that had none is requested again. A plan that does not build pickles,
    # and its unpickle raises the error of its build, with no request: of an AttributeError, such
    # as of a join on a tuple or on a Row, PySpark's `_schema` falls back to the Column of
    # `__getattr__`, whose `fields` the columns iterate, so the unpickle, a copy and a deep copy,
    # which read the columns too, raise NOT_ITERABLE.
    import copy
    import pickle

    from pyspark.errors import PySparkTypeError, PySparkValueError
    from pyspark.errors.exceptions.connect import SparkConnectGrpcException
    from pyspark.serializers import CloudPickleSerializer
    from pyspark.sql import Row

    spark, service = mock_connect
    serializer = CloudPickleSerializer()
    cached = spark.range(3)
    schema = cached.schema
    for df, later in ((cached, 0), (spark.range(4), 1)):
        data = serializer.dumps(df)
        before = len(service.analyze_requests)
        unpickled = serializer.loads(data)
        assert len(service.analyze_requests) == before + 1
        assert unpickled.schema == schema and unpickled.columns == ["id"]
        assert len(service.analyze_requests) == before + 1 + later
    failing = [
        (cached.limit(2.0), TypeError, "'float' object cannot be interpreted as an integer"),
        (cached.alias("a\ud800"), UnicodeEncodeError,
         "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed"),
        (cached.to("a long"), PySparkValueError,
         "[UNSUPPORTED_OPERATION] data type a long is not supported."),
    ]
    requests = (len(service.analyze_requests), len(service.execute_requests))
    for df, error_type, message in failing:
        data = serializer.dumps(df)
        with pytest.raises(error_type) as error:
            serializer.loads(data)
        assert type(error.value) is error_type and str(error.value) == message
        with pytest.raises(AttributeError, match="Can't pickle local object"):
            pickle.dumps(df)
    joins = [cached.join(cached, ("id",)), cached.join(cached, [cached.id == cached.id, Row(a=1)])]
    for df in joins:
        data = serializer.dumps(df)
        for call in (lambda: serializer.loads(data), lambda: copy.copy(df),
                     lambda: copy.deepcopy(df)):
            with pytest.raises(PySparkTypeError) as error:
                call()
            assert error.value.getCondition() == "NOT_ITERABLE"
            assert error.value.getMessageParameters() == {"objectName": "Column"}
        with pytest.raises(AttributeError, match="Can't pickle local object"):
            pickle.dumps(df)
    assert (len(service.analyze_requests), len(service.execute_requests)) == requests
    data = serializer.dumps(spark.range(5))
    service.failure = "rpc"
    with pytest.raises(SparkConnectGrpcException, match="schema unavailable"):
        serializer.loads(data)




def test_inheritable_threads_inherit_the_tags_of_the_session_as_pyspark(mock_connect):
    # As PySpark's of Spark Connect: InheritableThread takes the tags of its session of the
    # thread that starts it, and inheritable_thread_target those of the thread that wraps the
    # function, with the session as the active one of the thread; a plain thread has none.
    import threading

    from pyspark import InheritableThread, inheritable_thread_target
    from pyspark.sql import SparkSession

    spark, _ = mock_connect
    spark.addTag("parent")
    seen = {}

    def child(key):
        seen[key] = (spark.getTags(), SparkSession.getActiveSession() is spark)

    try:
        for thread in [
            threading.Thread(target=child, args=("plain",)),
            InheritableThread(target=child, args=("inheritable",), session=spark),
            threading.Thread(target=inheritable_thread_target(spark)(child), args=("target",)),
        ]:
            thread.start()
            thread.join()
        assert seen == {
            "plain": (set(), False),
            "inheritable": ({"parent"}, False),
            "target": ({"parent"}, True),
        }
        assert spark.getTags() == {"parent"}
    finally:
        spark.clearTags()
    with pytest.raises(AssertionError, match="Spark Connect must be provided"):
        InheritableThread(target=child)
    with pytest.raises(AssertionError, match="f is expected to be SparkSession"):
        inheritable_thread_target(child)(child)


def test_threads_of_inheritable_thread_targets_share_their_tags_as_pyspark(mock_connect):
    # As PySpark Connect's inheritable_thread_target, as Apache Spark's
    # test_inheritable_tags_with_deco: the threads of the function share the copy of the tags of
    # the thread that decorated it, of then, so a thread that the function starts sees the tags
    # that the thread that started it added, while the decorating thread keeps its own.
    import threading

    from pyspark import inheritable_thread_target

    spark, _ = mock_connect
    spark.addTag("a")
    try:
        @inheritable_thread_target(spark)
        def func(target):
            return target()

        spark.addTag("later")
        first, second = set(), set()

        def inner():
            spark.addTag("c")
            second.update(spark.getTags())

        def outer():
            spark.addTag("b")
            first.update(spark.getTags())
            nested = threading.Thread(target=func, args=(inner,))
            nested.start()
            nested.join()

        thread = threading.Thread(target=func, args=(outer,))
        thread.start()
        thread.join()
        assert spark.getTags() == {"a", "later"}
        assert first == {"a", "b"} and second == {"a", "b", "c"}
    finally:
        spark.clearTags()


