# --- Connect import-path shims + offline utility helpers ---------------------
# The pyspark.sql.connect.* modules are thin re-exports that pandas-on-Spark and the
# official connect tests import from; verify they import and re-export the Rust-backed
# classes so the drop-in's connect import path is exercised offline.
def test_connect_shim_imports():
    import importlib

    for mod in [
        "pyspark.sql.connect.column",
        "pyspark.sql.connect.dataframe",
        "pyspark.sql.connect.session",
        "pyspark.sql.connect.plan",
        "pyspark.sql.connect.proto",
        "pyspark.sql.connect.functions",
        "pyspark.sql.connect.functions.builtin",
        "pyspark.sql.connect.avro",
        "pyspark.sql.connect.protobuf",
        "pyspark.sql.connect.resource",
        "pyspark.sql.connect.streaming",
        "pyspark.sql.connect.client",
        "pyspark.sql.connect.shell",
    ]:
        m = importlib.import_module(mod)
        assert m is not None

    # Column/DataFrame re-exported under the connect path are the Rust-backed classes.
    from pyspark._pyspark import Column as RustColumn
    from pyspark._pyspark import DataFrame as RustDataFrame
    from pyspark.sql.connect.column import Column as ConnectColumn
    from pyspark.sql.connect.dataframe import DataFrame as ConnectDataFrame

    assert ConnectColumn is RustColumn
    assert ConnectDataFrame is RustDataFrame

    # The internal-function dispatcher builds an UnresolvedFunction by name.
    from pyspark.sql import functions as F
    from pyspark.sql.connect.functions.builtin import _invoke_function_over_columns

    assert repr(_invoke_function_over_columns("pandas_product", F.col("x"))) == "Column<'pandas_product(x)'>"


def test_the_connect_avro_protobuf_and_streaming_packages_are_pysparks():
    # As PySpark's, pyspark.sql.connect.avro, protobuf and streaming are the packages of their
    # modules only, vendored as they are, which re-export none of their names: the functions are
    # those of their `functions` modules, and the streaming classes those of `query` and
    # `readwriter`.
    import importlib
    import types

    for name, absent, module, present in [
        ("pyspark.sql.connect.avro", "from_avro", "functions", "from_avro"),
        ("pyspark.sql.connect.protobuf", "to_protobuf", "functions", "to_protobuf"),
        ("pyspark.sql.connect.streaming", "StreamingQuery", "query", "StreamingQuery"),
        ("pyspark.sql.connect.streaming", "DataStreamReader", "readwriter", "DataStreamReader"),
    ]:
        package = importlib.import_module(name)
        assert not hasattr(package, "__all__"), name
        own = [
            key for key, value in vars(package).items()
            if not key.startswith("_") and not isinstance(value, types.ModuleType)
        ]
        assert own == [], (name, own)
        with pytest.raises(ImportError):
            exec(f"from {name} import {absent}", {})
        assert hasattr(importlib.import_module(f"{name}.{module}"), present)


# The public names of PySpark 4.3.0's package pyspark.sql.streaming in a new process: the classes
# that it imports, and its modules that `import pyspark.sql` loads.
OFFICIAL_STREAMING_NAMES = [
    "DataStreamReader", "DataStreamWriter", "StatefulProcessor", "StatefulProcessorHandle",
    "StreamingQuery", "StreamingQueryException", "StreamingQueryListener",
    "StreamingQueryManager", "TwsTester", "list_state_client", "listener", "map_state_client",
    "query", "readwriter", "state", "stateful_processor", "stateful_processor_api_client",
    "tws_tester", "value_state_client",
]


def test_the_streaming_package_is_pysparks():
    # As PySpark's, pyspark.sql.streaming is PySpark's file, vendored as it is, which has no
    # __all__: a star import brings in its classes and its loaded modules, `state` among them, as
    # the drop-in's pyspark.sql.pandas.group_ops imports it as PySpark's does. Trigger, a name of
    # the drop-in's connect readwriter, and the read limits of its datasource module are not its
    # names.
    import importlib
    import subprocess
    import sys
    import textwrap

    from pyspark.errors import StreamingQueryException

    script = textwrap.dedent('''
        import json
        import pyspark.sql.streaming as streaming
        namespace = {}
        exec("from pyspark.sql.streaming import *", namespace)
        print(json.dumps([
            hasattr(streaming, "__all__"),
            sorted(name for name in vars(streaming) if not name.startswith("_")),
            sorted(name for name in namespace if name != "__builtins__"),
        ]))
    ''')
    result = subprocess.run([sys.executable, "-c", script], capture_output=True, text=True, timeout=120)
    assert result.returncode == 0, result.stderr
    has_all, names, star = json.loads(result.stdout)
    assert not has_all
    assert names == OFFICIAL_STREAMING_NAMES
    assert star == OFFICIAL_STREAMING_NAMES

    streaming = importlib.import_module("pyspark.sql.streaming")
    for name, module in [
        ("DataStreamReader", "readwriter"), ("DataStreamWriter", "readwriter"),
        ("StreamingQuery", "query"), ("StreamingQueryManager", "query"),
        ("StreamingQueryListener", "listener"), ("StatefulProcessor", "stateful_processor"),
        ("StatefulProcessorHandle", "stateful_processor"), ("TwsTester", "tws_tester"),
    ]:
        assert getattr(streaming, name) is getattr(
            importlib.import_module(f"pyspark.sql.streaming.{module}"), name), name
    assert streaming.StreamingQueryException is StreamingQueryException
    for name, module in [
        ("Trigger", "connect.streaming.readwriter"), ("ReadLimit", "streaming.datasource"),
        ("ReadAllAvailable", "streaming.datasource"), ("ReadMinRows", "streaming.datasource"),
        ("ReadMaxRows", "streaming.datasource"), ("ReadMaxFiles", "streaming.datasource"),
        ("ReadMaxBytes", "streaming.datasource"),
        ("SupportsTriggerAvailableNow", "streaming.datasource"),
    ]:
        assert not hasattr(streaming, name), name
        with pytest.raises(ImportError, match=f"cannot import name '{name}' from 'pyspark.sql.streaming'"):
            exec(f"from pyspark.sql.streaming import {name}", {})
        assert hasattr(importlib.import_module(f"pyspark.sql.{module}"), name), name


def test_module_namespaces_of_the_official_doctests_as_pyspark():
    # As PySpark's: the official doctests of PySpark Connect take the namespace of a module as
    # their globals (the `_test()` of each module), and their examples use these names of it.
    import subprocess
    import sys

    import pyspark
    import pyspark.sql.catalog
    import pyspark.sql.connect.catalog
    import pyspark.sql.connect.functions.builtin
    import pyspark.sql.dataframe
    from pyspark import is_remote_only
    from pyspark.sql.types import Row, StructType
    from pyspark.storagelevel import StorageLevel

    assert is_remote_only() is True
    dataframe = pyspark.sql.dataframe
    assert (dataframe.Row, dataframe.StorageLevel, dataframe.StructType) == (
        Row, StorageLevel, StructType
    )
    assert pyspark.sql.catalog.StorageLevel is StorageLevel
    assert pyspark.sql.connect.catalog.StorageLevel is StorageLevel
    assert pyspark.sql.connect.functions.builtin.sys is sys
    # The doctests of the stream reader and writer take the namespace of the connect reader's
    # module, which PySpark's module of them imports.
    code = (
        "import pyspark.sql.connect.streaming.readwriter, pyspark.sql.connect as connect; "
        "print(connect.readwriter.__name__)"
    )
    result = subprocess.run([sys.executable, "-c", code], capture_output=True, text=True, timeout=120)
    assert result.stdout.strip() == "pyspark.sql.connect.readwriter", result.stderr


def test_special_lengths_of_the_messages_of_spark_as_pyspark():
    # As PySpark's SpecialLengths, of the init message that pyspark.messages reads: the
    # vendored SparkSocketMessageReceiver reads it before the data.
    import io
    import struct

    from pyspark.messages.socket.spark_socket_message_receiver import SparkSocketMessageReceiver
    from pyspark.serializers import SpecialLengths
    from pyspark.sql.worker.utils import SpecialLengths as WorkerSpecialLengths

    assert SpecialLengths.START_OF_INIT_MESSAGE == -8 and WorkerSpecialLengths is SpecialLengths
    receiver = SparkSocketMessageReceiver(
        io.BytesIO(struct.pack("!ii", -8, 4) + b"init" + struct.pack("!i", -4))
    )
    assert bytes(receiver.get_init_message().read(4)) == b"init"
    receiver.get_data_stream()
    receiver.get_finish_signal_from_stream()


def test_module_level_names_as_pyspark(monkeypatch):
    # As official PySpark 4.3.0: the names of pyspark.util, and the __all__ of the modules of
    # pyspark.sql, of which a star import exports only those.
    import gc
    import typing

    import pyspark.util as util
    from pyspark.errors import PySparkRuntimeError

    assert util.__all__ == []
    assert isinstance(util.FuncT, typing.TypeVar)
    monkeypatch.setenv("SPARK_CONNECT_MODE", "1")
    assert util.spark_connect_mode() == "1" and util.default_api_mode() == "connect"
    monkeypatch.setenv("SPARK_CONNECT_MODE", "0")
    assert util.spark_connect_mode() == "0" and util.default_api_mode() == "classic"

    def stops():
        raise StopIteration("done")

    assert util.fail_on_stopiteration(lambda x: x + 1)(1) == 2
    with pytest.raises(PySparkRuntimeError) as error:
        util.fail_on_stopiteration(stops)()
    assert error.value.getCondition() == "STOP_ITERATION_OCCURRED"
    assert error.value.getMessageParameters() == {"exc": "done"}
    enabled = gc.isenabled()
    with util.disable_gc():
        assert not gc.isenabled()
    assert gc.isenabled() == enabled

    for module, expected in [
        ("pyspark.sql.udf", ["UDFRegistration"]),
        (
            "pyspark.sql.udtf",
            [
                "AnalyzeArgument",
                "AnalyzeResult",
                "PartitioningColumn",
                "OrderingColumn",
                "SelectedColumn",
                "SkipRestOfInputTableException",
                "UDTFRegistration",
            ],
        ),
        ("pyspark.sql.avro", ["functions"]),
        ("pyspark.sql.protobuf", ["functions"]),
    ]:
        namespace = {}
        exec(f"from {module} import *", namespace)
        assert [name for name in namespace if name != "__builtins__"] == expected, module


def test_connect_import_path_modules_as_pyspark(mock_connect):
    # As official PySpark 4.3.0: the modules of the connect import path, of the functions and
    # the classes of this client, and the deprecated functions of the builtin modules.
    import importlib
    import logging

    from pyspark.sql import functions as F
    from pyspark.sql.avro import functions as avro
    from pyspark.sql.datasource import DataSource
    from pyspark.sql.functions import partitioning
    from pyspark.sql.protobuf import functions as protobuf
    from pyspark.sql.table_arg import TableArg

    spark, service = mock_connect
    connect_partitioning = importlib.import_module("pyspark.sql.connect.functions.partitioning")
    assert importlib.import_module("pyspark.sql.connect.functions").partitioning is (
        connect_partitioning
    )
    # Of the modules of PySpark Connect, not the functions of pyspark.sql.functions, as PySpark's.
    for name in ["years", "months", "days", "hours", "bucket"]:
        function = getattr(connect_partitioning, name)
        assert function is not getattr(partitioning, name)
        assert function.__module__ == "pyspark.sql.connect.functions.partitioning"
    # So are the Avro and the Protobuf functions, as PySpark Connect's own, which run as the
    # classic ones do and pickle by reference to the modules of PySpark Connect.
    connect_avro = importlib.import_module("pyspark.sql.connect.avro.functions")
    connect_protobuf = importlib.import_module("pyspark.sql.connect.protobuf.functions")
    for connect_module, module, names in [
        (connect_avro, avro, ["from_avro", "to_avro"]),
        (connect_protobuf, protobuf, ["from_protobuf", "to_protobuf"]),
    ]:
        for name in names:
            function = getattr(connect_module, name)
            assert function is not getattr(module, name)
            assert function.__module__ == connect_module.__name__
            assert function.__doc__ == getattr(module, name).__doc__
            assert pickle.loads(pickle.dumps(function)) is function
    assert str(connect_avro.to_avro("a")) == str(avro.to_avro("a"))
    assert str(connect_protobuf.from_protobuf("a", "M")) == str(protobuf.from_protobuf("a", "M"))
    # As PySpark Connect's: the TableArg of a DataFrame's asTable() is of the class of its module,
    # a subclass of the classic TableArg, PySpark's (the drop-in's native one, a virtual one).
    connect_table_arg = importlib.import_module("pyspark.sql.connect.table_arg").TableArg
    assert connect_table_arg is not TableArg and issubclass(connect_table_arg, TableArg)
    typing_module = importlib.import_module("pyspark.sql.connect._typing")
    assert {"ColumnOrName", "DataTypeOrString", "LiteralType"} <= set(dir(typing_module))

    connect_logging = importlib.import_module("pyspark.sql.connect.logging")
    assert connect_logging.__all__ == ["configureLogging", "getLogLevel"]
    assert isinstance(connect_logging.logger, logging.Logger)
    if "SPARK_CONNECT_LOG_LEVEL" not in os.environ:
        assert connect_logging.getLogLevel() is None

    connect_builtin = importlib.import_module("pyspark.sql.connect.functions.builtin")
    for name in [
        "approxCountDistinct",
        "bitwiseNOT",
        "countDistinct",
        "shiftLeft",
        "shiftRight",
        "shiftRightUnsigned",
        "sumDistinct",
        "toDegrees",
        "toRadians",
        "chr",
        "random",
        "uuid",
    ]:
        assert getattr(F.builtin, name) is getattr(F, name), name
        assert getattr(connect_builtin, name) is not getattr(F, name), name
        assert getattr(connect_builtin, name).__module__ == connect_builtin.__name__, name

    # The registration of a data source registers it with the session.
    from pyspark.sql.connect.datasource import DataSourceRegistration

    class TestSource(DataSource):
        @classmethod
        def name(cls):
            return "test_source"

    DataSourceRegistration(spark).register(TestSource)
    assert service.execute_calls == 1
    # Of the session's registration, which takes PySpark's keyword.
    spark.dataSource.register(dataSource=TestSource)
    assert service.execute_calls == 2


def test_connect_utils_check_the_dependencies_of_the_client(tmp_path):
    # As PySpark Connect's pyspark.sql.connect.utils, but check_dependencies checks the
    # dependencies of this client, which do not include gRPC. The script runs of a file: of
    # a main module without one, check_dependencies takes it for doctests.
    import subprocess
    import sys
    import textwrap

    from pyspark.errors import PySparkImportError
    from pyspark.sql.connect import utils

    assert utils.get_python_ver() == "{:d}.{:d}".format(*sys.version_info[:2])
    utils.check_dependencies()
    for check in [
        utils.require_minimum_grpc_version,
        utils.require_minimum_grpcio_status_version,
        utils.require_minimum_googleapis_common_protos_version,
        utils.require_minimum_zstandard_version,
    ]:
        # Of the packages installed here, or not.
        try:
            check()
        except PySparkImportError as error:
            assert error.getCondition() in ("PACKAGE_NOT_INSTALLED", "UNSUPPORTED_PACKAGE_VERSION")
    script = textwrap.dedent(
        """
        import importlib.abc, sys

        class Block(importlib.abc.MetaPathFinder):
            def find_spec(self, name, path, target=None):
                if name.split(".")[0] in ("grpc", "grpc_status", "zstandard") or name.startswith(
                    "google.rpc"
                ):
                    raise ImportError("not installed: " + name)

        sys.meta_path.insert(0, Block())
        from pyspark.errors import PySparkImportError
        from pyspark.sql.connect import utils

        utils.check_dependencies()
        for check, package in [
            (utils.require_minimum_grpc_version, "grpcio"),
            (utils.require_minimum_grpcio_status_version, "grpcio-status"),
            (utils.require_minimum_googleapis_common_protos_version, "googleapis-common-protos"),
            (utils.require_minimum_zstandard_version, "zstandard"),
        ]:
            try:
                check()
            except PySparkImportError as error:
                assert error.getCondition() == "PACKAGE_NOT_INSTALLED"
                assert error.getMessageParameters()["package_name"] == package
            else:
                raise AssertionError(package)
        print("ok")
        """
    )
    path = tmp_path / "check_dependencies.py"
    path.write_text(script)
    result = subprocess.run(
        [sys.executable, str(path)], capture_output=True, text=True, timeout=120
    )
    assert result.returncode == 0 and result.stdout.strip() == "ok", result.stderr


