# --- UserDefinedType protocol + types.py helpers (offline) -------------------
from pyspark.sql.types import (
    ArrayType as _AT,
)
from pyspark.sql.types import (
    DoubleType as _DT,
)
from pyspark.sql.types import (
    IntegerType as _IT,
)
from pyspark.sql.types import (
    MapType as _MT,
)
from pyspark.sql.types import (
    StringType as _ST,
)
from pyspark.sql.types import (
    StructField as _SF,
)
from pyspark.sql.types import (
    StructType as _StT,
)
from pyspark.sql.types import (
    UserDefinedType,
    _create_row,
    _drop_metadata,
)


class _PointUDT(UserDefinedType):
    @classmethod
    def sqlType(cls):
        return _AT(_DT(), False)

    @classmethod
    def module(cls):
        return "tests.test_dropin_offline"

    def serialize(self, obj):
        return [float(obj[0]), float(obj[1])]

    def deserialize(self, datum):
        return (datum[0], datum[1])


class _BareUDT(UserDefinedType):
    @classmethod
    def sqlType(cls):
        return _IT()


def test_udt_protocol_roundtrip():
    udt = _PointUDT()
    assert udt.simpleString() == "udt"
    internal = udt.toInternal((1.0, 2.0))
    assert udt.fromInternal(internal) == (1.0, 2.0)
    # _cachedSqlType caches the sqlType instance.
    assert udt._cachedSqlType() is udt._cachedSqlType()
    # jsonValue (python UDT -> pyClass form) + json round-trips via fromJson.
    jv = udt.jsonValue()
    assert jv["type"] == "udt"
    assert "pyClass" in jv
    import json as _json

    assert _json.loads(udt.json())["type"] == "udt"
    # fromJson reconstructs the UDT from its serialized pyClass (covers the udt branch).
    UserDefinedType.fromJson(jv)
    # None passes through toInternal/fromInternal.
    assert udt.toInternal(None) is None


def test_udt_not_implemented_defaults():
    import pytest

    udt = _BareUDT()
    with pytest.raises(Exception):
        udt.serialize((1,))
    with pytest.raises(Exception):
        udt.deserialize(1)


def test_struct_field_metadata_is_the_stored_dict():
    # As PySpark's StructField, which keeps its metadata dict: an edit in place shows in the
    # field, its JSON, its equality and its pickle, and in the StructType that holds the field.
    f = _SF("a", _IT())
    f.metadata["comment"] = "x"
    assert f.metadata == {"comment": "x"} and f.metadata is f.metadata
    assert f.jsonValue()["metadata"] == {"comment": "x"}
    assert json.loads(f.json())["metadata"] == {"comment": "x"}
    assert f == _SF("a", _IT(), True, {"comment": "x"})
    assert pickle.loads(pickle.dumps(f)).metadata == {"comment": "x"}
    # A non-empty dict passed in is stored as is; an empty or no dict gives a new one.
    d = {"k": 1}
    g = _SF("a", _IT(), True, d)
    assert g.metadata is d
    d["k"] = 2
    assert g.jsonValue()["metadata"] == {"k": 2}
    empty = {}
    h = _SF("a", _IT(), True, empty)
    assert h.metadata == {} and h.metadata is not empty
    a, b = _SF("a", _IT()), _SF("a", _IT())
    assert a.metadata is not b.metadata
    # The edits show in the StructType that holds the field, whether the struct is made of
    # the field, the field is added, or the field is taken from the struct.
    f2 = _SF("b", _IT())
    st = _StT([f2])
    f2.metadata["k"] = "v"
    assert st.jsonValue()["fields"][0]["metadata"] == {"k": "v"}
    st2 = _StT()
    f3 = _SF("c", _IT())
    st2.add(f3)
    f3.metadata["k"] = "w"
    assert st2.jsonValue()["fields"][0]["metadata"] == {"k": "w"}
    st3 = _StT([_SF("a", _IT()), _SF("b", _AT(_IT()))])
    st3["a"].metadata["comment"] = "x"
    assert st3.jsonValue()["fields"][0]["metadata"] == {"comment": "x"}
    assert st3["a"].metadata is st3.fields[0].metadata
    assert json.loads(st3.json())["fields"][0]["metadata"] == {"comment": "x"}
    assert _StT.fromJson(st3.jsonValue()) == st3
    assert pickle.loads(pickle.dumps(st3)).jsonValue() == st3.jsonValue()


def test_struct_field_metadata_any_values():
    # StructField metadata accepts arbitrary JSON values (Dict[str, Any]), not just str,
    # and round-trips through json.
    f = _SF("a", _IT(), True, {"m": 1, "s": "x", "b": True, "l": [1, 2]})
    assert f.metadata == {"m": 1, "s": "x", "b": True, "l": [1, 2]}
    f2 = _SF.fromJson(f.jsonValue())
    assert f2.metadata["m"] == 1 and f2.metadata["b"] is True and f2.metadata["l"] == [1, 2]


def test_struct_fields_of_strs_that_utf8_cannot_encode_raise_their_encoding_error():
    # A StructField of a str of a lone surrogate, as its name or anywhere in its metadata, is made,
    # as PySpark's, whose `json()` escapes it and whose tree string writes it. The names and the
    # metadata of the plans of the drop-in's types are of UTF-8, so a plan of such metadata raises
    # the UnicodeEncodeError of the str, where PySpark's sends the JSON that `json.dumps` escapes,
    # and the simple string of such a name raises it, where PySpark's makes it (see
    # dev/parity/known-differences.md). A plan of such a name raises it, as PySpark's.
    message = "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed"
    for make, json_text in (
        (lambda: _SF("a\ud800", _IT()), '{"metadata":{},"name":"a\\ud800","nullable":true,'),
        (lambda: _SF("a", _IT(), True, {"k": "a\ud800"}), '{"metadata":{"k":"a\\ud800"},'),
        (lambda: _SF("a", _IT(), True, {"a\ud800": 1}), '{"metadata":{"a\\ud800":1},'),
        (
            lambda: _SF("a", _IT(), True, {"k": ["x", {"n": "a\ud800"}]}),
            '{"metadata":{"k":["x",{"n":"a\\ud800"}]},',
        ),
    ):
        field = make()
        assert field.json().startswith(json_text)
        assert _StT([field]).treeString().endswith(": integer (nullable = true)\n")
        with pytest.raises(UnicodeEncodeError) as error:
            pyspark.sql.functions.lit(None).cast(_StT([field]))._expr.to_plan(None)
        assert str(error.value) == message
    with pytest.raises(UnicodeEncodeError) as error:
        _SF("a\ud800", _IT()).simpleString()
    assert str(error.value) == message


def test_drop_metadata_and_create_row():
    st = _StT([_SF("a", _IT(), True, {"m": 1}), _SF("b", _AT(_IT()), True)])
    dm = _drop_metadata(st)
    assert not dm.fields[0].metadata
    _drop_metadata(_AT(_IT()))
    _drop_metadata(_MT(_ST(), _IT()))
    _drop_metadata(_IT())
    r = _create_row(["a", "b"], [1, 2])
    assert r["a"] == 1 and r["b"] == 2
    assert list(r.__fields__) == ["a", "b"]
    # The fields can be a row class, whose values name them, as Row.__call__ passes it.
    r2 = _create_row(T.Row("a", "b"), [3, 4])
    assert r2["a"] == 3 and r2.b == 4


