def test_the_client_banner_names_the_version_of_the_package(mock_connect):
    # The INFO log of the first session of a process names pyspark-client-rust's version, that of
    # pyproject.toml, which the release checks against Cargo.toml's, and not pyspark.__version__,
    # the version of Spark whose API the client mirrors.
    import subprocess
    import sys
    import textwrap
    from pathlib import Path

    _, service = mock_connect
    pyproject = (Path(__file__).resolve().parents[2] / "pyproject.toml").read_text()
    version = re.search(r'^version = "([^"]+)"$', pyproject, re.MULTILINE).group(1)
    script = textwrap.dedent('''
        import logging
        import sys

        class Collect(logging.Handler):
            def emit(self, record):
                print(record.getMessage())

        logger = logging.getLogger("pyspark")
        logger.setLevel(logging.INFO)
        logger.addHandler(Collect())
        from pyspark.sql import SparkSession

        SparkSession.builder.remote(sys.argv[1]).getOrCreate().stop()
    ''')
    result = subprocess.run([sys.executable, "-c", script, service.remote], capture_output=True,
                            text=True, timeout=120)
    assert result.returncode == 0, result.stdout + result.stderr
    banners = [line for line in result.stdout.splitlines() if "active: Spark Connect" in line]
    assert banners == [
        f"pyspark-client-rust {version} active: Spark Connect client backed by the native Rust "
        "engine (tonic), a drop-in for pyspark-client -- not the reference Python client. "
        "https://apache.github.io/spark-connect-rust/which-client/"
    ]


def test_lit_takes_an_int_or_a_float_by_its_type_as_pyspark(mock_connect):
    # As PySpark's LiteralExpression._infer_type, which takes an int or a float by isinstance: an
    # object that only converts to one (__index__, __float__) is UNSUPPORTED_DATA_TYPE, while the
    # subclasses of int and float, an IntEnum and the NumPy scalars are literals.
    import enum

    np = pytest.importorskip("numpy")
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import functions as F

    class Index:
        def __index__(self):
            return 7

    class Floaty:
        def __float__(self):
            return 2.5

    class Both(Index, Floaty):
        pass

    class MyInt(int):
        pass

    class MyFloat(float):
        pass

    class Small(enum.IntEnum):
        A = 5

    spark, _ = mock_connect
    for value in (Index(), Floaty(), Both(), Fraction(1, 2)):
        name = type(value).__name__
        for build in (lambda v: F.lit(v), lambda v: F.col("id").isin(v),
                      lambda v: F.when(F.col("id") == 0, v)):
            with pytest.raises(PySparkTypeError) as error:
                build(value)
            assert error.value.getCondition() == "UNSUPPORTED_DATA_TYPE"
            assert error.value.getMessageParameters() == {"data_type": name}
        for args in ({"x": value}, [value]):
            with pytest.raises(PySparkTypeError) as error:
                spark.sql("SELECT :x" if isinstance(args, dict) else "SELECT ?", args=args)
            assert error.value.getMessageParameters() == {"data_type": name}
    for value, text in ((MyInt(5), "5"), (MyFloat(1.5), "1.5"), (Small.A, "5"),
                        (np.int64(6), "6"), (np.float64(2.5), "2.5")):
        assert repr(F.lit(value)) == f"Column<'{text}'>"


def test_columns_of_strs_that_utf8_cannot_encode_fail_when_the_plan_is_built_as_pyspark(
    mock_connect,
):
    # As PySpark's expressions, which keep a column name, a SQL string or the str of a literal as
    # it is given, and set it in a protobuf string field when a request builds the plan: a str
    # that UTF-8 cannot encode makes a Column, whose plans fail, at `df.schema` or `collect()`,
    # with the UnicodeEncodeError of its encoding, and send no request. Its repr shows the str
    # escaped, where PySpark's shows it as it is, and its copies and pickles fail as it does.
    import copy
    import pickle

    from pyspark.sql import Column, Window
    from pyspark.sql import functions as F

    spark, service = mock_connect
    df = spark.range(1)
    bad = "a\ud800b"
    message = "'utf-8' codec can't encode character '\\ud800' in position %d: surrogates not allowed"
    cases = [
        (lambda: F.col(bad), r"a\ud800b"),
        (lambda: F.column(bad), r"a\ud800b"),
        (lambda: F.col(bad + ".*"), r"unresolvedstar(a\ud800b.*)"),
        (lambda: F.expr(bad), r"a\ud800b"),
        (lambda: F.lit(bad), r"a\ud800b"),
        (lambda: F.lit([bad]), r"array(a\ud800b)"),
        (lambda: F.col("id") == bad, r"==(id, a\ud800b)"),
        (lambda: F.upper(bad), r"upper(a\ud800b)"),
        (lambda: F.col(bad).desc(), r"a\ud800b DESC NULLS LAST"),
        (lambda: df[bad], r"a\ud800b"),
        (lambda: getattr(df, bad), r"a\ud800b"),
        (lambda: df.colRegex(bad), r"UnresolvedRegex(a\ud800b)"),
        (lambda: df.metadataColumn(bad), r"a\ud800b"),
        (lambda: F.col("st").getField(bad), r"st['a\ud800b']"),
        (lambda: F.col("st").withField(bad, F.lit(1)), r"update_field(st, a\ud800b, 1)"),
        (lambda: F.col("st").dropFields(bad), r"drop_field(st, a\ud800b)"),
        (lambda: F.call_function(bad), r"CallFunction('a\ud800b')"),
        (lambda: F.call_udf(bad, "id"), r"a\ud800b(id)"),
        (lambda: F.when(F.col("id") > 0, 1).otherwise([bad]), None),
        (lambda: F.count(F.lit(1)).over(Window.partitionBy(bad)), None),
        (lambda: F.count(F.lit(1)).over(Window.orderBy(bad)), None),
    ]
    for build, text in cases:
        column = build()
        assert isinstance(column, Column), text
        if text is not None:
            assert repr(column) == f"Column<'{text}'>"
        pickled = pickle.loads(pickle.dumps(column))
        for each in (column, copy.copy(column), copy.deepcopy(column), pickled):
            for request in (lambda: df.select(each).schema, lambda: df.select(each).collect()):
                with pytest.raises(UnicodeEncodeError) as error:
                    request()
                assert type(error.value) is UnicodeEncodeError
                assert str(error.value) == message % 1, text
    # The type of a cast is set after its child, as the unparsed type of a str.
    cast = F.col("id").cast("int\ud800")
    assert repr(cast) == r"Column<'CAST(id AS INT\UD800)'>"
    for column in (cast, F.col("id").try_cast("int\ud800")):
        with pytest.raises(UnicodeEncodeError) as error:
            df.select(column).schema
        assert str(error.value) == message % 3
    assert service.analyze_requests == [] and service.execute_requests == []


def test_column_names_and_sql_strings_raise_the_errors_of_pyspark_at_the_call(mock_connect):
    # As PySpark's `F.col`, which compares the name to "*" and calls its `endswith(".*")`, so an
    # int or None raises the AttributeError of `endswith`, and bytes its TypeError; and as its
    # `SQLExpression`, which asserts a str for `F.expr`, `selectExpr` and `filter`. `filter` of
    # an object that is neither a str nor a Column, and `lateralJoin` of an `on` that is not a
    # Column, raise the AttributeError of the `foreach` of their plans, which collect the
    # subqueries of their expressions. `agg` of a dict takes `F.col` of its keys.
    spark, _ = mock_connect
    df = spark.range(1)
    from pyspark.sql import functions as F

    endswith = "endswith first arg must be bytes or a tuple of bytes, not str"
    for call, error_type, message in [
        (lambda: F.col(5), AttributeError, "'int' object has no attribute 'endswith'"),
        (lambda: F.col(None), AttributeError, "'NoneType' object has no attribute 'endswith'"),
        (lambda: F.col(b"a"), TypeError, endswith),
        (lambda: df.agg({b"a": "max"}), TypeError, endswith),
        (lambda: df.groupBy().agg({5: "max"}), AttributeError,
         "'int' object has no attribute 'endswith'"),
        (lambda: F.expr(5), AssertionError, ""),
        (lambda: F.expr(b"a"), AssertionError, ""),
        (lambda: F.expr(None), AssertionError, ""),
        (lambda: df.selectExpr(b"a"), AssertionError, ""),
        (lambda: F.call_function(5), AssertionError, ""),
        (lambda: df.filter(5), AttributeError, "'int' object has no attribute 'foreach'"),
        (lambda: df.filter(b"id > 0"), AttributeError,
         "'bytes' object has no attribute 'foreach'"),
        (lambda: df.lateralJoin(df, on="id"), AttributeError,
         "'str' object has no attribute 'foreach'"),
    ]:
        with pytest.raises(error_type) as error:
            call()
        assert type(error.value) is error_type, message
        assert str(error.value) == message


def test_a_str_that_utf8_cannot_encode_is_the_encode_error_of_protobuf_as_pyspark(mock_connect):
    # As PySpark's, whose protobuf string field rejects a str with a lone surrogate, in protobuf's
    # default (upb) backend: the UnicodeEncodeError of its encoding, of the position of the
    # surrogate, when a request builds the plan of a literal, and at the call for the arguments
    # of sql, whose request the call builds.
    from pyspark.sql import functions as F

    spark, service = mock_connect
    value, long_value = "a\ud800b", "x" * 2000 + "\ud800"
    message = "'utf-8' codec can't encode character '\\ud800' in position %d: surrogates not allowed"
    for build, text in ((lambda: spark.range(1).select(F.lit(value)).collect(), message % 1),
                        (lambda: spark.range(1).filter(F.col("id") == value).schema, message % 1),
                        (lambda: spark.range(1).select(F.lit([value])).schema, message % 1),
                        (lambda: F.lit(long_value)._expr.to_plan(None), message % 2000),
                        (lambda: spark.sql("SELECT :x", args={"x": value}), message % 1),
                        (lambda: spark.sql("SELECT ?", args=[value]), message % 1)):
        with pytest.raises(UnicodeEncodeError) as error:
            build()
        assert type(error.value) is UnicodeEncodeError and str(error.value) == text
    assert service.execute_requests == [] and service.analyze_requests == []


def test_pandas_timestamp_literals_drop_their_nanoseconds_silently_as_pyspark(mock_connect):
    # As PySpark's TimestampType.toInternal and TimestampNTZType.toInternal, which read the
    # fields of a pandas Timestamp: its nanoseconds are dropped without the warning of
    # Timestamp.to_pydatetime, and the literal is that of the datetime of its microseconds.
    import warnings

    pd = pytest.importorskip("pandas")
    from pyspark.sql import functions as F

    spark, service = mock_connect

    def literal(column):
        spark.range(1).select(column).collect()
        # Project.expressions=3; Expression.literal=1; Literal.timestamp=17, timestamp_ntz=18.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
        expression = parse_message(parse_message(parse_message(plan)[3][0])[3][0])
        return parse_message(expression[1][0])

    seoul = datetime.timezone(datetime.timedelta(hours=9))
    for timestamp_type in ("TIMESTAMP_LTZ", "TIMESTAMP_NTZ"):
        service.confs = {"spark.sql.timestampType": timestamp_type}
        for value in (pd.Timestamp("2020-01-01 00:00:00.123456789"),
                      pd.Timestamp("2020-01-01 00:00:00.123456789", tz="Asia/Seoul")):
            micros = value.to_pydatetime(warn=False)
            with warnings.catch_warnings():
                warnings.simplefilter("error")
                column = F.lit(value)
            assert literal(column) == literal(F.lit(micros))
    assert literal(F.lit(pd.Timestamp("2020-01-01 09:00:00.5", tz=seoul))) == {
        18: [1577869200500000]}


def test_transform_asserts_that_the_function_returned_a_dataframe_as_pyspark(mock_connect):
    # As PySpark's DataFrame.transform, which asserts that the function returned a DataFrame.
    spark, _ = mock_connect
    df = spark.range(1)
    for result in (1, None, [df]):
        with pytest.raises(AssertionError) as error:
            df.transform(lambda frame, value=result: value)
        assert str(error.value) == (
            f"Func returned an instance of type [{type(result)!r}], should have been DataFrame.")
    selected = df.select("id")
    assert df.transform(lambda frame, other: other, selected) is selected


def _collect_metrics_plan_ids(relation):
    # Relation.common=1 (RelationCommon.plan_id=2), collect_metrics=29 (CollectMetrics.input=1,
    # name=2): the plan ID of each CollectMetrics of the relation, by its name.
    fields = parse_message(relation)
    if 29 not in fields:
        return {}
    metrics = parse_message(fields[29][0])
    ids = _collect_metrics_plan_ids(metrics[1][0])
    ids[metrics[2][0].decode()] = parse_message(fields[1][0])[2][0]
    return ids


def test_metrics_that_pyspark_cannot_convert_fail_the_action_of_their_observation_as_pyspark(
        mock_connect):
    # As PySpark's client, which converts the metrics of the Observations of a plan as they
    # arrive: the first one of a kind that LiteralExpression._to_value does not convert (a
    # year-month interval) raises UNSUPPORTED_LITERAL, of the text of its literal, from the
    # action, and neither its metrics nor those that come after it are set. Metrics observed by
    # a name are not converted by the action.
    import pyarrow as pa
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import Observation
    from pyspark.sql import functions as F

    spark, service = mock_connect
    first, second = Observation("first"), Observation("second")
    df = (spark.range(3).observe(first, F.count(F.lit(1)).alias("c"))
          .observe(second, F.max("id").alias("m")))
    df.collect()
    # ExecutePlanRequest.plan=3 -> Plan.root=1.
    ids = _collect_metrics_plan_ids(
        parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0])

    def observed(name, literal, key):
        # ExecutePlanResponse.observed_metrics=6 -> ObservedMetrics name=1, values=2, keys=3,
        # plan_id=4.
        return message_field(6, message_field(1, name) + message_field(2, literal)
                             + message_field(3, key) + varint_field(4, ids[name]))

    # Literal.long=7, year_month_interval=20.
    count, interval = varint_field(7, 3), varint_field(20, 14)
    # The rows of the result, for count: ExecutePlanResponse.arrow_batch=2 (ArrowBatch.row_count=1,
    # data=2).
    table = pa.table({"count(1)": pa.array([3], pa.int64())})
    sink = pa.BufferOutputStream()
    with pa.ipc.new_stream(sink, table.schema) as writer:
        writer.write_table(table)
    batch = message_field(2, varint_field(1, 1) + message_field(2, sink.getvalue().to_pybytes()))
    for action in (df.collect, df.count, lambda: list(df.toLocalIterator())):
        service.execute_payload = (batch + observed("second", interval, "m")
                                   + observed("first", count, "c"))
        with pytest.raises(PySparkTypeError) as error:
            action()
        assert error.value.getCondition() == "UNSUPPORTED_LITERAL"
        assert error.value.getMessageParameters() == {"literal": "year_month_interval: 14\n"}
        assert first.get == {} and second.get == {}
    # The metrics that come before the first that is not converted are set.
    service.execute_payload = observed("first", count, "c") + observed("second", interval, "m")
    with pytest.raises(PySparkTypeError):
        df.collect()
    assert first.get == {"c": 3} and second.get == {}
    service.execute_payload = message_field(6, message_field(1, "named")
                                            + message_field(2, interval) + message_field(3, "m"))
    named = spark.range(3).observe("named", F.max("id").alias("m"))
    assert named.collect() == []
    with pytest.raises(PySparkTypeError):
        named.executionInfo.flows


def _count_batch_and_observed_metrics(service, df):
    # The response of the row of a count() of 3 (ExecutePlanResponse.arrow_batch=2: row_count=1,
    # data=2), and a function of the response of the observed metrics of a name, of one literal
    # of a key, reported by the plan ID of the CollectMetrics of that name in the plan of `df`
    # (ExecutePlanResponse.observed_metrics=6: name=1, values=2, keys=3, plan_id=4).
    import pyarrow as pa

    df.collect()
    # ExecutePlanRequest.plan=3 -> Plan.root=1.
    ids = _collect_metrics_plan_ids(
        parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0])
    table = pa.table({"count(1)": pa.array([3], pa.int64())})
    sink = pa.BufferOutputStream()
    with pa.ipc.new_stream(sink, table.schema) as writer:
        writer.write_table(table)
    batch = message_field(2, varint_field(1, 1) + message_field(2, sink.getvalue().to_pybytes()))

    def observed(name, literal, key):
        return message_field(6, message_field(1, name) + message_field(2, literal)
                             + message_field(3, key) + varint_field(4, ids[name]))

    return batch, observed


def test_the_attributes_of_an_observation_are_those_of_its_dict_as_pyspark(mock_connect):
    # As PySpark Connect's Observation, a plain class: its _name, _result and _error are the
    # entries of vars(o), which observe and the actions set, and which a program sets and deletes,
    # of their effects on get, on a new observe and on the metrics of the actions, which update the
    # _result of the observation as it is then. Its _error is the one object that each read and
    # get give, of the error that the server reports, which the action gives to its _set_error.
    from pyspark.errors import PySparkAssertionError
    from pyspark.sql import functions as F
    from pyspark.sql.connect.observation import Observation

    spark, service = mock_connect
    observation = Observation("o")
    assert vars(observation) == {"_name": "o", "_result": None, "_error": None}
    assert list(vars(observation)) == ["_name", "_result", "_error"]
    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    assert vars(observation) == {"_name": "o", "_result": {}, "_error": None}
    batch, metrics = _count_batch_and_observed_metrics(service, df)
    service.execute_payload = batch + metrics("o", varint_field(7, 3), "c")
    df.collect()
    assert vars(observation) == {"_name": "o", "_result": {"c": 3}, "_error": None}

    # A result that is set is the one that get gives and that the actions update.
    replaced = {"kept": True}
    observation._result = replaced
    df.collect()
    assert observation.get is replaced and replaced == {"kept": True, "c": 3}
    # Of None, get raises, an action raises PySpark's AssertionError, and observe uses it again.
    observation._result = None
    with pytest.raises(PySparkAssertionError) as error:
        observation.get
    assert error.value.getCondition() == "NO_OBSERVE_BEFORE_GET"
    with pytest.raises(AssertionError):
        df.collect()
    observation._name = "again"
    again = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    assert vars(observation) == {"_name": "again", "_result": {}, "_error": None}
    batch, metrics = _count_batch_and_observed_metrics(service, again)
    service.execute_payload = batch + metrics("again", varint_field(7, 5), "c")
    again.collect()
    assert observation.get == {"c": 5}

    # An error that is set is raised by get, the same object each time.
    raised = ValueError("set")
    observation._error = raised
    with pytest.raises(ValueError) as error:
        observation.get
    assert error.value is raised and observation._error is raised
    del observation._error
    with pytest.raises(AttributeError):
        observation.get
    observation._error = None
    observation.other = 1
    assert list(vars(observation).items()) == [
        ("_name", "again"), ("_result", {"c": 5}), ("_error", None), ("other", 1)]

    # The error that the server reports is given to _set_error by the action, and is the one
    # object of each read. ExecutePlanResponse.observed_metrics=6: ObservedMetrics.name=1,
    # root_error_idx=5, errors=6; Error.error_type_hierarchy=1, message=2.
    class Recording(Observation):
        def _set_error(self, exc):
            self.recorded = exc
            super()._set_error(exc)

    failed = Recording("f")
    failing = spark.range(3).observe(failed, F.count(F.lit(1)).alias("c"))
    error = (message_field(1, "org.apache.spark.SparkArithmeticException")
             + message_field(2, "[DIVIDE_BY_ZERO] Division by zero. SQLSTATE: 22012"))
    service.execute_payload = batch + message_field(
        6, message_field(1, "f") + varint_field(5, 0) + message_field(6, error))
    failing.count()
    assert failed._error is failed._error is failed.recorded
    with pytest.raises(Exception, match="DIVIDE_BY_ZERO") as raised:
        failed.get
    assert raised.value is failed._error
    assert list(vars(failed)) == ["_name", "_result", "_error", "recorded"]


def test_observe_gives_the_dataframe_of_the_on_of_an_observation_as_pyspark(mock_connect):
    # As PySpark's DataFrame.observe, which checks its Columns and then gives what the _on of the
    # Observation gives, of a subclass too, after it sets `res._cached_schema` of its own: an
    # object that takes no attribute, as a str, raises the AttributeError of that.
    from pyspark.errors import PySparkValueError
    from pyspark.sql import functions as F
    from pyspark.sql.connect.observation import Observation

    spark, _ = mock_connect
    calls = []

    class Result:
        pass

    result = Result()

    class Mine(Observation):
        def _on(self, df, *exprs):
            calls.append((df, exprs))
            return result

    observation = Mine("m")
    df = spark.range(3)
    df.schema
    column = F.count(F.lit(1)).alias("c")
    assert df.observe(observation, column) is result
    assert result._cached_schema is df._cached_schema
    ((seen, exprs),) = calls
    assert seen is df and len(exprs) == 1 and exprs[0] is column
    del calls[:]

    class OfStr(Observation):
        def _on(self, df, *exprs):
            calls.append((df, exprs))
            return "of _on"

    with pytest.raises(AttributeError, match="_cached_schema"):
        df.observe(OfStr("s"), column)
    assert len(calls) == 1
    del calls[:]
    with pytest.raises(PySparkValueError) as error:
        df.observe(observation)
    assert error.value.getCondition() == "CANNOT_BE_EMPTY" and calls == []
    assert vars(observation) == {"_name": "m", "_result": None, "_error": None}


def test_the_plan_of_an_observation_is_built_of_its_name_as_it_is_then_as_pyspark(mock_connect):
    # As PySpark's CollectMetrics, which sets the str() of the _name of its Observation each time
    # it builds the plan, after its input, and whose observations name it so: a request of an
    # Observation renamed after observe carries its new name, of any object, by which its metrics
    # are set, and a name whose __str__ raises, or a str that UTF-8 cannot encode, fails each
    # request with that error, until it is renamed again. Observation._on does not read the name.
    # A deep copy of the DataFrame holds a copy of the Observation, of its name then, whose metrics
    # its actions set, as PySpark's deep copy of the plan.
    import copy

    import pyspark.sql.connect.proto as pb2
    from pyspark.sql import functions as F
    from pyspark.sql.connect.observation import Observation

    class Unnamed:
        def __str__(self):
            raise ValueError("no name")

    def sent_name():
        request = pb2.ExecutePlanRequest.FromString(service.execute_requests[-1])
        return request.plan.root.collect_metrics.name

    spark, service = mock_connect
    observation = Observation("before")
    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    observation._name = "after"
    batch, metrics = _count_batch_and_observed_metrics(service, df)
    assert sent_name() == "after"
    service.execute_payload = batch + metrics("after", varint_field(7, 3), "c")
    df.collect()
    assert observation.get == {"c": 3}
    for name, text in ((5, "5"), (None, "None"), (b"n", "b'n'")):
        observation._name = name
        df.collect()
        assert sent_name() == text
    sent = len(service.execute_requests)
    for name, error in (("lone \ud800", UnicodeEncodeError), (Unnamed(), ValueError)):
        observation._name = name
        with pytest.raises(error):
            df.collect()
    assert len(service.execute_requests) == sent
    observation._name = "again"
    batch, metrics = _count_batch_and_observed_metrics(service, df)
    assert sent_name() == "again"
    service.execute_payload = batch + metrics("again", varint_field(7, 4), "c")
    df.collect()
    assert observation.get == {"c": 4}
    copied = copy.deepcopy(df)
    (held,) = copied._plan.observations.values()
    assert held is not observation and list(copied._plan.observations) == ["again"]
    service.execute_payload = batch + metrics("again", varint_field(7, 5), "c")
    copied.collect()
    assert held.get == {"c": 5} and observation.get == {"c": 4}
    unnamed = Observation("unnamed")
    unnamed._name = Unnamed()
    observed = spark.range(3).observe(unnamed, F.count(F.lit(1)).alias("c"))
    sent = len(service.execute_requests)
    with pytest.raises(ValueError, match="no name"):
        observed.collect()
    assert len(service.execute_requests) == sent


def test_an_observation_in_a_cycle_through_its_result_is_collected_as_pyspark(mock_connect):
    # As PySpark's Observation, whose result dict is an attribute of its __dict__, which Python's
    # garbage collector sees: an observation that its result refers to is freed with it.
    import gc
    import weakref

    from pyspark.sql import functions as F
    from pyspark.sql.connect.observation import Observation

    spark, _ = mock_connect
    observation = Observation("cycle")
    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    observation.get["self"] = observation
    gone = weakref.ref(observation)
    del observation, df
    gc.collect()
    assert gone() is None


def test_an_action_converts_the_metrics_of_its_observations_as_pyspark(mock_connect):
    # As PySpark's client, which converts the metrics of an Observation when the action sets them
    # (LiteralExpression._to_value): a timestamp of the year 1, whose conversion to a local
    # datetime fails, raises the ValueError of the conversion from the action, which sets none of
    # its metrics.
    from pyspark.sql import functions as F
    from pyspark.sql.connect.observation import Observation

    spark, service = mock_connect
    observation = Observation("t")
    df = spark.range(3).observe(observation, F.min(F.current_timestamp()).alias("m"))
    batch, metrics = _count_batch_and_observed_metrics(service, df)
    # Expression.Literal.timestamp=17, the microseconds of 0001-01-01 00:00:00 UTC.
    service.execute_payload = batch + metrics("t", varint_field(17, -62135596800000000), "m")
    with pytest.raises(ValueError, match="year 0 is out of range"):
        df.collect()
    assert observation.get == {}


def test_only_the_observations_of_the_plan_of_an_action_receive_its_metrics_as_pyspark(
        mock_connect):
    # As PySpark's client, which converts and sets the metrics of the Observations of the plan of
    # an action (LogicalPlan.observations, of its children), and runs checkpoint, localCheckpoint
    # and a SQL statement without them: the metrics of an Observation of a DataFrame that only a
    # checkpoint, a SQL statement or a subquery runs set nothing, and a metric that PySpark does
    # not convert raises nothing there.
    import copy

    from pyspark.errors import PySparkTypeError
    from pyspark.sql import Observation
    from pyspark.sql import functions as F

    spark, service = mock_connect
    observation = Observation("o")
    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    batch, observed = _count_batch_and_observed_metrics(service, df)
    # Literal.long=7, year_month_interval=20; ExecutePlanResponse.checkpoint_command_result=19
    # (CheckpointCommandResult.relation=1, CachedRemoteRelation.relation_id=1).
    count = observed("o", varint_field(7, 3), "c")
    interval = observed("o", varint_field(20, 14), "c")
    checkpointed = message_field(19, message_field(1, message_field(1, "r1")))
    for metrics in (count, interval):
        service.execute_payload = checkpointed + metrics
        df.localCheckpoint()
        df.checkpoint()
        service.execute_payload = metrics
        statement = spark.sql("SELECT * FROM {d}", d=df)
        service.execute_payload = batch + metrics
        assert statement.count() == 3
        assert spark.range(1).select(df.select(F.max("id")).scalar()).count() == 3
        assert spark.range(1).where(df.exists()).count() == 3
        assert observation.get == {}
    # An action of a plan of the Observation sets its metrics, as does one of a copy of the
    # DataFrame, whose plan PySpark copies with the Observation, and both raise for a metric that
    # PySpark does not convert.
    service.execute_payload = batch + count
    assert df.where("id > 0").count() == 3 and observation.get == {"c": 3}
    service.execute_payload = batch + observed("o", varint_field(7, 4), "c")
    assert copy.copy(df).count() == 3 and observation.get == {"c": 4}
    service.execute_payload = batch + interval
    for frame in (df.union(spark.range(1)), copy.copy(df), copy.deepcopy(df)):
        with pytest.raises(PySparkTypeError):
            frame.count()
    assert observation.get == {"c": 4}


def test_a_deep_copy_sets_its_own_observations_and_a_shallow_one_shares_them_as_pyspark(
        mock_connect):
    # As PySpark's DataFrame.__reduce__, whose deep copy copies the plan, and so the Observations
    # of its CollectMetrics: an action of a deep copy sets the copied Observations, and not those
    # of the DataFrame, which keep the metrics that they had when it was copied; copy.copy shares
    # them, as do the DataFrames over the copied one.
    import copy

    from pyspark.sql import Observation
    from pyspark.sql import functions as F

    spark, service = mock_connect
    observation = Observation("o")
    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    batch, observed = _count_batch_and_observed_metrics(service, df)
    # Before the action of the copy: the original keeps its metrics, which are none.
    deep = copy.deepcopy(df)
    service.execute_payload = batch + observed("o", varint_field(7, 3), "c")
    assert deep.count() == 3 and observation.get == {}
    # A shallow copy of the deep copy shares the deep copy's Observations, not the original's.
    service.execute_payload = batch + observed("o", varint_field(7, 7), "c")
    assert copy.copy(deep).count() == 3 and observation.get == {}
    service.execute_payload = batch + observed("o", varint_field(7, 4), "c")
    assert copy.copy(df).count() == 3 and observation.get == {"c": 4}
    # After the action of the original: a deep copy has its metrics, and then its own.
    service.execute_payload = batch + observed("o", varint_field(7, 5), "c")
    assert df.count() == 3 and observation.get == {"c": 5}
    later = copy.deepcopy(df)
    assert observation.get == {"c": 5}
    service.execute_payload = batch + observed("o", varint_field(7, 6), "c")
    assert later.count() == 3 and observation.get == {"c": 5}


def test_a_deep_copy_of_a_join_sets_the_observations_of_its_copy_as_pyspark(mock_connect):
    # As PySpark's deep copy of a plan, which copies both Observations of a join: an action of
    # the copy sets the copies, and an action of the joined DataFrame sets the two Observations.
    import copy

    from pyspark.sql import Observation
    from pyspark.sql import functions as F

    spark, service = mock_connect
    first, second = Observation("first"), Observation("second")
    left = spark.range(3).observe(first, F.count(F.lit(1)).alias("c"))
    right = spark.range(5).observe(second, F.count(F.lit(1)).alias("c"))
    joined = left.join(right, "id")
    # The plan IDs of each side, which the join shares with its request.
    batch, observed = _count_batch_and_observed_metrics(service, left)
    _, observed_right = _count_batch_and_observed_metrics(service, right)
    copied = copy.deepcopy(joined)
    service.execute_payload = (batch + observed("first", varint_field(7, 3), "c")
                               + observed_right("second", varint_field(7, 5), "c"))
    assert copied.count() == 3
    assert first.get == {} and second.get == {}
    assert joined.count() == 3
    assert first.get == {"c": 3} and second.get == {"c": 5}


def test_a_deep_copy_copies_an_observation_once_with_the_objects_of_its_call_as_pyspark(
        mock_connect):
    # As PySpark's DataFrame.__reduce__, whose deep copy copies the plan, and so the Observation of
    # its CollectMetrics, with the memo of the call: an Observation that the call copies too, in a
    # tuple, a list or an object that holds both, in either order, is copied once, with its
    # attributes, and the actions of the copied DataFrame set that copy; so do those of another
    # DataFrame of the call, and of one copied with the same memo of the caller. The Observation
    # itself keeps its metrics.
    import copy

    from pyspark.sql import Observation
    from pyspark.sql import functions as F

    class Holder:
        def __init__(self, df, observation):
            self.df, self.observation = df, observation

    spark, service = mock_connect
    observation = Observation("o")
    observation.tags = ["t"]
    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    batch, observed = _count_batch_and_observed_metrics(service, df)

    def count(frame, value):
        service.execute_payload = batch + observed("o", varint_field(7, value), "c")
        return frame.count()

    holder = copy.deepcopy(Holder(df, observation))
    pairs = [copy.deepcopy((df, observation)), copy.deepcopy([observation, df])[::-1],
             (holder.df, holder.observation)]
    for value, (copied, copied_observation) in enumerate(pairs, start=3):
        assert copied_observation is not observation and copied_observation._name == "o"
        assert copied_observation.tags == ["t"] and copied_observation.tags is not observation.tags
        assert count(copied, value) == 3
        assert copied_observation.get == {"c": value} and observation.get == {}

    first, second, copied_observation = copy.deepcopy([df, df.where("id > 0"), observation])
    assert count(first, 6) == 3 and copied_observation.get == {"c": 6}
    assert count(second, 7) == 3 and copied_observation.get == {"c": 7}
    memo = {}
    copied = copy.deepcopy(df, memo)
    copied_observation = copy.deepcopy(observation, memo)
    assert copy.deepcopy(df, memo) is copied
    assert count(copied, 8) == 3 and copied_observation.get == {"c": 8}
    # A deep copy of the copies copies them so too, and a shallow copy of a copy shares its copy.
    copied, copied_observation = copy.deepcopy((df, observation))
    again, copied_again = copy.deepcopy((copied, copied_observation))
    assert count(again, 9) == 3 and copied_again.get == {"c": 9}
    assert copied_observation.get == {} and observation.get == {}
    assert count(copy.copy(copied), 11) == 3 and copied_observation.get == {"c": 11}
    assert copied_again.get == {"c": 9} and observation.get == {}
    # An attribute of the Observation that refers to the DataFrame refers to a copy of it of its
    # own, of the copied Observation, as the copy of the plan copies the Observation first.
    observation.df = df
    copied, copied_observation = copy.deepcopy((df, observation))
    assert copied_observation.df is not copied and copied_observation.df is not df
    assert count(copied_observation.df, 10) == 3 and copied_observation.get == {"c": 10}
    assert observation.get == {}


def test_a_deep_copy_copies_the_session_with_the_objects_of_its_call_as_pyspark(mock_connect):
    # As PySpark's DataFrame.__reduce__, whose deep copy copies the session after the plan with
    # the memo of the call, by SparkSession.__reduce__: the active session of its ID, once in a
    # call, so the copies of two DataFrames of the session share it, and a memo of the caller that
    # maps it to another session gives a copy of that one. Where no session is active, as on
    # another thread, a deep copy raises NO_ACTIVE_SESSION, and where another one is,
    # PySparkAssertionError; copy.copy keeps the session.
    import copy
    import threading

    from pyspark.errors import PySparkAssertionError, PySparkRuntimeError
    from pyspark.sql import SparkSession

    spark, service = mock_connect
    df = spark.range(3)
    memo = {}
    copies = copy.deepcopy([df, spark.range(5)], memo)
    assert all(copied.sparkSession is spark for copied in copies)
    assert memo[id(spark)] is spark
    seen = []

    def on_a_thread():
        try:
            copy.deepcopy(df)
        except PySparkRuntimeError as error:
            seen.append(error.getCondition())
        seen.append(copy.copy(df).sparkSession is spark)

    thread = threading.Thread(target=on_a_thread)
    thread.start()
    thread.join()
    assert seen == ["NO_ACTIVE_SESSION", True]
    other = SparkSession.builder.remote(service.remote).create()
    try:
        assert SparkSession.getActiveSession() is spark
        with pytest.raises(PySparkAssertionError, match="Expected session ID does not match"):
            copy.deepcopy(other.range(1))
        assert copy.deepcopy(df, {id(spark): other}).sparkSession is other
    finally:
        other.stop()


def test_deep_copies_into_another_session_hold_the_functions_of_their_udfs_as_pyspark(
    mock_connect,
):
    # As PySpark's copy.deepcopy of a DataFrame, which copies its plan, of deep copies of the
    # functions of its UDFs, and then its session, with the memo of the call: a copy into another
    # session, of a memo that maps the session to it, holds the functions as a copy in the session
    # does, the function itself and a copy of a callable object, which its requests pickle as they
    # are then, and copies of its Observations, of the plan IDs of the DataFrame, which the columns
    # of the DataFrame refer to. The copy requests its schema, as PySpark's reconstruction of it
    # reads its columns, and nothing else.
    import copy

    from pyspark.sql import Observation, SparkSession
    from pyspark.sql import functions as F
    from pyspark.sql.connect.proto import base_pb2

    spark, service = mock_connect
    other = SparkSession.builder.remote(service.remote).create()
    try:
        box = ["<old>"]
        marked = _Marked("<old>")
        observation = Observation("o")
        df = spark.range(1).select(
            F.udf(lambda x: box[0], "string")("id").alias("a"),
            F.udf(marked, "string")("id").alias("b"),
        ).observe(observation, F.count(F.lit(1)).alias("c"))
        df.schema
        sent = (len(service.analyze_requests), len(service.execute_requests))
        copied, copied_observation = copy.deepcopy((df, observation), {id(spark): other})
        assert (len(service.analyze_requests), len(service.execute_requests)) == (
            sent[0] + 1, sent[1])
        assert copied.sparkSession is other
        assert copied_observation is not observation
        box[0] = marked.mark = "<new>"
        copied.select(df["a"], df["b"]).explain()
        request = service.analyze_requests[-1]
        # The lambda, of the new value, and the copy of the callable object, of the old one.
        assert b"<new>" in request and b"<old>" in request
        root = base_pb2.AnalyzePlanRequest.FromString(request).explain.plan.root
        refers_to = df["a"]._expr.to_plan(None).unresolved_attribute.plan_id
        assert root.project.input.common.plan_id == refers_to
        assert root.project.expressions[0].unresolved_attribute.plan_id == refers_to
        df.explain()
        assert b"<old>" not in service.analyze_requests[-1]
        assert copied._plan.observations == {"o": copied_observation}
    finally:
        other.stop()


def test_a_copy_of_a_dataframe_has_an_execution_info_of_its_own_as_pyspark(mock_connect):
    # As PySpark's copy.copy of a DataFrame, a DataFrame(plan, session) of its plan: its
    # executionInfo is None until it executes, also of a DataFrame that executed, and then that of
    # its own executions, which leave the DataFrame's as it is; so is that of a deep copy and of an
    # unpickled DataFrame.
    import copy

    from pyspark.serializers import CloudPickleSerializer

    spark, service = mock_connect
    serializer = CloudPickleSerializer()
    df = spark.range(3)
    copied = copy.copy(df)
    copied.collect()
    assert df.executionInfo is None
    first = copied.executionInfo.operation_id
    assert first == _request_operation_id(service.execute_requests[-1])
    df.collect()
    original = df.executionInfo.operation_id
    assert original not in (None, first)
    copied.collect()
    assert df.executionInfo.operation_id == original
    assert copied.executionInfo.operation_id not in (first, original)
    for later in (copy.copy(df), copy.copy(copied), copy.deepcopy(df),
                  serializer.loads(serializer.dumps(df))):
        assert later.executionInfo is None


def test_execution_info_is_one_object_until_another_execution_as_pyspark(mock_connect):
    # As PySpark's executionInfo, the _execution_info that the last execution of the DataFrame
    # set: one object, with the attributes set on it, until another execution of the DataFrame
    # replaces it, which an action of a derived DataFrame does not; also of an observed metric of
    # a NaN, which is not equal to itself. The DataFrame keeps the object, which may keep the
    # DataFrame: the garbage collector frees both.
    import gc
    import math
    import struct
    import weakref

    spark, service = mock_connect
    # ObservedMetrics: name=1, values=2 of a Literal of double=11 (wire type 1), keys=3.
    nan = bytes([11 * 8 + 1]) + struct.pack("<d", math.nan)
    service.execute_payload = message_field(
        6, message_field(1, "o") + message_field(2, nan) + message_field(3, "x")
    )
    df = spark.range(3)
    assert df.executionInfo is None
    df.collect()
    info = df.executionInfo
    assert info is not None and df.executionInfo is info
    ((name, pairs),) = info.flows
    assert name == "o" and math.isnan(pairs["x"])
    info.custom = 1
    df.take(1)
    df.first()
    assert df.executionInfo is info and df.executionInfo.custom == 1
    df.collect()
    again = df.executionInfo
    assert again is not info and again.operation_id != info.operation_id
    assert df.executionInfo is again and not hasattr(again, "custom")
    again.frame = df
    frame = weakref.ref(df)
    del df, info, again
    gc.collect()
    assert frame() is None


def test_a_to_pandas_that_fails_to_convert_leaves_the_execution_info_as_pyspark(
        mock_connect, monkeypatch):
    # As PySpark's `_to_pandas`, which sets `_execution_info` once `SparkConnectClient.to_pandas`
    # has converted the result: a toPandas that fails after its execution, in its conversion,
    # leaves `executionInfo` as it was, None or the object of the last execution, and one that
    # converts sets that of its execution. `collect` sets it before it converts its rows, as
    # PySpark's `_to_table` does.
    import pyspark.sql.connect.client.core as client

    spark, service = mock_connect
    # The settings that toPandas reads.
    service.confs = {"spark.sql.session.timeZone": "UTC",
                     "spark.sql.execution.pandas.structHandlingMode": "legacy",
                     "spark.sql.execution.arrow.pyspark.selfDestruct.enabled": "false"}
    _two_row_range_results(service)
    convert = client._to_pandas

    def fails(*args, **kwargs):
        raise ValueError("conversion")

    monkeypatch.setattr(client, "_to_pandas", fails)
    df = spark.range(2)
    with pytest.raises(ValueError, match="conversion"):
        df.toPandas()
    assert df.executionInfo is None
    df.collect()
    info = df.executionInfo
    assert info.operation_id == _request_operation_id(service.execute_requests[-1])
    with pytest.raises(ValueError, match="conversion"):
        df.toPandas()
    assert df.executionInfo is info
    monkeypatch.setattr(client, "_to_pandas", convert)
    assert len(df.toPandas()) == 2
    assert df.executionInfo is not info
    assert df.executionInfo.operation_id == _request_operation_id(service.execute_requests[-1])


def test_copies_and_unpickled_dataframes_keep_support_repr_html_as_pyspark(mock_connect):
    # As PySpark's DataFrame.__reduce__, whose state carries _support_repr_html to a copy, a deep
    # copy and an unpickled DataFrame: once _repr_html_ was called, their repr is the string of the
    # schema with eager evaluation, else the table of eager evaluation; the _repr_html_ of a copy
    # leaves the DataFrame as it is.
    import copy

    import pyarrow as pa
    from pyspark.serializers import CloudPickleSerializer

    spark, service = mock_connect
    service.confs = {"spark.sql.repl.eagerEval.enabled": "true",
                     "spark.sql.repl.eagerEval.maxNumRows": "7",
                     "spark.sql.repl.eagerEval.truncate": "3"}
    table = pa.table({"html_string": ["<table/>"]})
    sink = pa.BufferOutputStream()
    with pa.ipc.new_stream(sink, table.schema) as writer:
        writer.write_table(table)
    # ExecutePlanResponse.arrow_batch=2: ArrowBatch.row_count=1, data=2.
    service.execute_payload = message_field(
        2, varint_field(1, 1) + message_field(2, sink.getvalue().to_pybytes()))
    serializer = CloudPickleSerializer()

    def copies(frame):
        return [copy.copy(frame), copy.deepcopy(frame), serializer.loads(serializer.dumps(frame))]

    df = spark.range(1)
    assert [repr(copied) for copied in copies(df)] == ["<table/>"] * 3
    for copied in copies(df):
        assert copied._repr_html_() == "<table/>"
    assert repr(df) == "<table/>"
    assert df._repr_html_() == "<table/>"
    assert [repr(copied) for copied in copies(df)] == ["DataFrame[id: bigint]"] * 3
    assert [repr(copied) for copied in copies(copy.deepcopy(df))] == ["DataFrame[id: bigint]"] * 3


def test_an_unpickled_dataframe_sets_copies_of_the_observations_as_pyspark(mock_connect):
    # As PySpark's unpickled plan, which has copies of the Observations of the pickled one: the
    # actions of an unpickled DataFrame, or of an unpickled deep copy, set the copies and not the
    # Observations of the DataFrame, before and after its own actions, which still set them; and
    # they raise for a metric that PySpark does not convert, as the copies are of their plan.
    import copy

    from pyspark.errors import PySparkTypeError
    from pyspark.serializers import CloudPickleSerializer
    from pyspark.sql import Observation
    from pyspark.sql import functions as F

    spark, service = mock_connect
    serializer = CloudPickleSerializer()
    observation = Observation("o")
    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    batch, observed = _count_batch_and_observed_metrics(service, df)
    # Literal.long=7, year_month_interval=20.
    for unpickled in (serializer.loads(serializer.dumps(df)),
                      serializer.loads(serializer.dumps(copy.deepcopy(df)))):
        service.execute_payload = batch + observed("o", varint_field(7, 3), "c")
        assert unpickled.count() == 3 and observation.get == {}
        service.execute_payload = batch + observed("o", varint_field(20, 14), "c")
        with pytest.raises(PySparkTypeError, match="UNSUPPORTED_LITERAL"):
            unpickled.count()
    service.execute_payload = batch + observed("o", varint_field(7, 4), "c")
    assert df.count() == 3 and observation.get == {"c": 4}
    unpickled = serializer.loads(serializer.dumps(df))
    service.execute_payload = batch + observed("o", varint_field(7, 5), "c")
    assert unpickled.count() == 3 and observation.get == {"c": 4}


def test_an_observation_copies_as_the_plain_object_of_pyspark(mock_connect):
    # As copy.copy and copy.deepcopy of PySpark's Observation, a plain object: a copy of an unused
    # one is of its name and is used on its own; a shallow copy of a used one shares its result
    # dict, so it has the metrics that the actions set later too, while a deep copy keeps those
    # that it had; both are used; and the attributes are copied as a plain object's.
    import copy

    from pyspark.errors import PySparkAssertionError
    from pyspark.sql import Observation
    from pyspark.sql import functions as F

    spark, service = mock_connect
    observation = Observation("o")
    for unused in (copy.copy(observation), copy.deepcopy(observation)):
        assert unused is not observation and unused._name == "o"
        with pytest.raises(PySparkAssertionError, match="NO_OBSERVE_BEFORE_GET"):
            unused.get
    unnamed = Observation()
    copied = copy.copy(unnamed)
    spark.range(1).observe(copied, F.count(F.lit(1)).alias("c"))
    assert copied._name is not None and unnamed._name is None
    with pytest.raises(PySparkAssertionError, match="NO_OBSERVE_BEFORE_GET"):
        unnamed.get
    spark.range(1).observe(unnamed, F.count(F.lit(1)).alias("c"))
    assert unnamed._name not in (None, copied._name)

    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    shallow, deep = copy.copy(observation), copy.deepcopy(observation)
    assert shallow.get == {} and deep.get == {}
    batch, observed = _count_batch_and_observed_metrics(service, df)
    service.execute_payload = batch + observed("o", varint_field(7, 3), "c")
    assert df.count() == 3
    assert observation.get == {"c": 3} and shallow.get == {"c": 3} and deep.get == {}
    later = copy.deepcopy(observation)
    for used in (shallow, deep, later, copy.copy(observation)):
        with pytest.raises(PySparkAssertionError, match="REUSE_OBSERVATION"):
            spark.range(1).observe(used, F.count(F.lit(1)).alias("c"))
    service.execute_payload = batch + observed("o", varint_field(7, 4), "c")
    assert df.count() == 3
    assert observation.get == {"c": 4} and shallow.get == {"c": 4} and later.get == {"c": 3}

    observation.tags = ["t"]
    observation.me = observation
    shallow = copy.copy(observation)
    assert shallow.tags is observation.tags and shallow.me is observation
    deep = copy.deepcopy(observation)
    assert deep.tags == ["t"] and deep.tags is not observation.tags and deep.me is deep
    both = copy.deepcopy([observation, observation])
    assert both[0] is both[1] and both[0] is not observation and both[0].get == {"c": 4}


from pyspark.sql.connect.observation import Observation as _ConnectObservation  # noqa: E402


class _ObservationOfTag(_ConnectObservation):
    def __init__(self, *args, tag=None, **kwargs):
        super().__init__(*args, **kwargs)
        self.tag = tag


def test_an_observation_of_a_subclass_constructs_copies_and_pickles_as_pyspark(mock_connect):
    # As PySpark Connect's Observation, a plain class: a subclass constructs of the arguments of
    # its __init__, which checks the name as PySpark's does, and its copies and pickles, at every
    # protocol, are of the subclass, with its name, its state and its attributes; a re-run of
    # __init__ makes it anew.
    import copy

    from pyspark.errors import PySparkTypeError, PySparkValueError
    from pyspark.sql import functions as F

    spark, service = mock_connect
    observation = _ObservationOfTag("o", tag="t")
    assert type(observation) is _ObservationOfTag and observation._name == "o"
    assert observation.tag == "t" and _ObservationOfTag()._name is None
    with pytest.raises(PySparkTypeError, match="NOT_EXPECTED_TYPE"):
        _ObservationOfTag(1)
    with pytest.raises(PySparkValueError, match="VALUE_NOT_NON_EMPTY_STR"):
        _ObservationOfTag("")
    with pytest.raises(TypeError, match="unexpected keyword argument 'other'"):
        _ConnectObservation("o", other=1)
    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    batch, observed = _count_batch_and_observed_metrics(service, df)
    service.execute_payload = batch + observed("o", varint_field(7, 3), "c")
    assert df.count() == 3
    copies = [copy.copy(observation), copy.deepcopy(observation)]
    copies += [pickle.loads(pickle.dumps(observation, protocol))
               for protocol in range(pickle.HIGHEST_PROTOCOL + 1)]
    for copied in copies:
        assert type(copied) is _ObservationOfTag and copied is not observation
        assert copied._name == "o" and copied.tag == "t" and copied.get == {"c": 3}
    observation.__init__("again")
    assert observation._name == "again" and observation.tag is None
    spark.range(1).observe(observation, F.count(F.lit(1)).alias("c"))


def test_an_observation_pickles_as_the_plain_object_of_pyspark(mock_connect):
    # As pickle of PySpark's Observation, a plain object of pyspark.sql.connect.observation, of
    # its __dict__: _name, _result and _error. So a Python worker of the server, whose PySpark
    # has no Rust client, unpickles PySpark's Observation, and this client its own: an unused one
    # is used on its own, a used one keeps its metrics, which no action sets, and a failed one
    # raises its error, of the class and the message of the error that the server sent.
    import copy
    import copyreg
    import io
    import pickle
    import subprocess
    import sys

    from pyspark import cloudpickle
    from pyspark.errors import PySparkAssertionError
    from pyspark.sql import Observation
    from pyspark.sql import functions as F
    from pyspark.sql.connect.observation import Observation as ConnectObservation

    class Worker(pickle.Unpickler):
        # The classes that a worker's PySpark finds: a plain class for the Observation.
        def find_class(self, module, name):
            if (module, name) == ("pyspark.sql.connect.observation", "Observation"):
                return type("Observation", (), {})
            return super().find_class(module, name)

    def on_worker(observation):
        # As cloudpickle pickles it into a worker, by reference to the class, and as pickle does.
        pickled = [vars(Worker(io.BytesIO(dumps(observation))).load())
                   for dumps in (pickle.dumps, cloudpickle.dumps)]
        # An exception is equal only to itself: compare its class and message.
        same = [{k: (type(v), str(v)) if isinstance(v, BaseException) else v
                 for k, v in state.items()} for state in pickled]
        assert same[0] == same[1]
        return pickled[1]

    # cloudpickle finds the module of a class only in sys.modules, where the Observation of
    # pyspark.sql, PySpark's classic class, puts it as it makes an Observation of the class of
    # that module, in a new process too.
    script = (
        "import sys\nfrom pyspark.sql import Observation\n"
        "m = 'pyspark.sql.connect.observation'\n"
        "print(m in sys.modules, type(Observation('o')).__module__ == m, m in sys.modules)\n"
    )
    imported = subprocess.run([sys.executable], input=script, capture_output=True, text=True,
                              check=True)
    assert imported.stdout.strip() == "False True True"
    spark, service = mock_connect
    unused = pickle.loads(pickle.dumps(Observation("u")))
    assert type(unused) is ConnectObservation and unused._name == "u"
    assert on_worker(Observation("u")) == {"_name": "u", "_result": None, "_error": None}
    spark.range(1).observe(unused, F.count(F.lit(1)).alias("c"))
    assert pickle.loads(pickle.dumps(unused)).get == {}

    observation = Observation("o")
    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    batch, observed = _count_batch_and_observed_metrics(service, df)
    service.execute_payload = batch + observed("o", varint_field(7, 3), "c")
    assert df.count() == 3
    observation.tag = "t"
    restored = pickle.loads(pickle.dumps(observation))
    assert restored.get == {"c": 3} and restored._name == "o" and restored.tag == "t"
    assert restored.get is restored.get
    assert on_worker(observation) == {"_name": "o", "_result": {"c": 3}, "_error": None,
                                      "tag": "t"}
    assert pickle.loads(pickle.dumps(observation, protocol=2)).get == {"c": 3}
    assert observation.__reduce_ex__(4)[:2] == (copyreg.__newobj__, (ConnectObservation,))
    with pytest.raises(PySparkAssertionError, match="REUSE_OBSERVATION"):
        spark.range(1).observe(restored, F.count(F.lit(1)).alias("c"))
    service.execute_payload = batch + observed("o", varint_field(7, 4), "c")
    assert df.count() == 3
    assert observation.get == {"c": 4} and restored.get == {"c": 3}
    shallow, deep = copy.copy(restored), copy.deepcopy(restored)
    assert shallow.get is restored.get and deep.get == {"c": 3} and deep.get is not restored.get

    # ExecutePlanResponse.observed_metrics=6: ObservedMetrics.name=1, root_error_idx=5, errors=6;
    # Error.error_type_hierarchy=1, message=2, spark_throwable=5; SparkThrowable.error_class=1,
    # sql_state=4.
    failed = Observation("f")
    failing = spark.range(3).observe(failed, F.count(F.lit(1)).alias("c"))
    error = (message_field(1, "org.apache.spark.SparkArithmeticException")
             + message_field(1, "java.lang.ArithmeticException")
             + message_field(2, "[DIVIDE_BY_ZERO] Division by zero. SQLSTATE: 22012")
             + message_field(5, message_field(1, "DIVIDE_BY_ZERO") + message_field(4, "22012")))
    service.execute_payload = batch + message_field(
        6, message_field(1, "f") + varint_field(5, 0) + message_field(6, error))
    assert failing.count() == 3
    with pytest.raises(Exception, match="DIVIDE_BY_ZERO") as raised:
        failed.get
    assert type(raised.value).__name__ == "ArithmeticException"
    for copied in (pickle.loads(pickle.dumps(failed)), copy.deepcopy(pickle.loads(
            pickle.dumps(failed)))):
        with pytest.raises(type(raised.value)) as again:
            copied.get
        assert str(again.value) == str(raised.value)
    assert type(on_worker(failed)["_error"]) is type(raised.value)


def test_an_observation_pickles_at_every_protocol_as_pyspark(mock_connect):
    # As pickle of PySpark's Observation, a plain object, at each protocol: the protocols 0 and 1
    # pickle it too, as the protocols 2 and up do, before and after the observed DataFrame ran,
    # and an unpickled one pickles again with the metrics that it keeps.
    from pyspark.errors import PySparkAssertionError
    from pyspark.sql import Observation
    from pyspark.sql import functions as F
    from pyspark.sql.connect.observation import Observation as ConnectObservation

    spark, service = mock_connect
    protocols = range(pickle.HIGHEST_PROTOCOL + 1)
    observation = Observation("o")
    for protocol in protocols:
        unused = pickle.loads(pickle.dumps(observation, protocol=protocol))
        assert type(unused) is ConnectObservation and unused._name == "o"
        again = pickle.loads(pickle.dumps(unused, protocol=protocol))
        assert type(again) is ConnectObservation and again._name == "o"
        spark.range(1).observe(again, F.count(F.lit(1)).alias("c"))

    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    batch, observed = _count_batch_and_observed_metrics(service, df)
    service.execute_payload = batch + observed("o", varint_field(7, 3), "c")
    assert df.count() == 3
    for protocol in protocols:
        restored = pickle.loads(pickle.dumps(observation, protocol=protocol))
        assert type(restored) is ConnectObservation and restored._name == "o"
        assert restored.get == {"c": 3}
        twice = pickle.loads(pickle.dumps(restored, protocol=protocol))
        assert twice._name == "o" and twice.get == {"c": 3}
        with pytest.raises(PySparkAssertionError, match="REUSE_OBSERVATION"):
            spark.range(1).observe(twice, F.count(F.lit(1)).alias("c"))


def test_a_failing_action_keeps_the_metrics_of_the_earlier_actions_as_pyspark(mock_connect):
    # As PySpark's client, which converts the metrics of an Observation before it updates the
    # Observation with them: the Observation of a metric that it does not convert, and those
    # whose metrics come after it, keep the metrics of the earlier actions, and the exception has
    # the operation ID of the execution, as PySpark's _handle_error stamps it.
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import Observation
    from pyspark.sql import functions as F

    spark, service = mock_connect
    first, second = Observation("first"), Observation("second")
    df = (spark.range(3).observe(first, F.count(F.lit(1)).alias("c"))
          .observe(second, F.max("id").alias("m")))
    _, observed = _count_batch_and_observed_metrics(service, df)
    # Literal.long=7, year_month_interval=20.
    interval = varint_field(20, 14)
    service.execute_payload = (observed("first", varint_field(7, 3), "c")
                               + observed("second", varint_field(7, 2), "m"))
    df.collect()
    assert first.get == {"c": 3} and second.get == {"m": 2}
    for payload, kept in [
        (observed("second", interval, "m") + observed("first", varint_field(7, 4), "c"),
         {"c": 3}),
        (observed("first", varint_field(7, 5), "c") + observed("second", interval, "m"),
         {"c": 5}),
    ]:
        service.execute_payload = payload
        with pytest.raises(PySparkTypeError) as error:
            df.collect()
        assert error.value.getCondition() == "UNSUPPORTED_LITERAL"
        assert first.get == kept and second.get == {"m": 2}
        assert error.value._operation_id == _request_operation_id(service.execute_requests[-1])


def test_flows_raise_for_a_metric_that_holds_one_pyspark_cannot_convert_as_pyspark(mock_connect):
    # As PySpark's PlanObservedMetrics.pairs, which converts each metric with
    # LiteralExpression._to_value: a metric of a name that holds a year-month interval as an
    # element, of an array, a struct or a map, raises UNSUPPORTED_LITERAL of that element.
    import pyspark.sql.connect.proto as pb2
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import functions as F

    spark, service = mock_connect
    # The literals as the server sends them, of their element, key, value and struct types.
    interval = pb2.DataType(year_month_interval=pb2.DataType.YearMonthInterval())
    string = pb2.DataType(string=pb2.DataType.String())
    first, later = (pb2.Expression.Literal(year_month_interval=n) for n in (12, 13))

    def struct(*elements):
        struct = pb2.Expression.Literal()
        struct.struct.struct_type.struct.fields.add(name="f", data_type=interval)
        struct.struct.elements.extend(elements)
        return struct

    def array(element_type, *elements):
        array = pb2.Expression.Literal()
        array.array.element_type.CopyFrom(element_type)
        array.array.elements.extend(elements)
        return array

    key_and_value = pb2.Expression.Literal()
    key_and_value.map.key_type.CopyFrom(string)
    key_and_value.map.value_type.CopyFrom(interval)
    key_and_value.map.keys.add(string="k")
    key_and_value.map.values.append(first)
    holders = [
        array(interval, first, later),
        struct(first),
        key_and_value,
        array(struct(first).struct.struct_type, struct(first)),
    ]
    named = spark.range(3).observe("named", F.max("id").alias("m"))
    for holder in holders:
        service.execute_payload = message_field(
            6, message_field(1, "named") + message_field(2, holder.SerializeToString())
            + message_field(3, "m"))
        assert named.collect() == []
        info = named.executionInfo
        with pytest.raises(PySparkTypeError) as error:
            info.flows
        assert error.value.getCondition() == "UNSUPPORTED_LITERAL"
        assert error.value.getMessageParameters() == {"literal": "year_month_interval: 12\n"}
        with pytest.raises(PySparkTypeError):
            [metrics.to_dict() for metrics in info._observations]


def test_json_names_of_nanosecond_timestamps_are_not_data_types_as_pyspark():
    # As PySpark's, which has no nanosecond timestamp types: their JSON names do not parse
    # (CANNOT_PARSE_DATATYPE), and pyspark.sql.types has no names of them.
    from pyspark.errors import PySparkValueError

    for name in ("timestamp_ntz(9)", "timestamp_ltz(7)"):
        field = {"name": "t", "type": name, "nullable": True, "metadata": {}}
        for parse in (lambda: T._parse_datatype_json_value(name),
                      lambda: T._parse_datatype_json_string(json.dumps(name)),
                      lambda: T.StructType.fromJson({"type": "struct", "fields": [field]}),
                      lambda: T.StructField.fromJson(field),
                      lambda: T.ArrayType.fromJson(
                          {"type": "array", "elementType": name, "containsNull": True}),
                      lambda: T.StructType().add("t", name)):
            with pytest.raises(PySparkValueError) as error:
                parse()
            assert error.value.getCondition() == "CANNOT_PARSE_DATATYPE"
            assert error.value.getMessageParameters() == {"msg": name}
    assert T._parse_datatype_json_value("timestamp_ntz") == T.TimestampNTZType()
    assert not hasattr(T, "TimestampNTZNanosType") and not hasattr(T, "TimestampLTZNanosType")


def test_local_iterators_call_the_progress_handlers_in_next_whatever_the_prefetch_as_pyspark(
        mock_connect):
    # As PySpark Connect's toLocalIterator, which ignores prefetchPartitions: the progress of
    # the execution reaches the handlers as next() reads it, on the iterating thread, so that
    # the exception of a handler is raised by next().
    import threading

    spark, service = mock_connect
    # ExecutePlanResponse.execution_progress=18 -> ExecutionProgress.stages=1 (StageInfo
    # stage_id=1, num_tasks=2), num_inflight_tasks=2.
    stage = varint_field(1, 7) + varint_field(2, 4)
    service.execute_payload = message_field(18, message_field(1, stage) + varint_field(2, 3))
    threads = []

    def handler(**kwargs):
        threads.append((threading.get_ident(), kwargs["done"]))

    spark.registerProgressHandler(handler)
    for prefetch in (False, True):
        threads.clear()
        assert list(spark.range(1).toLocalIterator(prefetch)) == []
        assert threads == [(threading.get_ident(), False), (threading.get_ident(), True)]
    spark.clearProgressHandlers()

    def failing(**kwargs):
        if not kwargs["done"]:
            raise ZeroDivisionError("update")

    spark.registerProgressHandler(failing)
    with pytest.raises(ZeroDivisionError):
        next(spark.range(1).toLocalIterator(prefetchPartitions=True))
    spark.clearProgressHandlers()


def test_local_iterators_take_any_prefetch_partitions_as_pyspark(mock_connect):
    # As PySpark Connect's toLocalIterator, which ignores prefetchPartitions: any value, by
    # position or by name, sends the plan of the default and yields the rows. The default is
    # False, as PySpark's.
    import inspect

    import pyarrow as pa
    from binary_configuration_cases import _results

    spark, service = mock_connect
    _results(service, pa.RecordBatch.from_arrays([pa.array([0, 1])], names=["id"]))
    df = spark.range(2)
    assert [row.id for row in df.toLocalIterator()] == [0, 1]
    # ExecutePlanRequest.plan=3.
    plan = parse_message(service.execute_requests[-1])[3]
    for value in (True, False, 1, 0, None, "x", [1]):
        assert [row.id for row in df.toLocalIterator(value)] == [0, 1]
        assert parse_message(service.execute_requests[-1])[3] == plan
        assert [row.id for row in df.toLocalIterator(prefetchPartitions=value)] == [0, 1]
        assert parse_message(service.execute_requests[-1])[3] == plan
    signature = inspect.signature(type(df).toLocalIterator)
    assert signature.parameters["prefetchPartitions"].default is False
    with pytest.raises(TypeError):
        df.toLocalIterator(True, 1)


def test_is_streaming_is_empty_and_input_files_are_asked_once_per_dataframe_as_pyspark(
        mock_connect):
    # As PySpark's isStreaming (a cached_property), isEmpty and inputFiles (functools.cache): a
    # DataFrame asks the server once, and keeps the answer after the session stopped.
    import pyarrow as pa

    spark, service = mock_connect
    table = pa.table({"count(1)": pa.array([1], pa.int64())})
    sink = pa.BufferOutputStream()
    with pa.ipc.new_stream(sink, table.schema) as writer:
        writer.write_table(table)
    # ExecutePlanResponse.schema=7, arrow_batch=2 (ArrowBatch.row_count=1, data=2).
    service.execute_payload = message_field(7, struct_schema("count(1)")) + message_field(
        2, varint_field(1, 1) + message_field(2, sink.getvalue().to_pybytes()))
    df = spark.range(1)
    try:
        assert df.isStreaming is False
        service.streaming = True
        assert df.isStreaming is False
    finally:
        service.streaming = False
    assert df.isEmpty() is False and df.isEmpty() is False
    assert df.inputFiles() == [] and df.inputFiles() == []
    # base.proto: AnalyzePlanRequest.is_streaming=8, input_files=9.
    asked = [field for request in service.analyze_requests for field in parse_message(request)]
    assert (asked.count(8), asked.count(9), len(service.execute_requests)) == (1, 1, 1)
    spark.stop()
    assert df.isStreaming is False and df.isEmpty() is False and df.inputFiles() == []


@pytest.mark.parametrize("cls,name,descriptor", [
    (_SS, "version", "cached_property"),
    (_ConnectDF, "dtypes", "getset_descriptor"),
    (_ConnectDF, "executionInfo", "getset_descriptor"),
    (_DF, "dtypes", "property"),
    (_DF, "executionInfo", "property"),
])
def test_property_not_method(cls, name, descriptor):
    # PySpark accesses these without parentheses. Concrete Rust getters remain
    # getset descriptors; the Python public base exposes ordinary properties, and the session's
    # `version` is PySpark Connect's `functools.cached_property`.
    assert type(inspect.getattr_static(cls, name)).__name__ == descriptor


def test_show_has_no_required_args_and_defaults_n_to_20():
    sig = inspect.signature(_DF.show)
    required = [
        p.name
        for p in sig.parameters.values()
        if p.name not in ("self", "cls")
        and p.kind in (p.POSITIONAL_OR_KEYWORD, p.POSITIONAL_ONLY, p.KEYWORD_ONLY)
        and p.default is inspect._empty
    ]
    assert required == [], required  # df.show() must work
    assert sig.parameters["n"].default == 20


