# The __all__ of PySpark 4.3.0's pyspark.sql.types, in its order.
OFFICIAL_TYPES_ALL = [
    "DataType", "NullType", "CharType", "StringType", "VarcharType", "BinaryType", "BooleanType",
    "DateType", "TimeType", "TimestampType", "TimestampNTZType", "DecimalType", "DoubleType",
    "Geography", "Geometry", "FloatType", "ByteType", "IntegerType", "LongType",
    "DayTimeIntervalType", "YearMonthIntervalType", "CalendarIntervalType", "Row", "ShortType",
    "ArrayType", "MapType", "StructField", "StructType", "VariantType", "VariantVal",
    "GeographyType", "GeometryType",
]


def test_types_all_and_its_star_import_are_pysparks():
    # As PySpark's: __all__ is PySpark's 32 names, the spatial and variant classes among them,
    # which a star import brings in. UserDefinedType and the private helpers are names of the
    # module that it does not list, and that a star import does not bring in.
    assert T.__all__ == OFFICIAL_TYPES_ALL
    namespace = {}
    exec("from pyspark.sql.types import *", namespace)
    namespace.pop("__builtins__")
    assert list(namespace) == OFFICIAL_TYPES_ALL
    assert all(namespace[name] is getattr(T, name) for name in OFFICIAL_TYPES_ALL)
    for name in ("UserDefinedType", "_drop_metadata", "_parse_datatype_json_string",
                 "_parse_datatype_json_value"):
        assert name not in namespace, name
        imported = {}
        exec(f"from pyspark.sql.types import {name}", imported)
        assert imported[name] is getattr(T, name), name


def test_streaming_progress_and_listeners_are_those_of_pyspark():
    # As PySpark's: the server leaves the totals of the rows out of the JSON of a progress, of
    # which the progress sums those of its sources; and a listener has a session.
    from pyspark.sql.streaming import listener as listener_module
    from pyspark.sql.streaming.listener import (
        QueryProgressEvent,
        StreamingQueryListener,
        StreamingQueryProgress,
    )

    source = {
        "description": "RateStreamV2[rowsPerSecond=10, rampUpTimeSeconds=0, numPartitions=default",
        "startOffset": "0", "endOffset": "1", "latestOffset": "1", "numInputRows": 10,
        "inputRowsPerSecond": 666.5, "processedRowsPerSecond": 30.5, "metrics": {},
    }
    progress = {
        "id": "74482783-456e-4ea8-ba81-a85565c714a3",
        "runId": "1615bcbd-7213-4d70-b9a3-094da5d810d7", "name": None,
        "timestamp": "2026-11-08T02:52:01.261Z", "batchId": 1, "batchDuration": 324,
        "durationMs": {"triggerExecution": 324}, "eventTime": {}, "stateOperators": [],
        "sources": [source, dict(source, numInputRows=5, inputRowsPerSecond=1.0)],
        "sink": {"description": "NoopTable", "numOutputRows": 15, "metrics": {}},
        "observedMetrics": {},
    }
    parsed = StreamingQueryProgress.fromJson(progress)
    assert parsed.numInputRows == 15 and parsed.inputRowsPerSecond == 667.5
    assert parsed.processedRowsPerSecond == 61.0 and parsed["numInputRows"] is None
    assert [s.numInputRows for s in parsed.sources] == [10, 5] and parsed.sink.numOutputRows == 15
    event = QueryProgressEvent.fromJson({"progress": progress})
    assert event.progress.numInputRows == 15 and event.progress.batchId == 1
    assert listener_module.__all__ == ["StreamingQueryListener"]

    class Listener(StreamingQueryListener):
        def onQueryStarted(self, event): ...
        def onQueryProgress(self, event): ...
        def onQueryIdle(self, event): ...
        def onQueryTerminated(self, event): ...

    listener = Listener()
    assert listener.spark is None
    listener._set_spark_session("session")
    assert listener.spark == "session"


def test_streaming_exports_the_stateful_processor_and_tws_tester():
    import pandas as pd
    from pyspark.sql import Row
    from pyspark.sql.streaming import (
        StatefulProcessor,
        StatefulProcessorHandle,
        TwsTester,
        stateful_processor,
        tws_tester,
    )

    assert StatefulProcessor is stateful_processor.StatefulProcessor
    assert StatefulProcessorHandle is stateful_processor.StatefulProcessorHandle
    assert TwsTester is tws_tester.TwsTester

    class RunningCount(StatefulProcessor):
        # As the running count of PySpark's tests of TwsTester.
        def __init__(self, use_pandas):
            self.use_pandas = use_pandas

        def init(self, handle):
            self.count = handle.getValueState(
                "count", T.StructType([T.StructField("value", T.IntegerType())]))

        def handleInputRows(self, key, rows, timerValues):
            count = self.count.get()[0] if self.count.exists() else 0
            if self.use_pandas:
                count += sum(len(frame) for frame in rows)
                self.count.update((count,))
                yield pd.DataFrame({"key": [key[0]], "count": [count]})
            else:
                count += sum(1 for _ in rows)
                self.count.update((count,))
                yield Row(key=key[0], count=count)

        def close(self):
            pass

    tester = TwsTester(RunningCount(use_pandas=False))
    assert tester.test("key1", [Row(value="a")]) == [Row(key="key1", count=1)]
    assert tester.test("key1", [Row(value="a"), Row(value="a")]) == [Row(key="key1", count=3)]
    assert tester.peekValueState("count", "key1") == (3,)
    assert tester.peekValueState("count", "key2") is None

    tester = TwsTester(RunningCount(use_pandas=True))
    result = tester.testInPandas("key1", pd.DataFrame({"value": ["a", "a"]}))
    assert result.to_dict("list") == {"key": ["key1"], "count": [2]}


