@pytest.mark.parametrize("labels", ["multi2", "multi3", "categorical"])
@pytest.mark.parametrize("cell, arrow_type", [
    # A naive datetime of a list is a timestamp_ntz, not a time of the session time zone.
    ([datetime.datetime(2020, 1, 2, 3)], lambda pa: pa.list_(pa.timestamp("us"))),
    # Decimals of a list take the smallest precision and scale that hold them, as PySpark does.
    ([decimal.Decimal("1.5"), decimal.Decimal("10.25")],
     lambda pa: pa.list_(pa.decimal128(4, 2))),
    # A dict cell is a struct of the value types of its keys, mixed or not, not a map.
    ({"u": 1, "v": "a"}, lambda pa: pa.struct([("u", pa.int64()), ("v", pa.string())])),
    ({"u": 1, "v": 2}, lambda pa: pa.struct([("u", pa.int64()), ("v", pa.int64())])),
])
def test_multi_and_categorical_labels_convert_cells_as_pyspark(
    mock_connect, labels, cell, arrow_type
):
    # A plain frame whose labels are a MultiIndex or a CategoricalIndex converts with Arrow,
    # as one with default labels and every frame: its cells take the types that PySpark infers
    # (a timestamp_ntz of a naive datetime, a struct of a dict).
    import pyarrow as pa

    pd = pytest.importorskip("pandas")
    columns = {
        "multi2": pd.MultiIndex.from_tuples([("a", "x")]),
        "multi3": pd.MultiIndex.from_tuples([("a", "x", "p")]),
        "categorical": pd.CategoricalIndex(["a"]),
    }[labels]
    data = pd.DataFrame([[cell]], columns=columns, dtype=object)
    table = _native_number_input_table(mock_connect, data)
    assert table.num_columns == 1
    assert table.schema.field(0).type == arrow_type(pa)
    assert table.column(0).to_pylist() == [cell]


def test_create_dataframe_pandas_errors_as_pyspark(mock_connect):
    pd = pytest.importorskip("pandas")
    from pyspark.errors import PySparkTypeError, PySparkValueError

    pdf = pd.DataFrame({"a": [1, 2], "b": ["x", "y"]})

    class Unconverted(pd.DataFrame):
        def astype(self, *args, **kwargs):
            raise AssertionError("no conversion of the rows of a frame of an atomic schema")

    # pyspark reports the parsed type, also for an atomic DDL string, and reads no data of the
    # frame, whatever its class.
    for frame in (pdf, Unconverted(pdf)):
        for schema, data_type in [(T.LongType(), "LongType()"), ("int", "IntegerType()")]:
            with pytest.raises(PySparkTypeError) as error:
                _local_create_dataframe(frame, schema, session=mock_connect[0])
            assert error.value.getCondition() == "UNSUPPORTED_DATA_TYPE_FOR_ARROW"
            assert error.value.getMessageParameters() == {"data_type": data_type}
    for data, schema in [(pd.DataFrame(index=[0, 1]), None), ([], None), ([], ["a"]),
                         (pdf.iloc[:0], None), (pdf.iloc[:0], ["a", "b"])]:
        with pytest.raises(PySparkValueError) as error:
            _local_create_dataframe(data, schema, session=mock_connect[0])
        assert error.value.getCondition() == "CANNOT_INFER_EMPTY_SCHEMA"


@pytest.mark.parametrize("data", [[(None,)], [(1, None)], [{"a": None}], [{"a": 1}, {"b": None}]])
def test_create_dataframe_cannot_type_an_all_null_field_as_pyspark(data, mock_connect):
    from pyspark.errors import PySparkValueError

    # A field without a non-null value in any row has no type to infer.
    with pytest.raises(PySparkValueError) as error:
        _local_create_dataframe(data, None, session=mock_connect[0])
    assert error.value.getCondition() == "CANNOT_DETERMINE_TYPE"


@pytest.mark.parametrize("data,condition,parameters", [
    # The types of every row merge, as in PySpark, and types of other classes do not.
    ([(1,), (2.5,)], "CANNOT_MERGE_TYPE", {"data_type1": "LongType", "data_type2": "DoubleType"}),
    ([(True,), (1,)], "CANNOT_MERGE_TYPE", {"data_type1": "BooleanType", "data_type2": "LongType"}),
    ([(decimal.Decimal("1.5"),), (1,)], "CANNOT_MERGE_TYPE",
     {"data_type1": "DecimalType", "data_type2": "LongType"}),
    # A row is a Row, a tuple, a list, a dict or an object, which None is not.
    ([(1,), None], "CANNOT_INFER_SCHEMA_FOR_TYPE", {"data_type": "NoneType"}),
    # A value of a type that cannot be inferred names its field.
    ([({1, 2},)], "CANNOT_INFER_TYPE_FOR_FIELD", {"field_name": "_1"}),
    ([(array.array("q", [1]),)], "CANNOT_INFER_TYPE_FOR_FIELD", {"field_name": "_1"}),
])
def test_create_dataframe_raises_inference_errors_as_pyspark(
        data, condition, parameters, mock_connect):
    from pyspark.errors import PySparkTypeError

    with pytest.raises(PySparkTypeError) as error:
        _local_create_dataframe(data, session=mock_connect[0])
    assert error.value.getCondition() == condition
    assert error.value.getMessageParameters() == parameters


def test_sample_sort_group_by_and_drop_take_their_arguments_as_pyspark(mock_connect):
    # As PySpark's: sample takes a fraction and a seed positionally, sort and groupBy take the
    # 1-based ordinals of columns, a negative one of sort descending, and drop takes Columns,
    # which it sends as expressions.
    import struct

    from pyspark.errors import PySparkIndexError, PySparkTypeError, PySparkValueError
    from pyspark.sql import functions as F

    spark, service = mock_connect
    df = spark.range(1)

    def relation(dataframe, field):
        # ExecutePlanRequest.plan=3, Plan.root=1.
        dataframe.collect()
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
        return parse_message(parse_message(plan)[field][0])

    # Relation.sample=12: Sample.upper_bound=3, a double, seed=5.
    for sampled in (df.sample(0.5, 42), df.sample(fraction=0.5, seed=42),
                    df.sample(False, 0.5, 42)):
        sample = relation(sampled, 12)
        assert struct.unpack("<d", sample[3][0]) == (0.5,) and sample[5] == [42]
    # Relation.drop=21: Drop.columns=2, of expressions, column_names=3.
    drop = relation(df.drop(F.col("a"), "b"), 21)
    assert len(drop[2]) == 1 and drop[3] == [b"b"]

    def column_name(expression):
        # Expression.unresolved_attribute=2, UnresolvedAttribute.unparsed_identifier=1.
        return parse_message(parse_message(expression)[2][0])[1][0]

    # Relation.sort=7, Sort.order=2: SortOrder.child=1, direction=2 (DESCENDING=2).
    for sorted_df, direction in ((df.sort(1), 1), (df.orderBy(-1), 2),
                                 (df.sort(1, ascending=False), 2)):
        order = parse_message(relation(sorted_df, 7)[2][0])
        assert column_name(order[1][0]) == b"id" and order[2] == [direction]
    # Relation.aggregate=9, Aggregate.grouping_expressions=3.
    grouping = relation(df.groupBy(1).count(), 9)[3]
    assert [column_name(expression) for expression in grouping] == [b"id"]

    for call, (error_type, condition, parameters) in (
        (lambda: df.sort(), (PySparkValueError, "CANNOT_BE_EMPTY", {"item": "cols"})),
        (lambda: df.sort(0), (PySparkIndexError, "ZERO_INDEX", {})),
        (lambda: df.groupBy(0), (PySparkIndexError, "INDEX_NOT_POSITIVE", {"index": "0"})),
        (lambda: df.sort(1.5), (PySparkTypeError, "NOT_EXPECTED_TYPE",
                                {"expected_type": "Column, int or str", "arg_name": "col",
                                 "arg_type": "float"})),
        (lambda: df.groupBy(1.5), (PySparkTypeError, "NOT_EXPECTED_TYPE",
                                   {"expected_type": "Column, int or str", "arg_name": "cols",
                                    "arg_type": "float"})),
        (lambda: df.drop(1), (PySparkTypeError, "NOT_EXPECTED_TYPE",
                              {"expected_type": "Column or str", "arg_name": "cols",
                               "arg_type": "tuple"})),
        (lambda: df.sample(True, 1), (PySparkTypeError, "NOT_EXPECTED_TYPE",
                                      {"expected_type": "bool, float or int",
                                       "arg_name": "withReplacement (optional), fraction "
                                                   "(required) and seed (optional)",
                                       "arg_type": "bool, int, NoneType"})),
    ):
        with pytest.raises(error_type) as error:
            call()
        assert error.value.getCondition() == condition
        assert error.value.getMessageParameters() == parameters


def test_sample_split_and_sample_by_draw_their_seed_from_python_random_as_pyspark(mock_connect):
    # As PySpark Connect's: without a seed, sample, randomSplit and sampleBy draw one with
    # random.randint(0, sys.maxsize), so random.seed makes their rows repeat across processes.
    # An explicit seed is sent as given and draws nothing. A sum of weights that is not
    # positive raises after the draw, a negative weight before it.
    import random
    import sys

    from pyspark.errors import PySparkValueError

    spark, service = mock_connect
    df = spark.range(10)

    def seed_of(dataframe, field):
        # Relation.sample=12 or Relation.sample_by=107, whose seed is StatSampleBy.seed=5.
        dataframe.collect()
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
        return parse_message(parse_message(plan)[field][0])[5][0]

    random.seed(42)
    draws = [random.randint(0, sys.maxsize) for _ in range(5)]
    random.seed(42)
    assert seed_of(df.sample(0.5, 7), 12) == 7
    assert seed_of(df.sample(0.5), 12) == draws[0]
    assert [seed_of(split, 12) for split in df.randomSplit([1.0, 2.0])] == [draws[1]] * 2
    with pytest.raises(PySparkValueError):
        df.randomSplit([0.0, 0.0])
    with pytest.raises(PySparkValueError):
        df.randomSplit([-1.0, 2.0])
    assert seed_of(df.sampleBy("id", {0: 1.0}), 107) == draws[3]
    assert seed_of(df.sample(fraction=0.5), 12) == draws[4]
    assert seed_of(df.stat.sampleBy("id", {0: 1.0}, 7), 107) == 7


def test_random_split_converts_its_seed_with_int_as_pyspark(mock_connect):
    # As PySpark Connect's randomSplit: the seed goes through int() in each Sample, so a float
    # is truncated and a str is parsed, and the splits are those of the int seed. A str that
    # int() rejects raises its ValueError, after the weights are checked.
    from pyspark.errors import PySparkValueError

    spark, service = mock_connect
    df = spark.range(10)

    def sample_of(dataframe):
        # The Sample relation (field 12) of the plan of the last request.
        dataframe.collect()
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
        return parse_message(plan)[12][0]

    expected = [sample_of(split) for split in df.randomSplit([1.0, 1.0], 1)]
    assert [sample_of(split) for split in df.randomSplit([1.0, 1.0], 1.5)] == expected
    assert [sample_of(split) for split in df.randomSplit([1.0, 1.0], "1")] == expected
    assert [parse_message(sample)[5][0] for sample in expected] == [1, 1]
    with pytest.raises(ValueError, match="invalid literal for int"):
        df.randomSplit([1.0, 1.0], "3.5")
    with pytest.raises(PySparkValueError) as error:
        df.randomSplit([0.0, 0.0], "3.5")
    assert error.value.getCondition() == "VALUE_NOT_POSITIVE"


def test_random_split_iterates_its_weights_as_pyspark(mock_connect):
    # As PySpark Connect's randomSplit, which iterates the weights for their check, their sum and
    # their proportions, and adds the proportions up from 0.0: any iterable is taken, as a set,
    # the keys of a dict or a dict; a generator is consumed by the check, so its sum is 0; and a
    # weight that does not add to a float, such as a Decimal, raises the TypeError of the
    # addition, before the seed is converted.
    from pyspark.errors import PySparkValueError

    spark, service = mock_connect
    df = spark.range(10)

    def bounds(splits):
        # Relation.sample=12: lower_bound=2, upper_bound=3, of the plan of the last request.
        found = []
        for split in splits:
            split.collect()
            plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
            sample = parse_message(parse_message(plan)[12][0])
            found.append(tuple(sample.get(field, [b""])[0] for field in (2, 3)))
        return found

    expected = bounds(df.randomSplit([1.0, 3.0], 7))
    for weights in ({1.0: "x", 3.0: "y"}, {1.0: 0, 3.0: 0}.keys(), (1.0, 3.0),
                    np.array([1.0, 3.0])):
        assert bounds(df.randomSplit(weights, 7)) == expected
    assert len(df.randomSplit({2.0, 1.0}, 7)) == 2
    with pytest.raises(PySparkValueError) as error:
        df.randomSplit((w for w in [1.0, 3.0]), 7)
    assert error.value.getMessageParameters() == {"arg_name": "sum(weights)", "arg_value": "0"}
    with pytest.raises(TypeError, match="unsupported operand type.*'float' and 'decimal.Decimal'"):
        df.randomSplit([decimal.Decimal("0.5"), decimal.Decimal("0.5")], "not a seed")


def test_seeds_that_pyspark_cannot_send_are_refused_as_pyspark(mock_connect):
    # As PySpark Connect's: randomSplit and sample take int() of the seed, and an int out of the
    # range of a long is the ValueError of protobuf. sampleBy's StatSampleBy asserts an int, so
    # a float, a str or an np.int64 is a bare AssertionError, and a bool passes the assertion but
    # is refused by the proto, the TypeError of protobuf's default (upb) backend since protobuf
    # 7.34. Its checks of col and fractions come first.
    from pyspark.errors import PySparkTypeError

    spark, service = mock_connect
    df = spark.range(10)

    def split(seed):
        return df.randomSplit([1.0, 1.0], seed)

    def sample(seed):
        return df.sample(0.5, seed)

    def keyword_sample(seed):
        return df.sample(fraction=0.5, seed=seed)

    def positional_sample(seed):
        return df.sample(False, 0.5, seed)

    out_of_range = (
        (1e30, "1000000000000000019884624838656"),
        (2**63, "9223372036854775808"),
        (-(2**63) - 1, "-9223372036854775809"),
        (np.uint64(2**63), "9223372036854775808"),
    )
    # The seed is converted by int() at the call, and its range by protobuf as the plan is sent:
    # the plans of randomSplit and sample raise it at each of their actions.
    for call in (split, sample, keyword_sample, positional_sample):
        for seed, shown in out_of_range:
            plans = call(seed)
            for plan in plans if isinstance(plans, list) else [plans]:
                with pytest.raises(ValueError) as error:
                    plan.collect()
                assert type(error.value) is ValueError
                assert str(error.value) == f"Value out of range: {shown}"

    def sample_by(seed):
        return df.sampleBy("id", {0: 0.5}, seed)

    def stat_sample_by(seed):
        return df.stat.sampleBy("id", {0: 0.5}, seed)

    for call in (sample_by, stat_sample_by):
        for seed in (3.7, np.int64(3), "3"):
            with pytest.raises(AssertionError) as error:
                call(seed)
            assert type(error.value) is AssertionError
            assert str(error.value) == ""
        for seed in (True, False):
            with pytest.raises(TypeError) as error:
                call(seed).collect()
            assert str(error.value) == (
                "Field spark.connect.StatSampleBy.seed: Expected an int, got a boolean.")
        for seed, shown in out_of_range[1:3]:
            with pytest.raises(ValueError) as error:
                call(seed).collect()
            assert str(error.value) == f"Value out of range: {shown}"
    with pytest.raises(PySparkTypeError) as error:
        df.sampleBy(1, {0: 0.5}, 3.7)
    assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
    with pytest.raises(PySparkTypeError) as error:
        df.sampleBy("id", [0.5], 3.7)
    assert error.value.getCondition() == "NOT_EXPECTED_TYPE"

    # The bounds of a long are valid seeds, sent as they are, by Sample.seed=5 and
    # StatSampleBy.seed=5, of Relation.sample=12 and Relation.sample_by=107.
    def sent_seed(dataframe, field):
        dataframe.collect()
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
        return parse_message(parse_message(plan)[field][0])[5][0]

    assert sent_seed(df.sample(0.5, 2**63 - 1), 12) == 2**63 - 1
    assert sent_seed(df.sampleBy("id", {0: 1.0}, 2**63 - 1), 107) == 2**63 - 1
    assert len(df.randomSplit([1.0, 1.0], -(2**63))) == 2
    assert df.sample(0.5, -(2**63)) is not None
    assert df.sampleBy("id", {0: 1.0}, -(2**63)) is not None


def test_sample_by_seeds_of_int_subclasses_are_set_as_protobuf_does_as_pyspark(mock_connect):
    # As PySpark's StatSampleBy, which sets its seed, an int, in the long field of the proto:
    # protobuf's default (upb) backend takes the int of an int subclass, and the ValueError of
    # one out of the range of a long shows that int, not the str() of the subclass.
    from pyspark.sql import DataFrame

    spark, service = mock_connect
    df = spark.range(10)

    class Seed(int):
        def __str__(self):
            return "seed"

        __repr__ = __str__

    # The seed is sent, as the proto's long, as the plan is: its error is raised at each action.
    for call in (df.sampleBy, df.stat.sampleBy):
        for seed, shown in ((Seed(2**63), "9223372036854775808"),
                            (Seed(-(2**63) - 1), "-9223372036854775809")):
            plan = call("id", {0: 0.5}, seed)
            assert isinstance(plan, DataFrame)
            with pytest.raises(ValueError) as error:
                plan.collect()
            assert str(error.value) == f"Value out of range: {shown}"
    # Relation.sample_by=107 -> StatSampleBy.seed=5.
    df.sampleBy("id", {0: 1.0}, Seed(5)).collect()
    plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
    assert parse_message(parse_message(plan)[107][0])[5] == [5]


def test_with_metadata_and_pivot_refer_to_their_column_through_the_dataframe_as_pyspark(
        mock_connect):
    # As PySpark's withMetadata (self[columnName]) and pivot (self._df[pivot_col]): the column
    # is an UnresolvedAttribute with the plan ID of the DataFrame, which is that of its input.
    spark, service = mock_connect
    df = spark.range(2)

    def root(dataframe):
        dataframe.collect()
        # ExecutePlanRequest.plan=3, Plan.root=1.
        return parse_message(parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0])

    def attribute_and_input_plan_ids(input_relation, expression):
        # Relation.common=1, RelationCommon.plan_id=2; Expression.unresolved_attribute=2,
        # UnresolvedAttribute.plan_id=2.
        return (parse_message(parse_message(input_relation)[1][0])[2][0],
                parse_message(parse_message(expression)[2][0])[2][0])

    # Relation.with_columns=23: WithColumns.input=1, aliases=2; Alias.expr=1.
    with_columns = parse_message(root(df.withMetadata("id", {"a": "b"}))[23][0])
    alias = parse_message(with_columns[2][0])
    input_plan_id, attribute_plan_id = attribute_and_input_plan_ids(
        with_columns[1][0], alias[1][0])
    assert attribute_plan_id == input_plan_id

    # Relation.aggregate=9: Aggregate.input=1, pivot=5, Pivot.col=1.
    aggregate = parse_message(root(df.groupBy("id").pivot("id").count())[9][0])
    pivot = parse_message(aggregate[5][0])
    input_plan_id, attribute_plan_id = attribute_and_input_plan_ids(
        aggregate[1][0], pivot[1][0])
    assert attribute_plan_id == input_plan_id

    # And the column `*` of withMetadata, self["*"], is the star of the DataFrame:
    # Expression.unresolved_star=5, UnresolvedStar.plan_id=2.
    with_columns = parse_message(root(df.withMetadata("*", {"a": "b"}))[23][0])
    star = parse_message(parse_message(with_columns[2][0])[1][0])
    assert 2 not in star
    input_plan_id = parse_message(parse_message(with_columns[1][0])[1][0])[2][0]
    assert parse_message(star[5][0])[2] == [input_plan_id]


def test_ordinals_and_names_of_columns_carry_the_origin_of_col_as_pyspark():
    # As PySpark's, `df[ordinal]`, and the columns of sort and groupBy of an ordinal or a
    # name, are of `F.col`, whose origin they carry. In a new interpreter, whose first column
    # of a session reads spark.python.sql.dataFrameDebugging.enabled.
    import subprocess
    import sys
    from pathlib import Path

    pytest.importorskip("grpc")
    code = """
import sys
sys.path.insert(0, sys.argv[1])
from _mock_connect_server import mock_connect_session, parse_message

def fragment(expression):
    # Expression.common=18 -> ExpressionCommon.origin=1 -> Origin.python_origin=1 ->
    # PythonOrigin.fragment=1.
    expression = parse_message(expression)
    if 18 not in expression:
        return None
    common = parse_message(expression[18][0])
    return parse_message(parse_message(common[1][0])[1][0])[1][0].decode()

if __name__ == "__main__":
    with mock_connect_session() as (spark, service):
        df = spark.range(1)

        def relation(dataframe, field):
            # ExecutePlanRequest.plan=3, Plan.root=1.
            dataframe.collect()
            plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
            return parse_message(parse_message(plan)[field][0])

        # Relation.project=3: Project.expressions=3.
        found = [fragment(relation(df.select(df[0]), 3)[3][0])]
        # Relation.sort=7: Sort.order=2, SortOrder.child=1.
        for sorted_df in (df.sort(1), df.sort(-1), df.sort("id")):
            found.append(fragment(parse_message(relation(sorted_df, 7)[2][0])[1][0]))
        # Relation.aggregate=9: Aggregate.grouping_expressions=3.
        for grouped in (df.groupBy(1), df.groupBy("id")):
            found.append(fragment(relation(grouped.count(), 9)[3][0]))
        print(found)
"""
    tests = str(Path(__file__).resolve().parent)
    result = subprocess.run(
        [sys.executable, "-c", code, tests], check=True, capture_output=True, text=True)
    assert result.stdout.strip().splitlines()[-1] == str(["col"] * 6)


def test_aggregates_range_partitions_and_join_conditions_carry_pysparks_origins():
    # As PySpark's: count of grouped data is the `alias` of its count, whose count and literal
    # have no origin; sum, avg, mean, min and max, and agg of a dict, give each column to
    # `F.col`, and their functions have no origin; repartitionByRange sorts a column by its
    # `asc`, whose sort order is of `asc_nulls_first`; and the plans of join and _joinAsOf of a
    # list of Columns reduce them with `&` each time they are built, so their `and`s are of
    # `__and__` at the call site of the request, not of the join, also of a deep copy, as
    # PySpark's copy of the plan objects builds them at each request too. In a new interpreter,
    # whose first column of a session reads spark.python.sql.dataFrameDebugging.enabled.
    import subprocess
    import sys
    from pathlib import Path

    pytest.importorskip("grpc")
    code = """
import sys
sys.path.insert(0, sys.argv[1])
from _mock_connect_server import mock_connect_session
from pyspark.sql.connect import proto

def origin(expression):
    # The fragment of the python_origin of the expression, and the line of its call site.
    if not expression.HasField("common"):
        return None
    python_origin = expression.common.origin.python_origin
    return python_origin.fragment, int(python_origin.call_site.rsplit(":", 1)[1])

def arguments(expression):
    return [origin(argument) for argument in expression.unresolved_function.arguments]

if __name__ == "__main__":
    with mock_connect_session() as (spark, service):
        df = spark.range(1)

        def root(dataframe):
            dataframe.collect()
            return proto.ExecutePlanRequest.FromString(service.execute_requests[-1]).plan.root

        found = []
        for grouped in (df.groupBy("id").count(), df.groupBy("id").pivot("id", [0]).count()):
            found.append([origin(e) for e in root(grouped).aggregate.aggregate_expressions])
        for function in ("sum", "avg", "mean", "min", "max"):
            for columns in ((), ("id",)):
                aggregate = root(getattr(df.groupBy("id"), function)(*columns)).aggregate
                (expression,) = aggregate.aggregate_expressions
                found.append((origin(expression), arguments(expression)))
        (expression,) = root(df.groupBy("id").agg({"id": "max"})).aggregate.aggregate_expressions
        found.append((origin(expression), arguments(expression)))
        repartitioned = root(df.repartitionByRange(2, "id", df.id.desc()))
        found.append([origin(e) for e in repartitioned.repartition_by_expression.partition_exprs])
        joined = df.join(df, [df.id == df.id, df.id == df.id, df.id == df.id])
        condition = root(joined).join.join_condition
        found.append((origin(condition), arguments(condition)))
        condition = root(df._joinAsOf(df, "id", "id", on=[df.id == df.id, df.id == df.id]))
        condition = condition.as_of_join.join_expr
        found.append((origin(condition), arguments(condition)))
        condition = root(__import__("copy").deepcopy(joined)).join.join_condition
        found.append((origin(condition), arguments(condition)))
        print(found)
"""
    tests = str(Path(__file__).resolve().parent)
    result = subprocess.run(
        [sys.executable, "-c", code, tests], check=True, capture_output=True, text=True)
    # The lines of the code above, as PySpark gives them for it: the requests are built at line
    # 22, in `root`, so the `and`s of a join are of that line, and not of the line of the join.
    assert result.stdout.strip().splitlines()[-1] == str([
        [("alias", 26)], [("alias", 26)], *[(None, [("col", 30)])] * 10, (None, [("col", 33)]),
        [("asc_nulls_first", 35), ("desc_nulls_last", 35)],
        (("__and__", 22), [("__and__", 22), ("__eq__", 37)]),
        (("__and__", 22), [("__eq__", 40), ("__eq__", 40)]),
        (("__and__", 22), [("__and__", 22), ("__eq__", 37)]),
    ])


def test_zip_with_index_and_to_json_carry_the_origins_of_their_columns_as_pyspark():
    # As PySpark's zipWithIndex, `self.select(F.col("*"),
    # F._invoke_function("distributed_sequence_id").alias(indexColName))`, and toJSON,
    # `self.select(F.to_json(F.struct(F.col("*"))).alias("value"))`: their star is of `col`, and
    # the alias of `alias`, at the call site, and their functions have no origin. In a new
    # interpreter, whose first column of a session reads
    # spark.python.sql.dataFrameDebugging.enabled.
    import subprocess
    import sys
    from pathlib import Path

    pytest.importorskip("grpc")
    code = """
import sys
sys.path.insert(0, sys.argv[1])
from _mock_connect_server import mock_connect_session
from pyspark.sql.connect import proto

def origin(expression):
    # The fragment of the python_origin of the expression, and the line of its call site.
    if not expression.HasField("common"):
        return None
    python_origin = expression.common.origin.python_origin
    return python_origin.fragment, int(python_origin.call_site.rsplit(":", 1)[1])

if __name__ == "__main__":
    with mock_connect_session() as (spark, service):
        df = spark.range(1)

        def root(dataframe):
            dataframe.collect()
            return proto.ExecutePlanRequest.FromString(service.execute_requests[-1]).plan.root

        star, index = root(df.zipWithIndex("i")).project.expressions
        found = [origin(star), origin(index), origin(index.alias.expr)]
        (value,) = root(df.toJSON()).project.expressions
        to_json = value.alias.expr
        (struct,) = to_json.unresolved_function.arguments
        (star,) = struct.unresolved_function.arguments
        found += [origin(value), origin(to_json), origin(struct), origin(star)]
        print(found)
"""
    tests = str(Path(__file__).resolve().parent)
    result = subprocess.run(
        [sys.executable, "-c", code, tests], check=True, capture_output=True, text=True)
    # The lines of the calls of zipWithIndex and toJSON in the code above.
    assert result.stdout.strip().splitlines()[-1] == str([
        ("col", 22), ("alias", 22), None, ("alias", 24), None, None, ("col", 24)])


def test_join_as_of_sends_the_as_of_join_as_pyspark(mock_connect):
    # As PySpark's plan.AsOfJoin: Relation.as_of_join=39, with left=1, right=2, left_as_of=3,
    # right_as_of=4, join_expr=5, using_columns=6, join_type=7, tolerance=8,
    # allow_exact_matches=9 and direction=10. The as-of columns are the columns of their
    # DataFrames, and `on` is a condition, or names when it is a name or a list of names.
    from pyspark.sql import DataFrame
    from pyspark.sql import functions as F

    spark, service = mock_connect
    left, right = spark.range(2), spark.range(3)

    def sent_as_of_join(joined):
        joined.collect()
        # ExecutePlanRequest.plan=3, Plan.root=1, Relation.as_of_join=39.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
        return parse_message(parse_message(plan)[39][0])

    def attribute(expression):
        # Expression.unresolved_attribute=2, UnresolvedAttribute.unparsed_identifier=1.
        return parse_message(parse_message(expression)[2][0])[1][0].decode()

    join = sent_as_of_join(left._joinAsOf(
        right, "id", "id", on=["id"], how="left", tolerance=F.lit(1),
        allowExactMatches=False, direction="forward"))
    assert attribute(join[3][0]) == "id" and attribute(join[4][0]) == "id"
    assert 1 in join and 2 in join and 5 not in join and join[6] == [b"id"]
    assert join[7] == [b"left"] and 8 in join
    assert join.get(9, [0]) == [0] and join[10] == [b"forward"]

    join = sent_as_of_join(left._joinAsOf(right, "id", "id"))
    assert 5 not in join and 6 not in join and 8 not in join
    assert join[7] == [b"inner"] and join[9] == [1] and join[10] == [b"backward"]

    join = sent_as_of_join(left._joinAsOf(
        right, left.id, right.id, on=left.id == right.id, how="left"))
    assert attribute(join[3][0]) == "id" and 5 in join and 6 not in join
    assert join[7] == [b"left"] and join[10] == [b"backward"]

    # As PySpark, which checks neither `how` nor `direction` but that `how` is a string: each
    # is sent as it is. The server reads the names, and other spellings of them, and refuses
    # the rest in the analysis.
    for how in ("inner", "left", "LEFT", "left_outer", "leftouter", "right", "sideways", ""):
        for direction in ("backward", "forward", "nearest", "Forward", "sideways", ""):
            join = sent_as_of_join(left._joinAsOf(
                right, "id", "id", how=how, direction=direction))
            # An empty string is the default of its field, which is not sent.
            assert join.get(7, [b""]) == [how.encode()]
            assert join.get(10, [b""]) == [direction.encode()]
    join = sent_as_of_join(left._joinAsOf(right, "id", "id", how=None))
    assert join[7] == [b"inner"]
    for how in (1, ["left"], b"left"):
        with pytest.raises(AssertionError, match="^how should be a string$"):
            left._joinAsOf(right, "id", "id", how=how)

    # PySpark sends `how`, `allowExactMatches` and `direction` in the plan, which raises the errors
    # of their protobuf fields when it is sent, as the errors of protobuf's default upb backend;
    # the as-of join raises them at each action. A str that UTF-8 cannot encode is a str to the
    # assert of `how`, and the UnicodeEncodeError of its encoding; a `direction` of bytes is decoded
    # as UTF-8, and any other value is upb's TypeError.
    for kwargs in ({"how": "a\ud800"}, {"direction": "a\ud800"}):
        plan = left._joinAsOf(right, "id", "id", **kwargs)
        assert isinstance(plan, DataFrame)
        with pytest.raises(UnicodeEncodeError) as e:
            plan.collect()
        assert str(e.value) == (
            "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed"
        )
    join = sent_as_of_join(left._joinAsOf(right, "id", "id", direction=b"forward"))
    assert join[10] == [b"forward"]
    plan = left._joinAsOf(right, "id", "id", direction=b"\xff")
    with pytest.raises(UnicodeDecodeError) as e:
        plan.collect()
    assert str(e.value) == "'utf-8' codec can't decode byte 0xff in position 0: invalid start byte"
    for direction in (1, None):
        plan = left._joinAsOf(right, "id", "id", direction=direction)
        with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
            plan.collect()
        with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
            plan.columns
    # allowExactMatches is a protobuf bool: an int is taken as its truth, and any other value that
    # is not an int raises the TypeError of the conversion at each action, as protobuf does.
    assert sent_as_of_join(left._joinAsOf(right, "id", "id", allowExactMatches=1))[9] == [1]
    join = sent_as_of_join(left._joinAsOf(right, "id", "id", allowExactMatches=0))
    assert join.get(9, [0]) == [0]
    for allow, message in (
        (None, "'NoneType' object cannot be interpreted as an integer"),
        ("yes", "'str' object cannot be interpreted as an integer"),
        (2**70, "Python int too large to convert to C long"),
    ):
        plan = left._joinAsOf(right, "id", "id", allowExactMatches=allow)
        with pytest.raises((TypeError, OverflowError)) as e:
            plan.collect()
        assert str(e.value) == message


def test_grouping_sets_group_by_their_grouping_columns_as_pyspark(mock_connect):
    # As PySpark's, groupingSets(groupingSets, *cols) groups by the sets with the grouping
    # columns `cols`: Relation.aggregate=9, Aggregate.group_type=2 (GROUPING_SETS=5),
    # grouping_expressions=3, grouping_sets=6 (GroupingSets.grouping_set=1).
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import functions as F

    spark, service = mock_connect
    df = spark.range(1)

    def column_names(expressions):
        # Expression.unresolved_attribute=2, UnresolvedAttribute.unparsed_identifier=1.
        return [parse_message(parse_message(e)[2][0])[1][0].decode() for e in expressions]

    def sent(grouped):
        grouped.agg(F.count("*")).collect()
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
        aggregate = parse_message(parse_message(plan)[9][0])
        sets = [column_names(parse_message(s).get(1, [])) for s in aggregate.get(6, [])]
        return aggregate[2], column_names(aggregate.get(3, [])), sets

    assert sent(df.groupingSets([["id"], []], "id", F.col("x"))) == (
        [5], ["id", "x"], [["id"], []])
    # No grouping columns, and a set of one column given alone.
    assert sent(df.groupingSets(["id", ("x", 1)])) == ([5], [], [["id"], ["x", "id"]])
    for call, arg_name, arg_type in (
        (lambda: df.groupingSets([["id"]], ["id"]), "cols", "list"),
        (lambda: df.groupingSets([[["id"]]]), "groupingSets", "list"),
        (lambda: df.groupingSets([1.5]), "groupingSets", "float"),
    ):
        with pytest.raises(PySparkTypeError) as error:
            call()
        assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
        assert error.value.getMessageParameters() == {
            "expected_type": "Column, int or str", "arg_name": arg_name, "arg_type": arg_type}


