def test_create_dataframe_of_a_numpy_array_as_pyspark(mock_connect):
    # As PySpark Connect's: an Arrow table of a column of each column of a 1- or 2-dimensional
    # array, named by the names, else `value` for one column, else `_1`, `_2`, ..., sent with
    # the schema, if any, for the server to cast to.
    import numpy as np
    import pyarrow as pa
    from pyspark.errors import PySparkValueError

    spark, service = mock_connect

    def sent(df):
        df.columns
        # Relation.local_relation=11: data=1, an Arrow IPC stream, and schema=2.
        relation = _sent_relation(service.analyze_requests[-1], 11)
        table = pa.ipc.open_stream(relation[1][0]).read_all()
        return table.to_pydict(), [json.loads(s) for s in relation.get(2, [])]

    assert sent(spark.createDataFrame(np.array([1, 2]))) == ({"value": [1, 2]}, [])
    assert sent(spark.createDataFrame(np.array([[1, 2], [3, 4]]))) == (
        {"_1": [1, 3], "_2": [2, 4]}, [])
    assert sent(spark.createDataFrame(np.array([[1], [2]]), ("x",))) == ({"x": [1, 2]}, [])
    schema = T.StructType().add("a", T.IntegerType()).add("b", T.StringType())
    assert sent(spark.createDataFrame(np.array([[1, 2]]), schema)) == (
        {"_1": [1], "_2": [2]}, [json.loads(schema.json())])
    assert sent(spark.createDataFrame(np.array([1.5]), T.DoubleType())) == (
        {"value": [1.5]}, ["double"])
    for data, schema, expected, actual in [
        (np.array([1, 2]), ["x", "y"], "2", "1"),
        (np.array([1, 2]), [], "0", "1"),
        (np.array([[1, 2]]), ["x"], "1", "2"),
        (np.array([[1, 2]]), T.IntegerType(), "1", "2"),
        (np.array([1, 2]), T.StructType().add("a", T.IntegerType()).add("b", T.LongType()),
         "2", "1"),
    ]:
        with pytest.raises(PySparkValueError) as e:
            spark.createDataFrame(data, schema)
        assert e.value.getCondition() == "AXIS_LENGTH_MISMATCH"
        assert e.value.getMessageParameters() == {
            "expected_length": expected, "actual_length": actual}
    for data in (np.zeros((2, 2, 2)), np.array(5)):
        with pytest.raises(PySparkValueError) as e:
            spark.createDataFrame(data)
        assert e.value.getCondition() == "INVALID_NDARRAY_DIMENSION"
        assert e.value.getMessageParameters() == {"dimensions": "1 or 2"}
    with pytest.raises(PySparkValueError) as e:
        spark.createDataFrame(np.array([]))
    assert e.value.getCondition() == "CANNOT_INFER_EMPTY_SCHEMA"


@pytest.mark.parametrize(
    "labels", ["datetime", "timedelta", "period", "interval", "multi_datetime"])
@pytest.mark.parametrize("cells, arrow_type, values", [
    # A mixed int and float column is a double, as PySpark infers it, not a row error.
    ("int_float", lambda pa: pa.float64(), [1.0, 2.5]),
    # A naive datetime of a list is a timestamp_ntz, not a time of the session time zone.
    ("naive_list", lambda pa: pa.list_(pa.timestamp("us")),
     [[datetime.datetime(2020, 1, 2, 3)], None]),
    # A dict is a struct of the value types of its keys, mixed or not, and not a map.
    ("dict", lambda pa: pa.struct([("u", pa.int64()), ("v", pa.string())]),
     [{"u": 1, "v": "a"}, None]),
    # A NaN in a list is a null, as PySpark has it.
    ("nan_list", lambda pa: pa.list_(pa.float64()), [[1.0, None], None]),
    # A NumPy int32 is an int, as PySpark infers it.
    ("np_int32", lambda pa: pa.int32(), [1, 2]),
])
def test_datetimelike_labels_convert_cells_as_pyspark(
    mock_connect, labels, cells, arrow_type, values
):
    # A plain frame whose labels are a DatetimeIndex, TimedeltaIndex, PeriodIndex or IntervalIndex
    # (or a MultiIndex with a DatetimeIndex level) converts with Arrow, as one with default labels:
    # its cells take the types that PySpark infers.
    import numpy as np
    import pyarrow as pa

    pd = pytest.importorskip("pandas")
    column = {
        "int_float": [1, 2.5],
        "naive_list": [[datetime.datetime(2020, 1, 2, 3)], None],
        "dict": [{"u": 1, "v": "a"}, None],
        "nan_list": [[1.0, float("nan")], None],
        "np_int32": [np.int32(1), np.int32(2)],
    }[cells]
    columns = {
        "datetime": pd.DatetimeIndex(["2020-01-01"]),
        "timedelta": pd.TimedeltaIndex(["1s"]),
        "period": pd.period_range("2020-01", periods=1, freq="M"),
        "interval": pd.interval_range(0, 1),
        "multi_datetime": pd.MultiIndex.from_tuples([(pd.Timestamp("2020-01-01"), "x")]),
    }[labels]
    data = pd.DataFrame({0: pd.Series(column, dtype=object)})
    data.columns = columns
    table = _native_number_input_table(mock_connect, data)
    assert table.num_columns == 1
    assert table.schema.field(0).type == arrow_type(pa)
    assert table.column(0).to_pylist() == values


@pytest.mark.parametrize("labels", [
    "Int64", "Float64", "boolean", "int64[pyarrow]", "timestamp[pyarrow]", "multi_Int64",
    "categorical_Int64"])
@pytest.mark.parametrize("cells, arrow_type, values", [
    ("int_float", lambda pa: pa.float64(), [1.0, 2.5]),
    ("naive_list", lambda pa: pa.list_(pa.timestamp("us")),
     [[datetime.datetime(2020, 1, 2, 3)], None]),
    ("dict", lambda pa: pa.struct([("u", pa.int64()), ("v", pa.string())]),
     [{"u": 1, "v": "a"}, None]),
    ("nan_list", lambda pa: pa.list_(pa.float64()), [[1.0, None], None]),
    ("np_int32", lambda pa: pa.int32(), [1, 2]),
])
def test_nullable_and_arrow_labels_convert_cells_as_pyspark(
    mock_connect, labels, cells, arrow_type, values
):
    # A plain frame whose labels are an Index of pandas' nullable or Arrow dtypes (a pivot or `.T`
    # of `convert_dtypes()` or Arrow-backed data), or a MultiIndex level or CategoricalIndex of
    # them, converts with Arrow as one with default labels: its cells take the types that PySpark
    # infers, as for the datetime-like labels above.
    import numpy as np
    import pyarrow as pa

    pd = pytest.importorskip("pandas")
    column = {
        "int_float": [1, 2.5],
        "naive_list": [[datetime.datetime(2020, 1, 2, 3)], None],
        "dict": [{"u": 1, "v": "a"}, None],
        "nan_list": [[1.0, float("nan")], None],
        "np_int32": [np.int32(1), np.int32(2)],
    }[cells]
    columns = {
        "Int64": pd.Index(pd.array([1], dtype="Int64")),
        "Float64": pd.Index(pd.array([1.5], dtype="Float64")),
        "boolean": pd.Index(pd.array([True], dtype="boolean")),
        "int64[pyarrow]": pd.Index(pd.array([1], dtype="int64[pyarrow]")),
        "timestamp[pyarrow]": pd.Index(pd.array([pd.Timestamp("2020-01-01")],
                                                dtype="timestamp[us][pyarrow]")),
        "multi_Int64": pd.MultiIndex.from_arrays([pd.array([1], dtype="Int64"), ["x"]]),
        "categorical_Int64": pd.CategoricalIndex(pd.array([1], dtype="Int64")),
    }[labels]
    data = pd.DataFrame({0: pd.Series(column, dtype=object)})
    data.columns = columns
    table = _native_number_input_table(mock_connect, data)
    assert table.num_columns == 1
    assert table.schema.field(0).type == arrow_type(pa)
    assert table.column(0).to_pylist() == values


def test_label_arrays_with_a_hook_of_their_own_decline_the_fast_paths():
    # The fast paths read the labels without running user code: a nullable or Arrow label array
    # whose instance shadows a hook that reading the labels reaches is declined, and the frame
    # takes PySpark's conversion, which reads the labels as PySpark does.
    pd = pytest.importorskip("pandas")
    pytest.importorskip("pyarrow")
    from pyspark.sql._pandas_input import _has_canonical_columns

    for dtype in ("Int64", "boolean", "int64[pyarrow]"):
        index = pd.Index(pd.array([1, 0], dtype=dtype))
        assert _has_canonical_columns(index), dtype
        vars(index)["_data"].__dict__["__iter__"] = lambda: iter(["shadowed"])
        assert not _has_canonical_columns(index), dtype


def test_catalog_function_class_name_is_none_without_a_class_as_pyspark(mock_connect):
    import pyarrow as pa

    spark, service = mock_connect
    # As PySpark's, a function whose className is null (a builtin such as `!=`) has None for
    # it, not an empty string. The mock answers with the rows of the catalog's Function.
    table = pa.table({
        "name": ["!=", "abs"], "catalog": [None, None], "namespace": [None, None],
        "description": ["d1", "d2"], "className": [None, "org.a.Abs"],
        "isTemporary": [True, True]})
    sink = pa.BufferOutputStream()
    with pa.ipc.new_stream(sink, table.schema) as writer:
        writer.write_table(table)
    # ExecutePlanResponse.arrow_batch=2: ArrowBatch.row_count=1, data=2.
    service.execute_payload = message_field(2, varint_field(1, table.num_rows) + message_field(
        2, sink.getvalue().to_pybytes()))
    functions = spark.catalog.listFunctions()
    assert [(f.name, f.className) for f in functions] == [("!=", None), ("abs", "org.a.Abs")]


