def test_create_dataframe_converts_numpy_scalars_as_pyarrow(mock_connect):
    import re

    np = pytest.importorskip("numpy")
    # As PySpark, where PyArrow takes a NumPy scalar as the Python value that it stands for:
    # an integer, a float (truncated for an integer type) and a bool (also for an integer).
    assert _is_local_created(
        mock_connect,
        [(np.int64(1), np.float32(0.5), np.bool_(True), np.float32(1.5), np.bool_(True))],
        "a bigint, b double, c boolean, d bigint, e bigint")
    for value, schema, message in [
        (np.bool_(True), "a double",
         r"Could not convert \S+ with type numpy\.bool_?: tried to convert to double"),
        (np.int64(1), "a boolean",
         r"Could not convert \S+ with type numpy\.int64: tried to convert to boolean"),
        (np.int32(300), "a tinyint", re.escape("Value 300 too large to fit in C integer type")),
        # An integer that a float type cannot hold exactly.
        (2**53 + 1, "a double", re.escape(
            "Integer value 9007199254740993 is outside of the range exactly representable by "
            "a IEEE 754 double precision value")),
        (2**24 + 1, "a float", re.escape(
            "Integer value 16777217 is outside of the range exactly representable by "
            "a IEEE 754 single precision value")),
    ]:
        with pytest.raises(ValueError, match=message):
            _local_create_dataframe([(value,)], schema, session=mock_connect[0])


def test_a_subquery_of_a_deep_plan_is_sent_or_raises_recursion_error_as_pyspark(mock_connect):
    # As PySpark, which sends a subquery under the plan that has it, so that its levels add to
    # those above it: one within the bound is sent (it overflowed the stack of the serializing
    # thread before), and a deeper one raises RecursionError without a request.
    spark, service = mock_connect

    def limited(df, levels):
        for _ in range(levels):
            df = df.limit(100)
        return df

    limited(spark.range(10).filter(limited(spark.range(1), 300).exists()), 33).collect()
    assert len(service.execute_requests) == 1
    with pytest.raises(RecursionError, match="the plans of its subqueries"):
        spark.range(10).filter(limited(spark.range(1), 800).exists()).collect()
    assert len(service.execute_requests) == 1


def test_a_plan_too_deep_to_send_raises_recursion_error_without_a_request(mock_connect):
    # As PySpark, whose client raises RecursionError while it builds the proto of a plan a few
    # hundred levels deep, before any request, rather than overflowing the native stack.
    from pyspark.sql import functions as F

    spark, service = mock_connect
    df = spark.range(10)
    for _ in range(10_000):
        df = df.filter(F.col("id") >= 0)
    for action in [df.count, df.collect, lambda: df.schema, df.explain]:
        with pytest.raises(RecursionError, match="a plan of 1000[12] levels"):
            action()
    assert service.execute_requests == []
    assert service.analyze_requests == []


def test_a_plan_of_256_levels_is_sent_from_a_thread_with_a_small_stack(mock_connect):
    # Each clone of a request recurses once per level of its plan, on the thread that sends it:
    # on a Python thread of 512 KiB, a plan of 256 levels overflowed the stack (SIGBUS) in the
    # clone. The thread runs in a subprocess, since the crash would end this one.
    import subprocess
    import sys

    _, service = mock_connect
    script = """
import threading
from pyspark.sql import SparkSession, functions as F
spark = SparkSession.builder.remote(REMOTE_URL).getOrCreate()

def work():
    df = spark.range(10)
    for x in range(255):
        df = df.withColumn(f"col{x}", F.lit(x))
    df.schema
    print("analyzed", flush=True)
    df.collect()
    print("collected", flush=True)

threading.stack_size(512 * 1024)
thread = threading.Thread(target=work)
thread.start()
thread.join()
# Closed without a release: the exit would send its clean_cache, which the count of
# requests below does not expect.
spark.release_session_on_close = False
spark.stop()
""".replace("REMOTE_URL", repr(service.remote))
    result = subprocess.run(
        [sys.executable, "-c", script], env=dict(os.environ, TZ="UTC"),
        capture_output=True, text=True, timeout=300)
    assert result.returncode == 0, result.stderr
    assert "analyzed" in result.stdout, result.stdout
    assert "collected" in result.stdout, result.stdout
    assert len(service.analyze_requests) == 1
    assert len(service.execute_requests) == 1


def test_an_expression_of_200_additions_is_sent_from_a_thread_with_a_small_stack(mock_connect):
    # As the plan above, for an expression: its clone recurses once per level, on a Python
    # thread of 512 KiB, which overflowed the stack (SIGBUS). The thread runs in a subprocess.
    import subprocess
    import sys

    _, service = mock_connect
    script = """
import threading
from pyspark.sql import SparkSession, functions as F
spark = SparkSession.builder.remote(REMOTE_URL).getOrCreate()

def work():
    c = F.col("id")
    for _ in range(200):
        c = c + 1
    df = spark.range(1).select(c.alias("x"))
    df.schema
    print("analyzed", flush=True)

threading.stack_size(512 * 1024)
thread = threading.Thread(target=work)
thread.start()
thread.join()
""".replace("REMOTE_URL", repr(service.remote))
    result = subprocess.run(
        [sys.executable, "-c", script], env=dict(os.environ, TZ="UTC"),
        capture_output=True, text=True, timeout=300)
    assert result.returncode == 0, result.stderr
    assert "analyzed" in result.stdout, result.stdout
    assert len(service.analyze_requests) == 1


def test_a_plan_over_a_deep_expression_is_analyzed_from_a_thread_with_a_small_stack(mock_connect):
    # The levels of a plan and the additions of an expression under it are one request: 300
    # levels over a column of 700 additions overflowed the stack of the analyzing thread (SIGBUS),
    # though each part is within its bound. The server sets the plan compression that a real one
    # does, whose encoded size is measured on the thread of the call.
    import subprocess
    import sys

    _, service = mock_connect
    service.confs = _plan_confs(str(10 << 20))
    script = """
import threading
from pyspark.sql import SparkSession, functions as F
spark = SparkSession.builder.remote(REMOTE_URL).getOrCreate()

def work():
    c = F.col("id")
    for _ in range(700):
        c = c + 1
    df = spark.range(1).withColumn("deep", c)
    for x in range(300):
        df = df.withColumn(f"col{x}", F.lit(x))
    print("schema", len(df.schema.fields), flush=True)
    print("dtypes", len(df.dtypes), flush=True)
    print("streaming", df.isStreaming, flush=True)
    df.explain()
    print("explained", flush=True)

threading.stack_size(512 * 1024)
thread = threading.Thread(target=work)
thread.start()
thread.join()
""".replace("REMOTE_URL", repr(service.remote))
    result = subprocess.run(
        [sys.executable, "-c", script], env=dict(os.environ, TZ="UTC"),
        capture_output=True, text=True, timeout=300)
    assert result.returncode == 0, result.stderr
    assert "schema 1" in result.stdout, result.stdout
    assert "explained" in result.stdout, result.stdout
    # dtypes reads the schema that schema analyzed, so three requests are analyzed.
    assert len(service.analyze_requests) == 3


def test_create_dataframe_raises_recursion_error_for_a_value_that_contains_itself(mock_connect):
    class Node:
        def __init__(self):
            self.parent = self

    cyclic = []
    cyclic.append(cyclic)
    # As PySpark, rather than overflowing the stack.
    for value in [Node(), cyclic]:
        with pytest.raises(RecursionError):
            _local_create_dataframe([(value,)], session=mock_connect[0])


# py_to_value converts the object cells of the pandas row path, which createDataFrame takes
# without PyArrow, plus fillna and pivot values; local rows use infer.convert. The "local"
# source below is a control for values that the exact-number fast path must not change.
@contextlib.contextmanager
def _pandas_row_path():
    """Meanwhile, createDataFrame converts pandas frames with its row path (py_to_value), as it
    does without PyArrow; with it, it converts every frame with PySpark's Arrow conversion."""
    import importlib

    # The module of the native binding, which earlier import-hook tests can leave another object
    # than the attribute of the package.
    helper = importlib.import_module("pyspark.sql._pandas_input")
    available = helper.pyarrow_available
    helper.pyarrow_available = lambda: False
    try:
        yield
    finally:
        helper.pyarrow_available = available


@pytest.fixture
def pandas_row_path():
    """The row path of pandas frames for the test (`_pandas_row_path`)."""
    with _pandas_row_path():
        yield


def _CustomizedFrame(pd):
    """A subclass of pandas.DataFrame, which createDataFrame converts with PySpark's Arrow
    conversion, as it converts a plain one: PySpark converts every pandas DataFrame so."""
    return type("CustomizedFrame", (pd.DataFrame,), {})


def _native_number_input_table(mock_connect, data, schema=None, *, source="local", named=False):
    """The Arrow table of the local relation of `createDataFrame(data, schema)`; `named`, of the
    names of the DataFrame, which PySpark's conversion of a pandas frame without a schema applies
    with toDF to its columns `_0`, `_1`, .... Of the "pandas" source, the values of the rows
    `data` are the object column `value` of a frame on the row path (`_pandas_row_path`)."""
    import pyarrow as pa

    spark, service = mock_connect
    if source == "pandas":
        pd = pytest.importorskip("pandas")
        data = pd.DataFrame({"value": [row[0] for row in data]}, dtype=object)
        with _pandas_row_path():
            df = spark.createDataFrame(data, schema)
    else:
        df = spark.createDataFrame(data, schema)
    df.toArrow()
    request = parse_message(service.execute_requests[-1])
    relation = parse_message(parse_message(request[3][0])[1][0])
    names = None
    while 18 in relation:  # Relation.to_df -> ToDF.input; column_names=2.
        rename = parse_message(relation[18][0])
        if names is None:
            names = [name.decode() for name in rename.get(2, [])]
        relation = parse_message(rename[1][0])
    local = parse_message(relation[11][0])
    table = pa.ipc.open_stream(local[1][0]).read_all()
    return table.rename_columns(names) if named and names else table


def _third_party_integer_array(pd, values):
    """An extension array of a class of a module outside pandas, as of a library such as
    BigQuery's `db_dtypes`, made of pandas' IntegerArray."""
    cls = type("ThirdPartyIntegerArray", (pd.arrays.IntegerArray,), {"__module__": __name__})
    return cls(np.array(values, dtype="int64"), np.zeros(len(values), dtype=bool))


@pytest.mark.parametrize("host", ["UTC", "America/Los_Angeles"])
@pytest.mark.parametrize("kind", ["subclass", "third-party array"])
@pytest.mark.parametrize("schema", [None, "t timestamp, id long"])
def test_customized_pandas_frames_take_the_session_time_zone_as_pyspark(
    mock_connect, monkeypatch, host, kind, schema
):
    # As PySpark, which converts every pandas DataFrame, of any class and any arrays, with its
    # conversion of each column to Arrow, which takes a naive datetime64 column as times of the
    # session time zone, whatever the zone of the host. Official, of a UTC or a Los Angeles host
    # and the session zone America/Los_Angeles: the instant 2021-06-01 19:00 UTC.
    from datetime import datetime, timezone

    if not hasattr(time, "tzset"):
        pytest.skip("client timezone control requires time.tzset")
    pd = pytest.importorskip("pandas")
    _, service = mock_connect
    service.confs = {"spark.sql.session.timeZone": "America/Los_Angeles"}
    times = pd.to_datetime(["2021-06-01 12:00:00"])
    if kind == "subclass":
        frame = _CustomizedFrame(pd)({"t": times, "id": [1]})
    else:
        frame = pd.DataFrame({"t": times, "id": pd.Series(_third_party_integer_array(pd, [1]))})
        assert type(frame["id"].array).__module__ == __name__
    try:
        with monkeypatch.context() as environment:
            environment.setenv("TZ", host)
            time.tzset()
            table = _native_number_input_table(mock_connect, frame, schema, named=True)
    finally:
        time.tzset()
    assert table.column("t").to_pylist() == [datetime(2021, 6, 1, 19, tzinfo=timezone.utc)]
    assert table.column("id").to_pylist() == [1]


@pytest.mark.parametrize("schema", [None, ["renamed"]])
@pytest.mark.parametrize("values, expected", [
    ([Row()], [[]]),
    ([Row(a=1, b=2), None, Row(a=3, b=None)], [[1, 2], None, [3, None]]),
    ([Row("a", "b")(1), Row("a", "b")(2)], [[1], [2]]),
    ([Row(a=None, b=None), Row(a=1, b=2)], [[None, None], [1, 2]]),
    ([Row(a=1, b=2), Row(a=1.5, b=2.5)], [[1.0, 2.0], [1.5, 2.5]]),
    ([Row(a=Row(x=1, y=2), b=Row(x=3, y=None))], [[[1, 2], [3, None]]]),
    ([[Row(x=1, y=2), Row(x=3, y=4)]], [[[1, 2], [3, 4]]]),
    ([{"child": Row(x=1, y=2)}], [{"child": [1, 2]}]),
])
def test_customized_pandas_named_rows_are_inferred_as_arrays(
    mock_connect, schema, values, expected
):
    # Official pandas inference sends the whole object column to Arrow without a Spark
    # type. Row field names do not participate, including for nested and short Rows.
    import pyarrow as pa

    pd = pytest.importorskip("pandas")
    frame = _CustomizedFrame(pd)({"value": values}, dtype=object)
    actual = _native_number_input_table(mock_connect, frame, schema).column(0).combine_chunks()
    wanted = pa.array(expected, from_pandas=True)
    assert actual.equals(wanted)


