def test_decimal_missing_c_accelerator_is_cached_and_keeps_hooks(decimal_ipc_protocol, tmp_path):
    # The extension's type cache belongs to the process, so reset decimal's modules and
    # hide the accelerator before importing pyspark. Count only conversion lookups.
    pytest.importorskip("pandas")
    import subprocess
    import sys

    script = r'''
import sys
# Exercise startup hooks that preload decimal before configuring the fallback.
import decimal
sys.modules.pop("decimal", None)
sys.modules.pop("_pydecimal", None)
sys.modules["_decimal"] = None
import decimal
import _pydecimal
assert decimal.Decimal is _pydecimal.Decimal
import builtins
import contextlib
from pathlib import Path
import subprocess
import pandas as pd
import pyarrow as pa
import pytest
from pyspark.sql import SparkSession
from pyspark.sql import _pandas_input
from pyspark.sql import types as T

# The row path of pandas frames, which createDataFrame takes without PyArrow.
_pandas_input.pyarrow_available = lambda: False

@contextlib.contextmanager
def session():
    payload = Path(sys.argv[3]) / "input.arrow"
    process = subprocess.Popen(
        [sys.executable, "-u", "-c", sys.argv[1], sys.argv[2], str(payload)],
        stdin=subprocess.PIPE, stdout=subprocess.PIPE, text=True,
    )
    spark = None
    try:
        port = int(process.stdout.readline())
        spark = SparkSession.builder.remote(f"sc://127.0.0.1:{port}").create()
        yield spark, payload
    finally:
        try:
            if spark is not None:
                spark.stop()
        finally:
            try:
                process.communicate("stop\n", timeout=20)
            except subprocess.TimeoutExpired:
                process.kill()
                process.communicate()
                raise
            assert process.returncode == 0

original_import = builtins.__import__
imports = []
conversion_import_counts = []

def tracked_import(name, *args, **kwargs):
    if name == "_decimal":
        imports.append(name)
    return original_import(name, *args, **kwargs)

def build(spark, data, schema=None):
    before = len(imports)
    builtins.__import__ = tracked_import
    try:
        return spark.createDataFrame(data, schema)
    finally:
        builtins.__import__ = original_import
        conversion_import_counts.append(len(imports) - before)

def assert_decimal_cells(payload, precision, scale, unscaled):
    # Compare raw signed Decimal128 cells without constructing expected Arrow Decimals
    # or relying on the client's result decoder to validate its own uploaded payload.
    table = pa.ipc.open_stream(payload.read_bytes()).read_all()
    table.validate(full=True)
    assert table.schema == pa.schema([pa.field("v", pa.decimal128(precision, scale))])
    column = table.column("v").combine_chunks()
    assert column.is_valid().to_pylist() == [value is not None for value in unscaled]
    cells = column.buffers()[1].to_pybytes()
    assert len(column) == len(unscaled)
    for index, value in enumerate(unscaled):
        if value is not None:
            assert cells[index * 16:(index + 1) * 16] == value.to_bytes(
                16, "little", signed=True
            )

with session() as (spark, payload):
    schema = T.StructType([T.StructField("v", T.DecimalType(10, 2))])
    rows = [(decimal.Decimal("1.235"),), (None,), (decimal.Decimal("-2.345"),)]
    build(spark, rows, schema).collect()
    assert_decimal_cells(payload, 10, 2, [124, None, -234])

    calls = []
    class Traced(decimal.Decimal):
        def __str__(self):
            calls.append("str")
            return super().__str__()

        def as_tuple(self):
            calls.append("tuple")
            return super().as_tuple()

    frame = pd.DataFrame({"v": [Traced("1.20"), None, Traced("-30.5"),
                                decimal.Decimal("1E+3")]}, dtype=object)
    # The row path keeps the Decimal hooks of its converter.
    build(spark, frame).collect()
    assert calls == ["str", "tuple", "str", "tuple", "tuple", "tuple"], calls
    assert_decimal_cells(payload, 6, 2, [120, None, -3050, 100000])

    class Broken(decimal.Decimal):
        def as_tuple(self):
            raise LookupError("pure Decimal tuple hook")

    failing = pd.DataFrame({"v": [Broken("1.25")]}, dtype=object)
    payload.unlink()
    with pytest.raises(LookupError, match="^pure Decimal tuple hook$"):
        build(spark, failing)
    assert not payload.exists()
    assert imports == ["_decimal"], imports
    assert conversion_import_counts == [1, 0, 0], conversion_import_counts
'''
    try:
        result = subprocess.run(
            [sys.executable, "-c", script, _DECIMAL_IPC_SERVER,
             str(decimal_ipc_protocol), str(tmp_path)],
            capture_output=True, text=True, timeout=180,
        )
    except subprocess.TimeoutExpired as error:
        output = []
        for name, value in (("stdout", error.stdout), ("stderr", error.stderr)):
            if isinstance(value, bytes):
                value = value.decode(errors="replace")
            output.append(f"{name}:\n{value or ''}")
        pytest.fail(
            "Decimal fallback child exceeded 180 seconds.\n" + "\n".join(output),
            pytrace=False,
        )
    assert result.returncode == 0, result.stdout + result.stderr


def test_decimal_public_pure_python_alias_native_pandas_uses_float():
    # Type caches are process-local: set the public alias before the extension is loaded,
    # while leaving the C accelerator available. Inspect the inline IPC without an execution;
    # the mock server answers the settings that createDataFrame reads first, as PySpark's.
    # This pins "Decimal class rebinding" in dev/parity/known-differences.md; update the
    # expected lossy values if pure-Python alias values become recognized as Decimals.
    import subprocess
    import sys
    from pathlib import Path

    pytest.importorskip("_decimal")
    pytest.importorskip("pandas")
    pytest.importorskip("pyarrow")
    script = r'''
import sys
import decimal
import _decimal
import _pydecimal
assert "pyspark._pyspark" not in sys.modules
assert _decimal.Decimal is not _pydecimal.Decimal
decimal.Decimal = _pydecimal.Decimal
import pandas as pd
import pyarrow as pa
assert "pyspark._pyspark" not in sys.modules
sys.path.insert(0, sys.argv[1])
from _mock_connect_server import parse_message
from pyspark.sql import SparkSession
from pyspark.sql import _pandas_input
assert decimal.Decimal is _pydecimal.Decimal

# The row path of pandas frames, which createDataFrame takes without PyArrow.
_pandas_input.pyarrow_available = lambda: False
values = [_pydecimal.Decimal("1.0000000000000000000001"), None,
          _pydecimal.Decimal("9007199254740993")]
spark = SparkSession.builder.remote(sys.argv[2]).create()
for schema in (None, ["v"]):
    frame = pd.DataFrame({"v": values}, dtype=object)
    relation = parse_message(spark.createDataFrame(frame, schema)._relation_bytes())
    while 18 in relation:
        relation = parse_message(parse_message(relation[18][0])[1][0])
    local = parse_message(relation[11][0])
    actual = pa.ipc.open_stream(local[1][0]).read_all()
    expected = pa.table({"v": pa.array([1.0, None, 9007199254740992.0], type=pa.float64())})
    actual.validate(full=True)
    assert actual.schema == expected.schema
    assert actual.equals(expected)
spark.stop()
'''
    pytest.importorskip("grpc")
    try:
        with mock_connect_session() as (_, service):
            result = subprocess.run(
                [sys.executable, "-c", script, str(Path(__file__).resolve().parent),
                 service.remote],
                capture_output=True, text=True, timeout=60,
            )
    except subprocess.TimeoutExpired as error:
        output = []
        for name, value in (("stdout", error.stdout), ("stderr", error.stderr)):
            if isinstance(value, bytes):
                value = value.decode(errors="replace")
            output.append(f"{name}:\n{value or ''}")
        pytest.fail(
            "Decimal public-alias child exceeded 60 seconds.\n" + "\n".join(output),
            pytrace=False,
        )
    assert result.returncode == 0, result.stdout + result.stderr


@pytest.mark.parametrize("kind", ["tuples", "pandas"])
@pytest.mark.parametrize("precision, scale, texts", [
    (18, 7, ["1E+3", "1E-7", "-1E-7", "+1.25E+2", "-1.25E-2", "0E+3", "-0E-7", None]),
    (18, 7, ["99999999999.9999999", "-99999999999.9999999", "1.234500E-3"]),
    (38, 0, ["1E+37", "-1E+37", "9.9999999999999999999999999999999999999E+37"]),
    (38, 38, ["1E-38", "-1E-38", "0E-38"]),
    (10, 2, ["123.45", "-123.45", "1.2300", "0.00", "-0.00"]),
])
def test_decimal_scientific_local_input_ipc(decimal_ipc_session, kind, precision, scale, texts):
    from decimal import Decimal

    import pyarrow as pa

    spark, payload = decimal_ipc_session
    values = [None if text is None else Decimal(text) for text in texts]
    data = [(value,) for value in values]
    if kind == "pandas":
        pd = pytest.importorskip("pandas")
        data = pd.DataFrame({"v": values})
    schema = T.StructType([T.StructField("v", T.DecimalType(precision, scale))])
    spark.createDataFrame(data, schema).collect()
    # Read the uploaded IPC independently rather than trusting collect's decoder.
    table = pa.ipc.open_stream(payload.read_bytes()).read_all()
    expected = pa.table({"v": pa.array(values, type=pa.decimal128(precision, scale))})
    assert table.schema == expected.schema
    assert table.equals(expected)
    # Check the physical little-endian Decimal128 cells as well as their values.
    actual = table.column(0).combine_chunks()
    wanted = expected.column(0).combine_chunks()
    for index, value in enumerate(values):
        if value is not None:
            offset = index * 16
            assert actual.buffers()[1][offset:offset + 16] == wanted.buffers()[1][offset:offset + 16]


@pytest.mark.parametrize("text", ["1E+1000000000", "-1E+1000000000"])
def test_decimal_scientific_local_input_overflow(decimal_ipc_session, text):
    from decimal import Decimal, InvalidOperation

    spark, payload = decimal_ipc_session
    schema = T.StructType([T.StructField("v", T.DecimalType(38, 0))])
    # Trap-mutating tests restore DefaultContext; its normal InvalidOperation trap
    # makes quantize reject this overflow before any IPC relation is uploaded.
    with pytest.raises(InvalidOperation):
        spark.createDataFrame([(Decimal(text),)], schema).collect()
    assert not payload.exists()


@pytest.mark.parametrize("kind", ["tuples", "pandas"])
@pytest.mark.parametrize("text, precision, scale, local_expected", [
    ("1.5E-7", 18, 7, "0.0000002"),
    ("-1.5E-7", 18, 7, "-0.0000002"),
    ("1E-8", 18, 7, "0.0000000"),
    ("0.00000015", 18, 7, "0.0000002"),
    ("1.235", 10, 2, "1.24"),
    ("1E+2", 2, 0, None),
    ("-1E+2", 2, 0, None),
    ("100000000000", 18, 7, None),
    ("1E+1000000000", 38, 0, None),
])
def test_decimal_rescaling_follows_pyspark(
    decimal_ipc_session, kind, text, precision, scale, local_expected
):
    # As PySpark 4.3.0: local rows are quantized half-even to the scale, and fail beyond
    # the precision, in the Decimal conversion; a pandas column fails its Arrow conversion
    # for any value that does not fit exactly, in either notation, rather than losing digits.
    from decimal import Decimal

    import pyarrow as pa
    from pyspark.errors import PySparkValueError

    spark, payload = decimal_ipc_session
    data = [(Decimal(text),)]
    if kind == "pandas":
        pd = pytest.importorskip("pandas")
        data = pd.DataFrame({"v": [Decimal(text)]}, dtype=object)
    schema = T.StructType([T.StructField("v", T.DecimalType(precision, scale))])
    if kind == "tuples" and local_expected is not None:
        spark.createDataFrame(data, schema).collect()
        actual = pa.ipc.open_stream(payload.read_bytes()).read_all()
        expected = pa.table({"v": pa.array([Decimal(local_expected)],
                                           type=pa.decimal128(precision, scale))})
        actual.validate(full=True)
        assert actual.schema == expected.schema
        assert actual.equals(expected)
        return
    if kind == "tuples":
        with pytest.raises(ArithmeticError):
            spark.createDataFrame(data, schema)
    else:
        with pytest.raises(PySparkValueError) as error:
            spark.createDataFrame(data, schema)
        assert str(error.value) == (
            "Exception thrown when converting pandas.Series (object) with name 'v' to Arrow "
            f"Array (decimal128({precision}, {scale})). It can be caused by overflows or other "
            "unsafe conversions warned by Arrow. Arrow safe type check can be disabled by using "
            "SQL config `spark.sql.execution.pandas.convertToArrowArraySafely`."
        )
    assert not payload.exists()


def test_non_nullable_null_type_is_rejected_before_the_rpc_as_pyspark(mock_connect):
    # As PySpark's to_arrow_schema, which local rows of a non-empty createDataFrame go through:
    # a null type that is not nullable, as a field, an array element, a map value or a map key,
    # at any depth, raises ValueError before anything is sent, never a panic or an Arrow error.
    # Empty data is not converted, and a nullable null type is accepted.
    spark, service = mock_connect
    null = T.NullType

    def struct(*fields):
        return T.StructType([T.StructField(name, typ, nullable) for name, typ, nullable in fields])

    rejected = [
        ([(None,)], struct(("a", null(), False))),
        ([Row(a=[])], struct(("a", T.ArrayType(null(), False), True))),
        ([Row(a=[None])], struct(("a", T.ArrayType(null(), False), True))),
        ([Row(a=[[]])], struct(("a", T.ArrayType(T.ArrayType(null(), False)), True))),
        ([Row(a=[Row(x=None)])], struct(("a", T.ArrayType(struct(("x", null(), False))), True))),
        ([Row(m={})], struct(("m", T.MapType(T.StringType(), null(), False), True))),
        ([Row(m={"k": None})], struct(("m", T.MapType(T.StringType(), null(), False), True))),
        ([Row(m={})], struct(("m", T.MapType(null(), T.StringType(), True), True))),
        ([Row(s=Row(x=None))], struct(("s", struct(("x", null(), False)), True))),
    ]
    for data, schema in rejected:
        calls = service.execute_calls
        with pytest.raises(ValueError) as error:
            spark.createDataFrame(data, schema)
        assert type(error.value) is ValueError
        assert str(error.value) == "A null type field may not be non-nullable"
        assert service.execute_calls == calls
    accepted = [
        ([], struct(("a", null(), False))),
        ([Row(a=[])], struct(("a", T.ArrayType(null(), True), True))),
        ([Row(a=[None])], struct(("a", T.ArrayType(null(), True), True))),
        ([(None,)], struct(("a", null(), True))),
    ]
    calls = service.execute_calls
    for data, schema in accepted:
        spark.createDataFrame(data, schema)
    assert service.execute_calls == calls


@pytest.mark.parametrize("kind", ["tuples", "pandas"])
@pytest.mark.parametrize("schema_mode", ["explicit", "names", "inferred"])
@pytest.mark.parametrize("texts", [
    ["123.4500", "-2.3400", "0.0000", "-0.0000", None],
    ["1.2300E+2", "-2.3400E+2", "0.00", "-0.00", None],
    ["0.001234500", "-0.000002300", "0.000000", None],
    ["123", "-4", "0", None],
    ["1E+3", "1E-7", "-0E-7", "1.2300E-7", None],
    ["1.0E+4", "-2.00E+3", "-0E-7", None],
])
def test_decimal_scale_input_ipc(decimal_ipc_session, kind, schema_mode, texts):
    # The scale of a Decimal comes from its text, not from as_tuple(): the IPC holds the same
    # cells and types as PySpark's, which types an inferred pandas column by its values as
    # Arrow does, and a local one as decimal(38, 18). The Decimal context of the thread,
    # here one that would round and trap, changes nothing.
    from decimal import ROUND_UP, Decimal, Inexact, localcontext

    import pyarrow as pa

    spark, payload = decimal_ipc_session
    values = [None if text is None else Decimal(text) for text in texts]
    name = "_1" if schema_mode == "inferred" and kind == "tuples" else "v"
    data = [(value,) for value in values]
    if kind == "pandas":
        pd = pytest.importorskip("pandas")
        data = pd.DataFrame({name: values}, dtype=object)
    if schema_mode == "explicit":
        decimal_type = pa.decimal128(18, 9)
        schema = T.StructType([T.StructField(name, T.DecimalType(18, 9))])
    else:
        decimal_type = pa.decimal128(38, 18) if kind == "tuples" else pa.array(values).type
        schema = [name] if schema_mode == "names" else None
    with localcontext() as context:
        context.prec = 2
        context.rounding = ROUND_UP
        context.traps[Inexact] = True
        spark.createDataFrame(data, schema).collect()
    table = pa.ipc.open_stream(payload.read_bytes()).read_all()
    # As PySpark's Arrow conversion of a pandas frame without a schema, whose table names its
    # columns _0, _1, ..., which toDF names.
    ipc_name = "_0" if kind == "pandas" and schema_mode != "explicit" else name
    expected = pa.table({ipc_name: pa.array(values, type=decimal_type)})
    table.validate(full=True)
    assert table.schema == expected.schema
    assert table.equals(expected)


def test_decimal_scale_of_subclasses(decimal_ipc_session):
    # A subclass can override __str__ and as_tuple, so it is still asked for both, as Arrow
    # does; their errors are raised.
    from decimal import Decimal

    import pyarrow as pa

    pd = pytest.importorskip("pandas")
    spark, payload = decimal_ipc_session
    calls = []

    class Traced(Decimal):
        def __str__(self):
            calls.append("str")
            return super().__str__()

        def as_tuple(self):
            calls.append("tuple")
            return super().as_tuple()

    values = [Traced("1.20"), None, Traced("-30.5")]
    spark.createDataFrame(pd.DataFrame({"v": values}, dtype=object), ["v"]).collect()
    assert calls.count("str") == 2 and "tuple" in calls
    table = pa.ipc.open_stream(payload.read_bytes()).read_all()
    expected = pa.array([Decimal("1.20"), None, Decimal("-30.5")])
    assert table.column(0).combine_chunks().equals(expected)

    for hook in ["__str__", "as_tuple"]:
        def fail(self):
            raise LookupError("decimal hook")

        failing = type("Failing", (Decimal,), {hook: fail})
        with pytest.raises(LookupError, match="decimal hook"):
            spark.createDataFrame(pd.DataFrame({"v": [failing("1.5")]}, dtype=object), ["v"])


@pytest.mark.parametrize("schema_mode", ["explicit", "names", "inferred"])
@pytest.mark.parametrize("hook_behavior", ["error", "scale"])
def test_decimal_scale_rebound_subclass_keeps_tuple_hook(
    decimal_ipc_session, monkeypatch, pandas_row_path, schema_mode, hook_behavior
):
    # A subclass rebound as decimal.Decimal is still a subclass, not the immutable C type.
    # Both conversion and inferred pandas typing of the row path must retain its as_tuple hook.
    import decimal
    from unittest.mock import Mock

    import pyarrow as pa
    from pyspark.sql import _pandas_input

    pd = pytest.importorskip("pandas")
    original = decimal.Decimal
    calls = []
    parts = original("123.45000").as_tuple()

    class Rebound(original):
        def __str__(self):
            calls.append("str")
            return "1.20"

        def as_tuple(self):
            calls.append("tuple")
            if hook_behavior == "error":
                raise LookupError("rebound Decimal tuple hook")
            return parts

    # Canonical-looking metadata must not make a Python heap type eligible either.
    Rebound.__name__ = "Decimal"
    Rebound.__module__ = "decimal"
    frame = pd.DataFrame({"v": [Rebound("1.20"), None]}, dtype=object)
    schema = T.StructType([T.StructField("v", T.DecimalType(10, 2))])
    if schema_mode != "explicit":
        schema = ["v"] if schema_mode == "names" else None
    spark, payload = decimal_ipc_session
    explicit_arrow = Mock(side_effect=AssertionError("native Decimal test reached explicit Arrow"))
    inferred_arrow = Mock(side_effect=AssertionError("native Decimal test reached inferred Arrow"))
    with monkeypatch.context() as alias:
        alias.setattr(decimal, "Decimal", Rebound)
        alias.setattr(_pandas_input, "prepare_pandas_table", explicit_arrow)
        alias.setattr(_pandas_input, "prepare_inferred_pandas_table", inferred_arrow)
        if hook_behavior == "error":
            with pytest.raises(LookupError, match="^rebound Decimal tuple hook$"):
                spark.createDataFrame(frame, schema)
        else:
            spark.createDataFrame(frame, schema).collect()
    explicit_arrow.assert_not_called()
    inferred_arrow.assert_not_called()
    if hook_behavior == "error":
        assert calls == ["str", "tuple"]
        assert not payload.exists()
    else:
        assert calls == ["str", "tuple"] + ([] if schema_mode == "explicit" else ["tuple"])
        table = pa.ipc.open_stream(payload.read_bytes()).read_all()
        expected_type = pa.decimal128(10, 2) if schema_mode == "explicit" else pa.decimal128(8, 5)
        assert table.schema.field("v").type == expected_type
        assert table.column(0).to_pylist() == [original("1.20"), None]


@pytest.mark.parametrize("schema", [["v"], T.StructType([T.StructField("v", T.DecimalType(10, 4))])])
def test_decimal_scale_avoids_coefficient_tuple(decimal_ipc_session, pandas_row_path, schema):
    # Exact Decimals are typed and converted from their text: no DecimalTuple is built.
    import cProfile
    from decimal import Decimal

    pd = pytest.importorskip("pandas")
    spark, _ = decimal_ipc_session
    tuple_constructor = type(Decimal("1.20").as_tuple()).__new__.__code__
    # Of the converter of the row path (`pandas_row_path`).
    values = pd.DataFrame({"v": [Decimal("123.4500"), Decimal("-2.3000"), None]}, dtype=object)
    profile = cProfile.Profile()
    profile.enable()
    try:
        spark.createDataFrame(values, schema)
    finally:
        profile.disable()
    assert not any(entry.code is tuple_constructor for entry in profile.getstats())


def test_decimal_explicit_pandas_schema_uses_arrow_conversion(decimal_ipc_session, monkeypatch):
    from decimal import Decimal

    import pyarrow as pa
    from pyspark.sql import _pandas_input

    pd = pytest.importorskip("pandas")
    spark, payload = decimal_ipc_session
    prepare = _pandas_input.prepare_pandas_table
    calls = []

    def prepare_table(*args):
        calls.append(True)
        return prepare(*args)

    monkeypatch.setattr(_pandas_input, "prepare_pandas_table", prepare_table)
    values = [Decimal("1.20"), None, Decimal("-30.5")]
    schema = T.StructType([T.StructField("v", T.DecimalType(10, 2))])
    spark.createDataFrame(pd.DataFrame({"v": values}, dtype=object), schema).collect()
    assert calls == [True]
    table = pa.ipc.open_stream(payload.read_bytes()).read_all()
    expected = pa.table({"v": pa.array(values, type=pa.decimal128(10, 2))})
    table.validate(full=True)
    assert table.schema == expected.schema
    assert table.equals(expected)


