def test_udf_profiles_are_collected_from_the_python_accumulators_as_pyspark(
        mock_connect, capsys, caplog):
    # As PySpark Connect's: spark.profile is a Profile of a ConnectProfilerCollector, which the
    # pickled updates of the UDF profiler, in the __python_accumulator__ observed metrics of an
    # execution, update; the updates of other accumulators are ignored, and the warning of one
    # that does not unpickle is logged.
    import cProfile
    import pstats

    from pyspark.accumulators import SpecialAccumulatorIds, specialAccumulatorSer
    from pyspark.sql.connect.profiler import ConnectProfilerCollector
    from pyspark.sql.profiler import Profile

    spark, service = mock_connect
    profiler = cProfile.Profile()
    profiler.enable()
    sum(range(10))
    profiler.disable()
    # As the profiler of the Python worker sends its stats.
    stats = pstats.Stats(profiler, stream=None)
    stats.stream = None

    def accumulator_metrics(*updates):
        # ExecutePlanResponse.observed_metrics=6 -> ObservedMetrics name=1, values=2
        # (Expression.Literal binary=2).
        observed = message_field(1, "__python_accumulator__")
        for update in updates:
            observed += message_field(2, message_field(2, update))
        return message_field(6, observed)

    service.execute_payload = accumulator_metrics(
        specialAccumulatorSer.dumps(
            (SpecialAccumulatorIds.SQL_UDF_PROFIER_V2, {7: {"perf": stats}})),
        specialAccumulatorSer.dumps((SpecialAccumulatorIds.SQL_UDF_PROFIER, {8: (stats, None)})),
        b"not a pickle",
    )
    with caplog.at_level("WARNING"):
        spark.range(1).collect()
    assert isinstance(spark.profile, Profile)
    assert isinstance(spark._profiler_collector, ConnectProfilerCollector)
    assert list(spark._profiler_collector._profile_results) == [7]
    assert "Error unpickling accumulator metric" in caplog.text
    capsys.readouterr()
    spark.profile.show(type="perf")
    assert "Profile of UDF<id=7>" in capsys.readouterr().out
    spark.profile.clear()
    assert spark._profiler_collector._profile_results == {}




def test_the_exception_of_a_done_call_fails_the_execution_as_pyspark(mock_connect, monkeypatch):
    # As PySpark Connect's Progress.__exit__, which makes the done call when the execution ends:
    # the exception of a handler's done call goes out of the execution as it is, not to
    # sys.unraisablehook, and it replaces the error of an execution that fails, which PySpark
    # keeps as its __context__. A registration of a function, which PySpark runs without a
    # Progress, makes no call.
    import sys

    from pyspark.sql.functions import udf

    spark, service = mock_connect
    # ExecutePlanResponse.execution_progress=18 -> one stage with tasks, as the tests above.
    stage = (varint_field(1, 7) + varint_field(2, 4) + varint_field(3, 1)
             + varint_field(4, 1024) + varint_field(5, 0))
    service.execute_payload = message_field(18, message_field(1, stage) + varint_field(2, 3))
    unraisable = []
    monkeypatch.setattr(sys, "unraisablehook", unraisable.append)
    error = ValueError("the done call raises")
    calls = []

    def failing(**kwargs):
        calls.append(kwargs["done"])
        if kwargs["done"]:
            raise error

    spark.registerProgressHandler(failing)
    try:
        for action in [lambda: spark.range(1).collect(),
                       lambda: list(spark.range(1).toLocalIterator()),
                       lambda: list(spark.range(1).toLocalIterator(prefetchPartitions=True))]:
            calls.clear()
            with pytest.raises(ValueError) as raised:
                action()
            assert raised.value is error and calls == [False, True]
        classes = ["org.apache.spark.sql.AnalysisException", "java.lang.Exception"]
        service.execute_error = ("[TABLE_OR_VIEW_NOT_FOUND] t", classes[0],
                                 _error_info(classes, errorClass="TABLE_OR_VIEW_NOT_FOUND"))
        with pytest.raises(ValueError) as raised:
            spark.range(1).collect()
        assert raised.value is error
        service.execute_error = None
        calls.clear()
        spark.udf.register("f", udf(lambda: 1))
        assert calls == []
    finally:
        service.execute_error = None
        spark.removeProgressHandler(failing)
    assert unraisable == []
    service.execute_payload = b""
    assert spark.range(1).collect() == []


def test_the_done_error_of_a_progress_handler_keeps_the_execution_error_as_context(mock_connect):
    # As PySpark's Progress.__exit__: a done call that raises after the execution failed raises
    # its own exception, with the exception of the execution as its __context__.
    from pyspark.errors import AnalysisException

    spark, service = mock_connect
    classes = ["org.apache.spark.sql.AnalysisException", "java.lang.Exception"]
    service.execute_error = ("[TABLE_OR_VIEW_NOT_FOUND] t", classes[0],
                             _error_info(classes, errorClass="TABLE_OR_VIEW_NOT_FOUND"))
    error = ValueError("done-a")

    def failing(**kwargs):
        if kwargs["done"]:
            raise error

    spark.registerProgressHandler(failing)
    try:
        with pytest.raises(ValueError) as raised:
            spark.range(1).collect()
    finally:
        service.execute_error = None
        spark.removeProgressHandler(failing)
    assert raised.value is error
    assert isinstance(raised.value.__context__, AnalysisException)
    assert "TABLE_OR_VIEW_NOT_FOUND" in str(raised.value.__context__)


def _progress_of_one_stage(service):
    # ExecutePlanResponse.execution_progress=18 -> ExecutionProgress.stages=1 (StageInfo
    # stage_id=1, num_tasks=2, num_completed_tasks=3, input_bytes_read=4, done=5),
    # num_inflight_tasks=2.
    stage = (varint_field(1, 7) + varint_field(2, 4) + varint_field(3, 1)
             + varint_field(4, 1024) + varint_field(5, 0))
    service.execute_payload = message_field(18, message_field(1, stage) + varint_field(2, 3))


def test_a_progress_handler_registered_while_the_handlers_are_cleared_is_called(mock_connect):
    # Clearing the handlers drops them, which runs the __del__ of one that nothing else holds;
    # a handler that it registers is in the list after the clear, as in the _progress_handlers
    # of PySpark's client, and is called. The number of handlers that the client keeps beside
    # the list must not be left at that of the cleared list.
    spark, service = mock_connect
    _progress_of_one_stage(service)
    calls = []

    def late(**kwargs):
        calls.append(kwargs["done"])

    class Registering:
        def __call__(self, **kwargs):
            pass

        def __del__(self):
            spark.registerProgressHandler(late)

    spark.registerProgressHandler(Registering())
    spark.clearProgressHandlers()
    try:
        spark.range(1).collect()
    finally:
        spark.clearProgressHandlers()
    assert calls == [False, True]


def test_progress_handlers_registered_and_removed_by_many_threads_at_once(mock_connect):
    # Threads that register and remove their own handlers at once leave the handlers, and the
    # number of them that the client keeps beside the list, as the last change left them: a
    # handler registered after them is called, and none is once they are all removed.
    import threading

    spark, service = mock_connect
    _progress_of_one_stage(service)
    threads, rounds = 8, 200
    barrier = threading.Barrier(threads)
    failures, calls = [], []

    def work(index):
        def own(**kwargs):
            calls.append(index)

        try:
            barrier.wait(10)
            for _ in range(rounds):
                spark.registerProgressHandler(own)
                spark.removeProgressHandler(own)
        except BaseException as error:  # noqa: BLE001
            failures.append(error)

    def kept(**kwargs):
        calls.append("kept")

    spark.registerProgressHandler(kept)
    workers = [threading.Thread(target=work, args=(index,)) for index in range(threads)]
    for worker in workers:
        worker.start()
    for worker in workers:
        worker.join(60)
    assert failures == []
    try:
        spark.range(1).collect()
        assert calls == ["kept", "kept"]
        spark.removeProgressHandler(kept)
        calls.clear()
        spark.range(1).collect()
        assert calls == []
    finally:
        spark.clearProgressHandlers()


def test_a_local_iterator_that_a_thread_is_running_raises_as_a_generator_does(mock_connect):
    # As PySpark's toLocalIterator, a generator: while a thread waits in it for the next row,
    # the next or close of another thread raises the ValueError of a generator that is already
    # executing, and the iterator goes on for the thread that runs it.
    import sys
    import threading

    spark, service = mock_connect
    _two_row_range_results(service)
    service.block_result_complete = True
    rows = spark.range(2).toLocalIterator()
    assert [next(rows).id, next(rows).id] == [0, 1]
    outcome = []

    def wait_for_the_row():
        return next(rows)

    def wait_for_the_end():
        try:
            outcome.append(wait_for_the_row())
        except BaseException as error:  # noqa: BLE001
            outcome.append(error)

    def in_the_fetch():
        # The thread is in the call to next once a frame that wait_for_the_row called, that of
        # the generator, is on its stack: the generator is then executing.
        frame = sys._current_frames().get(waiting.ident)
        while frame is not None:
            if frame.f_back is not None and frame.f_back.f_code.co_name == "wait_for_the_row":
                return True
            frame = frame.f_back
        return False

    waiting = threading.Thread(target=wait_for_the_end)
    waiting.start()
    try:
        deadline = time.monotonic() + 5
        while not in_the_fetch() and time.monotonic() < deadline:
            time.sleep(0.001)
        assert in_the_fetch()
        assert waiting.is_alive()
        for call in (lambda: next(rows), rows.close):
            with pytest.raises(ValueError, match="generator already executing"):
                call()
    finally:
        service.block_result_complete = False
        service.release_response()
        waiting.join(10)
    assert not waiting.is_alive()
    [ended] = outcome
    assert isinstance(ended, StopIteration)
    assert list(rows) == []


def test_the_done_error_of_a_handler_that_refuses_attributes_keeps_its_context(mock_connect):
    # As Python chains an exception raised while another is handled, which PySpark's
    # Progress.__exit__ relies on: the context is not set through the __setattr__ of the
    # exception, so one that refuses attributes has it too.
    from pyspark.errors import AnalysisException

    class Refusing(ValueError):
        def __setattr__(self, name, value):
            raise AttributeError(name)

    spark, service = mock_connect
    classes = ["org.apache.spark.sql.AnalysisException", "java.lang.Exception"]
    service.execute_error = ("[TABLE_OR_VIEW_NOT_FOUND] t", classes[0],
                             _error_info(classes, errorClass="TABLE_OR_VIEW_NOT_FOUND"))
    error = Refusing("done")

    def failing(**kwargs):
        if kwargs["done"]:
            raise error

    spark.registerProgressHandler(failing)
    try:
        with pytest.raises(Refusing) as raised:
            spark.range(1).collect()
    finally:
        service.execute_error = None
        spark.removeProgressHandler(failing)
    assert raised.value is error
    assert isinstance(raised.value.__context__, AnalysisException)


def test_a_failure_to_make_the_exception_of_a_server_error_is_its_context(
        mock_connect, monkeypatch):
    # Should the exception of the connect classes of an error of the server fail to be made,
    # the error is raised as the class of its kind, and the failure is not dropped: it is the
    # __context__ of the exception that is raised.
    import pyspark.errors.exceptions.connect as connect_errors
    from pyspark.errors import AnalysisException

    spark, service = mock_connect
    classes = ["org.apache.spark.sql.AnalysisException", "java.lang.Exception"]
    service.execute_error = ("[TABLE_OR_VIEW_NOT_FOUND] t", classes[0],
                             _error_info(classes, errorClass="TABLE_OR_VIEW_NOT_FOUND"))
    failure = LookupError("no exception of the connect classes")

    def failing(**kwargs):
        raise failure

    monkeypatch.setattr(connect_errors, "_convert_server_error", failing)
    try:
        with pytest.raises(AnalysisException) as raised:
            spark.range(1).collect()
    finally:
        service.execute_error = None
    assert "TABLE_OR_VIEW_NOT_FOUND" in str(raised.value)
    assert raised.value.__context__ is failure


def test_an_exception_that_refuses_its_operation_id_is_raised_and_the_refusal_reported(
        mock_connect, monkeypatch):
    # The _operation_id that the client stamps on the exception of an execution, as the
    # reference client does, is auxiliary: an exception that refuses it is the one raised, and
    # the refusal goes to sys.unraisablehook rather than nowhere.
    import sys

    import pyspark.errors.exceptions.connect as connect_errors

    class Refusing(Exception):
        def __setattr__(self, name, value):
            raise AttributeError(f"refused {name}")

    spark, service = mock_connect
    classes = ["org.apache.spark.sql.AnalysisException", "java.lang.Exception"]
    service.execute_error = ("[TABLE_OR_VIEW_NOT_FOUND] t", classes[0],
                             _error_info(classes, errorClass="TABLE_OR_VIEW_NOT_FOUND"))
    error = Refusing("server")
    unraisable = []
    monkeypatch.setattr(sys, "unraisablehook", unraisable.append)
    monkeypatch.setattr(connect_errors, "_convert_server_error", lambda **kwargs: error)
    try:
        with pytest.raises(Refusing) as raised:
            spark.range(1).collect()
    finally:
        service.execute_error = None
    assert raised.value is error
    [reported] = unraisable
    assert isinstance(reported.exc_value, AttributeError)
    assert "refused _operation_id" in str(reported.exc_value)
    assert reported.object is error


def test_a_dropped_local_iterator_hands_the_done_error_to_unraisablehook_with_an_object(
        mock_connect, monkeypatch):
    # As PySpark's generator of toLocalIterator, which is closed with its execution unfinished:
    # its done call raises, and the error goes to sys.unraisablehook with an object, which the
    # hook prints as the "Exception ignored in:" header.
    import sys

    pa = pytest.importorskip("pyarrow")

    spark, service = mock_connect
    # ExecutePlanResponse.arrow_batch=2: row_count=3, data=2, with three rows, so that the
    # iterator is left with rows when it is dropped, before the end of the execution.
    batch = pa.record_batch([pa.array([1, 2, 3])], names=["id"])
    sink = pa.BufferOutputStream()
    with pa.ipc.new_stream(sink, batch.schema) as writer:
        writer.write_batch(batch)
    service.execute_payload = message_field(2, varint_field(1, 3)
                                            + message_field(2, sink.getvalue().to_pybytes()))
    unraisable = []
    monkeypatch.setattr(sys, "unraisablehook", unraisable.append)
    error = ValueError("done-b")

    def failing(**kwargs):
        if kwargs["done"]:
            raise error

    spark.registerProgressHandler(failing)
    try:
        rows = spark.range(3).toLocalIterator()
        iterator_type = type(rows)
        assert next(rows) is not None
        rows = None
    finally:
        spark.removeProgressHandler(failing)
        service.execute_payload = b""
    assert len(unraisable) == 1
    assert unraisable[0].exc_value is error
    assert unraisable[0].object is not None
    assert unraisable[0].object is iterator_type


def test_progress_handler_that_runs_queries_without_end_is_bounded(mock_connect, monkeypatch):
    # A handler that runs a query for each progress of an execution nests the executions past
    # the bound of nested callbacks: the query past it fails with a RecursionError, which the
    # handlers' exceptions carry out of each execution, as PySpark's result loop does, instead of
    # the native stack overflowing. The outer query raises it.
    import sys

    spark, service = mock_connect
    # ExecutePlanResponse.execution_progress=18 -> one stage that is not done.
    stage = (varint_field(1, 7) + varint_field(2, 4) + varint_field(3, 1)
             + varint_field(4, 1024) + varint_field(5, 0))
    service.execute_payload = message_field(18, message_field(1, stage) + varint_field(2, 3))
    unraisable = []
    monkeypatch.setattr(sys, "unraisablehook", unraisable.append)
    calls = []

    def handler(**kwargs):
        calls.append(kwargs["done"])
        if not kwargs["done"]:
            spark.range(1).collect()

    spark.registerProgressHandler(handler)
    try:
        with pytest.raises(RecursionError):
            spark.range(1).collect()
    finally:
        spark.removeProgressHandler(handler)
    assert calls == [False, False, True, True]
    assert unraisable == []


def test_schema_cache_cold_children_keep_independent_caches(mock_connect):
    spark, service = mock_connect
    df = spark.range(10)
    before_lookup = df.limit(1)
    service.block_response = True
    with ThreadPoolExecutor(max_workers=1) as pool:
        lookup = pool.submit(lambda: df.schema)
        try:
            for _ in range(500):
                if service.calls:
                    break
                time.sleep(0.01)
            else:
                raise AssertionError("Metadata request never reached the server")
            # Constructing a child also runs with the GIL. It must not wait for
            # the in-flight cache miss, or this thread cannot release the server.
            during_lookup = df.filter("id > 0")
            assert not lookup.done()
        finally:
            service.release_response()
        assert lookup.result(timeout=10).fieldNames() == ["id"]
    assert service.calls == 1
    # Neither child picks up a cache populated after the child was constructed.
    for calls, child in enumerate((before_lookup, during_lookup), start=2):
        service.data_type = struct_schema(f"child_{calls}")
        assert child.columns == [f"child_{calls}"]
        assert service.calls == calls
    assert df.columns == ["id"]


def test_map_and_group_functions_reject_a_non_struct_return_type_as_pyspark(mock_connect):
    # As PySpark's MapPartitions, GroupMap, CoGroupMap and ApplyInPandasWithState, which check
    # the return type of their UDF when they are built: a type that is not a struct raises
    # INVALID_RETURN_TYPE_FOR_PANDAS_UDF, or INVALID_RETURN_TYPE_FOR_ARROW_UDF for an Arrow
    # function, at the call, before the server sees the plan.
    from pyspark.errors import PySparkTypeError

    spark, service = mock_connect
    df = spark.range(1)
    grouped = df.groupBy("id")
    cogrouped = grouped.cogroup(df.groupBy("id"))
    pandas_error = "INVALID_RETURN_TYPE_FOR_PANDAS_UDF"
    arrow_error = "INVALID_RETURN_TYPE_FOR_ARROW_UDF"
    cases = [
        (lambda: df.mapInPandas(lambda it: it, T.IntegerType()), pandas_error, "IntegerType()"),
        (lambda: df.mapInPandas(lambda it: it, "int"), pandas_error, "IntegerType()"),
        (lambda: df.mapInArrow(lambda it: it, "long"), pandas_error, "LongType()"),
        (lambda: grouped.applyInPandas(lambda pdf: pdf, "int"), pandas_error, "IntegerType()"),
        (lambda: grouped.applyInPandas(lambda pdf: pdf, T.ArrayType(T.IntegerType())),
         pandas_error, "ArrayType(IntegerType(), True)"),
        (lambda: grouped.applyInArrow(lambda table: table, T.LongType()), arrow_error, "LongType()"),
        (lambda: cogrouped.applyInPandas(lambda left, right: left, "int"),
         pandas_error, "IntegerType()"),
        (lambda: cogrouped.applyInArrow(lambda left, right: left, "long"),
         arrow_error, "LongType()"),
        (lambda: grouped.applyInPandasWithState(
            lambda key, pdfs, state: iter([]), T.IntegerType(),
            T.StructType([T.StructField("c", T.LongType())]), "append", "NoTimeout"),
         pandas_error, "IntegerType()"),
    ]
    for call, condition, return_type in cases:
        with pytest.raises(PySparkTypeError) as e:
            call()
        assert e.value.getCondition() == condition
        assert e.value.getMessageParameters()["return_type"] == return_type
    assert service.execute_requests == []


def test_map_and_group_functions_parse_their_ddl_before_they_read_the_columns_as_pyspark(
        mock_connect):
    # As PySpark's mapInPandas, mapInArrow, applyInPandas and applyInArrow, which parse a DDL
    # string (`_parse_ddl`) before they read the columns of the input, of an AnalyzePlan of its
    # schema, so a parse that fails sends nothing more; and the functions of cogroups, which
    # parse it and bind no columns, as they take the whole cogroups, so their inputs are not
    # analyzed. The result keeps the parsed schema. A return type that is neither a DataType nor
    # a str raises NOT_EXPECTED_TYPE, of the constructor of PySpark's UserDefinedFunction, before
    # any request.
    from pyspark.errors import PySparkException, PySparkTypeError

    spark, service = mock_connect

    def cogrouped():
        return spark.range(2).groupBy("id").cogroup(spark.range(2).groupBy("id"))

    calls = [
        (lambda schema: spark.range(2).mapInPandas(lambda it: it, schema),
         ["ddl_parse", "schema"]),
        (lambda schema: spark.range(2).mapInArrow(lambda it: it, schema), ["ddl_parse", "schema"]),
        (lambda schema: spark.range(2).groupBy("id").applyInPandas(lambda pdf: pdf, schema),
         ["ddl_parse", "schema"]),
        (lambda schema: spark.range(2).groupBy("id").applyInArrow(lambda table: table, schema),
         ["ddl_parse", "schema"]),
        (lambda schema: cogrouped().applyInPandas(lambda left, right: left, schema),
         ["ddl_parse"]),
        (lambda schema: cogrouped().applyInArrow(lambda left, right: left, schema), ["ddl_parse"]),
    ]
    for make, kinds in calls:
        start = len(service.recorded_order)
        result = make("id long")
        assert _sent_kinds(service, start) == kinds
        assert result.columns == ["id"]
        assert _sent_kinds(service, start) == kinds
        start = len(service.recorded_order)
        with pytest.raises(PySparkTypeError) as e:
            make(1)
        assert e.value.getCondition() == "NOT_EXPECTED_TYPE"
        assert e.value.getMessageParameters() == {
            "arg_name": "returnType", "expected_type": "DataType or str", "arg_type": "int"}
        assert _sent_kinds(service, start) == []
    # The parse is the first request, of which a failure is raised before the columns are read.
    service.failure = "rpc"
    for make, _ in calls:
        start = len(service.recorded_order)
        with pytest.raises(PySparkException, match="schema unavailable"):
            make("id long")
        assert _sent_kinds(service, start) == ["ddl_parse"]
    service.failure = None
    # Relation.co_group_map=32, CoGroupMap.func=5; Relation.map_partitions=28, MapPartitions.func
    # =2; CommonInlineUserDefinedFunction.arguments=3.
    for make, relation, function in [(calls[4][0], 32, 5), (calls[0][0], 28, 2)]:
        make("id long").collect()
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
        arguments = parse_message(parse_message(parse_message(plan)[relation][0])[function][0])
        assert len(arguments.get(3, [])) == (0 if relation == 32 else 1)


@pytest.mark.parametrize("transform", [
    pytest.param(lambda df: df.selectExpr("id AS renamed"), id="select"),
    pytest.param(lambda df: df.zipWithIndex(), id="zipWithIndex"),
    # Reference PySpark does not propagate through offset, despite its unchanged
    # output columns. Match its explicit propagation rules rather than guessing.
    pytest.param(lambda df: df.offset(1), id="offset"),
])
def test_schema_cache_other_transforms_analyze_independently(mock_connect, transform):
    spark, service = mock_connect
    df = spark.range(10)
    assert df.columns == ["id"]
    derived = transform(df)
    assert service.calls == 1
    service.data_type = struct_schema("derived")
    assert derived.columns == ["derived"]
    assert service.calls == 2
    assert df.columns == ["id"]


@pytest.mark.parametrize("operation", [
    "union", "unionAll", "unionByName", "subtract", "exceptAll", "intersect", "intersectAll",
])
def test_schema_cache_set_operations_require_equal_warm_schemas(mock_connect, operation):
    spark, service = mock_connect
    left, right = spark.range(10), spark.range(10)
    assert left.columns == right.columns == ["id"]
    assert service.calls == 2
    equal = getattr(left, operation)(right)
    assert equal.columns == ["id"]
    assert service.calls == 2

    cold = spark.range(10)
    missing = getattr(left, operation)(cold)
    assert service.calls == 2
    service.data_type = struct_schema("resolved")
    assert missing.columns == ["resolved"]
    assert service.calls == 3

    different = spark.range(10)
    assert different.columns == ["resolved"]
    assert service.calls == 4
    mismatched = getattr(left, operation)(different)
    service.data_type = struct_schema("coerced")
    assert mismatched.columns == ["coerced"]
    assert service.calls == 5
    assert left.columns == ["id"]


def test_schema_cache_set_operations_compare_the_metadata_as_python_as_pyspark(mock_connect):
    # As PySpark's `_merge_cached_schema`, which compares the cached schemas with `==`, of the
    # metadata dicts of their fields as Python compares them: `1 == 1.0 == True`, so the schema
    # of the left side is known without a request.
    spark, service = mock_connect

    def of(metadata):
        field = T.StructField("id", T.LongType(), True, metadata)
        return spark.range(3).to(T.StructType([field]))

    left = of({"x": 1})
    for operation in ("union", "unionByName", "subtract", "exceptAll", "intersect"):
        for metadata in ({"x": 1.0}, {"x": True}):
            merged = getattr(left, operation)(of(metadata))
            assert merged.schema.fields[0].metadata == {"x": 1}
    assert service.calls == 0
    service.data_type = struct_schema("resolved")
    assert left.union(of({"x": 1.5})).columns == ["resolved"]
    assert service.calls == 1


def test_dataframes_take_their_arguments_and_attributes_as_pyspark(mock_connect, monkeypatch):
    # As PySpark Connect's: the errors of randomSplit, withMetadata and withWatermark, and the
    # attributes of a DataFrame: a column of any name but a dunder one, which must be a column,
    # and JVM_ATTRIBUTE_NOT_SUPPORTED of those of a classic DataFrame.
    from pyspark.errors import (
        PySparkAttributeError,
        PySparkTypeError,
        PySparkValueError,
    )

    spark, _ = mock_connect
    df = spark.range(3)
    for weights, arg_name, arg_value in (([1.0, -1.0], "weights", "-1.0"),
                                          ([0, 0], "sum(weights)", "0")):
        with pytest.raises(PySparkValueError) as e:
            df.randomSplit(weights)
        assert e.value.getCondition() == "VALUE_NOT_POSITIVE"
        assert e.value.getMessageParameters() == {"arg_name": arg_name, "arg_value": arg_value}
    with pytest.raises(PySparkTypeError) as e:
        df.withMetadata("id", 1)
    assert e.value.getMessageParameters() == {
        "expected_type": "dict", "arg_name": "metadata", "arg_type": "int"}
    df.withMetadata("id", {"k": 1, "l": [1, 2]})
    for event_time, delay, arg_name, arg_type in ((1, "1 minute", "eventTime", "int"),
                                                  ("", "1 minute", "eventTime", "str"),
                                                  ("id", None, "delayThreshold", "NoneType")):
        with pytest.raises(PySparkTypeError) as e:
            df.withWatermark(event_time, delay)
        assert e.value.getMessageParameters() == {
            "arg_name": arg_name, "expected_type": "str", "arg_type": arg_type}
    assert type(df._not_a_dunder).__name__ == "Column"
    # `rdd` too: pyspark-client's DataFrame defines no `rdd` property (only a classic-capable
    # PySpark does), so its `__getattr__` raises an AttributeError, and `hasattr` is False.
    for name in ("_jseq", "_jdf", "_jmap", "_jcols", "rdd"):
        with pytest.raises(PySparkAttributeError) as e:
            getattr(df, name)
        assert e.value.getCondition() == "JVM_ATTRIBUTE_NOT_SUPPORTED"
        assert e.value.getMessageParameters() == {"attr_name": name}
    assert not hasattr(df, "rdd")
    with pytest.raises(PySparkAttributeError) as e:
        df.__not_a_column__
    assert e.value.getCondition() == "ATTRIBUTE_NOT_SUPPORTED"
    monkeypatch.setenv("PYSPARK_VALIDATE_COLUMN_NAME_LEGACY", "1")
    with pytest.raises(PySparkAttributeError) as e:
        df.not_a_column
    assert e.value.getMessageParameters() == {"attr_name": "not_a_column"}




def test_getitem_validates_a_name_with_the_legacy_flag_as_pyspark(mock_connect, monkeypatch):
    # As PySpark's `__getitem__` with PYSPARK_VALIDATE_COLUMN_NAME_LEGACY=1: `verify_col_name` of
    # the cached schema, which is requested unless it is cached, and else the server, of
    # `self.select(item).isLocal()`, whose request raises its error; a star is not validated.
    from pyspark.sql.connect.proto import base_pb2

    spark, service = mock_connect
    monkeypatch.setenv("PYSPARK_VALIDATE_COLUMN_NAME_LEGACY", "1")
    service.data_type = struct_schema("a")

    def kinds(item):
        start = len(service.recorded_order)
        assert repr(df[item]) == f"Column<'{item}'>"
        return _sent_kinds(service, start)

    df = spark.range(2)
    assert kinds("a") == ["schema"]
    assert kinds("a") == []
    assert kinds("`a`") == []
    assert kinds("b") == ["is_local"]
    request = base_pb2.AnalyzePlanRequest.FromString(service.analyze_requests[-1])
    project = request.is_local.plan.root.project
    assert [e.unresolved_attribute.unparsed_identifier for e in project.expressions] == ["b"]
    assert kinds("a.b") == ["is_local"]
    star = len(service.recorded_order)
    assert repr(df["*"]) == "Column<'unresolvedstar()'>"
    assert _sent_kinds(service, star) == []
    df = spark.range(2)
    assert kinds("c") == ["schema", "is_local"]
    monkeypatch.delenv("PYSPARK_VALIDATE_COLUMN_NAME_LEGACY")
    assert kinds("d") == []


def test_a_column_named_as_an_internal_method_is_an_attribute_as_pyspark(mock_connect):
    # As PySpark's DataFrame, which has no `column_names`, a method of the drop-in's Rust code
    # only: `df.column_names` is the Column of that name, of `__getattr__`.
    spark, _ = mock_connect
    df = spark.range(1).withColumnRenamed("id", "column_names")
    assert not hasattr(type(df), "column_names")
