def test_logical_plans_give_the_plans_of_their_relations_of_to_proto_as_pyspark(
    mock_connect, capsys
):
    # As PySpark's LogicalPlan.to_proto(session, debug=False): the Plan of the relation of
    # plan(session) as its root, which debug prints. A DataFrame's _plan gives the Plan of the
    # placeholder of its relation, which its plan(session) gives.
    import inspect

    import pyspark.sql.connect.proto as pb2
    from pyspark.sql.connect.plan import LogicalPlan, Range

    spark, _ = mock_connect
    assert list(inspect.signature(LogicalPlan.to_proto).parameters) == ["self", "session", "debug"]
    assert inspect.signature(LogicalPlan.to_proto).parameters["debug"].default is False
    plan = Range(0, 3, 1)
    proto = plan.to_proto(spark.client)
    assert isinstance(proto, pb2.Plan) and proto.WhichOneof("op_type") == "root"
    assert proto.root == plan.plan(spark.client)
    assert capsys.readouterr().out == ""
    assert plan.to_proto(spark.client, debug=True) == proto
    assert capsys.readouterr().out == f"{proto}\n"
    df = spark.range(3)
    assert df._plan.to_proto(spark.client).root == df._plan.plan(spark.client)


def test_ml_plans_send_a_deep_dataframe_without_parsing_it_as_pyspark(mock_connect):
    # As PySpark's pyspark.ml, which builds its plans over the relation of a DataFrame without
    # parsing it: a DataFrame of 120 chained withColumn calls is nested deeper than a protobuf
    # decoder parses. A plan over it holds a placeholder of one level, the extension that holds
    # the relation encoded, which the core replaces with the relation when the plan reaches it,
    # so the server receives the relation.
    import gc
    import weakref

    import pyspark.sql.connect.proto as pb2
    from pyspark.sql import functions as F
    from pyspark.sql.connect.dataframe import DataFrame
    from pyspark.sql.connect.plan import LogicalPlan

    class Transform(LogicalPlan):
        # The plan of a transformer of pyspark.ml.connect.proto, over its input.
        def __init__(self, child, name):
            super().__init__(child)
            self._name = name

        def plan(self, session):
            plan = self._create_proto_relation()
            plan.ml_relation.transform.input.CopyFrom(self._child.plan(session))
            plan.ml_relation.transform.obj_ref.CopyFrom(pb2.ObjectRef(id=self._name))
            return plan

    spark, service = mock_connect
    deep = spark.range(2)
    for i in range(120):
        deep = deep.withColumn(f"c{i}", F.lit(i))
    relation = deep._relation_bytes()
    # The placeholder of the relation is an extension, whose value holds the relation, which
    # protobuf does not parse, whatever the depth of the DataFrame.
    placeholder = deep._plan.plan(spark.client)
    assert placeholder.WhichOneof("rel_type") == "extension"
    assert placeholder.extension.value.endswith(relation)
    # Two plans of transformers, one over the other, over the DataFrame. The request is read as
    # bytes, as the deep relation is not parsed by protobuf: ExecutePlanRequest.plan=3,
    # Plan.root=1, Relation.ml_relation=300, MlRelation.transform=1, Transform.input=3,
    # Transform.obj_ref=1 and ObjectRef.id=1.
    nested = DataFrame(Transform(Transform(deep._plan, "m1"), "m2"), spark)
    nested.collect()
    root = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
    outer = parse_message(parse_message(root)[300][0])[1][0]
    assert parse_message(parse_message(outer)[1][0]) == {1: [b"m2"]}
    inner = parse_message(parse_message(outer)[3][0])
    inner_transform = parse_message(parse_message(inner[300][0])[1][0])
    assert parse_message(inner_transform[1][0]) == {1: [b"m1"]}
    assert inner_transform[3][0] == relation

    # A placeholder of a DataFrame that is gone stands for its relation, as the relation of
    # PySpark's plan(session) does, and keeps nothing alive.
    gone = spark.range(3)
    gone_relation = gone._relation_bytes()
    placeholder = gone._plan.plan(spark.client)
    freed = weakref.ref(gone)
    del gone
    gc.collect()
    assert freed() is None

    class Gone(LogicalPlan):
        def plan(self, session):
            return placeholder

    DataFrame(Transform(Gone(None), "m3"), spark).collect()
    root = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
    transform = parse_message(parse_message(parse_message(root)[300][0])[1][0])
    assert transform[3][0] == gone_relation


def test_the_relations_of_the_plans_of_dataframes_are_built_when_they_are_given_as_pyspark(
    mock_connect,
):
    # As PySpark's df._plan.plan(session), which builds the relation of the DataFrame when it is
    # called: the relation is sent, after the DataFrame is gone too, and of the bytes of a
    # message that holds it; it is that of the call, of the pickles of its UDFs then, and the
    # errors of its build are raised by the call, with no request sent.
    import gc
    import pickle
    import threading

    import pyspark.sql.connect.proto as pb2
    from pyspark.sql import functions as F

    spark, service = mock_connect
    client = spark.client

    def sent():
        return pb2.ExecutePlanRequest.FromString(service.execute_requests[-1]).plan

    list(client.to_table_as_iterator(pb2.Plan(root=spark.range(2)._plan.plan(client)), {}))
    assert sent().root.range.end == 2
    kept = spark.range(3).filter("id > 0")._plan.plan(client)
    gc.collect()
    plan = pb2.Plan(root=kept)
    for message in (plan, pb2.Plan.FromString(plan.SerializeToString())):
        list(client.to_table_as_iterator(message, {}))
        assert sent().root.filter.input.range.end == 3

    state = ["at the call"]
    df = spark.range(1).select(F.udf(lambda x: state[0], "string")("id"))
    relation = df._plan.plan(client)
    state[0] = "after the call"
    list(client.to_table_as_iterator(pb2.Plan(root=relation), {}))
    function = sent().root.project.expressions[0].common_inline_user_defined_function
    assert b"at the call" in function.python_udf.command
    assert b"after the call" not in function.python_udf.command

    lock = threading.Lock()
    unpicklable = spark.range(1).select(F.udf(lambda x: lock is not None, "boolean")("id"))
    requests = len(service.execute_requests)
    with pytest.raises(pickle.PicklingError):
        unpicklable._plan.plan(client)
    assert len(service.execute_requests) == requests


def test_the_relations_of_dataframes_in_expressions_and_changed_ones_are_sent_as_pyspark(
    mock_connect,
):
    # As PySpark's df._plan.plan(session), a relation that a plan holds wherever it holds it, and
    # with what the plan changes of it: the server receives the relation of the DataFrame in the
    # extension of a plugin's expression, also nested, and one whose common a plan or a plugin's
    # message changes (relation.common.plan_id = ...) with that change, in the message of an
    # extension and as a relation of a plan.
    import pyspark.sql.connect.proto as pb2
    from pyspark.sql.connect.proto import example_plugins_pb2 as plugins

    spark, service = mock_connect
    client = spark.client
    source = spark.range(3).withColumnRenamed("id", "k")
    relation = pb2.Relation.FromString(source._relation_bytes())

    def sent():
        return pb2.ExecutePlanRequest.FromString(service.execute_requests[-1]).plan

    plan = pb2.Plan()
    plan.root.project.input.range.end = 1
    plan.root.project.expressions.add().extension.Pack(
        plugins.ExamplePluginRelation(input=source._plan.plan(client)))
    alias = plan.root.project.expressions.add().alias
    alias.name.append("a")
    alias.expr.extension.Pack(plugins.ExamplePluginRelation(input=source._plan.plan(client)))
    list(client.to_table_as_iterator(plan, {}))
    message = plugins.ExamplePluginRelation()
    expressions = sent().root.project.expressions
    for extension in (expressions[0].extension, expressions[1].alias.expr.extension):
        assert extension.Unpack(message) and message.input == relation

    changed = source._plan.plan(client)
    changed.common.plan_id = 424242
    expected = pb2.Relation()
    expected.CopyFrom(relation)
    expected.common.plan_id = 424242
    plan = pb2.Plan()
    plan.root.extension.Pack(plugins.ExamplePluginRelation(input=changed))
    list(client.to_table_as_iterator(plan, {}))
    assert sent().root.extension.Unpack(message) and message.input == expected

    plan = pb2.Plan()
    plan.root.limit.input.CopyFrom(source._plan.plan(client))
    plan.root.limit.input.common.plan_id = 525252
    plan.root.limit.limit = 1
    list(client.to_table_as_iterator(plan, {}))
    expected.common.plan_id = 525252
    assert sent().root.limit.input == expected


def test_every_message_built_in_python_sends_the_relations_of_its_dataframes_as_pyspark(
    mock_connect,
):
    # As PySpark's messages, which hold the relations of df._plan.plan(session) as they are: each
    # message that the client is given sends the relation of a DataFrame that it holds as an input
    # and in the extension of an expression, and a string that is the placeholder's type URL as it
    # is: the relation of a DataFrame(plan, session), the plan of to_table, a command, an analysis
    # and the request of a session hook. The core reads the fields of such a message only when its
    # encoding holds a type URL that is not of a placeholder at its relations, as the last two do.
    import pyspark.sql.connect.proto as pb2
    from pyspark.sql.connect.dataframe import DataFrame
    from pyspark.sql.connect.plan import LogicalPlan
    from pyspark.sql.connect.proto import example_plugins_pb2 as plugins
    from pyspark.sql.connect.session import SparkSession

    spark, service = mock_connect
    client = spark.client
    source = spark.range(3).withColumnRenamed("id", "k")
    relation = pb2.Relation.FromString(source._relation_bytes())
    url = "type.googleapis.com/spark.connect.rust.DataFramePlaceholder"

    def project(kind):
        built = pb2.Relation()
        built.project.input.CopyFrom(source._plan.plan(client))
        expression = built.project.expressions.add()
        if kind == "expression":
            expression.extension.Pack(plugins.ExamplePluginRelation(input=source._plan.plan(client)))
        else:
            expression.unresolved_attribute.unparsed_identifier = url if kind == "string" else "k"
        return built

    def check(sent, kind):
        assert sent.project.input == relation, kind
        expression = sent.project.expressions[0]
        if kind == "expression":
            message = plugins.ExamplePluginRelation()
            assert expression.extension.Unpack(message) and message.input == relation
        else:
            name = url if kind == "string" else "k"
            assert expression.unresolved_attribute.unparsed_identifier == name

    def executed():
        return pb2.ExecutePlanRequest.FromString(service.execute_requests[-1]).plan

    class Built(LogicalPlan):
        def __init__(self, kind):
            super().__init__(None)
            self.kind = kind

        def plan(self, session):
            return project(self.kind)

    kinds = ("input", "expression", "string")
    for kind in kinds:
        DataFrame(Built(kind), spark).collect()
        check(executed().root, kind)
        list(client.to_table_as_iterator(pb2.Plan(root=project(kind)), {}))
        check(executed().root, kind)
        command = pb2.Command()
        command.write_operation.input.CopyFrom(project(kind))
        command.write_operation.source = "noop"
        client.execute_command(command)
        check(executed().command.write_operation.input, kind)
        client._analyze("schema", plan=pb2.Plan(root=project(kind)))
        check(pb2.AnalyzePlanRequest.FromString(service.analyze_requests[-1]).schema.plan.root, kind)

    hooked = []

    class Hook(SparkSession.Hook):
        def on_execute_plan(self, request):
            request.plan.root.CopyFrom(project(hooked[-1]))
            return request

    builder = SparkSession.builder.remote(service.remote)
    builder._registerHook(lambda _: Hook())
    other = builder.create()
    try:
        for kind in kinds:
            hooked.append(kind)
            other.range(1).collect()
            check(executed().root, kind)
    finally:
        other.stop()


def test_dataframes_of_plans_that_fail_to_build_raise_at_each_request_as_pyspark(
    mock_connect, capsys
):
    # As PySpark's DataFrame(plan, session), which keeps the plan and builds it at each request: a
    # DataFrame of a plan that fails to build, of the class or of a subclass, is made, and each of
    # its requests, and of the DataFrames over it, raises the error of the build, with no request
    # sent. Of the plan of a DataFrame (`df._plan`), the requests build the plan of that DataFrame:
    # they pickle the functions of its UDFs, of the PicklingError and the traceback of each
    # pickling that fails, and raise the error of an option that UTF-8 cannot encode. The requests
    # of a DataFrame of another plan whose build raises raise the exception of that build, which a
    # pickle of the DataFrame carries, as PySpark's unpickle builds the plan; the DataFrame keeps
    # the plan alive while it lives.
    import gc
    import threading
    import weakref

    from pyspark.serializers import CloudPickleSerializer
    from pyspark.sql import functions as F
    from pyspark.sql.connect.dataframe import DataFrame
    from pyspark.sql.connect.plan import LogicalPlan

    spark, service = mock_connect
    lock = threading.Lock()

    class Frame(DataFrame):
        pass

    unpicklable = spark.range(1).select(F.udf(lambda x: lock is not None, "boolean")("id"))
    unencodable = spark.read.format("json").option("k", "\ud800").load("p")
    sent = (len(service.analyze_requests), len(service.execute_requests))

    def schema_of(frame):
        return lambda: frame.schema

    for cls in (DataFrame, Frame):
        for source, error in ((unpicklable, pickle.PicklingError),
                              (unencodable, UnicodeEncodeError)):
            made = cls(source._plan, spark)
            assert type(made) is cls
            over = made.select("*")
            for request in (schema_of(made), made.collect, over.collect, made.collect):
                with pytest.raises(error):
                    request()
    capsys.readouterr()
    frame = DataFrame(unpicklable._plan, spark)
    for _ in range(2):
        with pytest.raises(pickle.PicklingError, match="cannot pickle '_thread.lock' object"):
            frame.count()
    assert capsys.readouterr().err.count("TypeError: cannot pickle '_thread.lock' object") == 2
    assert (len(service.analyze_requests), len(service.execute_requests)) == sent

    class Failing(LogicalPlan):
        def __init__(self):
            super().__init__(None)

        def plan(self, session):
            raise KeyError("boom")

    def requests_of(frame):
        for request in ("collect", "schema", "over", "collect"):
            with pytest.raises(KeyError, match="boom"):
                if request == "schema":
                    frame.schema
                elif request == "over":
                    frame.select("*").count()
                else:
                    frame.collect()

    plan = Failing()
    frame = DataFrame(plan, spark)
    assert frame["id"]._expr.to_plan(None).unresolved_attribute.plan_id == plan._plan_id
    requests_of(frame)
    data = CloudPickleSerializer().dumps(frame)
    with pytest.raises(KeyError, match="boom"):
        CloudPickleSerializer().loads(data)
    assert (len(service.analyze_requests), len(service.execute_requests)) == sent
    alive = weakref.ref(plan)
    del plan, frame
    gc.collect()
    assert alive() is None


def test_dataframes_of_plans_keep_the_plan_ids_of_their_plans_as_pyspark(mock_connect):
    # As PySpark's DataFrame(plan, session), which keeps the plan, of the _plan_id that the plan
    # took of the one counter of the plans of the process when it was made: the columns of the
    # DataFrame refer to that ID, and its relation is sent of it. The plan of a DataFrame
    # (`df._plan`) is of the plan IDs of the DataFrame, and a DataFrame of it is of the plan of
    # that DataFrame, in any session, so that the columns of either resolve against the other, as
    # those of two DataFrames of one plan do in PySpark. The plans of the Python client and the
    # relations of the core are numbered of one counter, so none has the ID of another.
    from pyspark.sql import SparkSession
    from pyspark.sql import functions as F
    from pyspark.sql.connect.dataframe import DataFrame
    from pyspark.sql.connect.plan import LogicalPlan, Range, SubqueryAlias
    from pyspark.sql.connect.proto import base_pb2

    spark, service = mock_connect

    def refers_to(column):
        return column._expr.to_plan(None).unresolved_attribute.plan_id

    def sent():
        return base_pb2.ExecutePlanRequest.FromString(service.execute_requests[-1]).plan.root

    df = spark.range(3).withColumn("v", F.col("id") * 10)
    assert df._plan._plan_id == df._plan._root_plan_id == refers_to(df["id"])
    assert df._plan._plan_id_with_rel is None
    other = SparkSession.builder.remote(service.remote).create()
    try:
        for session in (spark, other):
            frame = DataFrame(df._plan, session)
            assert frame.sparkSession is session
            assert refers_to(frame["v"]) == refers_to(df["v"]) == frame._plan._plan_id
            frame.select(df["v"]).collect()
            root = sent()
            assert root.project.input.common.plan_id == refers_to(df["v"])
            assert root.project.expressions[0].unresolved_attribute.plan_id == refers_to(df["v"])
    finally:
        other.stop()
    # A plan of subqueries: its plan ID is that of the WithRelations, and its root one of its own.
    scalar = spark.range(1).select(df.select(F.max("v")).scalar())
    assert scalar._plan._plan_id_with_rel == scalar._plan._plan_id != scalar._plan._root_plan_id
    scalar.collect()
    assert sent().common.plan_id == scalar._plan._plan_id
    assert sent().with_relations.root.common.plan_id == scalar._plan._root_plan_id
    # And so of a pickled Column of a subquery, which sends the plan of its subquery so too.
    unpickled = pickle.loads(pickle.dumps(df.select(F.max("v")).scalar()))
    scalar = spark.range(1).select(unpickled)
    assert scalar._plan._plan_id_with_rel == scalar._plan._plan_id != scalar._plan._root_plan_id
    scalar.collect()
    assert sent().common.plan_id == scalar._plan._plan_id
    assert sent().with_relations.root.common.plan_id == scalar._plan._root_plan_id
    # A plan of the Python client, of its plan ID.
    plan = SubqueryAlias(df._plan, "s")
    frame = DataFrame(plan, spark)
    assert refers_to(frame["id"]) == plan._plan_id
    frame.collect()
    assert sent().common.plan_id == plan._plan_id
    ids = set()
    for end in range(3):
        ids |= {
            Range(0, end, 1)._plan_id,
            refers_to(spark.range(end)["id"]),
            refers_to(DataFrame(Range(0, end, 1), spark).select("id")["id"]),
        }
    assert len(ids) == 9
    assert LogicalPlan(None)._plan_id > max(ids)


def test_plans_of_plugins_send_the_relations_of_their_dataframes_in_their_extensions(
    mock_connect,
):
    # As PySpark's plugins send them, such as Delta Lake's merge, whose plan is the extension of
    # a relation of a message that holds the plan of its source DataFrame
    # (relation.merge_into_table.source.CopyFrom(source._plan.plan(session))): the core replaces
    # the placeholder of the DataFrame in the message, of a type that it does not know, so the
    # server receives the relation of the DataFrame there. So does a plugin's command.
    import pyspark.sql.connect.proto as pb2
    from pyspark.sql.connect.dataframe import DataFrame
    from pyspark.sql.connect.plan import LogicalPlan
    from pyspark.sql.connect.proto import example_plugins_pb2 as plugins

    class PluginPlan(LogicalPlan):
        # The plan of a plugin's relation over its input, as Spark's example plugin defines it.
        def plan(self, session):
            plan = self._create_proto_relation()
            plugin = plugins.ExamplePluginRelation(custom_field="c")
            plugin.input.subquery_alias.input.CopyFrom(self._child.plan(session))
            plugin.input.subquery_alias.alias = "s"
            plan.extension.Pack(plugin)
            return plan

    spark, service = mock_connect
    source = spark.range(3).withColumnRenamed("id", "k")
    relation = pb2.Relation.FromString(source._relation_bytes())
    DataFrame(PluginPlan(source._plan), spark).collect()
    sent = plugins.ExamplePluginRelation()
    request = pb2.ExecutePlanRequest.FromString(service.execute_requests[-1])
    assert request.plan.root.extension.Unpack(sent)
    assert sent.custom_field == "c" and sent.input.subquery_alias.alias == "s"
    assert sent.input.subquery_alias.input == relation

    command = pb2.Command()
    command.extension.Pack(plugins.ExamplePluginRelation(input=source._plan.plan(spark.client)))
    spark.client.execute_command(command)
    request = pb2.ExecutePlanRequest.FromString(service.execute_requests[-1])
    assert request.plan.command.extension.Unpack(sent) and sent.input == relation


class _GcCounted:
    """An object of a class without a free list, whose each allocation the collector counts."""


def test_objects_traversed_while_they_are_created_do_not_crash(mock_connect):
    # The garbage collector of Python 3.11 can traverse an object of the extension while it is
    # created: object.__new__ tracks the object that it allocates, then allocates its __dict__,
    # which starts a collection when the free list of dicts is empty, before the value of the
    # object is written. The __traverse__ of the writers, the readers and their copies read the
    # zeroed memory of their state there, a null Arc or Py, and crashed the interpreter. A
    # collection at every second allocation (threshold 1), with the free list of dicts emptied and
    # the allocations before each object shifted by one, meets each kind of object there: also the
    # grouped data, the cogroups, the table arguments, the window specifications, the null and
    # statistics functions, the merge clauses, the stream writers, the data source registrations
    # and the session builders, and their copies, the rows of toLocalIterator, the expressions
    # of Columns and table arguments, and their copies, the plan objects of DataFrames
    # (`df._plan`) and their copies, the array, map, field and struct types,
    # which a schema of the server makes too, and the sessions, the catalogs and the registrations
    # of a Python subclass, which keeps its __dict__, and the objects that an unpickle makes
    # without arguments.
    import copy
    import gc

    from pyspark.sql import Window
    from pyspark.sql import functions as F
    from pyspark.sql.connect.catalog import Catalog
    from pyspark.sql.connect.client import DefaultChannelBuilder
    from pyspark.sql.connect.datasource import DataSourceRegistration
    from pyspark.sql.connect.session import SparkSession as ConnectSession
    from pyspark.sql.observation import Observation

    class SubSession(ConnectSession):
        pass

    class SubCatalog(Catalog):
        pass

    class SubRegistration(DataSourceRegistration):
        pass

    spark, _ = mock_connect
    df = spark.range(1)
    writer, writer_v2 = df.write, df.writeTo("t")
    reader, stream_reader = spark.read, spark.readStream
    group, table, window = df.groupBy("id"), df.asTable(), Window.partitionBy("id")
    cogroup, merge = group.cogroup(group), df.mergeInto("t", F.lit(True))
    na, stat, clause, stream_writer = df.na, df.stat, merge.whenMatched(), df.writeStream
    data_source = spark.dataSource
    builder = ConnectSession.builder._registerHook(lambda session: None).channelBuilder(
        DefaultChannelBuilder("sc://localhost"))
    column = F.col("id") + 1
    array, kv = T.ArrayType(T.DecimalType(10, 2)), T.MapType(T.StringType(), T.LongType())
    field = T.StructField("a", T.DecimalType(10, 2))
    struct = T.StructType([field])
    makers = [
        lambda: df.write, lambda: copy.copy(writer), lambda: df.writeTo("t"),
        lambda: copy.copy(writer_v2), lambda: df.mergeInto("t", F.lit(True)),
        lambda: spark.read, lambda: copy.copy(reader), lambda: spark.readStream,
        lambda: copy.copy(stream_reader), lambda: Observation("o"), lambda: df.select("id"),
        lambda: F.col("id"), lambda: df.groupBy("id"), lambda: copy.copy(group),
        lambda: group.pivot("id", [1]), lambda: group.cogroup(group), lambda: copy.copy(cogroup),
        lambda: df.asTable(), lambda: table.partitionBy("id"), lambda: copy.copy(table),
        lambda: Window.partitionBy("id"), lambda: window.orderBy("id"),
        lambda: window.rowsBetween(-1, 1), lambda: df.na, lambda: copy.copy(na),
        lambda: df.stat, lambda: copy.copy(stat), lambda: merge.whenMatched(),
        lambda: merge.whenNotMatched(F.col("id") > 0), lambda: merge.whenNotMatchedBySource(),
        lambda: copy.copy(clause), lambda: copy.copy(merge), lambda: df.writeStream,
        lambda: copy.copy(stream_writer), lambda: spark.dataSource,
        lambda: copy.copy(data_source), lambda: type(data_source)(spark),
        lambda: ConnectSession.builder, lambda: ConnectSession.Builder(),
        lambda: copy.copy(builder), lambda: df.toLocalIterator(),
        lambda: F.col("id")._expr, lambda: copy.copy(column._expr),
        lambda: copy.deepcopy(column._expr), lambda: table._subquery_expr,
        lambda: T.ArrayType(T.DecimalType(10, 2)),
        lambda: copy.deepcopy(array), lambda: T.MapType(T.StringType(), T.LongType()),
        lambda: copy.deepcopy(kv), lambda: T.StructField("a", T.DecimalType(10, 2)),
        lambda: copy.deepcopy(field), lambda: T.StructType([T.StructField("a", T.LongType())]),
        lambda: copy.deepcopy(struct), lambda: struct.toNullable(), lambda: df.schema,
        lambda: ConnectSession.__new__(ConnectSession), lambda: SubSession.__new__(SubSession),
        lambda: Catalog(spark), lambda: SubCatalog(spark), lambda: copy.copy(SubCatalog(spark)),
        lambda: SubRegistration(spark), lambda: copy.copy(SubRegistration(spark)),
        lambda: DataSourceRegistration.__new__(DataSourceRegistration),
        lambda: type(reader).__new__(type(reader)),
        lambda: type(stream_reader).__new__(type(stream_reader)),
        lambda: df._plan, lambda: copy.copy(df._plan), lambda: copy.deepcopy(df._plan),
    ]
    # The objects whose parts hold the function of a UDF, which make the Python objects of the
    # parts that they share as they are created (see `crate::gc`).
    udf = F.udf(lambda x: x, "long")("id")
    of_udf = df.select(udf.alias("v"), "id")
    makers += [
        lambda: F.udf(lambda x: x, "long")("id"), lambda: df.select(udf), lambda: udf + 1,
        lambda: of_udf.filter("v > 0"), lambda: of_udf.groupBy("v"), lambda: of_udf.asTable(),
        lambda: Window.partitionBy(udf), lambda: of_udf.write, lambda: of_udf.writeStream,
        lambda: of_udf.writeTo("t").partitionedBy(udf), lambda: of_udf.na, lambda: of_udf.stat,
        lambda: of_udf.mergeInto("t", udf > 0).whenMatched(udf > 1), lambda: udf._expr,
        lambda: copy.copy(of_udf), lambda: of_udf.toLocalIterator(),
        lambda: of_udf.groupBy("v").cogroup(of_udf.groupBy("id")), lambda: of_udf._plan,
        lambda: copy.deepcopy(of_udf._plan),
    ]
    thresholds = gc.get_threshold()
    gc.collect()
    gc.set_threshold(1)
    try:
        for make in makers:
            for shift in range(4):
                dicts = [{} for _ in range(100)]
                counted = [_GcCounted() for _ in range(shift)]
                made = make()
                del dicts, counted, made
    finally:
        gc.set_threshold(*thresholds)
    gc.collect()


def test_subquery_aliases_of_python_plans_send_the_relations_of_their_dataframes(mock_connect):
    # As PySpark's SubqueryAlias of pyspark.sql.connect.plan over the plan of a DataFrame, which
    # Delta Lake's DeltaTable.alias builds over its own plans, and the views of its SQL, which are
    # such aliases in the references of a WithRelations: the server receives the relation of the
    # DataFrame, of which the plan holds a placeholder, there and in the message of a plugin's
    # extension under an alias. The Observations of the DataFrame are those of the alias.
    import pyspark.sql.connect.proto as pb2
    from pyspark.sql import Observation
    from pyspark.sql import functions as F
    from pyspark.sql.connect.dataframe import DataFrame
    from pyspark.sql.connect.plan import SQL, LogicalPlan, SubqueryAlias
    from pyspark.sql.connect.proto import example_plugins_pb2 as plugins

    class PluginPlan(LogicalPlan):
        def plan(self, session):
            plan = self._create_proto_relation()
            plan.extension.Pack(plugins.ExamplePluginRelation(input=self._child.plan(session)))
            return plan

    spark, service = mock_connect
    source = spark.range(3).withColumnRenamed("id", "k")
    relation = pb2.Relation.FromString(source._relation_bytes())

    def sent():
        return pb2.ExecutePlanRequest.FromString(service.execute_requests[-1]).plan.root

    DataFrame(SubqueryAlias(SubqueryAlias(source._plan, "s"), "t"), spark).collect()
    assert sent().subquery_alias.alias == "t"
    assert sent().subquery_alias.input.subquery_alias.input == relation

    DataFrame(SQL("SELECT * FROM v", views=[SubqueryAlias(source._plan, "v")]), spark).collect()
    assert sent().with_relations.references[0].subquery_alias.input == relation

    DataFrame(SubqueryAlias(PluginPlan(source._plan), "p"), spark).collect()
    plugin = plugins.ExamplePluginRelation()
    assert sent().subquery_alias.input.extension.Unpack(plugin) and plugin.input == relation

    observation = Observation("o")
    observed = source.observe(observation, F.count(F.lit(1)).alias("c"))
    batch, metrics = _count_batch_and_observed_metrics(service, observed)
    service.execute_payload = batch + metrics("o", varint_field(7, 3), "c")
    assert DataFrame(SubqueryAlias(observed._plan, "s"), spark).count() == 3
    assert observation.get == {"c": 3}


def test_plans_and_commands_built_in_python_send_the_relations_of_their_dataframes(mock_connect):
    # As PySpark's plans and commands over the plan of a DataFrame: the server receives the
    # relation of the DataFrame, of which the plan holds a placeholder, under any relation built
    # with pyspark.sql.connect.proto, such as those that SparkSession.client is given, both sides
    # of a join included, and as the relation of a command. The Observations of the DataFrames of
    # a DataFrame of such a plan are those that PySpark's plan collects: both sides of a join.
    import pyspark.sql.connect.proto as pb2
    from pyspark.sql import Observation
    from pyspark.sql import functions as F
    from pyspark.sql.connect.dataframe import DataFrame
    from pyspark.sql.connect.plan import LogicalPlan

    spark, service = mock_connect
    client = spark.client
    source = spark.range(3).withColumnRenamed("id", "k")
    other = spark.range(5)
    relation = pb2.Relation.FromString(source._relation_bytes())
    other_relation = pb2.Relation.FromString(other._relation_bytes())

    def sent():
        return pb2.ExecutePlanRequest.FromString(service.execute_requests[-1]).plan

    plan = pb2.Plan()
    plan.root.limit.input.project.input.CopyFrom(source._plan.plan(client))
    plan.root.limit.limit = 2
    list(client.to_table_as_iterator(plan, {}))
    assert sent().root.limit.input.project.input == relation

    plan = pb2.Plan()
    plan.root.join.left.CopyFrom(source._plan.plan(client))
    plan.root.join.right.CopyFrom(other._plan.plan(client))
    list(client.to_table_as_iterator(plan, {}))
    assert (sent().root.join.left, sent().root.join.right) == (relation, other_relation)

    command = pb2.Command()
    command.create_dataframe_view.input.CopyFrom(source._plan.plan(client))
    command.create_dataframe_view.name = "v"
    client.execute_command(command)
    assert sent().command.create_dataframe_view.input == relation
    command = pb2.Command()
    command.write_operation.input.filter.input.CopyFrom(source._plan.plan(client))
    command.write_operation.source = "noop"
    client.execute_command(command)
    assert sent().command.write_operation.input.filter.input == relation

    class JoinPlan(LogicalPlan):
        def __init__(self, left, right):
            super().__init__(None)
            self._left, self._right = left, right

        def plan(self, session):
            plan = self._create_proto_relation()
            plan.join.left.CopyFrom(self._left.plan(session))
            plan.join.right.CopyFrom(self._right.plan(session))
            return plan

    left, right = Observation("l"), Observation("r")
    observed_left = source.observe(left, F.count(F.lit(1)).alias("c"))
    observed_right = other.observe(right, F.count(F.lit(1)).alias("c"))
    batch, left_metrics = _count_batch_and_observed_metrics(service, observed_left)
    _, right_metrics = _count_batch_and_observed_metrics(service, observed_right)
    service.execute_payload = (
        batch + left_metrics("l", varint_field(7, 3), "c")
        + right_metrics("r", varint_field(7, 5), "c")
    )
    assert DataFrame(JoinPlan(observed_left._plan, observed_right._plan), spark).count() == 3
    assert (left.get, right.get) == ({"c": 3}, {"c": 5})


def test_the_plans_of_dataframes_have_their_observations_as_pyspark(mock_connect):
    # As PySpark Connect's DataFrame._plan, whose LogicalPlan.observations its DataFrame gives the
    # executions of its client: the Observations of the plan by their names, those of observe on
    # it and on its inputs, both sides of a join and of a union, in the order of PySpark's dict,
    # but not a DataFrame observed by a name. A plan of pyspark.sql.connect.plan over it, such as
    # a SubqueryAlias, and a DataFrame of such a plan have them too, and an execution of the
    # client that is given them sets them, as SparkConnectClient.to_table sets them.
    import gc

    import pyspark.sql.connect.proto as pb2
    from pyspark.sql import Observation
    from pyspark.sql import functions as F
    from pyspark.sql.connect.dataframe import DataFrame
    from pyspark.sql.connect.plan import SQL, SubqueryAlias

    spark, service = mock_connect
    client = spark.client
    first, second, other = Observation("a"), Observation("b"), Observation("c")
    count = F.count(F.lit(1)).alias("n")
    source = spark.range(3)
    assert source._plan.observations == {}
    observed = source.observe(first, count).observe("named", count).observe(second, count)
    observations = observed._plan.observations
    assert list(observations) == ["a", "b"]
    assert observations["a"] is first and observations["b"] is second
    right = spark.range(5).observe(other, count)
    assert list(observed.join(right)._plan.observations) == ["a", "b", "c"]
    assert list(right.union(observed)._plan.observations) == ["c", "a", "b"]
    assert list(observed.filter("id > 0").limit(1)._plan.observations) == ["a", "b"]
    alias = SubqueryAlias(observed._plan, "s")
    assert list(alias.observations.items()) == list(observations.items())
    assert list(DataFrame(alias, spark)._plan.observations.items()) == list(observations.items())
    # The views of SQL are its references, not its child, as in PySpark.
    assert SQL("SELECT * FROM v", views=[SubqueryAlias(observed._plan, "v")]).observations == {}

    # An Observation that only the plan holds any more is that Observation, which the plan keeps
    # alive, as PySpark's plan holds it.
    dropped = spark.range(3).observe(Observation("d"), count)
    gc.collect()
    held = dropped._plan.observations["d"]
    assert type(held) is type(first) and held._name == "d"
    assert dropped._plan.observations["d"] is held

    observation = Observation("o")
    single = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    batch, metrics = _count_batch_and_observed_metrics(service, single)
    service.execute_payload = batch + metrics("o", varint_field(7, 3), "c")
    plan = pb2.Plan()
    plan.root.CopyFrom(single._plan.plan(client))
    client.to_table(plan, {})
    assert observation.get == {}
    client.to_table(plan, single._plan.observations)
    assert observation.get == {"c": 3}
    batch, metrics = _count_batch_and_observed_metrics(service, dropped)
    service.execute_payload = batch + metrics("d", varint_field(7, 3), "n")
    plan.root.CopyFrom(dropped._plan.plan(client))
    client.to_table(plan, dropped._plan.observations)
    assert held.get == {"n": 3}


def test_observations_are_pysparks_objects_of_a_live_result(mock_connect):
    # As PySpark Connect's Observation, a plain object: `get` is its `_result`, one dict, which the
    # executions that set its metrics update in place, so a dict read before an action has the
    # metrics after it, what is set on it stays, and a shallow copy shares it, where a deep copy
    # has a copy of it; `_result` is None before the Observation is used, and `_error` is None
    # until the server reports an error. The plan of observe holds the Observation itself, as
    # PySpark's CollectMetrics does, so its _plan.observations is that object, of its subclass and
    # its attributes, once the program dropped it, and a cycle through it is collected. An
    # execution of the client that is given an Observation that is not used for the name of the
    # metrics raises PySpark's AssertionError, of no arguments, when they arrive.
    import copy
    import gc
    import pickle
    import weakref

    import pyspark.sql.connect.proto as pb2
    from pyspark.errors import PySparkAssertionError
    from pyspark.sql import functions as F
    from pyspark.sql.connect.observation import Observation

    spark, service = mock_connect
    client = spark.client
    observation = Observation("o")
    assert observation._result is None and observation._error is None
    df = spark.range(3).observe(observation, F.count(F.lit(1)).alias("c"))
    held = observation.get
    assert held == {} and observation.get is held and observation._result is held
    batch, metrics = _count_batch_and_observed_metrics(service, df)
    service.execute_payload = batch + metrics("o", varint_field(7, 3), "c")
    df.collect()
    assert held == {"c": 3} and observation.get is held
    held["extra"] = 1
    shallow, deep = copy.copy(observation), copy.deepcopy(observation)
    assert shallow.get is held and deep.get == held and deep.get is not held
    unpickled = pickle.loads(pickle.dumps(observation))
    assert unpickled.get == held and unpickled._result == held
    service.execute_payload = batch + metrics("o", varint_field(7, 4), "c")
    df.collect()
    assert held == {"c": 4, "extra": 1} and shallow.get is held
    assert deep.get == {"c": 3, "extra": 1}
    assert observation._error is None

    class Mine(Observation):
        pass

    mine = Mine("m")
    mine.tag = "kept"
    dropped = spark.range(3).observe(mine, F.count(F.lit(1)).alias("c"))
    del mine
    gc.collect()
    (kept,) = dropped._plan.observations.values()
    assert type(kept) is Mine and kept.tag == "kept"
    assert dropped._plan.observations["m"] is kept

    def cycle():
        looped = Mine("cycle")
        looped.frame = spark.range(3).observe(looped, F.count(F.lit(1)).alias("c"))
        return weakref.ref(looped)

    looped = cycle()
    gc.collect()
    assert looped() is None

    plan = pb2.Plan()
    plan.root.CopyFrom(df._plan.plan(client))
    service.execute_payload = batch + metrics("o", varint_field(7, 5), "c")
    unused = Observation("o")
    with pytest.raises(AssertionError) as raised:
        client.to_table(plan, {"o": unused})
    assert type(raised.value) is AssertionError and raised.value.args == ()
    assert isinstance(raised.value._operation_id, str)
    assert unused._result is None
    with pytest.raises(PySparkAssertionError, match="NO_OBSERVE_BEFORE_GET"):
        unused.get
    # The Observations of the plan are used, and an Observation of another name is not read.
    client.to_table(plan, {"other": unused, **df._plan.observations})
    assert held == {"c": 5, "extra": 1}


def test_cycles_through_a_dataframe_of_a_python_plan_are_collected_as_pyspark(mock_connect):
    # As PySpark's DataFrame, a Python object: a cycle through a DataFrame of a Python plan, whose
    # plan keeps an object that keeps the DataFrame (as a pyspark.ml model keeps its summary's
    # model.transform(dataset)), is freed by the garbage collector, while a DataFrame derived from
    # it keeps the plan alive. With a collection at every allocation, the collector also meets
    # DataFrames that are still being created, before their value is written.
    import gc
    import weakref

    from pyspark.sql.connect.dataframe import DataFrame
    from pyspark.sql.connect.plan import LogicalPlan

    spark, _ = mock_connect
    source = spark.range(3)
    relation = source._plan.plan(spark.client)

    class Owner:
        pass

    class Plan(LogicalPlan):
        def plan(self, session):
            return relation

    def cycle():
        owner, plan = Owner(), Plan(None)
        plan.owner = owner
        owner.frame = DataFrame(plan, spark)
        return weakref.ref(owner)

    thresholds = gc.get_threshold()
    gc.set_threshold(1, 1, 1)
    try:
        collected = [cycle() for _ in range(20)]
        kept = cycle()
        derived = kept().frame.select("id").filter("id > 0")
        for _ in range(20):
            spark.range(3).select("id").filter("id > 0")
    finally:
        gc.set_threshold(*thresholds)
    gc.collect()
    assert all(owner() is None for owner in collected)
    assert kept() is not None
    del derived
    gc.collect()
    assert kept() is None


def test_cycles_through_the_plans_of_the_python_client_are_collected_as_pyspark(mock_connect):
    # As PySpark's DataFrames, Columns and the objects that hold them, Python objects that hold
    # their plan objects: a cycle through a plan of the Python client of a DataFrame(plan, session)
    # and an object that alone holds it, through the relation of the DataFrame or the subqueries of
    # the expressions of a plan or of a Column, of a plan that builds or not, is freed by the
    # garbage collector, as is one through the plan that an unpickled Column of the subquery of a
    # DataFrame of a plan that did not build keeps, to build it at its requests, and an unpickled
    # table argument of it. A holder that shares the plan, alive outside the cycle, keeps it alive
    # until it is freed.
    import gc
    import weakref

    from pyspark import cloudpickle
    from pyspark.sql import Window
    from pyspark.sql import functions as F
    from pyspark.sql.connect.dataframe import DataFrame
    from pyspark.sql.connect.plan import Range

    spark, _ = mock_connect
    other = spark.range(3)

    class Sentinel:
        pass

    class Kept(Range):
        def __init__(self, box):
            super().__init__(0, 3, 1)
            self.box = box

    class Failing(Kept):
        def plan(self, session):
            raise ValueError("fails", self.box)

    def scalar(df):
        return df.select(F.max("id")).scalar()

    holders = {
        "the DataFrame": lambda df: df,
        "a DataFrame derived from it": lambda df: df.filter("id > 0"),
        "a DataFrame over a subquery of it": lambda df: spark.range(1).select(scalar(df)),
        "a Column of its subquery": scalar,
        "the expression of a Column of its subquery": lambda df: scalar(df)._expr,
        "a table argument of it": lambda df: df.asTable(),
        "a window specification": lambda df: Window.partitionBy(scalar(df)),
        "an ordered window specification": lambda df: Window.orderBy(scalar(df)),
        "grouped data": lambda df: other.groupBy(scalar(df)),
        "a merge builder": lambda df: other.mergeInto("t", scalar(df) == F.col("id")),
        "a merge clause": lambda df: other.mergeInto("t", F.lit(True)).whenMatched(scalar(df) > 0),
        "a writer": lambda df: other.writeTo("t").partitionedBy(scalar(df)),
    }

    def cycle(plan_class, make):
        box = [Sentinel()]
        box.append(make(DataFrame(plan_class(box), spark)))
        return weakref.ref(box[0])

    for name, make in holders.items():
        for plan_class in (Kept, Failing):
            alive = cycle(plan_class, make)
            gc.collect()
            assert alive() is None, (name, plan_class.__name__)

    @F.udtf(returnType="id bigint")
    class Rows:
        def eval(self, row):
            yield (row["id"],)

    def unpickled_cycle(make, request):
        # The box of the unpickled plan, which the error of a request of the unpickled object
        # gives, keeps the object.
        held = pickle.loads(cloudpickle.dumps(make(DataFrame(Failing([Sentinel()]), spark))))
        with pytest.raises(ValueError) as raised:
            request(held)
        box = raised.value.args[1]
        del raised
        box.append(held)
        return weakref.ref(box[0])

    for make, request in [
        (scalar, lambda column: spark.range(1).select(column).collect()),
        (lambda df: df.asTable(), lambda table: Rows(table).collect()),
    ]:
        alive = unpickled_cycle(make, request)
        gc.collect()
        assert alive() is None

    box = [Sentinel()]
    df = DataFrame(Kept(box), spark)
    box.append(scalar(df))
    alive = weakref.ref(box[0])
    del box
    gc.collect()
    assert alive() is not None
    del df
    gc.collect()
    assert alive() is None


