def test_an_array_of_no_converter_reads_a_sequence_by_its_length_and_items_as_pyarrow(
    mock_connect,
):
    # As PyArrow's list conversion of a value that PySpark passes as it is: a list or a tuple
    # is read as it is stored, another sequence by its length and the item at each index, and
    # a NumPy array has to be one-dimensional. Its errors wait for the converters of the other
    # columns, and the first one in the order of the columns and then the rows is raised.
    import pyarrow as pa

    spark, service = mock_connect

    class GetOnly:
        def __init__(self, values):
            self.values = values

        def __getitem__(self, index):
            return self.values[index]

    class LongLen(GetOnly):
        def __len__(self):
            return len(self.values) + 3

    class ShortLen(GetOnly):
        def __len__(self):
            return 1

    class OwnIter(GetOnly):
        def __len__(self):
            return len(self.values)

        def __iter__(self):
            return iter([9] * len(self.values))

    class List(list):
        def __iter__(self):
            return iter([9] * len(self))

        def __getitem__(self, index):
            return 8

    class Tuple(tuple):
        def __iter__(self):
            return iter([9] * len(self))

        def __getitem__(self, index):
            return 8

    table, _ = _local_rows_relation_of(service, spark.createDataFrame(
        [(ShortLen([5, 6]),), (OwnIter([1, 2]),), (List([3, 4]),), (Tuple((5,)),),
         (np.array([6, 7]),)], "a array<int>"))
    assert table.column(0).to_pylist() == [[5], [1, 2], [3, 4], [5], [6, 7]]

    with pytest.raises(TypeError, match=r"^object of type 'GetOnly' has no len\(\)$"):
        spark.createDataFrame([(GetOnly([1, 2]),)], "a array<int>")
    with pytest.raises(IndexError, match="^list index out of range$"):
        spark.createDataFrame([(LongLen([1, 2]),)], "a array<int>")
    for value in (GetOnly([1]), LongLen([1])):
        with pytest.raises(AssertionError):
            spark.createDataFrame([(value, 0)], "a array<int>, b timestamp")
    with pytest.raises(TypeError, match="has no len"):
        spark.createDataFrame([(GetOnly([1]),), (["x"],)], "a array<int>")
    for rows in ([(["x"],), (GetOnly([1]),)], [(LongLen(["x", 2]),)]):
        with pytest.raises(pa.ArrowInvalid, match="^Could not convert 'x' with type str"):
            spark.createDataFrame(rows, "a array<int>")

    for value, schema, arrow_type in [
        (np.array([[1, 2], [3, 4]]), "a array<int>", "list<element: int32>"),
        (np.array(5), "a array<double>", "list<element: double>"),
        (np.zeros((0, 2)), "a array<date>", "list<element: date32[day]>"),
        (np.array([[1, 2]]), "a array<array<bigint>>", "list<element: list<element: int64>>"),
        ([np.array([[1, 2]])], "a array<array<smallint>>", "list<element: int16>"),
    ]:
        with pytest.raises(pa.ArrowInvalid) as e:
            spark.createDataFrame([(value,)], schema)
        assert str(e.value) == (
            f"Can only convert 1-dimensional array values of {arrow_type} to a variable-sized "
            "list"
        )


def test_nested_duplicate_field_names_are_deduplicated_in_the_arrow_schema(mock_connect):
    # As PySpark's _deduplicate_field_names: the Arrow schema of nested struct fields numbers
    # duplicate names, which the server cannot read, while the schema of the relation keeps
    # the names. A top-level duplicate name is not renamed.
    import pyarrow as pa
    from pyspark.sql import Row
    from pyspark.sql import types as T

    spark, service = mock_connect
    R = Row("a", "a")
    table, schema = _local_rows_relation_of(service, spark.createDataFrame([(R(1, 2),)]))
    assert table.schema.field(0).type == pa.struct([("a_0", pa.int64()), ("a_1", pa.int64())])
    assert table.column(0).to_pylist() == [{"a_0": 1, "a_1": 2}]
    assert [f["name"] for f in schema["fields"][0]["type"]["fields"]] == ["a", "a"]

    explicit = T.StructType([T.StructField("s", T.StructType([
        T.StructField("a", T.LongType()), T.StructField("a", T.LongType())]))])
    table, schema = _local_rows_relation_of(service, spark.createDataFrame([((1, 2),)], explicit))
    assert table.column("s").to_pylist() == [{"a_0": 1, "a_1": 2}]
    assert [f["name"] for f in schema["fields"][0]["type"]["fields"]] == ["a", "a"]

    table, _ = _local_rows_relation_of(service, spark.createDataFrame(
        [([(1, 2)],)], "s array<struct<a:bigint,a:bigint>>"))
    assert table.column("s").to_pylist() == [[{"a_0": 1, "a_1": 2}]]

    table, _ = _local_rows_relation_of(service, spark.createDataFrame(
        [(1, 2)], "a bigint, a bigint"))
    assert table.schema.names == ["a", "a"]
    assert table.column(1).to_pylist() == [2]


# ------------------------------------------------------- DataFrame completion

def _completion_varint(value):
    result = bytearray()
    while value > 127:
        result.append((value & 127) | 128)
        value >>= 7
    result.append(value)
    return bytes(result)


def _completion_message(field, value):
    if isinstance(value, str):
        value = value.encode()
    return _completion_varint(field * 8 + 2) + _completion_varint(len(value)) + value


def _completion_schema(names=("id",)):
    # DataType.struct=21, Struct.fields=1, DataType.long=7.
    return _completion_message(21, b"".join(_completion_message(1, _completion_field(name, _completion_message(7, b"")))
                                  for name in names))


def _completion_field(name, data_type):
    return (_completion_message(1, name) + _completion_message(2, data_type) + b"\x18\x01"
            + _completion_message(4, '{"note":"original"}'))


def _completion_serve(connection):
    from concurrent.futures import ThreadPoolExecutor

    import grpc

    # A separate process also exercises columns/dtypes, whose first access may
    # hold the client's GIL while waiting for the RPC.
    class Service:
        calls = 0
        data_type = _completion_schema()
        failure = None

        def analyze(self, request, context):
            self.calls += 1
            if self.failure == "rpc":
                context.abort(grpc.StatusCode.INVALID_ARGUMENT, "schema unavailable")
            if self.failure == "no-result":
                return b""
            if self.failure == "missing-schema":
                return _completion_message(2, b"")
            if self.failure == "invalid-type":
                return _completion_message(2, _completion_message(1, b""))
            # base.proto: AnalyzePlanResponse.schema=2, Schema.schema=1.
            return _completion_message(2, _completion_message(1, self.data_type))

    service = Service()
    with ThreadPoolExecutor(max_workers=4) as executor:
        server = grpc.server(executor)
        handler = grpc.unary_unary_rpc_method_handler(service.analyze)
        server.add_generic_rpc_handlers((grpc.method_handlers_generic_handler(
            "spark.connect.SparkConnectService", {"AnalyzePlan": handler}),))
        port = server.add_insecure_port("127.0.0.1:0")
        server.start()
        connection.send(port)
        try:
            while True:
                command = connection.recv()
                if command[0] == "stop":
                    break
                if command[0] == "get":
                    connection.send(getattr(service, command[1]))
                elif command[0] == "set":
                    setattr(service, command[1], command[2])
                    connection.send(None)
        finally:
            server.stop(0).wait()


class _CompletionRemoteService:
    def __init__(self, connection):
        object.__setattr__(self, "connection", connection)

    def __getattr__(self, name):
        self.connection.send(("get", name))
        assert self.connection.poll(10), "Mock server did not respond"
        return self.connection.recv()

    def __setattr__(self, name, value):
        self.connection.send(("set", name, value))
        assert self.connection.poll(10), "Mock server did not respond"
        self.connection.recv()


@pytest.fixture
def completion_analyzed():
    import multiprocessing

    from pyspark.sql import SparkSession

    pytest.importorskip("grpc")
    context = multiprocessing.get_context("spawn")
    parent, child = context.Pipe()
    process = context.Process(target=_completion_serve, args=(child,))
    process.start()
    try:
        assert parent.poll(20), "Mock server did not start"
        port = parent.recv()
        spark = SparkSession.builder.remote(f"sc://127.0.0.1:{port}").getOrCreate()
        yield spark, _CompletionRemoteService(parent)
    finally:
        if process.is_alive():
            parent.send(("stop",))
        process.join(10)
        if process.is_alive():
            process.terminate()
            process.join(10)
        parent.close()
        child.close()


@pytest.mark.parametrize("value, wire_type", [
    (-(2**63), "long"),
    (-(2**31) - 1, "long"),
    (-(2**31), "integer"),
    (-1, "integer"),
    (0, "integer"),
    (2**31 - 1, "integer"),
    (2**31, "long"),
    (2**63 - 1, "long"),
])
def test_integer_literal_wire_boundaries(value, wire_type):
    from enum import IntEnum

    from pyspark.sql import functions as F
    from pyspark.sql.connect import proto

    class IntegerSubclass(int):
        pass

    class IntegerEnum(IntEnum):
        VALUE = value

    expected = proto.Expression.Literal()
    setattr(expected, wire_type, value)
    for scalar in (value, IntegerSubclass(value), IntegerEnum.VALUE):
        literal = F.lit(scalar)._expr.to_plan(None).literal
        compared = (F.col("id") == scalar)._expr.to_plan(None)
        assert literal == expected
        assert compared.unresolved_function.arguments[1].literal == expected


def test_exact_primitive_literals_skip_numpy_probes(monkeypatch):
    import sys
    from enum import IntEnum

    from pyspark import _pyspark
    from pyspark.sql import functions as F
    from pyspark.sql.connect import proto

    class IntegerSubclass(int):
        pass

    class FloatSubclass(float):
        pass

    class StringSubclass(str):
        pass

    class BytesSubclass(bytes):
        pass

    class ByteArraySubclass(bytearray):
        pass

    class IntegerEnum(IntEnum):
        VALUE = 5

    class ProbeSentinel:
        @property
        def ndarray(self):
            raise RuntimeError("NumPy probe reached")

    exact = [
        (None, proto.Expression.Literal(null=proto.DataType(null=proto.DataType.NULL()))),
        (True, proto.Expression.Literal(boolean=True)),
        (5, proto.Expression.Literal(integer=5)),
        (1.25, proto.Expression.Literal(double=1.25)),
        ("x", proto.Expression.Literal(string="x")),
        (b"x", proto.Expression.Literal(binary=b"x")),
        (bytearray(b"x"), proto.Expression.Literal(binary=b"x")),
    ]
    for value, expected in exact:
        assert F.lit(value)._expr.to_plan(None).literal == expected

    with monkeypatch.context() as patch:
        patch.setitem(sys.modules, "numpy", ProbeSentinel())
        for value, expected in exact:
            literal = _pyspark.functions.pyfunc_lit(value)._expr.to_plan(None).literal
            assert literal == expected
        for value in (
            IntegerSubclass(5),
            FloatSubclass(1.25),
            StringSubclass("x"),
            BytesSubclass(b"x"),
            ByteArraySubclass(b"x"),
            IntegerEnum.VALUE,
            2**63,
        ):
            with pytest.raises(RuntimeError, match="NumPy probe reached"):
                _pyspark.functions.pyfunc_lit(value)


@pytest.mark.parametrize("method", ["isin", "getItem", "__getitem__", "when", "otherwise"])
def test_column_value_primitives_skip_numpy_probes(monkeypatch, method):
    import sys
    from enum import IntEnum

    from pyspark.sql import functions as F

    class IntegerEnum(IntEnum):
        VALUE = 5

    class ProbeSentinel:
        @property
        def ndarray(self):
            raise RuntimeError("NumPy probe reached")

    column = F.col("a")
    condition = column > 0
    when = F.when(condition, 0)
    if method == "when":
        build = lambda value: when.when(condition, value)
    elif method == "otherwise":
        build = when.otherwise
    else:
        build = getattr(column, method)

    def literal(value):
        plan = build(value)._expr.to_plan(None)
        if method in ("getItem", "__getitem__"):
            return plan.unresolved_extract_value.extraction.literal
        index = {"isin": 1, "when": 3, "otherwise": 2}[method]
        return plan.unresolved_function.arguments[index].literal

    values = [
        False, True, -(2**63), -(2**31) - 1, -(2**31), 0, 2**31 - 1, 2**31, 2**63 - 1,
        -0.0, 1.25, float("inf"), float("nan"), "", "雪", b"", b"\x00\xff",
        bytearray(), bytearray(b"\x00\xff"),
    ]
    expected = [F.lit(value)._expr.to_plan(None).literal.SerializeToString() for value in values]
    subclasses = [type(f"{type(value).__name__}Subclass", (type(value),), {})(value)
                  for value in (5, 1.25, "x", b"x", bytearray(b"x"))]
    with monkeypatch.context() as patch:
        patch.setitem(sys.modules, "numpy", ProbeSentinel())
        for value, wire in zip(values, expected):
            # Serialized literals also distinguish signed zero and compare NaN reliably.
            assert literal(value).SerializeToString() == wire
        # A str that UTF-8 cannot encode is a literal, whose plan fails when it is built.
        with pytest.raises(UnicodeEncodeError):
            literal("\ud800")
        for value in [*subclasses, IntegerEnum.VALUE, 2**63, -(2**63) - 1]:
            with pytest.raises(RuntimeError, match="NumPy probe reached"):
                build(value)


def test_boolean_literals_keep_their_wire_type():
    from pyspark.sql import functions as F
    from pyspark.sql.connect import proto

    for value in (False, True):
        expected = proto.Expression.Literal(boolean=value)
        assert F.lit(value)._expr.to_plan(None).literal == expected
        compared = (F.col("flag") == value)._expr.to_plan(None)
        assert compared.unresolved_function.arguments[1].literal == expected


def test_int_literals_beyond_a_long_raise_value_not_between_as_pyspark():
    # As PySpark's LiteralExpression._infer_type: an int beyond the range of a long is an error,
    # not a double, which would make `col == 2**63` match the rows of the longs next to it. The
    # maximum is JVM_SHORT_MAX, as PySpark writes it. fillna sends the value as a proto literal,
    # which raises ValueError for it when the plan is built.
    from pyspark.errors import PySparkValueError
    from pyspark.sql import functions as F

    spark = _offline_session()
    df = spark.range(1)
    for case in (
        lambda: F.lit(2**70),
        lambda: F.lit(-(2**63) - 1),
        lambda: F.col("id") == 2**63,
        lambda: F.col("id") > 2**70,
        lambda: F.col("id").isin([1, 2**70]),
        lambda: F.col("id").between(1, 2**70),
        lambda: F.when(F.col("id") > 0, 2**70),
        lambda: F.array(F.lit(1), F.lit(2**70)),
        lambda: F.lit([2**70]),
    ):
        with pytest.raises(PySparkValueError) as e:
            case()
        assert e.value.getCondition() == "VALUE_NOT_BETWEEN"
        assert e.value.getMessageParameters() == {
            "arg_name": "value", "min": "-9223372036854775808", "max": "32767"}
    # fillna sets its value in the long field of a literal when its plan is built, which raises.
    filled = df.fillna(2**70)
    with pytest.raises(ValueError, match="Value out of range: 1180591620717411303424"):
        filled.collect()
    # The bounds of a long, and a float beyond them, are fine.
    assert F.lit(2**63 - 1) is not None and F.lit(-(2**63)) is not None
    assert F.lit(2.0**70) is not None
    spark.stop()


@pytest.mark.parametrize("names", [
    ["z", "a"],
    ["with space", "a.b", "with`tick", "", "123", "class", "雪", "_private"],
    ["id", "id", "select", "columns", "__dir__", "_ipython_key_completions_"],
    [],
])
def test_completion_matches_python_connect(completion_analyzed, names):
    from pyspark.sql import Column

    spark, service = completion_analyzed
    service.data_type = _completion_schema(names)
    df = spark.range(10)
    assert df._ipython_key_completions_() == names
    assert service.calls == 1
    expected = sorted(set(dir(type(df))) | set(names))
    # Each first access must analyze its own fresh plan, with or without caching.
    assert spark.range(10).__dir__() == expected
    assert service.calls == 2
    assert dir(spark.range(10)) == expected
    assert service.calls == 3
    assert callable(df.select)
    assert callable(df.__dir__)
    assert callable(df._ipython_key_completions_)
    assert df.columns == names
    for name in names:
        assert isinstance(df[name], Column)
    assert df.schema.fieldNames() == names


def test_ddl_schemas_are_parsed_on_the_server_as_pyspark(mock_connect):
    # As PySpark Connect's `_parse_ddl`, which asks the server to parse a DDL schema, of
    # createDataFrame and of the map functions; a type is sent as it is.
    spark, service = mock_connect

    def ddl_requests():
        # base.proto: AnalyzePlanRequest.ddl_parse=11, DDLParse.ddl_string=1.
        return [parse_message(parse_message(request)[11][0])[1][0].decode()
                for request in service.analyze_requests if 11 in parse_message(request)]

    def sent_local_schema():
        # The LocalRelation of the type that the server parsed: AnalyzePlanRequest.schema=4 ->
        # plan=1 -> root=1 -> (Relation.to_df=18 -> input=1 ->) local_relation=11 -> schema=2.
        relation = parse_message(parse_message(parse_message(
            parse_message(service.analyze_requests[-1])[4][0])[1][0])[1][0])
        while 18 in relation:
            relation = parse_message(parse_message(relation[18][0])[1][0])
        return T._parse_datatype_json_string(parse_message(relation[11][0])[2][0].decode())

    spark.createDataFrame([], "id long").columns
    assert sent_local_schema().simpleString() == "struct<id:bigint>"
    nested = "id struct<a:int,b:double> NOT NULL"
    spark.createDataFrame([], nested).columns
    assert sent_local_schema() == T.StructType([T.StructField("id", T.StructType([
        T.StructField("a", T.IntegerType()), T.StructField("b", T.DoubleType())]), False)])
    assert ddl_requests() == ["id long", nested]
    df = spark.range(1)
    df.mapInPandas(lambda it: it, "id long NOT NULL")
    df.mapInArrow(lambda it: it, "id long COMMENT 'c'")
    df.groupBy("id").applyInPandas(lambda pdf: pdf, "`id` long")
    df.groupBy("id").cogroup(df.groupBy("id")).applyInArrow(lambda left, right: left, "id: long")
    assert ddl_requests()[2:] == [
        "id long NOT NULL", "id long COMMENT 'c'", "`id` long", "id: long"]
    df.mapInPandas(lambda it: it, T.StructType([T.StructField("id", T.LongType())]))
    assert len(ddl_requests()) == 6


def test_completion_lists_are_independent(completion_analyzed):
    spark, service = completion_analyzed
    df = spark.range(10)
    df._ipython_key_completions_().append("extra")
    df.__dir__().clear()
    assert df._ipython_key_completions_() == ["id"]
    assert "select" in dir(df)
    service.data_type = _completion_schema(["changed"])
    assert spark.range(10)._ipython_key_completions_() == ["changed"]


@pytest.mark.parametrize("method", ["__dir__", "_ipython_key_completions_"])
@pytest.mark.parametrize("failure", ["rpc", "no-result", "missing-schema", "invalid-type"])
def test_completion_propagates_schema_errors_and_can_retry(completion_analyzed, method, failure):
    spark, service = completion_analyzed
    df = spark.range(10)
    service.failure = failure
    message = {
        "rpc": "schema unavailable",
        "no-result": "no schema in response",
        "missing-schema": "Schema is missing",
        "invalid-type": "DataType kind not set",
    }[failure]
    for count in (1, 2):
        with pytest.raises(Exception, match=message):
            getattr(df, method)()
        assert service.calls == count
    service.failure = None
    assert "id" in getattr(df, method)()
    assert service.calls == 3


