def test_star_import_of_functions_exports_the_official_names_only():
    # A star import brings in exactly the names of PySpark's __all__. The names that PySpark has
    # only as attributes (chr, random, uuid, ...) are not exported, so they do not shadow the
    # builtin chr and the stdlib random and uuid; nor are the avro and protobuf functions, which
    # PySpark has in pyspark.sql.avro.functions and pyspark.sql.protobuf.functions.
    import builtins

    from pyspark.sql import functions as F

    assert F.__all__ == OFFICIAL_FUNCTIONS_ALL
    namespace = {}
    exec("from pyspark.sql.functions import *", namespace)
    namespace.pop("__builtins__")
    assert list(namespace) == OFFICIAL_FUNCTIONS_ALL
    for name in ("chr", "random", "uuid", "countDistinct", "bitwiseNOT", "toDegrees",
                 "approxCountDistinct"):
        assert name not in namespace
        assert callable(getattr(F, name))
    assert F.random is F.rand
    assert "chr" not in namespace and builtins.chr(65) == "A"
    for name in ("from_avro", "from_avro_with_options", "to_avro", "to_avro_with_schema",
                 "from_protobuf", "to_protobuf"):
        assert name not in namespace
        assert not hasattr(F, name)


def test_avro_and_protobuf_functions_are_on_their_official_modules(tmp_path, mock_connect):
    import pyspark.sql.avro.functions as avro
    import pyspark.sql.protobuf.functions as protobuf
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import functions as F

    spark, service = mock_connect
    c = F.col("v")
    assert type(avro.from_avro(c, "{}")).__name__ == "Column"
    assert type(avro.from_avro("v", "{}", {"mode": "PERMISSIVE"})).__name__ == "Column"
    assert type(avro.to_avro(c)).__name__ == "Column"
    assert type(avro.to_avro(c, "{}")).__name__ == "Column"
    with pytest.raises(PySparkTypeError) as error:
        avro.from_avro(1, "{}")
    assert error.value.getCondition() == "INVALID_TYPE"
    assert error.value.getMessageParameters() == {
        "arg_name": "data", "arg_type": "pyspark.sql.Column or str"}
    # As PySpark's, the descriptor file is read (it was ignored before), and the bytes reach the
    # server as the binary of the function's descriptor set.
    descriptor = tmp_path / "m.desc"
    descriptor.write_bytes(b"\x00fue-e-descriptor\xff")
    spark.range(1).select(protobuf.from_protobuf(F.col("id"), "M", descFilePath=str(descriptor))).collect()
    assert b"\x00fue-e-descriptor\xff" in service.execute_requests[-1]


def test_avro_and_protobuf_functions_take_their_strings_as_literals_as_pyspark(mock_connect):
    # As PySpark's: the schema of from_avro and to_avro, and the message name and the descriptor
    # set of from_protobuf and to_protobuf, are `lit` of the values as they are given, which a
    # request sets when it builds the plan, and which the server reads. So a str that UTF-8
    # cannot encode fails each DataFrame of the Column, and not the call, and a message name or a
    # descriptor set of another type is sent as its literal, as PySpark does not check them.
    import pyspark.sql.avro.functions as avro
    import pyspark.sql.protobuf.functions as protobuf
    from pyspark.sql.connect.proto import base_pb2

    spark, service = mock_connect
    df = spark.range(1)
    unencodable = "'utf-8' codec can't encode character '\\ud800' in position 1: surrogates not allowed"
    for column in (
        avro.from_avro("id", "a\ud800"),
        avro.from_avro("id", "a\ud800", {"k": "v"}),
        avro.to_avro("id", "a\ud800"),
        protobuf.from_protobuf("id", "a\ud800"),
        protobuf.to_protobuf("id", "a\ud800", options={"k": "v"}),
        protobuf.from_protobuf("id", "m", binaryDescriptorSet="a\ud800"),
    ):
        with pytest.raises(UnicodeEncodeError) as error:
            df.select(column).schema
        assert str(error.value) == unencodable
    assert service.analyze_requests == []

    def sent(column):
        # The function and the literals of its arguments after the first, as they are sent.
        df.select(column).collect()
        root = base_pb2.ExecutePlanRequest.FromString(service.execute_requests[-1]).plan.root
        function = root.project.expressions[0].unresolved_function
        literals = [argument.literal for argument in function.arguments[1:]]
        return function.function_name, [
            getattr(literal, literal.WhichOneof("literal_type")) for literal in literals]

    assert sent(avro.from_avro("id", "{}")) == ("from_avro", ["{}"])
    assert sent(avro.to_avro("id", "{}")) == ("to_avro", ["{}"])
    assert sent(protobuf.from_protobuf("id", 5)) == ("from_protobuf", [5])
    assert sent(protobuf.to_protobuf("id", b"m")) == ("to_protobuf", [b"m"])
    null = sent(protobuf.from_protobuf("id", None, binaryDescriptorSet="x"))
    assert null[0] == "from_protobuf" and null[1][1] == "x"
    assert sent(protobuf.from_protobuf("id", "m", binaryDescriptorSet=b"\x00d")) == (
        "from_protobuf", ["m", b"\x00d"])


def test_numpy_scalar_literals_are_typed_by_their_dtype_as_pyspark(mock_connect):
    import struct

    np = pytest.importorskip("numpy")
    from pyspark.sql import functions as F

    spark, service = mock_connect
    # As PySpark's LiteralExpression of a NumPy scalar, typed by its dtype: a bool, a signed int
    # of 8 to 64 bits (tinyint to bigint), float32 (float) and float64 (double). The Literal
    # fields are: boolean=3, byte=4, short=5, integer=6, long=7, float=10, double=11, string=13,
    # binary=2.
    cases = [
        (np.bool_(True), 3, 1),
        (np.int8(5), 4, 5),
        (np.int16(5), 5, 5),
        (np.int32(5), 6, 5),
        (np.int64(5), 7, 5),
        (np.int64(2**40), 7, 2**40),
        (np.float32(1.5), 10, struct.pack("<f", 1.5)),
        (np.float64(1.5), 11, struct.pack("<d", 1.5)),
        (np.str_("abc"), 13, b"abc"),
        (np.bytes_(b"ab"), 2, b"ab"),
        # A Python int and float keep their types: int (integer) and double.
        (5, 6, 5),
        (1.5, 11, struct.pack("<d", 1.5)),
    ]
    for value, field, expected in cases:
        spark.range(1).select(F.lit(value)).collect()
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
        expression = parse_message(parse_message(parse_message(plan)[3][0])[3][0])
        literal = parse_message(expression[1][0])
        assert sorted(literal) == [field], repr(value)
        assert literal[field] == [expected], repr(value)


def test_numpy_scalars_of_other_types_are_unsupported_as_pyspark(mock_connect):
    np = pytest.importorskip("numpy")
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import functions as F

    # As PySpark's, the unsupported NumPy scalars are UNSUPPORTED_DATA_TYPE, named by their
    # Python type; and an array of an unsupported dtype is UNSUPPORTED_NUMPY_ARRAY_SCALAR.
    for value, type_name in [
        (np.uint8(5), "uint8"),
        (np.uint64(5), "uint64"),
        (np.float16(1.5), "float16"),
        (np.complex128(1 + 2j), "complex128"),
        (np.datetime64("2020-01-01"), "datetime64"),
        (np.timedelta64(1, "D"), "timedelta64"),
    ]:
        with pytest.raises(PySparkTypeError) as error:
            F.lit(value)
        assert error.value.getCondition() == "UNSUPPORTED_DATA_TYPE"
        assert error.value.getMessageParameters() == {"data_type": type_name}
    with pytest.raises(PySparkTypeError) as error:
        F.lit(np.array([1], dtype=np.uint8))
    assert error.value.getCondition() == "UNSUPPORTED_NUMPY_ARRAY_SCALAR"
    assert error.value.getMessageParameters() == {"dtype": "uint8"}


def test_map_with_user_defined_keys_is_built_from_the_deserialized_keys():
    # The Rust client passes a map whose keys have a user-defined type as its (key, value) pairs,
    # so that the converter deserializes the keys before it builds the dict, as PySpark does.
    from pyspark.sql.types import _udt_field_converters

    schema = T.StructType([
        T.StructField("m", T.MapType(_DayPointUDT(), T.IntegerType())),
        T.StructField("n", T.MapType(T.StringType(), _DayPointUDT())),
    ])
    m, n = _udt_field_converters(schema)
    assert m([([1.0, 2.0], 1), ([3.0, 4.0], None)]) == {(1.0, 2.0): 1, (3.0, 4.0): None}
    assert m(None) is None
    assert m([]) == {}
    assert n({"x": [1.0, 2.0]}) == {"x": (1.0, 2.0)}
    assert n({}) == {}


def test_numpy_longdouble_scalar_matches_dtype_and_class_checks_as_pyspark():
    np = pytest.importorskip("numpy")
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import functions as F

    value = np.longdouble(1.5)
    if isinstance(value, (float, np.float32, np.float64)):
        pytest.skip("longdouble aliases a supported float scalar class here")
    if value.dtype == np.dtype("float64"):
        # A dtype mapping to DoubleType does not suffice: PySpark also asserts that its
        # scalar is a float, np.float32 or np.float64. Distinct eight-byte longdouble
        # classes (such as on macOS arm64 and Windows) fail without a message.
        with pytest.raises(AssertionError) as error:
            F.lit(value)
        assert error.value.args == ()
    else:
        # Linux CI normally has a wider longdouble, which exercises the unsupported
        # dtype path; the distinct integer aliases below exercise the class check there.
        with pytest.raises(PySparkTypeError) as error:
            F.lit(value)
        assert error.value.getCondition() == "UNSUPPORTED_DATA_TYPE"
        assert error.value.getMessageParameters() == {"data_type": type(value).__name__}


def test_numpy_longdouble_array_matches_dtype_and_element_checks_as_pyspark():
    np = pytest.importorskip("numpy")
    from pyspark.errors import PySparkTypeError
    from pyspark.sql import functions as F

    value = np.array([1.5], dtype=np.longdouble)
    if isinstance(value[0], (float, np.float32, np.float64)):
        pytest.skip("longdouble aliases a supported float scalar class here")
    if value.dtype == np.dtype("float64"):
        # A mapped array dtype still builds its literals through each scalar's checks.
        with pytest.raises(AssertionError) as error:
            F.lit(value)
        assert error.value.args == ()
    else:
        with pytest.raises(PySparkTypeError) as error:
            F.lit(value)
        assert error.value.getCondition() == "UNSUPPORTED_NUMPY_ARRAY_SCALAR"
        assert error.value.getMessageParameters() == {"dtype": value.dtype.name}


