def test_the_retry_policies_of_a_client_are_the_ones_it_was_given_as_pysparks(mock_connect):
    # As PySpark's `set_retry_policies` and `get_retry_policies` (test_retry_client_unit), which
    # keep the policy objects of the client: those of a client of a session of its own, of its
    # newSession and its clone, and of a session that the program dropped while a DataFrame holds
    # it, are the objects that were set, of their classes.
    import gc

    from pyspark.sql.connect.client import SparkConnectClient
    from pyspark.sql.connect.client.retries import DefaultPolicy

    spark, service = mock_connect

    class MyPolicy(DefaultPolicy):
        pass

    policy = DefaultPolicy(max_retries=3)
    mine = MyPolicy(max_retries=2)
    client = SparkConnectClient(service.remote)
    clients = [client, client.newSession(), client.clone()]
    for each in clients:
        each.set_retry_policies([policy])
        gc.collect()
        assert each.get_retry_policies()[0] is policy
        each.set_retry_policies([mine])
        assert each.get_retry_policies() == [mine] and type(mine) is MyPolicy
    other = spark.newSession()
    df = other.range(1)
    other.client.set_retry_policies([policy])
    del other
    gc.collect()
    assert df.sparkSession.client.get_retry_policies()[0] is policy
    df.sparkSession.stop()
    for each in clients:
        each.close()


def test_the_iterators_of_an_execution_read_nothing_of_the_client_again_as_pysparks(
    mock_connect,
):
    # As PySpark's iterators of an execution, whose request is built once, and whose reattaches
    # and releases copy it: an extension that is not an Any, added once the iteration started,
    # does not fail the rest of it, which reads nothing of the client.
    import pyarrow as pa
    import pyspark.sql.connect.proto as pb2

    spark, service = mock_connect
    client = spark.client
    sink = pa.BufferOutputStream()
    table = pa.table({"id": pa.array([0, 1, 2], pa.int64())})
    with pa.ipc.new_stream(sink, table.schema) as writer:
        writer.write_table(table)
    # ExecutePlanResponse.schema=7 and arrow_batch=2: ArrowBatch.row_count=1, data=2.
    service.execute_payload = message_field(7, struct_schema()) + message_field(
        2, varint_field(1, 3) + message_field(2, sink.getvalue().to_pybytes())
    )
    it = spark.range(3).toLocalIterator()
    assert next(it).id == 0
    client.global_user_context_extensions.append(("bad", 5))
    assert [row.id for row in it] == [1, 2]
    client.global_user_context_extensions.clear()
    plan = pb2.Plan(root=pb2.Relation(range=pb2.Range(end=1)))
    items = client.to_table_as_iterator(plan, {})
    assert next(items) is not None
    client.global_user_context_extensions.append(("bad", 5))
    assert len(list(items)) == 1
    client.global_user_context_extensions.clear()
    # ExecutePlanResponse.sql_command_result=5 -> SqlCommandResult.relation=1.
    service.execute_payload = message_field(5, message_field(1, b""))
    items = client.execute_command_as_iterator(
        pb2.Command(sql_command=pb2.SqlCommand(input=pb2.Relation(sql=pb2.SQL(query="x"))))
    )
    assert "sql_command_result" in next(items)
    client.global_user_context_extensions.append(("bad", 5))
    assert list(items) == []
    client.global_user_context_extensions.clear()
    with pytest.raises(TypeError, match="^Expected a message object, but got 5.$"):
        client.global_user_context_extensions.append(("bad", 5))
        spark.range(1).collect()
    client.global_user_context_extensions.clear()


def test_a_copy_and_its_client_send_their_own_attributes_at_once_as_pysparks(mock_connect):
    # As copy.copy of PySpark's client, of its own attributes: the requests of a copy and of its
    # client, sent at once from threads of their own, carry their own users and global
    # extensions, and a call of the session that the method of a copy makes meanwhile, as of a
    # progress handler, is of the session's.
    import copy
    import threading

    import pyspark.sql.connect.proto as pb2
    from pyspark.sql.connect.proto._rust import Any

    spark, service = mock_connect
    client = spark.client
    copied = copy.copy(client)
    copied._user_id = "copy"
    copied.global_user_context_extensions = [("global_x", Any(type_url="type.googleapis.com/x"))]
    user = client._user_id
    command = pb2.Command(
        sql_command=pb2.SqlCommand(input=pb2.Relation(sql=pb2.SQL(query="SELECT 1")))
    )

    def run(each, tag):
        spark.addTag(tag)
        for _ in range(30):
            each.execute_command(command)

    threads = [threading.Thread(target=run, args=(copied, "A")) for _ in range(2)]
    threads += [threading.Thread(target=run, args=(client, "B")) for _ in range(2)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    sent = [pb2.ExecutePlanRequest.FromString(data) for data in service.execute_requests]
    for request in sent:
        if list(request.tags) == ["A"]:
            assert request.user_context.user_id == "copy"
            assert [e.type_url for e in request.user_context.extensions] == [
                "type.googleapis.com/x"
            ]
        else:
            assert list(request.tags) == ["B"] and request.user_context.user_id == user
            assert list(request.user_context.extensions) == []
    assert len(sent) == 120

    # ExecutePlanResponse.execution_progress=18, of a stage of tasks.
    stage = varint_field(1, 7) + varint_field(2, 4) + varint_field(3, 1)
    service.execute_payload = message_field(18, message_field(1, stage) + varint_field(2, 3))
    nested = []

    def handler(**kwargs):
        if not nested:
            nested.append(spark.range(2).filter("id > 0").schema)

    spark.registerProgressHandler(handler)
    try:
        copied.execute_command(command)
    finally:
        spark.clearProgressHandlers()
    assert nested
    analysis = pb2.AnalyzePlanRequest.FromString(service.analyze_requests[-1])
    assert analysis.user_context.user_id == user
    execution = pb2.ExecutePlanRequest.FromString(service.execute_requests[-1])
    assert execution.user_context.user_id == "copy"


def test_client_get_operation_statuses_sends_pysparks_get_status_request(mock_connect):
    # As PySpark Connect's SparkConnectClient._get_operation_statuses (client/core.py:2183-2237):
    # a GetStatusRequest of the session ID, of the client type and of the user of the client's
    # requests, of an operation_status that is set even of no operation ID, which asks of all of
    # them, of the operation IDs, and of the extensions of each level; the GetStatusResponse is
    # what it gives.
    import pyspark.sql.connect.proto as pb2
    from pyspark.sql.connect.proto._rust import Any

    spark, service = mock_connect
    client = spark.client
    spark.range(1).collect()
    execute = pb2.ExecutePlanRequest.FromString(service.execute_requests[-1])
    every = client._get_operation_statuses()
    assert type(every).__name__ == "GetStatusResponse"
    assert every.session_id == spark.session_id and len(every.operation_statuses) == 0
    asked = client._get_operation_statuses(
        ["op-1", "op-2"],
        [Any(type_url="type.googleapis.com/operation")],
        [Any(type_url="type.googleapis.com/request")],
    )
    unknown = pb2.GetStatusResponse.OperationStatus.OPERATION_STATE_UNKNOWN
    assert [(status.operation_id, status.state) for status in asked.operation_statuses] == [
        ("op-1", unknown),
        ("op-2", unknown),
    ]
    first, second = (pb2.GetStatusRequest.FromString(r) for r in service.get_status_requests)
    for request in (first, second):
        assert request.session_id == spark.session_id
        assert request.client_type == execute.client_type
        assert request.user_context.user_id == execute.user_context.user_id == client._user_id
        assert request.HasField("operation_status")
    assert list(first.operation_status.operation_ids) == []
    assert len(first.operation_status.extensions) == 0 and len(first.extensions) == 0
    assert list(second.operation_status.operation_ids) == ["op-1", "op-2"]
    assert [e.type_url for e in second.operation_status.extensions] == [
        "type.googleapis.com/operation"
    ]
    assert [e.type_url for e in second.extensions] == ["type.googleapis.com/request"]


def test_the_tags_and_extensions_of_a_thread_copy_and_pickle_as_pysparks_set_and_list(
    mock_connect,
):
    # As PySpark Connect's thread_local.tags and user_context_extensions, a plain set and a plain
    # list: their copies and deep copies are a set and a list of the same members, and their
    # pickles a plain set and a plain list.
    import copy
    import pickle

    from pyspark.sql.connect.proto._rust import Any

    spark, _ = mock_connect
    client = spark.client
    local = client.thread_local
    client.add_tag("a")
    client.add_threadlocal_user_context_extension(Any(type_url="type.googleapis.com/t"))
    for value, kind in ((local.tags, set), (local.user_context_extensions, list)):
        for copied in (copy.copy(value), copy.deepcopy(value)):
            assert type(copied) is kind and copied == value
    pickled = pickle.loads(pickle.dumps(local.tags))
    assert type(pickled) is set and pickled == {"a"}
    local.user_context_extensions = []
    pickled = pickle.loads(pickle.dumps(local.user_context_extensions))
    assert type(pickled) is list and pickled == []


def test_the_tags_and_extensions_of_a_thread_that_has_none_are_pysparks(mock_connect):
    # As PySpark Connect's client in a thread whose thread_local has neither: the removal of a
    # thread-local extension and the clear of the extensions leave the thread without a list of
    # them, while the removal of a tag and get_tags give it an empty set of tags.
    import threading

    spark, _ = mock_connect
    client = spark.client
    seen = {}

    def other():
        local = client.thread_local
        client.remove_user_context_extension("threadlocal_missing")
        client.clear_user_context_extensions()
        seen["extensions"] = hasattr(local, "user_context_extensions")
        client.remove_tag("missing")
        seen["removed"] = set(local.tags)
        del local.tags
        seen["got"] = set(client.get_tags())

    thread = threading.Thread(target=other)
    thread.start()
    thread.join()
    assert seen == {"extensions": False, "removed": set(), "got": set()}


def test_the_other_attributes_of_a_thread_local_are_copied_and_deleted_as_pysparks(mock_connect):
    # As PySpark Connect's thread_local, each attribute of which inheritable_thread_target copies
    # with copy.deepcopy, when it decorates a function, to the threads that run the function, and
    # an attribute of which a thread deletes is gone.
    import threading

    from pyspark.util import inheritable_thread_target

    spark, _ = mock_connect
    local = spark.client.thread_local
    local.marker = ["parent"]

    @inheritable_thread_target(spark)
    def child():
        return local.marker

    seen = []
    thread = threading.Thread(target=lambda: seen.append(child()))
    thread.start()
    thread.join()
    assert seen == [["parent"]] and seen[0] is not local.marker
    del local.marker
    assert not hasattr(local, "marker")


def test_the_thread_local_of_a_client_outlives_its_session_as_pysparks(mock_connect):
    # As PySpark Connect's thread_local, a threading.local, and its global list of extensions,
    # which a caller may keep: once the session is gone, the tags and the extensions that a thread
    # sets and deletes, and a change of the list, are those of plain ones.
    import gc
    import weakref

    from pyspark.sql.connect.proto._rust import Any

    spark, _ = mock_connect
    other = spark.newSession()
    local = other.client.thread_local
    extensions = other.client.global_user_context_extensions
    local.tags = {"a"}
    gone = weakref.ref(other)
    other.stop()
    del other
    gc.collect()
    assert gone() is None
    local.tags = {"b"}
    assert type(local.tags) is set and local.tags == {"b"}
    del local.tags
    assert not hasattr(local, "tags")
    local.user_context_extensions = [("threadlocal_a", Any(type_url="type.googleapis.com/a"))]
    assert type(local.user_context_extensions) is list
    del local.user_context_extensions
    extensions.append(("global_a", Any(type_url="type.googleapis.com/a")))
    assert [extension_id for extension_id, _ in extensions] == ["global_a"]


def test_client_tags_interrupts_and_sessions_are_those_of_its_session_as_pyspark(mock_connect):
    # As PySpark Connect's SparkConnectClient, whose tags, interrupts and sessions are those of
    # SparkSession.addTag, interruptOperation, newSession and cloneSession.
    import pyspark.sql.connect.proto as pb2
    from pyspark.errors import PySparkValueError

    spark, service = mock_connect
    client = spark.client
    client.add_tag("a")
    assert client.get_tags() == spark.getTags() == {"a"}
    for tag, condition in (
        (None, "CANNOT_BE_NONE"), ("a,b", "VALUE_ALLOWED"), ("", "VALUE_NOT_NON_EMPTY_STR")):
        with pytest.raises(PySparkValueError) as error:
            client.add_tag(tag)
        assert error.value.getCondition() == condition
    client.remove_tag("missing")
    client.clear_tags()
    assert client.get_tags() == set()

    # The interrupts of a tag and of an operation assert that there is one.
    with pytest.raises(AssertionError):
        client.interrupt_tag(None)
    with pytest.raises(AssertionError):
        client.interrupt_operation(None)
    assert client.interrupt_operation("op") == ["op"]
    sent = pb2.InterruptRequest.FromString(service.interrupt_requests[-1])
    assert sent.operation_id == "op" and sent.session_id == spark.session_id

    other = client.newSession()
    cloned = client.clone()
    try:
        assert type(other) is type(client) and other is not client
        assert other._session.session_id not in (spark.session_id, service.cloned_session_id)
        assert cloned._session.session_id == service.cloned_session_id
        assert pb2.CloneSessionRequest.FromString(
            service.clone_requests[-1]).session_id == spark.session_id
    finally:
        other.close()
        cloned.close()


def test_literal_values_decode_from_their_protos_as_pyspark():
    import datetime

    import pyspark.sql.connect.proto as pb2
    from pyspark.sql import types as T
    from pyspark.sql.connect.expressions import LiteralExpression as L

    literal = pb2.Expression.Literal
    assert L._to_value(literal(byte=3)) == 3
    assert L._to_value(literal(byte=3), T.ByteType()) == 3
    assert L._to_value(literal(short=4), T.ShortType()) == 4
    assert L._to_value(literal(float=1.5), T.FloatType()) == 1.5
    assert L._to_value(literal(binary=b"x"), T.BinaryType()) == b"x"
    assert L._to_value(literal(null=pb2.DataType())) is None
    # A timestamp is microseconds from the epoch, as a naive datetime of the session's zone.
    assert L._to_value(literal(timestamp=1577934245000006), T.TimestampType()) == (
        datetime.datetime(2020, 1, 2, 3, 4, 5, 6))
    assert L._to_value(literal(timestamp=0)) == datetime.datetime(1970, 1, 1)
    # A value of another type than the one given is an assertion, as in PySpark.
    for value, data_type in ((literal(byte=3), T.LongType()),
                             (literal(binary=b"x"), T.LongType()),
                             (literal(timestamp=1), T.LongType())):
        with pytest.raises(AssertionError):
            L._to_value(value, data_type)


