def test_failed_release_of_a_cached_relation_is_logged_as_pyspark(monkeypatch):
    from pyspark.sql.connect import plan as plan_module
    from pyspark.sql.connect.plan import CachedRemoteRelation

    class FailingSession:
        class client:  # noqa: N801 - the session's client, as the finalizer reads it
            is_closed = False

        def _execute_command(self, command):
            raise RuntimeError("boom")

    # The finalizer releases the relation on the server, and only logs a failure, as PySpark.
    # The connect logger is disabled unless configured, so the test records its warnings.
    warnings_logged = []

    class Recorder:
        def warning(self, message):
            warnings_logged.append(message)

    monkeypatch.setattr(plan_module, "logger", Recorder())
    relation = CachedRemoteRelation("relation-1", FailingSession())
    relation.__del__()
    # Collecting the relation runs its finalizer again, which must not log a second time.
    relation._relation_id = None
    assert warnings_logged == ["RemoveRemoteCachedRelation failed with exception: boom."]


@pytest.mark.parametrize("name", [
    "byte", "short", "intc", "int_", "intp", "long", "longlong", "single", "double",
])
@pytest.mark.parametrize("as_array", [False, True], ids=["scalar", "array"])
def test_numpy_numeric_aliases_match_reference_scalar_classes(name, as_array):
    np = pytest.importorskip("numpy")
    from pyspark.sql import functions as F

    # Read real scalar exports without NumPy's deprecated builtin-alias lookup warnings.
    scalar_type = vars(np).get(name)
    if scalar_type is None or not issubclass(scalar_type, np.generic):
        pytest.skip(f"numpy.{name} is not a NumPy scalar class in this NumPy")
    value = scalar_type(1.5 if np.issubdtype(scalar_type, np.floating) else 5)
    kind, size = value.dtype.kind, value.dtype.itemsize
    if kind == "i":
        # These are the classes asserted by LiteralExpression for the inferred width.
        accepted_classes = (int,) + tuple(
            getattr(np, f"int{width}") for width in (8, 16, 32, 64) if width <= size * 8
        )
        spark_type = {1: "tinyint", 2: "smallint", 4: "int", 8: "bigint"}[size]
        rendered = "5"
    else:
        accepted_classes = (float, np.float32) + ((np.float64,) if size == 8 else ())
        spark_type = {4: "float", 8: "double"}[size]
        rendered = "1.5"
    literal = np.array([value], dtype=scalar_type) if as_array else value
    if not isinstance(value, accepted_classes):
        # Distinct longlong scalars have int64 dtype but fail the class assertion on
        # Linux/macOS; platforms where it aliases int64 exercise the success case.
        with pytest.raises(AssertionError) as error:
            F.lit(literal)
        assert error.value.args == ()
    elif as_array:
        assert repr(F.lit(literal)).lower() == (
            f"column<'cast(array({rendered}) as array<{spark_type}>)'>"
        )
    else:
        assert repr(F.lit(literal)) == f"Column<'{rendered}'>"


