def test_repr_handles_wide_schema_and_independent_dataframe(repr_analyzed):
    spark, service = repr_analyzed
    service.data_type = _repr_struct(*[(f"c{i}", _repr_message(7, b"")) for i in range(256)])
    df = spark.range(10)
    assert repr(df) == "DataFrame[" + ", ".join(f"c{i}: bigint" for i in range(256)) + "]"
    # A new independent DataFrame resolves updated server metadata even when
    # another change caches the original DataFrame's schema.
    service.data_type = _repr_struct(("renamed", _repr_message(11, b"")))
    assert repr(spark.range(10)) == "DataFrame[renamed: string]"
    assert service.calls == 2
    assert service.execute_calls == 0


# --------------------------------------------------------------------------- ExecutePlan (mock)


def _request_operation_id(request):
    # ExecutePlanRequest.operation_id=6.
    return parse_message(request)[6][0].decode()


def test_execution_info_decodes_observed_metrics_and_operation_id(mock_connect):
    import datetime

    import pyspark.sql.connect.proto as pb2

    spark, service = mock_connect
    ts = 1_700_000_000_123_456
    # expressions.proto Literal: timestamp=17, day_time_interval=21; a struct and a map of their
    # types, as the server sends them.
    struct = pb2.Expression.Literal()
    struct.struct.struct_type.struct.fields.add(
        name="a", data_type=pb2.DataType(integer=pb2.DataType.Integer()))
    struct.struct.struct_type.struct.fields.add(
        name="b", data_type=pb2.DataType(string=pb2.DataType.String()))
    struct.struct.elements.add(integer=7)
    struct.struct.elements.add(string="x")
    struct_literal = struct.SerializeToString()
    key_and_value = pb2.Expression.Literal()
    key_and_value.map.key_type.string.SetInParent()
    key_and_value.map.value_type.date.SetInParent()
    key_and_value.map.keys.add(string="k")
    key_and_value.map.values.add(date=1)
    map_literal = key_and_value.SerializeToString()
    # base.proto ObservedMetrics: name=1, values=2, keys=3; ExecutePlanResponse.observed_metrics=6.
    observed = message_field(1, "o")
    for literal in (
        varint_field(17, ts),
        struct_literal,
        map_literal,
        varint_field(21, 90_061_000_001),
    ):
        observed += message_field(2, literal)
    for key in ("ts", "s", "m", "dt"):
        observed += message_field(3, key)
    service.execute_payload = message_field(6, observed)

    assert spark.range(1).executionInfo is None
    df = spark.range(1)
    df.collect()
    info = df.executionInfo
    # The information is that of the DataFrame that ran, as in PySpark.
    assert spark.range(1).executionInfo is None
    assert info.operation_id == _request_operation_id(service.execute_requests[-1])
    ((name, pairs),) = info.flows
    assert name == "o"
    assert pairs["ts"] == datetime.datetime.fromtimestamp(ts // 10**6).replace(
        microsecond=ts % 10**6
    )
    assert (pairs["s"].a, pairs["s"].b) == (7, "x")
    assert pairs["m"] == {"k": datetime.date(1970, 1, 2)}
    assert pairs["dt"] == datetime.timedelta(microseconds=90_061_000_001)


def test_connect_functions_package_exports_the_deprecated_functions_as_pyspark():
    # As PySpark Connect's functions package, which star-imports its builtin module (which has
    # no __all__): the functions that pyspark.sql.functions no longer lists are attributes of
    # it too, as the Connect tests use them through their CF alias.
    import random

    import pyspark.sql.connect.functions as connect_functions
    from pyspark.sql.connect.functions import builtin

    for name in ("countDistinct", "sumDistinct", "approxCountDistinct", "chr", "toDegrees",
                 "toRadians", "shiftLeft", "shiftRight", "shiftRightUnsigned", "bitwiseNOT",
                 "random", "uuid"):
        assert getattr(connect_functions, name) is getattr(builtin, name)
    assert connect_functions.py_random is random
    assert connect_functions.bitwiseNOT(connect_functions.col("id")) is not None


def test_execution_info_unsupported_literal_raises_on_flows(mock_connect):
    from pyspark.errors import PySparkTypeError

