@pytest.mark.parametrize("raised", [Exception, KeyboardInterrupt])
def test_exception_of_a_signal_handler_is_raised_by_collect_as_pyspark(mock_connect, raised):
    # As PySpark's: an exception that the handler of the signal raises is the one that the
    # waiting call raises, at once, and the operation is interrupted for a KeyboardInterrupt only,
    # as the `except KeyboardInterrupt` of PySpark's execution interrupts it.
    import signal
    import threading

    class Stop(raised):
        pass

    def stop(signum, frame):
        raise Stop()

    spark, service = mock_connect
    service.block_execute = True
    previous = signal.signal(signal.SIGINT, stop)
    timer = threading.Timer(0.3, os.kill, (os.getpid(), signal.SIGINT))
    started = time.monotonic()
    timer.start()
    try:
        with pytest.raises(Stop):
            spark.range(3).count()
    finally:
        timer.cancel()
        signal.signal(signal.SIGINT, previous)
        service.release_response()
    assert time.monotonic() - started < 3
    assert len(service.interrupt_requests) == (1 if raised is KeyboardInterrupt else 0)


def _two_row_range_results(service):
    # The result of each range: two rows in one Arrow batch, which the iterators read from the
    # buffer of the batch before they wait for the next response.
    import pyarrow as pa

    table = pa.table({"id": pa.array([0, 1], pa.int64())})
    sink = pa.BufferOutputStream()
    with pa.ipc.new_stream(sink, table.schema) as writer:
        writer.write_table(table)
    # ExecutePlanResponse.schema=7 and arrow_batch=2: ArrowBatch.row_count=1, data=2.
    service.execute_payload = message_field(7, struct_schema("id")) + message_field(
        2, varint_field(1, table.num_rows) + message_field(2, sink.getvalue().to_pybytes()))


def test_sigint_interrupts_the_iterator_that_waits_and_not_a_held_one(mock_connect):
    # As PySpark's: the signal interrupts the operation of the iterator whose next waits for the
    # server, even though another iterator that was started after it is alive and half-consumed.
    # That other iterator goes on, and the interrupted one raises KeyboardInterrupt at once.
    import signal
    import threading

    spark, service = mock_connect
    _two_row_range_results(service)
    service.block_result_complete = True
    waiting = spark.range(2).toLocalIterator()
    assert next(waiting).id == 0
    service.block_result_complete = False
    held = spark.range(2).toLocalIterator()
    assert next(held).id == 0
    assert next(waiting).id == 1
    timer = threading.Timer(0.3, os.kill, (os.getpid(), signal.SIGINT))
    started = time.monotonic()
    timer.start()
    try:
        with pytest.raises(KeyboardInterrupt):
            next(waiting)
    finally:
        timer.cancel()
        service.release_response()
    assert time.monotonic() - started < 3
    # ExecutePlanRequest.operation_id=6, of the execution of the waiting iterator, which is the
    # last one that was started; InterruptRequest.operation_id=6.
    operation_id = parse_message(service.execute_requests[-2]).get(6, [b""])[0]
    [interrupt] = service.interrupt_requests
    assert parse_message(interrupt)[6] == [operation_id]
    # The held iterator still yields its next row.
    assert next(held).id == 1


def test_sigint_during_stop_with_an_unconsumed_iterator_raises_at_once(mock_connect):
    # As PySpark's stop: the release of the session is a wait that no execution of the caller
    # stands behind, so a signal ends it at once, though an iterator of the caller is alive and
    # half-consumed. The iterator is not interrupted, and the session stays open.
    import signal
    import threading

    spark, service = mock_connect
    _two_row_range_results(service)
    held = spark.range(2).toLocalIterator()
    assert next(held).id == 0
    service.release_session_blocked = True
    timer = threading.Timer(0.3, os.kill, (os.getpid(), signal.SIGINT))
    started = time.monotonic()
    timer.start()
    try:
        with pytest.raises(KeyboardInterrupt):
            spark.stop()
    finally:
        timer.cancel()
    assert time.monotonic() - started < 3
    assert not spark.is_stopped
    assert service.interrupt_requests == []
    service.release_session_blocked = False
    service.release_session_release()
    spark.stop()
    assert spark.is_stopped
    assert next(held).id == 1


def test_sigint_during_stop_with_a_registered_listener_raises_at_once(mock_connect):
    # As PySpark's stop, with a StreamingQueryListener registered from this thread: its
    # subscription is an execution of the listener bus, which a wait of this thread does not wait
    # for, so a signal ends the release of the session at once, and the session stays open.
    import signal
    import threading

    from pyspark.sql.streaming.listener import StreamingQueryListener

    class Listener(StreamingQueryListener):
        def onQueryStarted(self, event):
            pass

        def onQueryProgress(self, event):
            pass

        def onQueryIdle(self, event):
            pass

        def onQueryTerminated(self, event):
            pass

    spark, service = mock_connect
    service.listener_bus_enabled = True
    spark.streams.addListener(Listener())
    assert service.wait_listener_registration(1)
    service.release_session_blocked = True
    timer = threading.Timer(0.3, os.kill, (os.getpid(), signal.SIGINT))
    started = time.monotonic()
    timer.start()
    try:
        with pytest.raises(KeyboardInterrupt):
            spark.stop()
    finally:
        timer.cancel()
    assert time.monotonic() - started < 3
    assert not spark.is_stopped
    service.release_session_blocked = False
    service.release_session_release()
    spark.stop()
    assert spark.is_stopped


def test_sigint_during_add_listener_keeps_the_registration_removable(mock_connect):
    # As PySpark's append: a signal that ends the wait for the server's acknowledgement raises
    # KeyboardInterrupt at once, and the listener stays in the bus, while the server still adds
    # its listener once it answers. A removeListener then removes that registration.
    import signal
    import threading

    from pyspark.sql.streaming.listener import StreamingQueryListener

    class Listener(StreamingQueryListener):
        def onQueryStarted(self, event):
            pass

        def onQueryProgress(self, event):
            pass

        def onQueryIdle(self, event):
            pass

        def onQueryTerminated(self, event):
            pass

    spark, service = mock_connect
    service.listener_bus_enabled = True
    service.listener_register_blocked = True
    listener = Listener()
    # The release comes well after the signal: a wait that the signal does not end lasts until it.
    release = threading.Timer(2.5, service.release_listener_registration)
    timer = threading.Timer(0.5, os.kill, (os.getpid(), signal.SIGINT))
    release.start()
    timer.start()
    started = time.monotonic()
    try:
        with pytest.raises(KeyboardInterrupt):
            spark.streams.addListener(listener)
    finally:
        timer.cancel()
    assert time.monotonic() - started < 2
    release.join(5)
    assert service.wait_listener_registration(1)
    assert spark.streams._sqlb._listener_bus == [listener]
    spark.streams.removeListener(listener)
    assert spark.streams._sqlb._listener_bus == []
    assert service.listener_removals == 1


def test_a_second_sigint_during_add_listener_removes_the_server_listener_before_the_next_add(
        mock_connect):
    # A second signal ends the wait for the server's acknowledgement of addListener, after the
    # server added its listener. The server answers a later ADD of the session with no response
    # while it holds that listener, so the next addListener removes it first.
    import signal
    import threading

    from pyspark.sql.streaming.listener import StreamingQueryListener

    class Listener(StreamingQueryListener):
        def onQueryStarted(self, event):
            pass

        def onQueryProgress(self, event):
            pass

        def onQueryIdle(self, event):
            pass

        def onQueryTerminated(self, event):
            pass

    spark, service = mock_connect
    service.listener_bus_enabled = True
    service.listener_register_blocked = True
    # The interrupt of the first signal is retried, as the server is unavailable for it, so only
    # the second signal ends the wait, as PySpark's retry sleep raises at it.
    service.interrupt_failure = ("UNAVAILABLE", "server is unavailable")
    # A wait that the signals do not end is released after 10 s, so the test fails, not hangs.
    release = threading.Timer(10, service.release_listener_registration)
    timers = [threading.Timer(delay, os.kill, (os.getpid(), signal.SIGINT)) for delay in (0.5, 1.0)]
    release.start()
    for timer in timers:
        timer.start()
    started = time.monotonic()
    try:
        with pytest.raises(KeyboardInterrupt):
            spark.streams.addListener(Listener())
    finally:
        for timer in timers:
            timer.cancel()
        service.interrupt_failure = None
    assert 0.9 < time.monotonic() - started < 5
    release.cancel()
    service.release_listener_registration()
    assert service.wait_listener_registration(1)
    assert service.listener_removals == 0
    service.listener_register_blocked = False
    listener = Listener()
    spark.streams.addListener(listener)
    assert service.listener_removals == 1
    assert service.listener_subscriptions == 2
    spark.streams.removeListener(listener)


