@pytest.mark.parametrize("kwargs, condition, parameters", [
    ({}, "ONLY_ALLOW_SINGLE_TRIGGER", {}),
    ({"processingTime": "1 second", "once": True}, "ONLY_ALLOW_SINGLE_TRIGGER", {}),
    ({"processingTime": "  "}, "VALUE_NOT_NON_EMPTY_STR",
     {"arg_name": "processingTime", "arg_value": "  "}),
    ({"continuous": 5}, "VALUE_NOT_NON_EMPTY_STR", {"arg_name": "continuous", "arg_value": "5"}),
    ({"realTime": ""}, "VALUE_NOT_NON_EMPTY_STR", {"arg_name": "realTime", "arg_value": ""}),
    ({"once": False}, "VALUE_NOT_ALLOWED", {"arg_name": "once", "allowed_values": "[True]"}),
    ({"availableNow": 1}, "VALUE_NOT_ALLOWED",
     {"arg_name": "availableNow", "allowed_values": "[True]"}),
], ids=["none", "two", "empty", "not-a-string", "empty-real-time", "once-false",
        "available-now-1"])
def test_stream_writer_triggers_are_checked_as_pyspark(offline_spark, kwargs, condition,
                                                        parameters):
    from pyspark.errors import PySparkValueError

    w = offline_spark.readStream.format("rate").load().writeStream
    with pytest.raises(PySparkValueError) as error:
        w.trigger(**kwargs)
    assert error.value.getCondition() == condition
    assert error.value.getMessageParameters() == parameters
    # A trigger of None is not given, as in PySpark.
    assert w.trigger(processingTime=None, once=True) is w


def test_foreach_sends_the_function_of_each_partition_as_pyspark(mock_connect):
    # As PySpark's foreach: the command (func, None, serializer, serializer) of the function of
    # _construct_foreach_function, which calls a function with each row of a partition, in a
    # PythonUDF of the command and the Python version only, as of foreachBatch;
    # ATTRIBUTE_NOT_CALLABLE for an object without a callable process, open or close; and
    # STREAMING_CONNECT_SERIALIZATION_ERROR for a function that does not pickle, as of
    # foreachBatch.
    import sys
    import threading

    from pyspark import cloudpickle
    from pyspark.errors import PySparkAttributeError, PySparkPicklingError

    spark, service = mock_connect
    # ExecutePlanResponse.write_stream_operation_start_result=8: query_id=1 (id=1, run_id=2).
    service.execute_payload = message_field(
        8, message_field(1, message_field(1, "q") + message_field(2, "r"))
    )
    writer = spark.readStream.format("rate").load().writeStream

    def row_function(row):
        raise ValueError(f"the row {row}")

    writer.foreach(row_function).start()
    # ExecutePlanRequest.plan=3, Plan.command=2, Command.write_stream_operation_start=6:
    # WriteStreamOperationStart.foreach_writer=13 of StreamingForeachFunction.python_function=1
    # of PythonUDF.command=3.
    plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
    start = parse_message(parse_message(plan[2][0])[6][0])
    udf = parse_message(parse_message(start[13][0])[1][0])
    function, return_type, input_serializer, output_serializer = cloudpickle.loads(udf[3][0])
    assert return_type is None and input_serializer is output_serializer
    with pytest.raises(ValueError, match="the row 7"):
        function(0, iter([7]))
    # PythonUDF: command=3 and python_ver=4, and no output_type=1 nor eval_type=2, which
    # PySpark's DataStreamWriter does not set. And so of foreachBatch=14.
    python_ver = f"{sys.version_info.major}.{sys.version_info.minor}"
    assert sorted(udf) == [3, 4] and udf[4] == [python_ver.encode()]
    writer.foreachBatch(lambda df, batch_id: None).start()
    plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
    start = parse_message(parse_message(plan[2][0])[6][0])
    udf = parse_message(parse_message(start[14][0])[1][0])
    assert sorted(udf) == [3, 4] and udf[4] == [python_ver.encode()]

    class NoProcess:
        pass

    class Uncallable:
        process = 1

    class UncallableClose:
        def process(self, row):
            pass

        close = 1

    for writer_object, attr_name in [
        (1, "process"),
        (NoProcess(), "process"),
        (Uncallable(), "process"),
        (UncallableClose(), "close"),
    ]:
        with pytest.raises(PySparkAttributeError) as e:
            writer.foreach(writer_object)
        assert e.value.getCondition() == "ATTRIBUTE_NOT_CALLABLE"
        assert e.value.getMessageParameters() == {"attr_name": attr_name, "obj_name": "f"}
    lock = threading.Lock()
    for method, name, function in [
        (writer.foreach, "foreach", lambda row: lock),
        (writer.foreachBatch, "foreachBatch", lambda df, batch_id: lock),
    ]:
        with pytest.raises(PySparkPicklingError) as e:
            method(function)
        assert e.value.getCondition() == "STREAMING_CONNECT_SERIALIZATION_ERROR"
        assert e.value.getMessageParameters() == {"name": name}


def test_stream_writer_sends_its_trigger_as_pyspark(mock_connect):
    # As PySpark's: the trigger of a WriteStreamOperationStart, an interval or duration
    # stripped, of the real-time trigger too.
    spark, service = mock_connect
    # ExecutePlanResponse.write_stream_operation_start_result=8: query_id=1 (id=1, run_id=2).
    service.execute_payload = message_field(
        8, message_field(1, message_field(1, "q") + message_field(2, "r")))

    def sent(**trigger):
        spark.readStream.format("rate").load().writeStream.format("memory").queryName(
            "q").trigger(**trigger).start()
        # ExecutePlanRequest.plan=3 -> Plan.command=2 -> Command.write_stream_operation_start=6.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        start = parse_message(parse_message(plan[2][0])[6][0])
        # WriteStreamOperationStart: processing_time_interval=5, available_now=6, once=7,
        # continuous_checkpoint_interval=8, real_time_batch_duration=100.
        return {field: start[field] for field in (5, 6, 7, 8, 100) if field in start}

    assert sent(processingTime=" 1 second ") == {5: [b"1 second"]}
    assert sent(once=True) == {7: [1]}
    assert sent(availableNow=True) == {6: [1]}
    assert sent(continuous="1 minute") == {8: [b"1 minute"]}
    assert sent(realTime=" 5 seconds ") == {100: [b"5 seconds"]}


def test_stream_writer_takes_its_query_name_and_columns_as_pyspark(offline_spark):
    # As PySpark's DataStreamWriter: queryName, also of start and toTable, raises
    # VALUE_NOT_NON_EMPTY_STR for a name that is not a non-empty str, and partitionBy and
    # clusterBy take a list or a tuple of column names alone.
    from pyspark.errors import PySparkValueError

    writer = offline_spark.readStream.format("rate").load().writeStream
    calls = [writer.queryName, lambda name: writer.start(queryName=name)]
    calls.append(lambda name: writer.toTable("t", queryName=name))
    for name in ("", "  ", 1):
        for call in calls:
            with pytest.raises(PySparkValueError) as e:
                call(name)
            assert e.value.getCondition() == "VALUE_NOT_NON_EMPTY_STR"
            assert e.value.getMessageParameters() == {
                "arg_name": "queryName",
                "arg_value": str(name),
            }
    with pytest.raises(PySparkValueError):
        writer.queryName(None)
    for columns in (["a", "b"], ("a", "b")):
        assert writer.partitionBy(columns) is writer
        assert writer.clusterBy(columns) is writer
    assert writer.partitionBy("a", "b") is writer
    with pytest.raises(TypeError):
        writer.partitionBy(["a"], "b")


def test_merge_into_writer_mutates_and_returns_self(offline_spark):
    # PySpark: withSchemaEvolution and every clause action change the writer and
    # return that same writer; a clause object can be used more than once.
    from pyspark.sql import functions as F

    src = offline_spark.range(3)
    m = src.mergeInto("target", F.col("id") == F.col("target.id"))
    assert m.withSchemaEvolution() is m

    matched = m.whenMatched(F.col("id") > 1)
    assert matched.updateAll() is m
    assert matched.update({"id": F.col("id")}) is m
    assert matched.delete() is m
    assert m.whenMatched().delete() is m

    not_matched = m.whenNotMatched()
    assert not_matched.insertAll() is m
    assert not_matched.insert({"id": F.col("id")}) is m

    by_source = m.whenNotMatchedBySource(F.col("target.id") < 0)
    assert by_source.updateAll() is m
    assert by_source.update({"id": F.lit(0)}) is m
    assert by_source.delete() is m

    # The ignore-the-return-value form keeps working on the original object.
    m.whenNotMatched().insertAll()
    m.withSchemaEvolution()
    assert m.whenMatched().updateAll() is m


def test_merge_builders_keep_their_conditions_and_build_their_clauses_as_pyspark(mock_connect):
    # As PySpark's MergeIntoWriter, which keeps the conditions as they are given, and whose
    # clause actions build their assignments and condition as `_build_merge_action` does: the
    # assignments in the order of `assignments.items()`, in which the merge sends them, each key
    # the SQL expression of `expr(k)`, which asserts a str, and each value a Column, whose
    # `to_plan` another object lacks, and then the condition. An action raises their errors in
    # that order, and adds no clause; the merge raises the error of the condition of mergeInto,
    # after it built its source.
    from pyspark.errors import PySparkAttributeError
    from pyspark.sql import functions as F
    from pyspark.sql.connect.proto import base_pb2

    spark, service = mock_connect
    df = spark.range(1)
    names = ["v", "id", "a", "nope"]
    merge = df.mergeInto("t", F.lit(True))
    merge.whenMatched().update({name: F.lit(1) for name in names})
    merge.whenNotMatched().insert({name: F.lit(1) for name in reversed(names)})
    merge.whenNotMatchedBySource(F.lit(False)).update({name: F.col("id") for name in names})
    merge.merge()
    command = base_pb2.ExecutePlanRequest.FromString(
        service.execute_requests[-1]).plan.command.merge_into_table_command

    def keys(action):
        return [assignment.key.expression_string.expression
                for assignment in action.merge_action.assignments]

    assert keys(command.match_actions[0]) == names
    assert keys(command.not_matched_actions[0]) == names[::-1]
    assert keys(command.not_matched_by_source_actions[0]) == names
    requests = len(service.execute_requests)
    writer = df.mergeInto("t", 5)
    clause = writer.whenMatched(5)
    to_plan = "'int' object has no attribute 'to_plan'"
    unencodable = "'utf-8' codec can't encode character '\\udc0{}' in position 1: surrogates not allowed"
    for call, error_type, message in (
        (clause.delete, AttributeError, to_plan),
        (lambda: clause.update({"a": F.lit(1)}), AttributeError, to_plan),
        (lambda: writer.whenMatched().update({b"a": F.lit(1)}), AssertionError, ""),
        (lambda: writer.whenNotMatched().insert({5: F.lit(1)}), AssertionError, ""),
        (lambda: writer.whenMatched().update({"a": 1}), AttributeError, to_plan),
        (lambda: writer.whenMatched().update([("a", F.lit(1))]), AttributeError,
         "'list' object has no attribute 'items'"),
        (lambda: writer.whenMatched(F.lit("b\udc01")).update({"a\udc00": F.lit("c\udc02")}),
         UnicodeEncodeError, unencodable.format(0)),
        (lambda: writer.whenNotMatched(F.lit("b\udc01")).insert({"a": F.lit("c\udc02")}),
         UnicodeEncodeError, unencodable.format(2)),
        (lambda: writer.whenNotMatchedBySource(F.lit("b\udc01")).delete(), UnicodeEncodeError,
         unencodable.format(1)),
    ):
        with pytest.raises(error_type) as error:
            call()
        assert type(error.value) is error_type and str(error.value) == message
    with pytest.raises(AttributeError) as error:
        writer.merge()
    assert type(error.value) is AttributeError and str(error.value) == to_plan
    of_row = df.mergeInto("t", Row(a=1))
    with pytest.raises(PySparkAttributeError) as error:
        of_row.merge()
    assert error.value.getCondition() == "ATTRIBUTE_NOT_SUPPORTED"
    assert error.value.getMessageParameters() == {"attr_name": "to_plan"}
    assert len(service.execute_requests) == requests


def test_merges_send_the_clauses_as_their_actions_built_them_as_pyspark(mock_connect):
    # As PySpark's MergeIntoWriter, whose clause actions keep the `MergeAction` protos that
    # `_build_merge_action` builds, which the merge sends: the functions of the UDFs of a clause
    # are pickled once, when its action adds it, so a value that a function reads, changed after
    # that, is not that of the merge, of a copy of the builder either; and a window of no
    # partitions of a clause warns once, at its action. The condition of mergeInto is built by
    # the merge. A clause of a function that does not pickle raises at its action.
    import copy
    import threading
    import warnings

    from pyspark.sql import Window
    from pyspark.sql import functions as F
    from pyspark.sql.connect.proto import base_pb2

    spark, service = mock_connect
    state = ["<clause>"]
    df = spark.range(3)
    merge = df.mergeInto("t", F.udf(lambda x: state[0] == "", "boolean")("id"))
    merge.whenMatched(F.udf(lambda x: state[0] == "", "boolean")("id")).update(
        {"v": F.udf(lambda x: state[0], "string")("id")})
    state[0] = "<merge>"
    for writer in (merge, copy.copy(merge)):
        writer.merge()
        command = base_pb2.ExecutePlanRequest.FromString(
            service.execute_requests[-1]).plan.command.merge_into_table_command
        action = command.match_actions[0].merge_action
        for sent in (action.condition, action.assignments[0].value):
            udf = sent.common_inline_user_defined_function.python_udf.command
            assert b"<clause>" in udf and b"<merge>" not in udf
        condition = command.merge_condition.common_inline_user_defined_function.python_udf.command
        assert b"<merge>" in condition
    with warnings.catch_warnings(record=True) as record:
        warnings.simplefilter("always")
        clause = df.mergeInto("t", F.lit(True)).whenMatched(
            F.row_number().over(Window.orderBy("id")) > 0)
        assert record == []
        writer = clause.delete()
        assert len(record) == 1
        writer.merge()
        assert len(record) == 1
    lock = threading.Lock()
    requests = len(service.execute_requests)
    with pytest.raises(pickle.PicklingError):
        df.mergeInto("t", F.lit(True)).whenMatched(
            F.udf(lambda x: bool(lock), "boolean")("id")).delete()
    assert len(service.execute_requests) == requests


# --------------------------------------------------------------------------- artifact uploads that stream their chunks, and class files

def test_add_artifacts_refuses_the_paths_pyspark_refuses(tmp_path):
    # Each error is PySpark's for the path and the flags, raised before any upload.
    import errno

    from pyspark.errors import PySparkRuntimeError, PySparkValueError

    for name in ["A.class", "m.py", "n.txt", "b.tar.gz", "b.zip", "b#c.zip"]:
        (tmp_path / name).write_bytes(b"x")
    (tmp_path / "dirx.jar").mkdir()
    (tmp_path / "sub").mkdir()

    def at(name):
        return str(tmp_path / name)

    def unsupported(name):
        return {"operation": f"{at(name)} file format"}

    cases = [
        # A class file is refused, unless it is a file.
        (at("A.class"), {}, PySparkRuntimeError, "UNSUPPORTED_OPERATION", unsupported("A.class")),
        (at("A.class"), {"pyfile": True}, PySparkRuntimeError, "UNSUPPORTED_OPERATION", unsupported("A.class")),
        (at("A.class"), {"archive": True}, PySparkRuntimeError, "UNSUPPORTED_OPERATION", unsupported("A.class")),
        # A flag takes only its formats, and a fragment names only an archive.
        (at("m.py"), {"archive": True}, PySparkRuntimeError, "UNSUPPORTED_OPERATION", unsupported("m.py")),
        (at("n.txt"), {"pyfile": True}, PySparkRuntimeError, "UNSUPPORTED_OPERATION", unsupported("n.txt")),
        (at("b.tar.gz"), {"pyfile": True}, PySparkRuntimeError, "UNSUPPORTED_OPERATION", unsupported("b.tar.gz")),
        (at("b.zip") + "#alias", {}, PySparkRuntimeError, "UNSUPPORTED_OPERATION", unsupported("b.zip")),
        (at("b%23c.zip") + "#alias", {"archive": True}, PySparkValueError, "VALUE_ALLOWED",
         {"arg_name": "artifact path", "disallowed_value": "#"}),
        # Remote URIs are refused whatever the flags.
        ("s3://bucket/a.jar", {}, PySparkRuntimeError, "UNSUPPORTED_OPERATION", {"operation": "s3 scheme"}),
        ("hdfs://h/a.jar", {"file": True}, PySparkRuntimeError, "UNSUPPORTED_OPERATION",
         {"operation": "hdfs scheme"}),
        # A path without a suffix is a format, even when it is a directory.
        (at("sub"), {}, PySparkRuntimeError, "UNSUPPORTED_OPERATION", unsupported("sub")),
    ]
    spark = _offline_session()
    for path, flags, error_type, condition, parameters in cases:
        with pytest.raises(error_type) as error:
            spark.addArtifacts(path, **flags)
        assert error.value.getCondition() == condition, path
        assert error.value.getMessageParameters() == parameters, path
    # A file that Python cannot open is the error of open, as PySpark's LocalFile raises it.
    for path, flags, expected in [
        (at("sub"), {"file": True}, f"[Errno 21] Is a directory: '{at('sub')}'"),
        (at("dirx.jar"), {"archive": True}, f"[Errno 21] Is a directory: '{at('dirx.jar')}'"),
        (at("missing.jar"), {}, f"[Errno 2] No such file or directory: '{at('missing.jar')}'"),
        ("file://" + at("missing.jar"), {"pyfile": True},
         f"[Errno 2] No such file or directory: '{at('missing.jar')}'"),
    ]:
        with pytest.raises(OSError) as error:
            spark.addArtifacts(path, **flags)
        assert str(error.value) == expected, path
        assert error.value.errno in (errno.ENOENT, errno.EISDIR), path


def test_column_origins_capture_their_call_site_without_importing_per_call(mock_connect, monkeypatch):
    # As PySpark's `_with_origin`: a Column operation carries the call site of its user code,
    # which `_capture_call_site` gives, but the capture does not import IPython and ipykernel
    # on every call, where ipykernel is missing.
    import builtins

    import pyspark.errors.utils as errors_utils
    from pyspark.sql import functions as F

    spark, service = mock_connect
    monkeypatch.setattr(errors_utils, "_enable_debugging_cache", True)
    # One line on purpose: the call site that is captured is the line of the Column.
    column = F.col("id") + 1; expected = errors_utils._capture_call_site(1)  # noqa: E702
    imports = []
    real_import = builtins.__import__

    def counting_import(name, *args, **kwargs):
        if name in ("IPython", "ipykernel"):
            imports.append(name)
        return real_import(name, *args, **kwargs)

    monkeypatch.setattr(builtins, "__import__", counting_import)
    for _ in range(200):
        F.col("id") + 1
    assert len(imports) <= 1
    spark.range(1).select(column).collect()
    assert expected.encode() in service.execute_requests[-1]


def test_add_artifacts_reads_a_path_that_is_not_a_str_as_pyspark(mock_connect, tmp_path):
    # As PySpark's ArtifactManager._parse_artifacts, which parses each path with urlparse once the
    # flags are checked and the paths before it are uploaded: a pathlib path, an int or another
    # object that urlparse cannot decode raises its AttributeError, and bytes or a falsy object
    # parse into a scheme of bytes, which is not supported. spark.addArtifacts, addArtifact and
    # client.add_artifacts read their paths so.
    import pathlib

    from pyspark.errors import PySparkRuntimeError, PySparkValueError

    spark, service = mock_connect
    client = spark.client
    module = tmp_path / "artifact_module.py"
    module.write_text("x = 1\n")
    adds = [
        lambda path: spark.addArtifacts(path, pyfile=True),
        lambda path: spark.addArtifact(path, pyfile=True),
        lambda path: client.add_artifacts(path, pyfile=True, archive=False, file=False),
    ]
    for add in adds:
        for path, kind in ((module, "PosixPath"), (pathlib.PurePosixPath(module), "PurePosixPath"),
                           (5, "int")):
            with pytest.raises(AttributeError) as error:
                add(path)
            assert str(error.value) == f"'{kind}' object has no attribute 'decode'"
        for path, scheme in ((str(module).encode(), "b''"),
                             (("file://" + str(module)).encode(), "b'file'"),
                             (None, "b''"), (0, "b''")):
            with pytest.raises(PySparkRuntimeError) as error:
                add(path)
            assert error.value.getCondition() == "UNSUPPORTED_OPERATION"
            assert error.value.getMessageParameters() == {"operation": f"{scheme} scheme"}
    assert service.add_artifacts_requests == []
    # The flags are checked first, and the paths before one that is not supported are uploaded.
    with pytest.raises(PySparkValueError) as error:
        spark.addArtifacts(module, pyfile=True, archive=True)
    assert error.value.getCondition() == "INVALID_MULTIPLE_ARGUMENT_CONDITIONS"
    with pytest.raises(AttributeError):
        spark.addArtifacts(str(module), module, pyfile=True)
    assert len(service.add_artifacts_requests) == 1


def test_add_artifacts_puts_a_pyfile_zip_on_the_client_path_before_opening_it(tmp_path, monkeypatch):
    # As PySpark's _parse_artifacts: a zip, egg or jar of pyfile is put on sys.path before its
    # file is opened, and a Python file is not.
    import sys

    monkeypatch.setattr(sys, "path", list(sys.path))
    spark = _offline_session()
    zipped = str(tmp_path / "missing.zip")
    with pytest.raises(FileNotFoundError):
        spark.addArtifacts(zipped, pyfile=True)
    assert sys.path[1] == zipped
    before = list(sys.path)
    with pytest.raises(FileNotFoundError):
        spark.addArtifacts(str(tmp_path / "missing.py"), pyfile=True)
    assert sys.path == before


# --------------------------------------------------------------------------- reader schema

def _sent_read_schema(request):
    """The DataSource.schema of a captured AnalyzePlanRequest: schema=4 -> plan=1 -> root=1 ->
    read=2 -> data_source=2 -> schema=2."""
    message = parse_message(request)
    for field in (4, 1, 1, 2, 2):
        message = parse_message(message[field][0])
    return message[2][0].decode()


def test_apply_in_pandas_with_state_sends_its_relation_as_pyspark(mock_connect):
    import json

    spark, service = mock_connect
    output = T.StructType([T.StructField("id", T.LongType()), T.StructField("c", T.LongType())])
    # A schema of a Python subclass is sent of its methods, as PySpark sends its `json()`.
    state = type("StateType", (T.StructType,), {})([T.StructField("c", T.LongType())])
    spark.range(3).groupBy("id").applyInPandasWithState(
        lambda key, frames, s: frames, output, state, "update", "NoTimeout").collect()
    # plan=3 -> root=1 -> apply_in_pandas_with_state=34: func=3, output_schema=4,
    # state_schema=5, output_mode=6, timeout_conf=7.
    root = parse_message(parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0])
    assert 34 in root, sorted(root)
    apply = parse_message(root[34][0])
    assert json.loads(apply[4][0]) == output.jsonValue()
    assert json.loads(apply[5][0]) == state.jsonValue() and state.jsonValue()["type"] == "state"
    assert (apply[6][0], apply[7][0]) == (b"update", b"NoTimeout")
    # CommonInlineUserDefinedFunction.python_udf=4 -> PythonUDF.eval_type=2.
    assert parse_message(parse_message(apply[3][0])[4][0])[2][0] == 208


def test_apply_in_pandas_with_state_sends_its_schemas_as_given_as_pyspark(mock_connect):
    # As PySpark's: the output schema is the return type of the function, whose DDL string is
    # parsed once the columns of the input are read, and both schemas are sent as they are given,
    # for the server to parse, so the state schema is not parsed. A state schema that protobuf
    # does not take as a str fails each request of the DataFrame with its TypeError, as PySpark's
    # plan fails to build, and bytes are sent as their UTF-8. An output schema that is neither a
    # DataType nor a str raises NOT_EXPECTED_TYPE before any request.
    from pyspark.errors import PySparkTypeError

    spark, service = mock_connect

    def stateful(output, state):
        return spark.range(3).groupBy("id").applyInPandasWithState(
            lambda key, frames, s: frames, output, state, "append", "NoTimeout")

    def sent_schemas():
        # plan=3 -> root=1 -> apply_in_pandas_with_state=34: output_schema=4, state_schema=5.
        root = parse_message(parse_message(service.execute_requests[-1])[3][0])[1][0]
        apply = parse_message(parse_message(root)[34][0])
        return apply[4][0].decode(), apply[5][0].decode()

    start = len(service.recorded_order)
    df = stateful("id long", "c long")
    assert _sent_kinds(service, start) == ["schema", "ddl_parse"]
    df.collect()
    assert sent_schemas() == ("id long", "c long")
    stateful("id long", b"c long").collect()
    assert sent_schemas() == ("id long", "c long")
    for state in (1, None):
        df = stateful("id long", state)
        start = len(service.recorded_order)
        with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
            df.schema
        assert _sent_kinds(service, start) == []
    start = len(service.recorded_order)
    with pytest.raises(PySparkTypeError) as e:
        stateful(1, "c long")
    assert e.value.getCondition() == "NOT_EXPECTED_TYPE"
    assert _sent_kinds(service, start) == []


def test_stateful_group_methods_set_their_modes_when_the_plan_is_built_as_pyspark(mock_connect):
    # As PySpark's ApplyInPandasWithState and BaseTransformWithStateInPySpark plans, which set the
    # output mode and the timeout, and the output mode, the time mode and the event-time column,
    # in their string fields when they are built: bytes are sent as their UTF-8, and a value that
    # protobuf does not take fails each request of the DataFrame, not the call, in the order of
    # the build. ApplyInPandasWithState pickles its function before it sets them, and the
    # transformWithState plans set the output mode once they built the grouping, and the others
    # once they built the initial state, before they pickle the function. The event-time column
    # is always set, "" when it is omitted, and transformWithState sends its output schema as
    # transformWithStateInPandas does, a DDL string unparsed.
    import threading

    from pyspark.sql import functions as F
    from pyspark.sql.connect.proto import base_pb2
    from pyspark.sql.streaming.stateful_processor import StatefulProcessor

    class Processor(StatefulProcessor):
        def init(self, handle):
            pass

        def handleInputRows(self, key, rows, timerValues):
            yield from []

        def close(self):
            pass

    class Unpicklable(Processor):
        def __init__(self):
            self.lock = threading.Lock()

    spark, service = mock_connect
    lock = threading.Lock()

    def grouped(*cols):
        return spark.range(3).groupBy(*(cols or ("id",)))

    def apply(mode="append", timeout="NoTimeout", func=lambda key, frames, state: frames):
        return grouped().applyInPandasWithState(func, "id long", "c long", mode, timeout)

    def tws(pandas, mode="append", time="None", processor=None, by=(), **kwargs):
        method = "transformWithStateInPandas" if pandas else "transformWithState"
        return getattr(grouped(*by), method)(processor or Processor(), "id long", mode, time,
                                             **kwargs)

    def root(dataframe):
        dataframe.collect()
        return base_pb2.ExecutePlanRequest.FromString(service.execute_requests[-1]).plan.root

    applied = root(apply(b"update", b"NoTimeout")).apply_in_pandas_with_state
    assert (applied.output_mode, applied.timeout_conf) == ("update", "NoTimeout")
    for pandas in (True, False):
        info = root(tws(pandas)).group_map.transform_with_state_info
        assert info.HasField("event_time_column_name") and info.event_time_column_name == ""
        assert info.output_schema.unparsed.data_type_string == "id long"
        group_map = root(tws(pandas, b"update", b"None", eventTimeColumnName=b"ts")).group_map
        info = group_map.transform_with_state_info
        assert (group_map.output_mode, info.time_mode, info.event_time_column_name) == (
            "update", "None", "ts")
    bad_type = "bad argument type for built-in operation"
    initial = grouped(F.col("a\udc00"))
    calls = [
        (lambda: apply(5), TypeError, bad_type),
        (lambda: apply(timeout="a\ud800"), UnicodeEncodeError, "\\ud800"),
        (lambda: apply(None, "a\ud800"), TypeError, bad_type),
        (lambda: apply(5, func=lambda key, frames, state: lock), pickle.PicklingError, "lock"),
    ]
    for pandas in (True, False):
        calls += [
            (lambda pandas=pandas: tws(pandas, 5), TypeError, bad_type),
            (lambda pandas=pandas: tws(pandas, time=b"\xff"), UnicodeDecodeError, "0xff"),
            (lambda pandas=pandas: tws(pandas, eventTimeColumnName=None), TypeError, bad_type),
            (lambda pandas=pandas: tws(pandas, 5, "a\ud800"), TypeError, bad_type),
            (lambda pandas=pandas: tws(pandas, time="a\ud800", eventTimeColumnName=5),
             UnicodeEncodeError, "\\ud800"),
            (lambda pandas=pandas: tws(pandas, time=5, by=[]), TypeError, bad_type),
            (lambda pandas=pandas: tws(pandas, time=5, processor=Unpicklable()), TypeError,
             bad_type),
            (lambda pandas=pandas: tws(pandas, 5, by=[F.col("a\udc00")]), UnicodeEncodeError,
             "\\udc00"),
            (lambda pandas=pandas: tws(pandas, 5, initialState=initial), TypeError, bad_type),
            (lambda pandas=pandas: tws(pandas, time=5, initialState=initial), UnicodeEncodeError,
             "\\udc00"),
        ]
    # The calls read the columns of their input and parse their DDL, as PySpark's do.
    dataframes = [(call(), error_type, message) for call, error_type, message in calls]
    start = len(service.recorded_order)
    for dataframe, error_type, message in dataframes:
        with pytest.raises(error_type) as error:
            dataframe.schema
        assert type(error.value) is error_type and message in repr(str(error.value)), message
    assert _sent_kinds(service, start) == []


@pytest.mark.parametrize("method", ["transformWithStateInPandas", "transformWithState"])
def test_transform_with_state_checks_its_initial_state_and_type_first_as_pyspark(
    mock_connect, method
):
    # As PySpark's, which checks `self._df._check_same_session(initialState._df)` first: an object
    # without `_df` raises its AttributeError, and a `_df` that is not a DataFrame of the session,
    # as the Column of a DataFrame's `_df`, or grouped data of another session, SESSION_NOT_SAME.
    # Then UserDefinedFunction raises NOT_EXPECTED_TYPE of an output type that is neither a
    # DataType nor a str, then the `_grouping_cols` of the initial state are read, and then the
    # columns of the input, so a bad type raises before any request.
    from pyspark.errors import PySparkTypeError, SessionNotSameException
    from pyspark.sql.streaming.stateful_processor import StatefulProcessor

    class Processor(StatefulProcessor):
        def init(self, handle):
            pass

        def handleInputRows(self, key, rows, timerValues):
            yield from rows

        def close(self):
            pass

    class Fake:
        def __init__(self, df):
            self._df = df

    spark, service = mock_connect
    other = spark.newSession()
    df = spark.range(2)

    def call(initial=None, output="id long"):
        return getattr(df.groupBy("id"), method)(
            Processor(), output, "append", "None", initialState=initial)

    start = len(service.recorded_order)
    with pytest.raises(AttributeError, match="'int' object has no attribute '_df'"):
        call(5, output=5)
    for initial in (df, other.range(2).groupBy("id"), Fake(other.range(2))):
        with pytest.raises(SessionNotSameException) as error:
            call(initial, output=5)
        assert error.value.getCondition() == "SESSION_NOT_SAME"
    for initial in (None, df.groupBy("id"), Fake(df)):
        with pytest.raises(PySparkTypeError) as error:
            call(initial, output=5)
        assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
        assert error.value.getMessageParameters() == {
            "expected_type": "DataType or str", "arg_name": "returnType", "arg_type": "int"}
    with pytest.raises(AttributeError, match="'Fake' object has no attribute '_grouping_cols'"):
        call(Fake(df))
    assert _sent_kinds(service, start) == []
    assert call(df.groupBy("id")).columns == ["id"]


@pytest.mark.parametrize("read", [
    lambda spark, schema: spark.read.schema(schema).csv("unused.csv"),
    lambda spark, schema: spark.read.csv("unused.csv", schema=schema),
    lambda spark, schema: spark.read.load("unused", format="json", schema=schema),
    lambda spark, schema: spark.readStream.schema(schema).csv("unused"),
    lambda spark, schema: spark.readStream.csv("unused", schema=schema),
    lambda spark, schema: spark.readStream.load("unused", format="json", schema=schema),
], ids=["read.schema", "read.csv", "read.load", "readStream.schema", "readStream.csv",
        "readStream.load"])
def test_reader_schema_is_sent_as_pyspark_sends_it(mock_connect, read):
    from pyspark.errors import PySparkTypeError

    spark, service = mock_connect
    struct = T.StructType([T.StructField("a", T.LongType(), True, {"comment": "key"})])

    class SchemaType(T.StructType):
        pass

    # pyspark sends a StructType as its `json()` and a string as is, for the server to parse: of
    # a Python subclass, of its methods, and of the metadata dict, which holds an int of more
    # than 64 bits as it is.
    for schema, sent in [
        (struct, '{"fields":[{"metadata":{"comment":"key"},"name":"a","nullable":true,'
                 '"type":"long"}],"type":"struct"}'),
        ("a long COMMENT 'key'", "a long COMMENT 'key'"),
        (SchemaType([T.StructField("a", T.LongType(), True, {"k": 10**30})]),
         '{"fields":[{"metadata":{"k":1000000000000000000000000000000},"name":"a",'
         '"nullable":true,"type":"long"}],"type":"schema"}'),
    ]:
        read(spark, schema).columns
        assert _sent_read_schema(service.analyze_requests[-1]) == sent
    with pytest.raises(PySparkTypeError) as error:
        read(spark, T.LongType())
    assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
    assert error.value.getMessageParameters() == {
        "arg_name": "schema", "expected_type": "str or struct type", "arg_type": "LongType"}


def _sent_relation(request, field, execute=False):
    """The relation `field` of the root of a captured AnalyzePlanRequest, or ExecutePlanRequest with
    `execute`: AnalyzePlanRequest.schema=4 -> plan=1, or ExecutePlanRequest.plan=3 (its field 4 is
    the client type); then Plan.root=1."""
    message = parse_message(request)
    plan = message[3][0] if execute else parse_message(message[4][0])[1][0]
    root = parse_message(parse_message(plan)[1][0])
    assert field in root, sorted(root)
    return parse_message(root[field][0])


def _struct_field_names(data_type):
    # DataType.struct=21 -> Struct.fields=1 -> StructField.name=1.
    struct = parse_message(parse_message(data_type)[21][0])
    return [parse_message(field)[1][0].decode() for field in struct[1]]


@pytest.mark.parametrize("read, format, option", [
    (lambda spark, df: spark.read.csv(df, schema="a INT, b STRING", sep=";"), 1, b"sep"),
    (lambda spark, df: spark.read.json(df, schema="a INT, b STRING", lineSep=";"), 2,
     b"lineSep"),
    (lambda spark, df: spark.read.xml(df, schema="a INT, b STRING", rowTag=";"), 3, b"rowTag"),
], ids=["csv", "json", "xml"])
def test_reader_parses_a_dataframe_of_strings_as_pyspark(mock_connect, read, format, option):
    # As PySpark's, csv, json and xml of a DataFrame parse its strings: a Parse (Relation.parse
    # =30) of the DataFrame (input=1) in the format (format=2), with the schema (schema=3) of
    # the reader and its options (options=4).
    spark, service = mock_connect
    strings = T.StructType([T.StructField("value", T.StringType())])
    read(spark, spark.createDataFrame([("1;x",)], strings)).columns
    parse = _sent_relation(service.analyze_requests[-1], 30)
    assert parse[2] == [format]
    # The server parses a DDL schema, as PySpark's `StructType.fromDDL`:
    # AnalyzePlanRequest.ddl_parse=11 -> ddl_string=1.
    assert [parse_message(parse_message(request)[11][0])[1][0]
            for request in service.analyze_requests if 11 in parse_message(request)] == [
        b"a INT, b STRING"]
    assert _struct_field_names(parse[3][0]) == ["a", "b"]
    assert parse_message(parse[4][0]) == {1: [option], 2: [b";"]}
    assert 1 in parse
    # A schema of JSON, as a StructType sends it, or none.
    struct = T.StructType([T.StructField("c", T.LongType())])
    spark.read.json(spark.createDataFrame([("{}",)], strings), schema=struct).columns
    assert _struct_field_names(_sent_relation(service.analyze_requests[-1], 30)[3][0]) == ["c"]
    spark.read.csv(spark.createDataFrame([("1",)], strings)).columns
    assert 3 not in _sent_relation(service.analyze_requests[-1], 30)
    # The reader keeps the schema and the options of a parse, but not its format, which
    # only `load` sets.
    reader = spark.read.format("parquet")
    reader.csv(spark.createDataFrame([("1",)], strings), schema="a INT", sep=";")
    assert (reader._format, reader._schema, reader._options) == ("parquet", "a INT", {"sep": ";"})
    reader.csv("p", sep=",")
    assert (reader._format, reader._schema, reader._options) == ("csv", "a INT", {"sep": ","})


def test_reader_parse_raises_pysparks_errors_of_a_schema_that_its_json_parse_refuses(mock_connect):
    # As PySpark's Parse plan, which reads the JSON of the reader's schema with
    # StructType.fromJson when it is built: a type of its class only, such as AtomicType(), whose
    # json() is its name, raises CANNOT_PARSE_DATATYPE, and a StructField as a type
    # UNSUPPORTED_DATA_TYPE, of the type of its JSON. The call of csv, json or xml does not raise;
    # each request of the DataFrame does, and sends nothing. The messages are official PySpark
    # 4.3.0's.
    from pyspark.errors import PySparkValueError

    spark, service = mock_connect
    strings = spark.createDataFrame([("1",)], T.StructType([T.StructField("v", T.StringType())]))
    field = T.StructField("x", T.IntegerType())
    for schema, message in [
        (T.StructType([T.StructField("a", T.AtomicType())]),
         "[CANNOT_PARSE_DATATYPE] Unable to parse datatype. atomic."),
        (T.StructType([T.StructField("a", T.MapType(T.StringType(), T.DataType()))]),
         "[CANNOT_PARSE_DATATYPE] Unable to parse datatype. data."),
        (T.StructType([T.StructField("a", field)]),
         "[UNSUPPORTED_DATA_TYPE] Unsupported DataType `integer`."),
        ('{"fields":[{"metadata":{},"name":"a","nullable":true,"type":"atomic"}],"type":"struct"}',
         "[CANNOT_PARSE_DATATYPE] Unable to parse datatype. atomic."),
        ('{"fields":[{"metadata":{},"name":"a","nullable":true,"type":"null"}],"type":"struct"}',
         "[CANNOT_PARSE_DATATYPE] Unable to parse datatype. null."),
        ('{"fields":[{"metadata":{},"name":"a","nullable":true,"type":"unparsed(\\"atomic\\")"}],'
         '"type":"struct"}',
         '[CANNOT_PARSE_DATATYPE] Unable to parse datatype. unparsed("atomic").'),
    ]:
        for read in ("csv", "json", "xml"):
            df = getattr(spark.read.schema(schema), read)(strings)
            sent = (len(service.execute_requests), len(service.analyze_requests))
            for request in (lambda: df.schema, df.collect):
                with pytest.raises(PySparkValueError) as error:
                    request()
                assert str(error.value) == message, (schema, read)
            assert (len(service.execute_requests), len(service.analyze_requests)) == sent


def test_local_relations_send_pysparks_json_of_their_schema(mock_connect):
    # As PySpark's createDataFrame, which sends the json() of its schema with local data: a type
    # of its class only and a StructField as a type, nested in the schema, are in it as their own
    # JSON, of a NumPy array, an empty pandas DataFrame and empty rows alike, where the drop-in
    # wrote unparsed(...) of them. The JSON is official PySpark 4.3.0's.
    np = pytest.importorskip("numpy")
    pd = pytest.importorskip("pandas")
    spark, service = mock_connect
    numeric = T.StructType([
        T.StructField("i", T.IntegerType()), T.StructField("a", T.ArrayType(T.NumericType())),
    ])
    numeric_json = (
        '{"fields":[{"metadata":{},"name":"i","nullable":true,"type":"integer"},'
        '{"metadata":{},"name":"a","nullable":true,'
        '"type":{"containsNull":true,"elementType":"numeric","type":"array"}}],"type":"struct"}'
    )
    field = T.StructType([T.StructField("a", T.StructField("x", T.IntegerType()))])
    field_json = (
        '{"fields":[{"metadata":{},"name":"a","nullable":true,'
        '"type":{"metadata":{},"name":"x","nullable":true,"type":"integer"}}],"type":"struct"}'
    )
    for data, schema, expected in [
        (np.array([[1, 2]]), numeric, numeric_json),
        (pd.DataFrame({"i": [], "a": []}), numeric, numeric_json),
        (np.array([[1]]), field, field_json),
        ([], field, field_json),
    ]:
        spark.createDataFrame(data, schema).columns
        # Relation.local_relation=11 -> LocalRelation.schema=2.
        local = _sent_relation(service.analyze_requests[-1], 11)
        assert local[2] == [expected.encode()]


def test_reader_and_writer_check_their_arguments_as_pyspark(mock_connect):
    # As PySpark Connect's: a write of a mode other than append, overwrite, error and ignore
    # raises UNSUPPORTED_OPERATION, of the last mode set, before it sends anything, also of
    # errorifexists, which its WriteOperation does not take, unlike classic PySpark's writer;
    # format(None) unsets the format; the reader raises JVM_ATTRIBUTE_NOT_SUPPORTED
    # of _jreader, asserts the bounds of a JDBC column and refuses a schema in changes; and csv,
    # text and orc of None read without a path.
    from pyspark.errors import AnalysisException, PySparkAttributeError, PySparkValueError

    spark, service = mock_connect
    df = spark.range(3)
    for write, mode in [
        (lambda: df.write.mode("bad").save("p"), "bad"),
        (lambda: df.write.mode("append").mode("default").saveAsTable("t"), "default"),
        (lambda: df.write.mode(" append").insertInto("t"), " append"),
        (lambda: df.write.parquet("p", mode=""), ""),
        (lambda: df.write.jdbc("jdbc:x", "t", mode="bad"), "bad"),
        (lambda: df.write.mode("errorifexists").insertInto("t"), "errorifexists"),
        (lambda: df.write.parquet("p", mode="ErrorIfExists"), "ErrorIfExists"),
    ]:
        sent = len(service.execute_requests)
        with pytest.raises(PySparkValueError) as e:
            write()
        assert e.value.getCondition() == "UNSUPPORTED_OPERATION"
        assert e.value.getMessageParameters() == {"operation": mode}
        assert len(service.execute_requests) == sent

    def sent_write():
        # ExecutePlanRequest.plan=3, Plan.command=2, Command.write_operation=2.
        plan = parse_message(parse_message(service.execute_requests[-1])[3][0])
        return parse_message(parse_message(plan[2][0])[2][0])

    # WriteOperation.source=2 and mode=5, of SAVE_MODE_APPEND=1 and SAVE_MODE_ERROR_IF_EXISTS=3.
    df.write.mode("bad").mode("APPEND").format("json").format(None).save("p")
    assert 2 not in sent_write() and sent_write()[5] == [1]
    df.write.mode("error").insertInto("t")
    assert sent_write()[5] == [3]
    df.write.jdbc("jdbc:x", "t", properties={"user": 1, "flag": True, "skip": None})
    # WriteOperation.options=9, of entries of key=1 and value=2.
    options = {parse_message(entry)[1][0]: parse_message(entry)[2][0] for entry in sent_write()[9]}
    assert options == {b"user": b"1", b"flag": b"true", b"url": b"jdbc:x", b"dbtable": b"t"}

    reader = spark.read.format("csv")
    assert reader.format(None) is reader and reader._format is None
    stream = spark.readStream.format("rate")
    assert stream.format(None) is stream
    with pytest.raises(PySparkAttributeError) as e:
        spark.read._jreader
    assert e.value.getCondition() == "JVM_ATTRIBUTE_NOT_SUPPORTED"
    assert e.value.getMessageParameters() == {"attr_name": "_jreader"}
    with pytest.raises(AnalysisException) as e:
        spark.read.schema("a int").changes("t")
    assert e.value.getCondition() == "_LEGACY_ERROR_TEMP_1189"
    assert e.value.getMessageParameters() == {"operation": "changes"}
    assert "User specified schema not supported with `changes`." in str(e.value)
    for bounds, missing in [({}, "lowerBound"), ({"lowerBound": 1}, "upperBound"),
                            ({"lowerBound": 1, "upperBound": 2}, "numPartitions")]:
        reader = spark.read
        with pytest.raises(AssertionError, match=f"{missing} can not be None when ``column``"):
            reader.jdbc("jdbc:x", "t", column="c", **bounds)
        assert reader._format == "jdbc" and reader._options == {}

    def sent_data_source():
        # Relation.read=2 -> Read.data_source=2: options=3, of entries of key=1 and value=2,
        # and predicates=5.
        source = parse_message(_sent_relation(service.analyze_requests[-1], 2)[2][0])
        options = {parse_message(e)[1][0].decode(): parse_message(e)[2][0].decode()
                   for e in source.get(3, [])}
        return options, [p.decode() for p in source.get(5, [])]

    spark.read.jdbc("jdbc:x", "t", column="c", lowerBound=1, upperBound=2, numPartitions="3",
                    predicates=["p"], properties={"user": 1, "flag": True}).columns
    assert sent_data_source() == ({
        "partitionColumn": "c", "lowerBound": "1", "upperBound": "2", "numPartitions": "3",
        "user": "1", "flag": "true", "url": "jdbc:x", "dbtable": "t"}, [])
    spark.read.jdbc("jdbc:x", "t", lowerBound=1, predicates=["p"]).columns
    assert sent_data_source() == ({"url": "jdbc:x", "dbtable": "t"}, ["p"])
    for read in (spark.read.csv, spark.read.text, spark.read.orc):
        read(None).columns
        assert _sent_data_source_paths(service.analyze_requests[-1]) == []


def test_jdbc_properties_are_keywords_as_pyspark(mock_connect):
    # As PySpark's jdbc of the reader and the writer, which pass the properties as
    # `options(**properties)`: a key that is not a str raises the TypeError of the unpacking
    # before any property is set, with the format (and the options of a column, the mode) already
    # set, where a key went through str() as another option name before.
    spark, service = mock_connect
    df = spark.range(1)
    sent = len(service.execute_requests), len(service.analyze_requests)
    for key in (1, b"user", None):
        reader = spark.read
        with pytest.raises(TypeError) as error:
            reader.jdbc("jdbc:x", "t", properties={"user": "u", key: "v"})
        assert type(error.value) is TypeError and str(error.value) == "keywords must be strings"
        assert reader._format == "jdbc" and reader._options == {}
        reader = spark.read
        with pytest.raises(TypeError, match="^keywords must be strings$"):
            reader.jdbc("jdbc:x", "t", column="c", lowerBound=1, upperBound=2, numPartitions=3,
                        properties={key: "v"})
        assert reader._options == {
            "partitionColumn": "c", "lowerBound": "1", "upperBound": "2", "numPartitions": "3"}
        with pytest.raises(TypeError, match="^keywords must be strings$"):
            df.write.jdbc("jdbc:x", "t", mode="append", properties={key: "v"})
    assert (len(service.execute_requests), len(service.analyze_requests)) == sent


def test_option_keys_that_are_not_str_are_keywords_as_pyspark(mock_connect):
    # As PySpark's `**options` methods, which are Python functions: CPython unpacks a key that is
    # not a str as the TypeError `keywords must be strings`, before the method does anything, so
    # no option is set (bytes and int keys used to be set as their str()), and nothing is sent.
    import warnings

    from pyspark.sql import functions as F

    spark, service = mock_connect
    df = spark.range(1)
    sent = len(service.execute_requests), len(service.analyze_requests)
    for key in (1, b"multiLine"):
        kwargs = {key: True}
        reader = spark.read.format("json")
        with pytest.raises(TypeError, match="^keywords must be strings$"):
            reader.options(**kwargs)
        assert reader._format == "json" and reader._options == {}
        calls = [
            lambda: spark.read.load("p", **kwargs),
            lambda: spark.read.parquet("p", **kwargs),
            lambda: spark.read._set_opts(**kwargs),
            lambda: spark.readStream.options(**kwargs),
            lambda: spark.readStream.load("p", **kwargs),
            lambda: spark.range(1).write.options(**kwargs),
            lambda: spark.range(1).write.save("p", **kwargs),
            lambda: spark.range(1).write.saveAsTable("t", **kwargs),
            lambda: spark.range(1).writeTo("t").options(**kwargs),
            lambda: spark.range(1).writeStream.options(**kwargs),
            lambda: spark.range(1).writeStream.start("p", **kwargs),
            lambda: spark.range(1).writeStream.toTable("t", **kwargs),
            lambda: df.show(**kwargs),
            lambda: df._show_string(**kwargs),
            lambda: df.sort("id", **kwargs),
            lambda: df.orderBy("id", **kwargs),
            lambda: df.sortWithinPartitions("id", **kwargs),
            lambda: df._to_pandas(**kwargs),
            lambda: df.select(F.col("id").alias("x", **kwargs)),
            lambda: df.select(F.col("id").name("x", **kwargs)),
            lambda: spark.catalog.createTable("t", "p", "json", **kwargs),
            lambda: spark.catalog.createExternalTable("t", "p", "json", **kwargs),
        ]
        for call in calls:
            with pytest.raises(TypeError, match="^keywords must be strings$"):
                call()
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter("always")
            with pytest.raises(TypeError, match="^keywords must be strings$"):
                spark.catalog.createExternalTable("t", "p", "json", **kwargs)
        assert not caught
    assert (len(service.execute_requests), len(service.analyze_requests)) == sent


def test_jdbc_predicates_are_checked_as_pyspark(mock_connect):
    # As PySpark's jdbc, whose DataSource plan asserts that the predicates are a list of str,
    # after the reader has its format, url and dbtable: a bare AssertionError for any other value.
    # The predicates are not checked when a column is given, which reads its partitions instead.
    spark, service = mock_connect
    sent = len(service.execute_requests), len(service.analyze_requests)
    for predicates in (("a=1",), "a=1", [1], [None], [b"a=1"], ["a=1", 2], ()):
        reader = spark.read
        with pytest.raises(AssertionError) as error:
            reader.jdbc("jdbc:x", "t", predicates=predicates)
        assert str(error.value) == ""
        assert reader._format == "jdbc" and reader._options == {"url": "jdbc:x", "dbtable": "t"}
    assert (len(service.execute_requests), len(service.analyze_requests)) == sent
    spark.read.jdbc("jdbc:x", "t", column="c", lowerBound=1, upperBound=2, numPartitions=2,
                    predicates="a=1").columns


def test_show_counts_are_proto_int32_as_pyspark(mock_connect):
    # As PySpark's ShowString, whose num_rows and truncate are proto int32 fields that protobuf
    # converts: an int out of their range raises the ValueError of the value, not an OverflowError.
    spark, service = mock_connect
    df = spark.range(1)
    sent = len(service.execute_requests), len(service.analyze_requests)
    for value in (2**31, -(2**31) - 1, 2**70):
        for kwargs in ({"n": value}, {"truncate": value}):
            with pytest.raises(ValueError, match=f"^Value out of range: {value}$"):
                df._show_string(**kwargs)
        with pytest.raises(ValueError, match=f"^Value out of range: {value}$"):
            df.show(n=value)
    assert (len(service.execute_requests), len(service.analyze_requests)) == sent


# Each method takes a catch-all of the keywords it does not name, which its visible signature does
# not show. The keywords are passed as a dict argument, so that the lambda is not refused itself.
UNEXPECTED_KEYWORD_CALLS = [
    ("DataFrameReader.json", lambda s, kw: s.read.json("p", **kw)),
    ("DataFrameReader.csv", lambda s, kw: s.read.csv("p", **kw)),
    ("DataFrameReader.orc", lambda s, kw: s.read.orc("p", **kw)),
    ("DataFrameReader.text", lambda s, kw: s.read.text("p", **kw)),
    ("DataFrameReader.xml", lambda s, kw: s.read.xml("p", **kw)),
    ("DataStreamReader.json", lambda s, kw: s.readStream.json("p", **kw)),
    ("DataStreamReader.parquet", lambda s, kw: s.readStream.parquet("p", **kw)),
    ("DataStreamReader.csv", lambda s, kw: s.readStream.csv("p", **kw)),
    ("DataStreamReader.text", lambda s, kw: s.readStream.text("p", **kw)),
    ("DataStreamReader.orc", lambda s, kw: s.readStream.orc("p", **kw)),
    ("DataStreamReader.xml", lambda s, kw: s.readStream.xml("p", **kw)),
    ("DataFrameWriter.parquet", lambda s, kw: s.range(1).write.parquet("p", **kw)),
    ("DataFrameWriter.json", lambda s, kw: s.range(1).write.json("p", **kw)),
    ("DataFrameWriter.csv", lambda s, kw: s.range(1).write.csv("p", **kw)),
    ("DataFrameWriter.orc", lambda s, kw: s.range(1).write.orc("p", **kw)),
    ("DataFrameWriter.text", lambda s, kw: s.range(1).write.text("p", **kw)),
    ("DataFrameWriter.xml", lambda s, kw: s.range(1).write.xml("p", **kw)),
    # CPython names a method by its qualified name, which is that of the builder's class in PySpark.
    ("SparkSession.Builder.config", lambda s, kw: s.builder.config(**kw)),
]


@pytest.mark.parametrize(
    "method, call", UNEXPECTED_KEYWORD_CALLS, ids=[method for method, _ in UNEXPECTED_KEYWORD_CALLS]
)
def test_unexpected_keywords_are_keywords_as_pyspark(offline_spark, method, call):
    # As PySpark's methods, which are Python functions with no **kwargs: a key that is not a str
    # raises `keywords must be strings`, and a str key that the method does not take raises the
    # unexpected keyword argument of the method. Both are raised before the call does anything.
    # The lazy session has no server, so a call that sent a request would fail with a connection
    # error instead of these TypeErrors, which is how the lack of a request is checked here.
    with pytest.raises(TypeError) as error:
        call(offline_spark, {1: "1"})
    assert str(error.value) == "keywords must be strings"
    with pytest.raises(TypeError) as error:
        call(offline_spark, {"foo": 1})
    assert str(error.value) == f"{method}() got an unexpected keyword argument 'foo'"
    # A str key need not have UTF-8, such as one with a lone surrogate, which CPython's message
    # keeps as it is.
    with pytest.raises(TypeError) as error:
        call(offline_spark, {"\ud800": 1})
    assert str(error.value) == f"{method}() got an unexpected keyword argument '\ud800'"


def test_known_keywords_still_bind_with_the_unexpected_catch_all(offline_spark):
    # The catch-all takes only the keywords that the method does not name: those bind as before.
    from pyspark.sql import DataFrame

    reader = offline_spark.read
    assert isinstance(reader.json("p", multiLine=True), DataFrame)
    assert reader._format == "json" and reader._options == {"multiLine": "true"}
    reader = offline_spark.read
    reader.csv("p", sep=";", header=True)
    assert reader._format == "csv" and reader._options == {"sep": ";", "header": "true"}


def test_reader_paths_are_checked_as_pyspark(offline_spark):
    from pyspark.errors import PySparkTypeError

    # json and xml take a path, a list of them or a DataFrame; csv loads any other path,
    # which load then asserts, as PySpark's.
    for read in (offline_spark.read.json, offline_spark.read.xml):
        for path in (1, ("p",)):
            with pytest.raises(PySparkTypeError) as error:
                read(path)
            assert error.value.getCondition() == "NOT_EXPECTED_TYPE"
            assert error.value.getMessageParameters() == {
                "arg_name": "path", "expected_type": "str, list, or DataFrame",
                "arg_type": type(path).__name__}
    for read in (
        lambda path: offline_spark.read.csv(path),
        lambda path: offline_spark.read.load(path),
        lambda path: offline_spark.read.orc(path),
        lambda path: offline_spark.read.text(path),
        lambda path: offline_spark.read.json([path]),
    ):
        for path in (("p",), 1):
            with pytest.raises(AssertionError):
                read(path)
    with pytest.raises(AssertionError):
        offline_spark.read.parquet("p", 1)


def _sent_data_source_paths(request):
    # Relation.read=2 -> Read.data_source=2 -> DataSource.paths=4.
    read = _sent_relation(request, 2)
    return [path.decode() for path in parse_message(read[2][0]).get(4, [])]


