# --------------------------------------------------------------------------- plan compression

PLAN_COMPRESSION_THRESHOLD = "spark.connect.session.planCompression.threshold"
PLAN_COMPRESSION_ALGORITHM = "spark.connect.session.planCompression.defaultAlgorithm"


def _plan_confs(threshold):
    return {PLAN_COMPRESSION_THRESHOLD: threshold, PLAN_COMPRESSION_ALGORITHM: "ZSTD"}


def _sent_plan(requests):
    # ExecutePlanRequest.plan=3; Plan.root=1, or Plan.compressed_operation=3 whose data=1,
    # op_type=2 (OP_TYPE_RELATION=1) and compression_codec=3 (COMPRESSION_CODEC_ZSTD=1).
    return parse_message(parse_message(requests[-1])[3][0])


def _collect_in_new_session(service, confs, make_df):
    # The plan compression of a session is read once, so each threshold gets a session of its own.
    from pyspark.sql import SparkSession

    service.confs = confs
    spark = SparkSession.builder.remote(service.remote).create()
    try:
        make_df(spark).collect()
    finally:
        spark.stop()
    return _sent_plan(service.execute_requests)


def _long_literal_frame(spark):
    from pyspark.sql import functions as F

    return spark.range(1).select(F.length(F.lit("x" * 4096)))


def test_plans_over_the_server_threshold_are_sent_as_zstd_relations(mock_connect):
    zstandard = pytest.importorskip("zstandard")

    spark, service = mock_connect
    service.confs = _plan_confs("1024")
    _long_literal_frame(spark).collect()
    plan = _sent_plan(service.execute_requests)
    assert 1 not in plan
    operation = parse_message(plan[3][0])
    assert operation[2] == [1]
    assert operation[3] == [1]
    assert len(operation[1][0]) < 4096

    # The same plan, sent uncompressed by a session whose threshold is above its size.
    root = _collect_in_new_session(
        service,
        _plan_confs(str(1 << 30)),
        _long_literal_frame,
    )[1][0]
    # The plan IDs of two DataFrames differ, so the relations are compared by their fields.
    reader = zstandard.ZstdDecompressor().stream_reader(io.BytesIO(operation[1][0]))
    relation = reader.read()
    assert b"x" * 4096 in relation and len(relation) == len(root)
    assert parse_message(relation).keys() == parse_message(root).keys()


def test_plans_at_the_server_threshold_are_sent_as_they_are(mock_connect):
    spark, service = mock_connect
    size = len(_collect_in_new_session(
        service, _plan_confs(str(1 << 30)), _long_literal_frame)[1][0])
    at_threshold = _collect_in_new_session(
        service, _plan_confs(str(size)), _long_literal_frame)
    assert 3 not in at_threshold and len(at_threshold[1][0]) == size
    over_threshold = _collect_in_new_session(
        service, _plan_confs(str(size - 1)), _long_literal_frame)
    assert 1 not in over_threshold and 3 in over_threshold


def test_registrations_are_sent_as_they_are_without_the_lookup_as_pyspark(mock_connect):
    # As PySpark's `register_udf`, `register_udtf`, `register_data_source` and `register_java` of
    # `_execute`, which set their command in the plan of their request as it is: the
    # registrations of a session make no lookup of its plan compression, and one over the
    # threshold is sent uncompressed. The plan after them makes the lookup.
    from pyspark.sql import functions as F
    from pyspark.sql.datasource import DataSource

    spark, service = mock_connect
    service.confs = _plan_confs("1024")
    payload = "x" * 4096

    class Echo:
        def eval(self, n):
            yield (n + len(payload),)

    class Large(DataSource):
        @classmethod
        def name(cls):
            return "large" + payload

    spark.udf.register("large_udf", lambda v: v + len(payload), T.IntegerType())
    spark.udtf.register("large_udtf", F.udtf(Echo, returnType="a int", useArrow=False))
    spark.dataSource.register(Large)
    spark.udf.registerJavaFunction("large_java" + payload, "org.example.Large", T.IntegerType())
    assert service.plan_compression_lookups == 0
    assert len(service.execute_requests) == 4
    for request in service.execute_requests:
        # Plan.command=2, of no compressed_operation=3.
        plan = _sent_plan([request])
        assert list(plan) == [2] and len(plan[2][0]) > 4096
    _long_literal_frame(spark).collect()
    assert service.plan_compression_lookups == 1
    assert 3 in _sent_plan(service.execute_requests)


def test_plan_compression_is_read_once_per_session(mock_connect):
    spark, service = mock_connect
    service.confs = _plan_confs("1024")
    frame = _long_literal_frame(spark)
    frame.collect()
    frame.collect()
    assert service.plan_compression_lookups == 1


def test_to_proto_reads_nothing_of_the_client_once_the_compression_is_known_as_pyspark(
    mock_connect,
):
    # As PySpark's `_try_compress_and_set_plan`, which looks the settings of the plan compression
    # up for the first plan, of the request of the lookup, and then reads nothing of its client: a
    # plan under the threshold, set as it is, and one over it, compressed, are built of a client
    # whose user and session ID no request takes, and look nothing up. The session gives the
    # threshold once it is known, -1 of a compression that is disabled, and None before.
    from pyspark.sql import SparkSession

    _, service = mock_connect
    for confs, threshold, large_type in [
        (_plan_confs("1024"), 1024, "compressed_operation"),
        (_plan_confs(None), -1, "root"),
    ]:
        service.confs = confs
        session = SparkSession.builder.remote(service.remote).create()
        try:
            client = session.client
            assert client._session._plan_compression_threshold() is None
            session.range(1)._plan.to_proto(client)
            assert client._session._plan_compression_threshold() == threshold
            lookups = service.plan_compression_lookups
            user_id, session_id = client._user_id, client._session_id
            client._user_id, client._session_id = 123, 5
            try:
                small = session.range(3)._plan.to_proto(client)
                large = _long_literal_frame(session)._plan.to_proto(client)
            finally:
                client._user_id, client._session_id = user_id, session_id
            assert small.WhichOneof("op_type") == "root"
            assert large.WhichOneof("op_type") == large_type
            assert service.plan_compression_lookups == lookups
        finally:
            session.stop()


