def test_a_builder_remote_that_is_not_a_str_fails_create_as_pyspark(mock_connect):
    # As PySpark's `remote`, which keeps the value as it is, and `create` takes its `str()`, which
    # is not a Spark Connect URL: bytes, an int and a bool all raise INVALID_CONNECT_URL there.
    from pyspark.errors import PySparkValueError
    from pyspark.sql import SparkSession

    for url in [b"sc://localhost:15013", 3, True]:
        builder = SparkSession.builder.remote(url)
        with pytest.raises(PySparkValueError, match="INVALID_CONNECT_URL"):
            builder.create()


def test_a_builder_remote_set_to_none_fails_create_as_pyspark(mock_connect, monkeypatch):
    # As PySpark's Connect builder: `remote(None)`, and a config of spark.remote of None, keep the
    # URL as None, which `create` asserts whatever SPARK_REMOTE is. `getOrCreate` returns the
    # session that exists, as PySpark's does, and a later `remote` replaces the None.
    from pyspark.sql.connect.session import SparkSession

    spark, service = mock_connect
    monkeypatch.setenv("SPARK_REMOTE", service.remote)
    builders = [
        lambda: SparkSession.builder.remote(None),
        lambda: SparkSession.builder.remote(location=None),
        lambda: SparkSession.builder.config("spark.remote", None),
    ]
    for builder in builders:
        with pytest.raises(AssertionError):
            builder().create()
        assert builder().getOrCreate() is spark
    replaced = SparkSession.builder.remote(None).remote(service.remote).create()
    try:
        assert replaced is not spark
    finally:
        replaced.stop()
    # A remote without an argument is the default URL, which the builder keeps in its options.
    assert SparkSession.builder.remote()._options == {"spark.remote": "sc://localhost"}


def test_empty_rows_send_the_json_of_a_raw_nullable_schema_as_pyspark(mock_connect):
    # As PySpark's empty LocalRelation, which sends `schema.json()` as it is: a nullable flag that
    # is not a bool stays raw in the text, which the server cannot parse, so its DataFrame fails
    # with its ParseException. The relation of the empty rows carries that text, and a schema of
    # bool flags is sent as before. The schema of the DataFrame is analyzed, which sends the plan.
    import json

    from pyspark.sql import types as T

    spark, service = mock_connect

    def sent_schema(flag):
        schema = T.StructType([T.StructField("x", T.IntegerType(), flag)])
        df = spark.createDataFrame([], schema)
        df.schema
        # LocalRelation=11 of the relation, and LocalRelation.schema=2.
        local = _sent_relation(service.analyze_requests[-1], 11)
        assert len(local[2]) == 1
        return local[2][0].decode()

    for flag in [0, 1, "x", None, [1]]:
        expected = {"fields": [{"metadata": {}, "name": "x", "nullable": flag, "type": "integer"}],
                    "type": "struct"}
        assert sent_schema(flag) == json.dumps(expected, separators=(",", ":"), sort_keys=True)
    assert json.loads(sent_schema(False)) == {
        "fields": [{"metadata": {}, "name": "x", "nullable": False, "type": "integer"}],
        "type": "struct"}


def test_a_shallow_copy_of_a_merge_builder_keeps_its_schema_evolution_as_pyspark(mock_connect):
    # As PySpark, where withSchemaEvolution sets the attribute of the builder it is called on,
    # so a copy that sets it sends it alone, while the clauses that the copy adds are shared.
    import copy

    from pyspark.sql import functions as F

    spark, service = mock_connect

    def sent_schema_evolution():
        # ExecutePlanRequest.plan=3, Plan.command=2, Command.merge_into_table_command=16, and
        # MergeIntoTableCommand.with_schema_evolution=7.
        command = parse_message(parse_message(service.execute_requests[-1])[3][0])
        merge = parse_message(parse_message(command[2][0])[16][0])
        return bool(merge.get(7))

    builder = spark.range(1).mergeInto("t", F.col("id") == 1).whenMatched().updateAll()
    copied = copy.copy(builder)
    copied.withSchemaEvolution()
    copied.whenNotMatched().insertAll()
    builder.merge()
    assert sent_schema_evolution() is False
    copied.merge()
    assert sent_schema_evolution() is True
    assert len(service.execute_requests) >= 2


class _NotAMode:
    # An object that is not a save mode, whose `lower()` names none of them.
    def lower(self):
        return "bogus"


def test_copies_of_the_writers_share_their_kept_arguments_as_pyspark(mock_connect):
    # As PySpark's copy.copy of a writer, which shares its `_write`: an argument that the copy keeps
    # for the write (a format, a save mode, a partitioning or clustering column, or a provider) is in
    # the write of the original too, as an attribute set on the shared object is.
    import copy

    from pyspark.errors import PySparkValueError

    spark, _ = mock_connect
    df = spark.range(1)
    writer = df.write
    copied = copy.copy(writer)
    copied.format(5)
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        writer.mode("overwrite").save()
    writer.format("noop")
    copied.mode(b"append")
    with pytest.raises(PySparkValueError) as error:
        writer.save()
    assert error.value.getCondition() == "UNSUPPORTED_OPERATION"
    writer.mode("overwrite")
    copied.partitionBy(5)
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        writer.save()
    writer.partitionBy("id")
    copied.clusterBy(5)
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        writer.save()
    writer.clusterBy("id")
    copied.format(5)
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        writer.save()

    v2 = df.writeTo("forked_copy_table")
    copied_v2 = copy.copy(v2)
    copied_v2.using(5)
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        v2.append()
    v2.using("noop")
    copied_v2.clusterBy(5)
    with pytest.raises(TypeError, match="^bad argument type for built-in operation$"):
        v2.append()


def test_deep_copies_keep_the_kept_arguments_through_the_memo_as_pyspark(mock_connect):
    # As PySpark's copy.deepcopy, which copies the state of a writer, and the objects that it keeps,
    # through the memo: the copied save mode of the copied writer is the copy of the object.
    import copy

    from pyspark.errors import PySparkValueError

    spark, _ = mock_connect
    mode = _NotAMode()
    copied = copy.deepcopy({"writer": spark.range(1).write.mode(mode), "mode": mode})
    with pytest.raises(PySparkValueError) as error:
        copied["writer"].format("noop").save()
    assert error.value.getMessageParameters()["operation"] is copied["mode"]
    assert copied["mode"] is not mode


def test_reader_copies_keep_their_format_and_share_their_options_as_pyspark(mock_connect):
    # As PySpark's copy.copy of a reader: the copy shares the options, and its format and schema
    # stay its own, so a format on the copy does not reach the original.
    import copy

    spark, _ = mock_connect
    reader = spark.read.format("noop")
    copied = copy.copy(reader)
    copied.format(5).option("k", "v")
    assert reader.load() is not None
    assert reader._options == {"k": "v"}
